import { PrismaClient } from '@prisma/client';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const prisma = new PrismaClient();

// In ESM/Next.js context, __dirname is not always available, but since we run this via tsx:
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

async function main() {
  const seedFile = path.join(__dirname, 'data', 'e3_live_activations_bilingual_seed.json');

  if (!fs.existsSync(seedFile)) {
    console.error(`Seed file not found: ${seedFile}`);
    process.exit(1);
  }

  const fileContent = fs.readFileSync(seedFile, 'utf-8');
  const seedData = JSON.parse(fileContent);

  console.log(`Starting to seed ${seedData.activations.length} attractions...`);

  for (const activation of seedData.activations) {
    const slug = activation.slug;

    // Build the main Attraction data
    const attractionData = {
      nameEn: activation.coreDetails.name.en,
      nameAr: activation.coreDetails.name.ar,
      taglineEn: activation.coreDetails.tagline?.en || null,
      taglineAr: activation.coreDetails.tagline?.ar || null,
      descriptionEn: activation.coreDetails.description?.en || null,
      descriptionAr: activation.coreDetails.description?.ar || null,

      heroMediaType: activation.heroMediaController?.mediaType === 'IMAGE_CAROUSEL' ? 'IMAGE' : activation.heroMediaController?.mediaType || 'IMAGE',
      heroMediaUrl: activation.heroMediaController?.primaryMediaUrl || null,
      heroFallbackUrl: activation.heroMediaController?.fallbackImageUrl || null,
      heroThumbnailUrl: activation.heroMediaController?.thumbnailImageUrl || null,

      mapUrl: activation.bookingAndMaps?.mapUrl || null,
      ticketingUrl: activation.bookingAndMaps?.ticketingUrl || null,

      features: activation.whatsInside || [],
      partnerOffers: activation.partnerOffer ? [activation.partnerOffer] : [],
      partners: activation.generalPartners || [],
      socialPreviews: activation.socialPreviews || [],
      newsCoverage: activation.newsAndCoverage || [],
      operations: activation.operations || {},
      temporalStatus: activation.temporalRules || {},

      isPublished: true,
    };

    console.log(`Upserting attraction: ${slug}`);

    const upsertedAttraction = await prisma.attraction.upsert({
      where: { slug },
      update: attractionData,
      create: {
        slug,
        ...attractionData,
      },
    });

    // Handle Pricing
    if (activation.pricingAndTickets && activation.pricingAndTickets.length > 0) {
      for (const pricing of activation.pricingAndTickets) {
        // Attempt to match existing pricing by title
        const existingPricing = await prisma.attractionPricing.findFirst({
          where: { attractionId: upsertedAttraction.id, titleEn: pricing.tierTitle.en }
        });

        const pricingData = {
          attractionId: upsertedAttraction.id,
          titleEn: pricing.tierTitle.en,
          titleAr: pricing.tierTitle.ar,
          descriptionEn: pricing.shortDescription?.en || null,
          descriptionAr: pricing.shortDescription?.ar || null,
          price: pricing.priceBase || 0,
          discount: pricing.discountPercent || null,
        };

        if (existingPricing) {
          await prisma.attractionPricing.update({
            where: { id: existingPricing.id },
            data: pricingData
          });
        } else {
          await prisma.attractionPricing.create({
            data: pricingData
          });
        }
      }
    }

    // Handle Gallery
    if (activation.mediaGallery && activation.mediaGallery.length > 0) {
      // Clear existing gallery and recreate
      await prisma.attractionGalleryItem.deleteMany({
        where: { attractionId: upsertedAttraction.id }
      });

      const galleryData = activation.mediaGallery.map((item: any, index: number) => ({
        attractionId: upsertedAttraction.id,
        url: item.mediaUrl,
        orderIndex: index
      }));

      await prisma.attractionGalleryItem.createMany({
        data: galleryData
      });
    }
  }

  console.log("Seeding completed successfully.");
}

main()
  .catch((e) => {
    console.error("Seeding failed:", e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

process.env.TURBOPACK = '0';
process.env.NEXT_PRIVATE_LOCAL_WEBPACK = 'true';
import { createServer } from 'http'
import { parse } from 'url'
import next from 'next'
import { initSocket } from './src/lib/socket'

const dev = process.env.NODE_ENV !== 'production'
const hostname = 'localhost'
const port = parseInt(process.env.PORT || '3000', 10)

// when using middleware `hostname` and `port` must be provided below
const app = next({ dev, hostname, port, turbo: false } as any)
const handle = app.getRequestHandler()

app.prepare().then(() => {
  const server = createServer(async (req, res) => {
    try {
      // Be sure to pass `true` as the second argument to `url.parse`.
      // This tells it to parse the query portion of the URL.
      const parsedUrl = parse(req.url!, true)
      await handle(req, res, parsedUrl)
    } catch (err) {
      console.error('Error occurred handling', req.url, err)
      res.statusCode = 500
      res.end('internal server error')
    }
  })

  // Hook up Socket.io server
  initSocket(server)

  server
    .once('error', (err) => {
      console.error(err)
      process.exit(1)
    })
    .listen(port, () => {
      console.log(`> Ready on http://${hostname}:${port} (Custom Server + Socket.io)`)
    })
})

import React from 'react'
import { UniversalMediaRenderer } from '@/components/shared/UniversalMediaRenderer'

import prisma from '@/lib/db'

export const metadata = {
  title: 'About Us - E3 Corporate',
  description: 'Learn about E3, our leadership, values, and our mission to engineer landmark experiences across the MENA region.',
}

export const dynamic = 'force-dynamic'

export default async function AboutPage({ params }: { params: Promise<{ locale: string }> }) {
  const { locale } = await params;
  const isAr = locale === 'ar';

  let employeeProfiles: any[] = []
  let page: any = null

  try {
    employeeProfiles = await prisma.employeeProfile.findMany({
      where: { isActive: true },
      orderBy: { order: "asc" },
      take: 3
    })
    page = await prisma.pages.findUnique({
      where: { slug: "b2b-about" }
    });
  } catch (error) {
    console.error("Error fetching b2b about page data:", error)
  }

  const leadership = employeeProfiles.map((emp) => ({
    name: `${emp.firstName} ${emp.lastName}`,
    title: emp.designation,
    image: emp.profileImage || 'https://images.unsplash.com/photo-1560250097-0b93528c311a?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80'
  }))

  const cmsData = (page?.content as any) || {};

  const headerTitle = isAr ? (cmsData?.header?.titleAr || 'نحن اي ثري.') : (cmsData?.header?.titleEn || 'We are E3.');
  const headerSubtitle = isAr ? (cmsData?.header?.subtitleAr || 'خبراء هندسة الفعاليات. نحول الرؤى الإبداعية الطموحة إلى واقع تشغيلي لا تشوبه شائبة.') : (cmsData?.header?.subtitleEn || 'Event Engineering Experts. We turn ambitious creative visions into flawless operational reality.');
  const headerMediaType = cmsData?.header?.mediaType || 'IMAGE';
  const headerMediaUrl = cmsData?.header?.mediaUrl || null;
  const headerFallbackImageUrl = cmsData?.header?.fallbackImageUrl || null;

  const storyTitle = isAr ? (cmsData?.story?.titleAr || 'قصتنا') : (cmsData?.story?.titleEn || 'Our Story');

  const defaultStoryAr = `تأسست E3 في الدوحة برؤية واضحة: قطاع الفعاليات السريع النمو في المنطقة بحاجة إلى شريك يفهم الطموح الإبداعي للفعاليات الضخمة والهندسة التشغيلية المطلوبة لتقديمها.

على مدار العقد الماضي، نمونا من شركة تنفيذ منصات إلى منظومة متكاملة من هندسة الفعاليات، التكنولوجيا الغامرة، وتشغيل الوجهات.

اليوم، نضم أكثر من 120 متخصصاً ونمتلك إحدى أكبر مستودعات المعدات والتقنيات في الشرق الأوسط.`;

  const defaultStoryEn = `E3 was founded in Doha with a simple premise: the region's rapidly growing events sector needed a partner that understood both the creative ambition of mega-events and the hard engineering required to deliver them.

Over the past decade, we have grown from a boutique staging company into a comprehensive ecosystem of event engineering, immersive technology, and venue operations. 

Today, we employ over 120 full-time specialists and maintain one of the largest inventories of staging, rigging, and XR hardware in the Middle East.`;

  const storyContent = isAr ? (cmsData?.story?.contentAr || defaultStoryAr) : (cmsData?.story?.contentEn || defaultStoryEn);
  const storyMediaType = cmsData?.story?.mediaType || 'IMAGE';
  const storyMediaUrl = cmsData?.story?.mediaUrl || null;
  const legacyImageMediaId = cmsData?.story?.imageMediaId || null;
  const storyFallbackImageUrl = cmsData?.story?.fallbackImageUrl || null;

  const values = cmsData?.values && cmsData.values.length > 0 ? cmsData.values.map((v: any) => ({
    title: isAr ? (v.titleAr || v.titleEn) : v.titleEn,
    desc: isAr ? (v.descAr || v.descEn) : v.descEn
  })) : [
    { 
      title: isAr ? 'الدقة الهندسية' : 'Engineering Precision', 
      desc: isAr ? 'نتعامل مع الإبداع بصرامة الهندسة الإنشائية. لا تفاصيل صغيرة جداً، ولا هامش أمان يتساهل به.' : 'We treat creativity with the rigor of structural engineering. No detail is too small, no safety margin too tight.' 
    },
    { 
      title: isAr ? 'التميز التشغيلي' : 'Operational Excellence', 
      desc: isAr ? 'التصاميم الجميلة لا تعني شيئاً إذا فشل التنفيذ. نحن نتحمل المسؤولية الكاملة عن التشغيل المباشر.' : 'Beautiful designs mean nothing if the execution fails. We take extreme ownership of the live operation.' 
    },
    { 
      title: isAr ? 'الأصالة الثقافية' : 'Cultural Resonance', 
      desc: isAr ? 'جذورنا في قطر، وبنينا للعالم. نحترم السياق المحلي مع وضع معايير عالمية.' : 'Rooted in Qatar, built for the world. Our experiences respect local context while setting global benchmarks.' 
    },
  ];

  // Fetch story image if it's a media URL
  const finalMediaUrl = storyMediaUrl || legacyImageMediaId || 'https://images.unsplash.com/photo-1497366216548-37526070297c?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80';

  return (
    <div className="flex flex-col w-full min-h-screen bg-zinc-950 pt-20" dir={isAr ? 'rtl' : 'ltr'}>
      
      {/* Header */}
      <section className="relative min-h-[50vh] flex flex-col justify-center py-20 border-b border-zinc-900 overflow-hidden">
        {headerMediaUrl ? (
          <div className="absolute inset-0 z-0">
            <UniversalMediaRenderer 
              type={headerMediaType as any}
              src={headerMediaUrl}
              alt="About Hero Background"
              poster={headerFallbackImageUrl}
            />
            <div className="absolute inset-0 bg-zinc-950/70" />
          </div>
        ) : (
          <div className="absolute inset-0 z-0 bg-zinc-900/50" />
        )}
        
        <div className="container relative z-10 mx-auto px-4 md:px-8">
          <h1 className="text-5xl md:text-7xl font-black text-zinc-100 tracking-tight mb-6 drop-shadow-xl">
            {headerTitle}
          </h1>
          <p className="text-xl text-zinc-300 max-w-2xl font-medium drop-shadow-md">
            {headerSubtitle}
          </p>
        </div>
      </section>

      {/* The Story */}
      <section className="py-24">
        <div className="container mx-auto px-4 md:px-8">
          <div className="grid md:grid-cols-2 gap-16 items-center">
            <div>
              <h2 className="text-3xl font-black text-zinc-100 mb-6 tracking-tight">{storyTitle}</h2>
              <div className="space-y-6 text-lg text-zinc-400 leading-relaxed whitespace-pre-wrap">
                {storyContent || `E3 was founded in Doha with a simple premise: the region's rapidly growing events sector needed a partner that understood both the creative ambition of mega-events and the hard engineering required to deliver them.

Over the past decade, we have grown from a boutique staging company into a comprehensive ecosystem of event engineering, immersive technology, and venue operations. 

Today, we employ over 120 full-time specialists and maintain one of the largest inventories of staging, rigging, and XR hardware in the Middle East.`}
              </div>
            </div>
            <div className="relative aspect-square rounded-xl overflow-hidden bg-zinc-900 border border-zinc-800">
               <UniversalMediaRenderer 
                type={storyMediaType as any}
                src={finalMediaUrl}
                alt="E3 Headquarters"
                poster={storyFallbackImageUrl}
               />
               <div className="absolute inset-0 flex items-center justify-center text-zinc-700 font-bold mix-blend-difference pointer-events-none">
                 [E3]
               </div>
            </div>
          </div>
        </div>
      </section>

      {/* Values */}
      <section className="py-24 bg-zinc-900 border-y border-zinc-800">
        <div className="container mx-auto px-4 md:px-8">
          <h2 className="text-3xl font-black text-zinc-100 mb-12 tracking-tight text-center">{isAr ? 'قيمنا الأساسية' : 'Our Core Values'}</h2>
          
          <div className="grid md:grid-cols-3 gap-8">
            {values.map((val: any, i: number) => (
              <div key={i} className="p-8 rounded-lg bg-zinc-950 border border-zinc-800">
                <div className="w-12 h-12 rounded-sm bg-emerald-500/10 border border-emerald-500/20 text-emerald-500 flex items-center justify-center font-black text-xl mb-6">
                  0{i + 1}
                </div>
                <h3 className="text-2xl font-bold text-zinc-100 mb-4">{val.title}</h3>
                <p className="text-zinc-400">{val.desc}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Leadership */}
      <section className="py-24">
        <div className="container mx-auto px-4 md:px-8">
          <h2 className="text-3xl font-black text-zinc-100 mb-12 tracking-tight">{isAr ? 'القيادة' : 'Leadership'}</h2>
          
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {leadership.map((leader, i) => (
              <div key={i} className="group">
                <div className="aspect-[3/4] bg-zinc-900 rounded-lg overflow-hidden border border-zinc-800 mb-6 relative">
                  <UniversalMediaRenderer 
                    type="IMAGE"
                    src={leader.image}
                    alt={leader.name}
                  />
                  <div className="absolute inset-0 bg-zinc-950/20 group-hover:bg-transparent transition-colors" />
                </div>
                <h3 className="text-2xl font-bold text-zinc-100 mb-1 group-hover:text-emerald-400 transition-colors">
                  {leader.name}
                </h3>
                <div className="text-emerald-500 font-bold uppercase tracking-widest text-sm">
                  {leader.title}
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

    </div>
  )
}

import React from 'react'
import 'next/link'
import { db } from "@/lib/db"
import { UniversalMediaRenderer } from '@/components/shared/UniversalMediaRenderer'
import { CareerListings } from '@/components/careers/CareerListings'

export const dynamic = 'force-dynamic'

export default async function B2BCareersPage({ params }: { params: Promise<{ locale: string }> }) {
  const { locale } = await params;
  const isAr = locale === 'ar'

  let pageData: any = null
  try {
    pageData = await db.pages.findUnique({
      where: { slug: 'b2b-careers' }
    })
  } catch (error) {
    console.error("Error loading b2b careers page:", error)
  }

  const content = pageData?.content as any || {}

  const heroTitle = isAr ? (content?.hero?.titleAr || "انضم لفريقنا") : (content?.hero?.titleEn || "Join Our Team");
  const heroSubtitle = isAr ? (content?.hero?.subtitleAr || "اصنع مستقبل الترفيه معنا.") : (content?.hero?.subtitleEn || "Build the future of entertainment with us.");
  const mediaType = content?.hero?.mediaType || "IMAGE";
  const mediaUrl = content?.hero?.mediaUrl || "";

  const bgMediaType = content?.background?.mediaType || "IMAGE";
  const bgMediaUrl = content?.background?.mediaUrl || "";

  const footerMediaType = content?.footer?.mediaType || "IMAGE";
  const footerMediaUrl = content?.footer?.mediaUrl || "";

  const jobs = Array.isArray(content.jobs) && content.jobs.length > 0 ? content.jobs : [
    {
      titleEn: "Senior Full Stack Engineer",
      titleAr: "مهندس برمجيات أول",
      department: "Engineering",
      location: "Doha, Qatar",
      type: "Full-time",
      applicationLink: "mailto:careers@e3.qa"
    },
    {
      titleEn: "Event Operations Manager",
      titleAr: "مدير عمليات الفعاليات",
      department: "Operations",
      location: "Doha, Qatar",
      type: "Full-time",
      applicationLink: "mailto:careers@e3.qa"
    }
  ]

  return (
    <div className="flex flex-col w-full min-h-screen bg-zinc-950 pt-20 relative" dir={isAr ? 'rtl' : 'ltr'}>
      
      {/* Background Media */}
      {bgMediaUrl && (
        <div className="fixed inset-0 z-0 pointer-events-none">
          <UniversalMediaRenderer src={bgMediaUrl} type={bgMediaType} className="w-full h-full object-cover opacity-20" />
          <div className="absolute inset-0 bg-zinc-950/50" />
        </div>
      )}

      {/* Hero Section */}
      <section className="relative w-full h-[60vh] min-h-[500px] flex items-center justify-center overflow-hidden z-10">
        {mediaUrl && (
          <div className="absolute inset-0 z-0">
            <UniversalMediaRenderer src={mediaUrl} type={mediaType} className="w-full h-full object-cover opacity-60" />
            <div className="absolute inset-0 bg-gradient-to-t from-zinc-950 via-zinc-950/50 to-transparent" />
          </div>
        )}
        <div className="relative z-10 text-center px-4 max-w-4xl mx-auto mt-20">
          <h1 className="text-5xl md:text-7xl font-bold text-white tracking-tight uppercase mb-6 drop-shadow-lg">
            {heroTitle}
          </h1>
          <p className="text-xl md:text-2xl text-zinc-300 max-w-2xl mx-auto drop-shadow-md font-light">
            {heroSubtitle}
          </p>
        </div>
      </section>

      {/* Open Roles Grid */}
      <section className="py-24 px-4 md:px-8 lg:px-16 max-w-7xl mx-auto w-full relative z-10">
        <div className="mb-12 flex items-center justify-between border-b border-zinc-800 pb-6">
          <h2 className="text-3xl font-bold text-white tracking-tight">
            {isAr ? "الوظائف المتاحة" : "Open Roles"}
          </h2>
          <span className="text-zinc-500 font-medium">{jobs.length} {isAr ? "وظيفة" : "Positions"}</span>
        </div>

        <CareerListings jobs={jobs} isAr={isAr} portal="B2B" />
      </section>

      {/* Footer Media */}
      {footerMediaUrl && (
        <section className="relative w-full h-[40vh] min-h-[300px] flex items-center justify-center overflow-hidden z-10 mt-12">
          <UniversalMediaRenderer src={footerMediaUrl} type={footerMediaType} className="w-full h-full object-cover opacity-80" />
          <div className="absolute inset-0 bg-gradient-to-t from-zinc-950 to-transparent" />
        </section>
      )}
      
    </div>
  )
}

import React from 'react'
import Link from 'next/link'
import { ArrowRight, Quote } from 'lucide-react'
import { notFound } from 'next/navigation'
import { UniversalMediaRenderer } from '@/components/shared/UniversalMediaRenderer'
import { db } from "@/lib/db"

export default async function CaseStudyPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params

  const project = await db.caseStudy.findUnique({
    where: { slug },
    include: {
      teamMembers: {
        include: {
          employeeProfile: true
        }
      },
      attraction: true
    }
  })

  if (!project || !project.isPublished) {
    notFound()
  }

  // Get next project for the footer
  const nextProject = await db.caseStudy.findFirst({
    where: { 
      isPublished: true,
      year: { lte: project.year || new Date().getFullYear() },
      id: { not: project.id }
    },
    orderBy: { year: 'desc' }
  }) || await db.caseStudy.findFirst({
    where: { 
      isPublished: true,
      id: { not: project.id }
    },
    orderBy: { year: 'desc' }
  })

  const metrics = Array.isArray(project.metrics) ? project.metrics as any[] : []
  const gallery = Array.isArray(project.gallery) ? project.gallery as any[] : []
  const testimonials = Array.isArray(project.testimonials) ? (project.testimonials as any[]).filter(t => t.isVisible !== false) : []

  return (
    <div className="flex flex-col w-full bg-zinc-950 min-h-screen">
      
      {/* 1. Immersive Hero */}
      <section className="relative min-h-[85vh] flex flex-col justify-end pb-16 pt-32 overflow-hidden">
        <div className="absolute inset-0 z-0">
          {project.heroImageUrl ? (
            <UniversalMediaRenderer 
              type={"IMAGE"} 
              src={project.heroImageUrl}
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="w-full h-full bg-zinc-900" />
          )}
          <div className="absolute inset-0 bg-zinc-950/60" />
          <div className="absolute inset-0 bg-gradient-to-t from-zinc-950 via-zinc-950/80 to-transparent" />
        </div>

        <div className="container relative z-10 mx-auto px-4 md:px-8">
          <div className="mb-8">
            <Link href="/b2b/case-studies" className="inline-flex items-center gap-2 text-sm font-bold text-zinc-400 hover:text-emerald-400 uppercase tracking-wider transition-colors">
              <ArrowRight className="w-4 h-4 rotate-180" /> All Case Studies
            </Link>
          </div>
          
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8">
            <div className="max-w-5xl">
              <h1 className="text-5xl md:text-7xl lg:text-8xl font-black text-zinc-100 tracking-tight mb-6 leading-[1.1]">
                {project.titleEn}
              </h1>
              {project.attraction && (
                <div className="inline-block px-4 py-2 bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 font-bold rounded-full text-sm uppercase tracking-widest backdrop-blur-sm">
                  Powered by {project.attraction.nameEn}
                </div>
              )}
            </div>
            
            {project.clientLogoUrl && (
              <div className="shrink-0 bg-zinc-900/50 backdrop-blur-md p-6 rounded-2xl border border-zinc-800/50 hidden md:block">
                <img src={project.clientLogoUrl} alt={project.clientName || "Client Logo"} className="h-16 w-auto object-contain" />
              </div>
            )}
          </div>
        </div>
      </section>

      {/* 2. Key Details Bar */}
      <section className="border-y border-zinc-800 bg-zinc-900/20 backdrop-blur-sm">
        <div className="container mx-auto px-4 md:px-8">
          <div className="grid grid-cols-2 md:grid-cols-4 py-8 gap-8">
            {project.clientName && (
              <div>
                <div className="text-xs text-zinc-500 uppercase tracking-widest font-bold mb-2">Client</div>
                <div className="text-zinc-100 font-bold text-lg">{project.clientName}</div>
              </div>
            )}
            {project.category && (
              <div>
                <div className="text-xs text-zinc-500 uppercase tracking-widest font-bold mb-2">Category</div>
                <div className="text-zinc-100 font-bold text-lg">{project.category}</div>
              </div>
            )}
            {project.year && (
              <div>
                <div className="text-xs text-zinc-500 uppercase tracking-widest font-bold mb-2">Year</div>
                <div className="text-zinc-100 font-bold text-lg">{project.year}</div>
              </div>
            )}
          </div>
        </div>
      </section>

      {/* 3. The Challenge / Solution */}
      <section className="py-24 md:py-32">
        <div className="container mx-auto px-4 md:px-8">
          <div className="max-w-5xl mx-auto space-y-24">
            
            {project.challengeEn && (
              <div className="grid md:grid-cols-12 gap-8 md:gap-16">
                <div className="md:col-span-5">
                  <h3 className="text-4xl md:text-5xl font-black text-zinc-100 tracking-tight sticky top-32 leading-tight">The<br/>Challenge</h3>
                </div>
                <div className="md:col-span-7">
                  <div className="text-xl md:text-2xl text-zinc-400 leading-relaxed whitespace-pre-wrap font-medium">
                    {project.challengeEn}
                  </div>
                </div>
              </div>
            )}
            
            {project.solutionEn && (
              <div className="grid md:grid-cols-12 gap-8 md:gap-16">
                <div className="md:col-span-5">
                  <h3 className="text-4xl md:text-5xl font-black text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-cyan-400 tracking-tight sticky top-32 leading-tight">The<br/>Solution</h3>
                </div>
                <div className="md:col-span-7">
                  <div className="text-xl md:text-2xl text-zinc-300 leading-relaxed font-medium whitespace-pre-wrap">
                    {project.solutionEn}
                  </div>
                </div>
              </div>
            )}
            
          </div>
        </div>
      </section>

      {/* 4. Bento Metrics */}
      {metrics.length > 0 && (
        <section className="py-24 bg-zinc-900/30 border-y border-zinc-800">
          <div className="container mx-auto px-4 md:px-8">
            <h3 className="text-3xl md:text-4xl font-black text-zinc-100 tracking-tight mb-12 text-center">Impact & Metrics</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 max-w-6xl mx-auto">
              {metrics.map((m: any, i: number) => {
                // Determine span based on index to create a bento look
                const isLarge = i === 0 && metrics.length % 2 !== 0;
                return (
                  <div key={i} className={`bg-zinc-900 border border-zinc-800 rounded-3xl p-8 md:p-12 flex flex-col justify-center items-center text-center group hover:border-emerald-500/50 transition-colors ${isLarge ? 'md:col-span-2 lg:col-span-3' : ''}`}>
                    <div className={`font-black text-zinc-100 tracking-tight mb-4 ${isLarge ? 'text-6xl md:text-8xl' : 'text-5xl md:text-6xl'} group-hover:scale-105 transition-transform duration-500`}>
                      {m.valueEn}
                    </div>
                    <div className="text-sm md:text-base text-zinc-500 font-bold uppercase tracking-widest">{m.labelEn}</div>
                  </div>
                )
              })}
            </div>
          </div>
        </section>
      )}

      {/* 5. Team & Testimonials Bento */}
      {(project.teamMembers.length > 0 || testimonials.length > 0) && (
        <section className="py-24 md:py-32">
          <div className="container mx-auto px-4 md:px-8">
            <div className="max-w-6xl mx-auto grid grid-cols-1 lg:grid-cols-2 gap-8">
              
              {/* Testimonials */}
              {testimonials.length > 0 && (
                <div className={`flex flex-col gap-6 ${project.teamMembers.length === 0 ? 'lg:col-span-2' : ''}`}>
                  <h3 className="text-2xl font-black text-zinc-100 tracking-tight mb-4">Client Feedback</h3>
                  {testimonials.map((t, i) => (
                    <div key={i} className="bg-gradient-to-br from-zinc-900 to-zinc-900/50 border border-zinc-800 rounded-3xl p-8 relative overflow-hidden flex-1 flex flex-col">
                      <Quote className="w-12 h-12 text-zinc-800 absolute top-6 end-6 -rotate-6" />
                      <div className="text-lg md:text-xl text-zinc-300 italic mb-8 relative z-10 flex-1">
                        &quot;{t.quoteEn}&quot;
                      </div>
                      <div className="text-zinc-500 font-bold uppercase tracking-widest text-sm relative z-10">
                        {t.authorName}
                      </div>
                    </div>
                  ))}
                </div>
              )}

              {/* Team Members */}
              {project.teamMembers.length > 0 && (
                <div className={`flex flex-col gap-6 ${testimonials.length === 0 ? 'lg:col-span-2' : ''}`}>
                  <h3 className="text-2xl font-black text-zinc-100 tracking-tight mb-4">Key Team</h3>
                  <div className="bg-zinc-900 border border-zinc-800 rounded-3xl p-8 flex-1">
                    <div className="flex flex-col gap-2">
                      {project.teamMembers.map((tm, i) => (
                        <div key={i} className="group relative py-4 border-b border-zinc-800/50 last:border-0 flex justify-between items-center cursor-default">
                          <div className="text-xl font-bold text-zinc-300 group-hover:text-zinc-100 transition-colors z-10 mix-blend-difference">
                            {tm.employeeProfile?.firstName} {tm.employeeProfile?.lastName}
                          </div>
                          <div className="text-zinc-500 uppercase tracking-widest text-xs font-bold z-10">
                            {tm.roleEn || tm.employeeProfile?.designation}
                          </div>
                          
                          {/* Hover Image Reveal */}
                          {tm.employeeProfile?.profileImage && (
                            <div className="absolute top-1/2 start-1/2 -translate-x-1/2 -translate-y-1/2 w-32 h-32 rounded-full overflow-hidden opacity-0 scale-50 group-hover:opacity-100 group-hover:scale-100 transition-all duration-300 pointer-events-none z-0 shadow-2xl">
                              <img src={tm.employeeProfile.profileImage} alt={tm.employeeProfile.firstName} className="w-full h-full object-cover" />
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              )}
              
            </div>
          </div>
        </section>
      )}

      {/* 6. Gallery Bento */}
      {gallery.length > 0 && (
        <section className="py-24 bg-zinc-900/30 border-t border-zinc-800">
          <div className="container mx-auto px-4 md:px-8">
            <h2 className="text-3xl md:text-4xl font-black text-zinc-100 tracking-tight mb-12 text-center">Project Gallery</h2>
            
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 md:gap-6 max-w-7xl mx-auto auto-rows-[250px] md:auto-rows-[300px]">
              {gallery.map((img: any, i: number) => {
                // Determine bento size based on index pattern
                const isLarge = i % 5 === 0;
                const isTall = i % 5 === 2;
                const isWide = i % 5 === 3;
                
                let spanClasses = "col-span-2 md:col-span-1 row-span-1";
                if (isLarge) spanClasses = "col-span-2 md:col-span-2 row-span-1 md:row-span-2";
                else if (isTall) spanClasses = "col-span-2 md:col-span-1 row-span-1 md:row-span-2";
                else if (isWide) spanClasses = "col-span-2 md:col-span-2 row-span-1";

                return (
                  <div key={i} className={`bg-zinc-950 rounded-3xl border border-zinc-800 overflow-hidden relative group ${spanClasses}`}>
                    <UniversalMediaRenderer 
                      type={"IMAGE"} 
                      src={img.url}
                      className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700"
                    />
                    {img.captionEn && (
                      <div className="absolute inset-0 bg-gradient-to-t from-zinc-950/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-end p-6 md:p-8">
                        <div className="text-zinc-100 font-bold">{img.captionEn}</div>
                      </div>
                    )}
                  </div>
                )
              })}
            </div>
          </div>
        </section>
      )}

      {/* 7. Next Project */}
      {nextProject && (
        <section className="py-32 bg-emerald-500 text-zinc-950 text-center">
          <div className="container mx-auto px-4">
            <div className="text-sm font-bold uppercase tracking-widest mb-6 opacity-80">Next Project</div>
            <Link href={`/b2b/case-studies/${nextProject.slug}`} className="group inline-flex flex-col md:flex-row items-center gap-4 text-4xl md:text-7xl font-black tracking-tight">
              <span className="group-hover:me-4 transition-all">{nextProject.titleEn}</span>
              <ArrowRight className="w-10 h-10 md:w-16 md:h-16 opacity-0 group-hover:opacity-100 transition-all -translate-x-8 group-hover:translate-x-0 rtl:-scale-x-100" />
            </Link>
          </div>
        </section>
      )}

    </div>
  )
}

import React from 'react'
import Link from 'next/link'
import { Filter } from 'lucide-react'
import { db } from "@/lib/db"
import { UniversalMediaRenderer } from '@/components/shared/UniversalMediaRenderer'
import { MediaRenderer } from "@/components/ui/MediaRenderer"

export const metadata = {
  title: 'Case Studies & Featured Work - E3 Corporate',
  description: 'Explore our portfolio of mega events, immersive installations, and entertainment destinations delivered across the Middle East.',
}

export const dynamic = 'force-dynamic'

export default async function CaseStudiesIndexPage({ params }: { params: Promise<{ locale: string }> }) {
  const { locale } = await params;
  const isAr = locale === 'ar';
  let caseStudies: any[] = []
  let pageData: any = null
  
  try {
    const results = await Promise.all([
      db.caseStudy.findMany({
        where: { isPublished: true },
        orderBy: { year: 'desc' }
      }),
      db.pages.findUnique({
        where: { slug: 'b2b-cases' }
      })
    ])
    caseStudies = results[0]
    pageData = results[1]
  } catch (error) {
    console.error("Error fetching b2b case studies:", error)
  }

  const content = pageData?.content as any || {}
  
  const hero = {
    title: isAr ? (content.hero?.titleAr || content.hero?.title || 'أعمال مميزة.') : (content.hero?.titleEn || content.hero?.title || "Featured Work."),
    subtitle: isAr ? (content.hero?.subtitleAr || content.hero?.subtitle || 'مجموعة مختارة من المشاريع البارزة التي توضح قدرتنا على هندسة وبناء وتشغيل التجارب على نطاق واسع.') : (content.hero?.subtitleEn || content.hero?.subtitle || "A selection of landmark projects demonstrating our capacity to engineer, build, and operate experiences at scale."),
    mediaType: content.hero?.mediaType || "IMAGE",
    mediaUrl: content.hero?.mediaUrl || ""
  }
  
  const cta = content?.cta ? {
    ...content.cta,
    title: isAr ? (content.cta.titleAr || content.cta.title) : (content.cta.titleEn || content.cta.title),
    description: isAr ? (content.cta.descriptionAr || content.cta.description) : (content.cta.descriptionEn || content.cta.description),
    primaryCta: isAr ? (content.cta.primaryCtaAr || content.cta.primaryCta) : (content.cta.primaryCtaEn || content.cta.primaryCta)
  } : null;

  const categories = isAr 
    ? ['الكل', 'فعالية كبرى', 'وجهات وتجارب', 'إنتاج حي', 'تقنيات غامرة', 'وجهات ترفيهية', 'ترفيه عائلي'] 
    : ['All', 'Mega Event', 'Attractions', 'Live Production', 'Immersive', 'Destination', 'Family Entertainment']

  return (
    <div className="flex flex-col w-full min-h-screen bg-zinc-950 pt-20" dir={isAr ? 'rtl' : 'ltr'}>
      
      {/* Header */}
      <section className="relative min-h-[60vh] flex items-center py-20 md:py-32 border-b border-zinc-900 overflow-hidden">
        <div className="absolute inset-0 z-0">
          {hero.mediaUrl ? (
            <UniversalMediaRenderer 
              type={hero.mediaType || "IMAGE"} 
              src={hero.mediaUrl}
              alt="Cases Hero Background"
            />
          ) : (
            <div className="w-full h-full bg-gradient-to-b from-emerald-500/5 to-transparent pointer-events-none" />
          )}
          {hero.mediaUrl && <div className="absolute inset-0 bg-zinc-950/80" />}
          {hero.mediaUrl && <div className="absolute inset-0 bg-gradient-to-r from-zinc-950 via-zinc-950/80 to-transparent" />}
        </div>
        
        <div className="container mx-auto px-4 md:px-8 relative z-10">
          <h1 className="text-5xl md:text-7xl font-black text-zinc-100 tracking-tight mb-6 max-w-4xl">
            {hero.title.split(' ').map((word: string, i: number, arr: string[]) => 
              i === arr.length - 1 ? <span key={i} className="text-emerald-400">{word}</span> : <span key={i}>{word} </span>
            )}
          </h1>
          <p className="text-xl text-zinc-400 max-w-2xl font-medium">
            {hero.subtitle}
          </p>
        </div>
      </section>

      {/* Filters & Grid */}
      <section className="py-12 md:py-20">
        <div className="container mx-auto px-4 md:px-8">
          
          {/* Filters */}
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12 opacity-50 pointer-events-none">
            <div className="flex items-center gap-4 overflow-x-auto pb-2 scrollbar-hide">
              <div className="flex items-center gap-2 text-zinc-500 font-bold uppercase tracking-wider text-xs me-4 shrink-0">
                <Filter className="w-4 h-4" /> Filter by
              </div>
              {categories.map((cat, i) => (
                <button 
                  key={cat}
                  className={`px-4 py-2 rounded-full border whitespace-nowrap text-sm font-bold transition-colors ${
                    i === 0 
                      ? 'bg-zinc-100 text-zinc-900 border-zinc-100' 
                      : 'bg-transparent text-zinc-400 border-zinc-800 hover:border-zinc-600'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>

          {/* Grid */}
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
            {caseStudies.map((project) => (
              <Link 
                key={project.id} 
                href={`/b2b/case-studies/${project.slug}`}
                className="group block"
              >
                <div className="relative aspect-[4/3] rounded-lg overflow-hidden bg-zinc-900 mb-6 border border-zinc-800 group-hover:border-emerald-500/50 transition-colors">
                  {project.heroImageUrl || project.thumbnailUrl ? (
                    <MediaRenderer 
                      url={project.heroImageUrl || project.thumbnailUrl} 
                      type={project.heroMediaType || project.thumbnailMediaType} 
                      alt={isAr ? project.titleAr : project.titleEn} 
                      className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" 
                    />
                  ) : (
                    <div className="absolute inset-0 flex items-center justify-center text-zinc-600 font-medium">
                      [Image: {isAr ? project.titleAr : project.titleEn}]
                    </div>
                  )}
                  <div className="absolute inset-0 bg-zinc-950/20 group-hover:bg-transparent transition-colors" />
                </div>
                
                <h3 className="text-2xl font-bold text-zinc-100 mb-2 group-hover:text-emerald-400 transition-colors">
                  {isAr ? project.titleAr : project.titleEn}
                </h3>
                
                <div className="flex flex-wrap items-center gap-x-4 gap-y-2 text-sm font-medium text-zinc-400">
                  {project.category && <span>{isAr ? (project as any).categoryAr || project.category : project.category}</span>}
                  {project.category && project.clientName && <span className="w-1 h-1 rounded-full bg-zinc-700" />}
                  {project.clientName && <span>{project.clientName}</span>}
                  
                  {Array.isArray(project.metrics) && project.metrics.length > 0 && (
                    <>
                      <span className="w-1 h-1 rounded-full bg-zinc-700 hidden md:block" />
                      <span className="text-emerald-400">{(project.metrics as any[])[0]?.value} {isAr ? (project.metrics as any[])[0]?.labelAr || (project.metrics as any[])[0]?.label : (project.metrics as any[])[0]?.label}</span>
                    </>
                  )}
                </div>
              </Link>
            ))}
          </div>

          {caseStudies.length === 0 && (
            <div className="text-center py-20 border border-zinc-800 rounded-xl bg-zinc-900/20">
              <p className="text-zinc-500 font-medium text-lg">Case studies list is being updated.</p>
            </div>
          )}

        </div>
      </section>

      {/* CTA */}
      {cta && cta.title && (
        <section className="py-24 border-t border-zinc-900 bg-zinc-950 relative overflow-hidden">
          <div className="absolute inset-0 z-0">
            {cta.mediaUrl ? (
              <UniversalMediaRenderer 
                type={cta.mediaType || "IMAGE"} 
                src={cta.mediaUrl}
                alt="CTA Background"
              />
            ) : (
              <div className="w-full h-full bg-gradient-to-b from-emerald-500/5 to-transparent pointer-events-none" />
            )}
            {cta.mediaUrl && <div className="absolute inset-0 bg-zinc-950/80" />}
          </div>

          <div className="container mx-auto px-4 md:px-8 text-center relative z-10">
            <h2 className="text-4xl md:text-5xl font-black text-zinc-100 mb-6">{cta.title}</h2>
            <p className="text-xl text-zinc-400 mb-10 max-w-2xl mx-auto">{cta.description}</p>
            <Link 
              href={cta.primaryLink || '/b2b/contact'}
              className="inline-flex items-center justify-center h-14 px-8 rounded-full bg-emerald-500 text-zinc-950 font-bold hover:bg-emerald-400 transition-colors"
            >
              {cta.primaryCta || 'Contact Us'}
            </Link>
          </div>
        </section>
      )}

    </div>
  )
}

import React from 'react'
import 'next/link'
import { db } from "@/lib/db"
import { UniversalMediaRenderer } from '@/components/shared/UniversalMediaRenderer'

export const metadata = {
  title: 'Clients & Partners - E3 Corporate',
  description: 'Organisations, brands, and government entities that trust E3 to deliver their most important experiences.',
}

export const dynamic = 'force-dynamic'

export default async function ClientsPage({ params }: { params: Promise<{ locale: string }> }) {
  const { locale } = await params;
  const isAr = locale === 'ar'
  
  let dbPartners: any[] = []
  let pageData: any = null

  try {
    const results = await Promise.all([
      db.partner.findMany({
        where: { isVisible: true },
        orderBy: [
          { orderIndex: 'asc' },
          { name: 'asc' }
        ]
      }),
      db.pages.findUnique({
        where: { slug: 'b2b-partners' }
      })
    ])
    dbPartners = results[0]
    pageData = results[1]
  } catch (error) {
    console.error("Error fetching b2b partners data:", error)
  }

  const content = pageData?.content as any || {}
  const hero = content?.hero || {
    titleEn: "Trusted by the Best.",
    titleAr: "يحظى بثقة الأفضل.",
    subtitleEn: "We partner with ambitious government entities, global brands, and premier destinations to deliver experiences that matter.",
    subtitleAr: "نحن نتشارك مع هيئات حكومية طموحة، وعلامات تجارية عالمية، ووجهات رائدة لتقديم تجارب تهم.",
    mediaType: "IMAGE",
    mediaUrl: ""
  }

  const heroTitle = isAr ? hero.titleAr : hero.titleEn;
  const heroSubtitle = isAr ? hero.subtitleAr : hero.subtitleEn;

  // Group by category
  const categoriesMap = {
    'GOVERNMENT': { nameEn: 'Government & Tourism', nameAr: 'الجهات الحكومية والسياحة', clients: [] as any[] },
    'CORPORATE': { nameEn: 'Corporate & Brands', nameAr: 'الشركات والعلامات التجارية', clients: [] as any[] },
    'VENUE': { nameEn: 'Venues & Destinations', nameAr: 'الوجهات والمواقع', clients: [] as any[] },
    'AGENCY': { nameEn: 'Agencies', nameAr: 'الوكالات', clients: [] as any[] },
    'TECHNOLOGY': { nameEn: 'Technology', nameAr: 'التكنولوجيا', clients: [] as any[] },
    'OTHER': { nameEn: 'Other', nameAr: 'أخرى', clients: [] as any[] },
  }

  dbPartners.forEach(p => {
    if (categoriesMap[p.category as keyof typeof categoriesMap]) {
      categoriesMap[p.category as keyof typeof categoriesMap].clients.push(p)
    }
  })

  const categories = Object.values(categoriesMap).filter(c => c.clients.length > 0)

  const testimonials = [
    {
      quote: isAr ? "لقد أوفت E3 بوعدها في وقت زمني قياسي. قدرتهم على حشد الموارد، وهندسة الهياكل الآمنة، والعمل بسلاسة على نطاق واسع لا مثيل لها في المنطقة." : "E3 delivered on an impossible timeline. Their ability to marshal resources, engineer safe structures, and operate smoothly at scale is unmatched in the region.",
      author: isAr ? "حسن الإبراهيم" : "Hassan Al Ibrahim",
      title: isAr ? "مدير الفعاليات" : "Director of Events",
      company: isAr ? "قطر للسياحة" : "Qatar Tourism"
    },
    {
      quote: isAr ? "كانت قبة XR درسًا متقدمًا في سرد القصص الغامرة. تنفيذ لا تشوبه شائبة من الفكرة إلى التسليم النهائي." : "The XR Dome was a masterclass in immersive storytelling. Flawless execution from concept to final delivery.",
      author: isAr ? "سارة آل ثاني" : "Sarah Al-Thani",
      title: isAr ? "المدير الإبداعي" : "Creative Director",
      company: isAr ? "مشيرب العقارية" : "Msheireb Properties"
    }
  ]

  return (
    <div className="flex flex-col w-full min-h-screen bg-zinc-950 pt-20" dir={isAr ? 'rtl' : 'ltr'}>
      
      {/* Header */}
      <section className="relative min-h-[60vh] flex items-center py-20 md:py-32 border-b border-zinc-900 overflow-hidden">
        <div className="absolute inset-0 z-0">
          {hero.mediaUrl ? (
            <UniversalMediaRenderer 
              type={hero.mediaType || "IMAGE"} 
              src={hero.mediaUrl}
              alt="Clients Hero Background"
            />
          ) : (
            <div className="w-full h-full bg-gradient-to-b from-emerald-500/5 to-transparent pointer-events-none" />
          )}
          {hero.mediaUrl && <div className="absolute inset-0 bg-zinc-950/80" />}
          {hero.mediaUrl && <div className="absolute inset-0 bg-gradient-to-r from-zinc-950 via-zinc-950/80 to-transparent" />}
        </div>
        
        <div className="container mx-auto px-4 md:px-8 relative z-10">
          <h1 className="text-5xl md:text-7xl font-black text-zinc-100 tracking-tight mb-6 max-w-4xl">
            {heroTitle.split(' ').map((word: string, i: number, arr: string[]) => 
              i === arr.length - 1 ? <span key={i} className="text-emerald-400">{word}</span> : <span key={i}>{word} </span>
            )}
          </h1>
          <p className="text-xl text-zinc-400 max-w-2xl font-medium">
            {heroSubtitle}
          </p>
        </div>
      </section>

      {/* Clients Grid */}
      <section className="py-24">
        <div className="container mx-auto px-4 md:px-8 space-y-24">
          
          {categories.length === 0 ? (
            <div className="text-center py-12 border border-zinc-800 rounded-xl bg-zinc-900/20">
              <p className="text-zinc-500 font-medium">Partners list is being updated.</p>
            </div>
          ) : categories.map((category, i) => (
            <div key={i}>
              <h2 className="text-2xl font-black text-zinc-100 tracking-tight mb-8 flex items-center gap-4">
                {isAr ? category.nameAr : category.nameEn}
                <div className="h-px flex-1 bg-zinc-900" />
              </h2>
              
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {category.clients.map((client, j) => (
                  <div 
                    key={client.id || j}
                    className="aspect-[3/2] rounded-lg bg-zinc-900 border border-zinc-800 flex items-center justify-center p-8 hover:bg-zinc-800 hover:border-emerald-500/50 transition-colors group cursor-default relative overflow-hidden"
                  >
                    {client.logoUrl ? (
                      <img 
                        src={client.logoUrl} 
                        alt={client.name} 
                        className="max-w-[80%] max-h-[80%] object-contain grayscale opacity-60 group-hover:grayscale-0 group-hover:opacity-100 transition-all duration-300 relative z-10" 
                      />
                    ) : (
                      <div className="text-zinc-500 font-bold text-center group-hover:text-zinc-300 transition-colors relative z-10">
                        {client.name}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          ))}

        </div>
      </section>

      {/* Testimonials */}
      <section className="py-24 bg-zinc-900 border-t border-zinc-800">
        <div className="container mx-auto px-4 md:px-8">
          <h2 className="text-4xl font-black text-zinc-100 tracking-tight mb-16 text-center">{isAr ? "ماذا يقولون عنا" : "What They Say"}</h2>
          
