    </div>
  )
}

"use client"

import React, { useState, useEffect } from 'react'
import { CheckCircle2, ArrowRight } from 'lucide-react'
import { useB2BRFP } from '@/store/b2b-store'
import { useParams } from 'next/navigation'
import { UniversalMediaRenderer } from '@/components/shared/UniversalMediaRenderer'
import Link from 'next/link'

export default function ContactRFPPage() {
  const { inquiryType, setInquiryType } = useB2BRFP()
  const [submitted, setSubmitted] = useState(false)
  const [cmsData, setCmsData] = useState<any>({})
  
  const params = useParams()
  const locale = params?.locale as string || 'en'
  const isAr = locale === 'ar'

  useEffect(() => {
    fetch('/api/cms/pages/b2b-contact')
      .then(res => res.json())
      .then(json => {
        if (json && json.data && json.data.content) {
          setCmsData(json.data.content)
        } else if (json && json.content) {
          setCmsData(json.content)
        }
      })
      .catch(console.error)
  }, [])

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault()
    
    const formData = new FormData(e.currentTarget)
    const data = {
      name: formData.get("name"),
      company: formData.get("company"),
      email: formData.get("email"),
      phone: formData.get("phone"),
      interestServices: [inquiryType],
      notes: formData.get("notes"),
    }

    try {
      const res = await fetch("/api/crm/leads/ingest", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data)
      })

      if (res.ok) {
        setSubmitted(true)
      } else {
        alert(isAr ? 'عذرًا، حدث خطأ أثناء إرسال طلبك. يرجى المحاولة لاحقًا.' : 'Sorry, there was an error submitting your request. Please try again later.')
      }
    } catch (err) {
      console.error(err)
      alert(isAr ? 'خطأ في الاتصال بالخادم.' : 'Error connecting to the server.')
    }
  }

  const headerTitle = isAr 
    ? (cmsData?.header?.titleAr || cmsData?.header?.titleEn || 'تواصل معنا / تقديم طلب عروض') 
    : (cmsData?.header?.titleEn || 'Contact Us / Submit RFP');
  const headerSubtitle = isAr 
    ? (cmsData?.header?.subtitleAr || cmsData?.header?.subtitleEn || 'هل لديك مشروع أو فعاليات كبرى تخطط لها؟ دعنا نساعدك في بناء خطة تنفيذ ناجحة.') 
    : (cmsData?.header?.subtitleEn || 'Planning a major event, venue, or activation? Let us help you engineer a successful delivery plan.');
  
  const businessEmail = cmsData?.inquiries?.business;
  const careersEmail = cmsData?.inquiries?.careers;
  const phone = cmsData?.inquiries?.phone;

  const hqAddress = isAr ? cmsData?.headquarters?.addressAr : cmsData?.headquarters?.addressEn;

  const careersCtaTitle = isAr ? (cmsData?.careersCta?.titleAr || "انضم لفريقنا") : (cmsData?.careersCta?.titleEn || "Join Our Team");
  const careersCtaDesc = isAr ? (cmsData?.careersCta?.descriptionAr || "اكتشف فرصاً جديدة لبناء تجارب استثنائية.") : (cmsData?.careersCta?.descriptionEn || "Discover new opportunities to build extraordinary experiences.");
  const careersCtaText = isAr ? (cmsData?.careersCta?.ctaTextAr || "استكشف الوظائف") : (cmsData?.careersCta?.ctaTextEn || "Explore Careers");

  const feedbackCtaTitle = isAr ? (cmsData?.feedbackCta?.titleAr || "اقتراحات وملاحظات") : (cmsData?.feedbackCta?.titleEn || "Suggestions & Feedback");
  const feedbackCtaDesc = isAr ? (cmsData?.feedbackCta?.descriptionAr || "ساعدنا في التحسين من خلال مشاركة أفكارك.") : (cmsData?.feedbackCta?.descriptionEn || "Help us improve by sharing your thoughts.");
  const feedbackCtaText = isAr ? (cmsData?.feedbackCta?.ctaTextAr || "شارك الملاحظات") : (cmsData?.feedbackCta?.ctaTextEn || "Share Feedback");

  const faqCtaTitle = isAr ? (cmsData?.faqCta?.titleAr || "الأسئلة الشائعة") : (cmsData?.faqCta?.titleEn || "B2B FAQs");
  const faqCtaDesc = isAr ? (cmsData?.faqCta?.descriptionAr || "ابحث عن إجابات للأسئلة الشائعة حول خدماتنا وعملياتنا.") : (cmsData?.faqCta?.descriptionEn || "Find answers to commonly asked questions about our services and processes.");
  const faqCtaText = isAr ? (cmsData?.faqCta?.ctaTextAr || "عرض الأسئلة") : (cmsData?.faqCta?.ctaTextEn || "View FAQs");

  return (
    <div className="flex flex-col w-full min-h-screen bg-zinc-950 pt-20" dir={isAr ? 'rtl' : 'ltr'}>
      
      {/* Header */}
      <section className="relative py-32 border-b border-zinc-900 overflow-hidden">
        {cmsData?.header?.mediaUrl && (
          <div className="absolute inset-0 z-0">
            <UniversalMediaRenderer 
              src={cmsData.header.mediaUrl}
              type={cmsData.header.mediaType || "IMAGE"}
              alt="B2B Contact Header"
              className="w-full h-full object-cover opacity-30"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-zinc-950 via-zinc-950/80 to-transparent" />
          </div>
        )}
        <div className="container mx-auto px-4 md:px-8 relative z-10">
          <h1 className="text-5xl md:text-7xl font-black text-zinc-100 tracking-tight mb-6">
            {headerTitle}
          </h1>
          <p className="text-xl text-zinc-400 max-w-2xl font-medium">
            {headerSubtitle}
          </p>
        </div>
      </section>

      {/* Form Section */}
      <section className="py-24">
        <div className="container mx-auto px-4 md:px-8">
          <div className="grid md:grid-cols-12 gap-16">
            
            {/* Left Column - Contact Info */}
            <div className="md:col-span-5 space-y-12">
              {(businessEmail || careersEmail || phone) && (
                <div>
                  <h3 className="text-2xl font-bold text-zinc-100 mb-6 tracking-tight">{isAr ? 'استفسارات مباشرة' : 'Direct Inquiries'}</h3>
                  <ul className="space-y-6">
                    {businessEmail && (
                      <li>
                        <div className="text-sm font-bold text-zinc-500 uppercase tracking-widest mb-1">{isAr ? 'تطوير الأعمال' : 'Business Development'}</div>
                        <a href={`mailto:${businessEmail}`} className="text-xl font-medium text-emerald-400 hover:text-emerald-300 transition-colors">{businessEmail}</a>
                      </li>
                    )}
                    {careersEmail && (
                      <li>
                        <div className="text-sm font-bold text-zinc-500 uppercase tracking-widest mb-1">{isAr ? 'الوظائف والمواهب' : 'Careers & Talent'}</div>
                        <a href={`mailto:${careersEmail}`} className="text-xl font-medium text-zinc-300 hover:text-zinc-100 transition-colors">{careersEmail}</a>
                      </li>
                    )}
                    {phone && (
                      <li>
                        <div className="text-sm font-bold text-zinc-500 uppercase tracking-widest mb-1">{isAr ? 'الهاتف' : 'Phone'}</div>
                        <a href={`tel:${phone}`} className="text-xl font-medium text-zinc-300 hover:text-zinc-100 transition-colors">{phone}</a>
                      </li>
                    )}
                  </ul>
                </div>
              )}

              {hqAddress && (
                <div>
                  <h3 className="text-2xl font-bold text-zinc-100 mb-6 tracking-tight">{isAr ? 'المقر الرئيسي' : 'Headquarters'}</h3>
                  <div className="text-lg text-zinc-400 leading-relaxed whitespace-pre-wrap">
                    {hqAddress}
                  </div>
                </div>
              )}
            </div>

            {/* Right Column - Form */}
            <div className="md:col-span-7">
              {submitted ? (
                <div className="p-12 rounded-xl bg-zinc-900 border border-emerald-500/50 text-center">
                  <div className="w-20 h-20 bg-emerald-500/20 rounded-full flex items-center justify-center mx-auto mb-6">
                    <CheckCircle2 className="w-10 h-10 text-emerald-500" />
                  </div>
                  <h3 className="text-3xl font-black text-zinc-100 tracking-tight mb-4">{isAr ? 'تم استلام الطلب' : 'Request Received'}</h3>
                  <p className="text-zinc-400 text-lg mb-8">
                    {isAr ? 'سيقوم فريقنا بمراجعة استفسارك والتواصل معك خلال 24 ساعة.' : 'Our team will review your inquiry and connect with you within 24 hours.'}
                  </p>
                  <button 
                    onClick={() => setSubmitted(false)}
                    className="px-6 py-3 rounded-sm border border-zinc-700 text-zinc-300 font-bold hover:bg-zinc-800 transition-colors"
                  >
                    {isAr ? 'إرسال استفسار آخر' : 'Submit Another Inquiry'}
                  </button>
                </div>
              ) : (
                <form onSubmit={handleSubmit} className="space-y-8 p-10 rounded-xl bg-zinc-900/50 border border-zinc-800">
                  
                  {/* Inquiry Type */}
                  <div className="space-y-4">
                    <label className="text-sm font-bold text-zinc-500 uppercase tracking-widest">{isAr ? 'نوع الاستفسار' : 'Inquiry Type'}</label>
                    <div className="flex flex-wrap gap-4">
                      {(isAr ? ['تقديم طلب عروض', 'أعمال عامة', 'شراكة', 'أخرى'] : ['RFP Submission', 'General Business', 'Partnership', 'Other']).map(type => (
                        <label 
                          key={type} 
                          className={`px-5 py-3 rounded-sm border cursor-pointer font-bold text-sm transition-colors ${
                            inquiryType === type 
                              ? 'border-emerald-500 bg-emerald-500/10 text-emerald-400'
                              : 'border-zinc-700 bg-zinc-950 text-zinc-400 hover:border-zinc-500'
                          }`}
                        >
                          <input 
                            type="radio" 
                            name="type" 
                            value={type}
                            className="hidden"
                            checked={inquiryType === type}
                            onChange={(e) => setInquiryType(e.target.value)}
                          />
                          {type}
                        </label>
                      ))}
                    </div>
                  </div>

                  {/* Contact Info */}
                  <div className="grid md:grid-cols-2 gap-6">
                    <div className="space-y-2">
                      <label className="text-sm font-bold text-zinc-400">{isAr ? 'الاسم الكامل' : 'Full Name'}</label>
                      <input 
                        required
                        name="name"
                        type="text" 
                        className="w-full bg-zinc-950 border border-zinc-800 rounded-sm px-4 py-3 text-zinc-100 focus:outline-none focus:border-emerald-500 transition-colors"
                        placeholder={isAr ? 'فلان الفلاني' : 'Jane Doe'}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-sm font-bold text-zinc-400">{isAr ? 'الشركة' : 'Company'}</label>
                      <input 
                        required
                        name="company"
                        type="text" 
                        className="w-full bg-zinc-950 border border-zinc-800 rounded-sm px-4 py-3 text-zinc-100 focus:outline-none focus:border-emerald-500 transition-colors"
                        placeholder={isAr ? 'اسم المنظمة' : 'Organization Name'}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-sm font-bold text-zinc-400">{isAr ? 'البريد الإلكتروني' : 'Email Address'}</label>
                      <input 
                        required
                        name="email"
                        type="email" 
                        className="w-full bg-zinc-950 border border-zinc-800 rounded-sm px-4 py-3 text-zinc-100 focus:outline-none focus:border-emerald-500 transition-colors"
                        placeholder={isAr ? 'name@company.com' : 'jane@company.com'}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-sm font-bold text-zinc-400">{isAr ? 'رقم الهاتف' : 'Phone Number'}</label>
                      <input 
                        type="tel" 
                        name="phone"
                        className="w-full bg-zinc-950 border border-zinc-800 rounded-sm px-4 py-3 text-zinc-100 focus:outline-none focus:border-emerald-500 transition-colors"
                        placeholder="+974 XXXX XXXX"
                      />
                    </div>
                  </div>

                  {/* Message */}
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-zinc-400">{isAr ? 'تفاصيل المشروع أو الرسالة' : 'Project Details or Message'}</label>
                    <textarea 
                      required
                      name="notes"
                      rows={5}
                      className="w-full bg-zinc-950 border border-zinc-800 rounded-sm px-4 py-3 text-zinc-100 focus:outline-none focus:border-emerald-500 transition-colors resize-none"
                      placeholder={isAr ? 'أخبرنا عن متطلباتك والجدول الزمني والنطاق...' : 'Tell us about your requirements, timeline, and scale...'}
                    />
                  </div>

                  {/* File Upload (Mock) */}
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-zinc-400">{isAr ? 'المرفقات (اختياري)' : 'Attachments (Optional)'}</label>
                    <div className="w-full border-2 border-dashed border-zinc-800 rounded-sm p-8 text-center hover:border-zinc-600 transition-colors cursor-pointer bg-zinc-950">
                      <p className="text-sm text-zinc-500 font-medium">{isAr ? 'اسحب وأفلت مستندات هنا، أو انقر للتصفح' : 'Drag & drop RFP documents here, or click to browse'}</p>
                      <p className="text-xs text-zinc-600 mt-2">PDF, DOCX, ZIP up to 50MB</p>
                    </div>
                  </div>

                  {/* Submit */}
                  <button 
                    type="submit"
                    className="w-full py-4 bg-emerald-500 text-zinc-950 font-bold text-lg rounded-sm hover:bg-emerald-400 transition-colors flex items-center justify-center gap-2"
                  >
                    {isAr ? 'إرسال الاستفسار' : 'Submit Inquiry'} <ArrowRight className={`w-5 h-5 ${isAr ? 'rotate-180' : ''}`} />
                  </button>

                  <p className="text-xs text-zinc-600 text-center max-w-sm mx-auto">
                    {isAr ? 'من خلال إرسال هذا النموذج، فإنك توافق على سياسة الخصوصية الخاصة بنا وتوافق على تخزين بياناتك لمعالجة هذا الاستفسار.' : 'By submitting this form, you agree to our Privacy Policy and consent to us storing your data to process this inquiry.'}
                  </p>
                </form>
              )}
            </div>

          </div>
        </div>
      </section>

      {/* CTA Bento Grid */}
      {(careersCtaTitle || feedbackCtaTitle || faqCtaTitle) && (
        <section className="py-24 border-t border-zinc-900 bg-zinc-950">
          <div className="container mx-auto px-4 md:px-8">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              
              {/* Careers CTA */}
              {careersCtaTitle && (
                <div className="relative group overflow-hidden rounded-2xl aspect-square md:aspect-auto md:h-[400px] flex flex-col justify-end p-8 border border-zinc-800/50">
                  {cmsData?.careersCta?.mediaUrl && (
                    <div className="absolute inset-0 z-0">
                      <UniversalMediaRenderer 
                        src={cmsData.careersCta.mediaUrl}
                        type={cmsData.careersCta.mediaType || "IMAGE"}
                        alt="Careers Background"
                        className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
                      />
                    </div>
                  )}
                  {/* Glassmorphism overlay */}
                  <div className="absolute inset-0 z-10 bg-gradient-to-t from-zinc-950/90 via-zinc-950/40 to-transparent pointer-events-none" />
                  <div className="absolute inset-0 z-10 bg-zinc-950/20 backdrop-blur-[2px] group-hover:backdrop-blur-0 transition-all duration-500 pointer-events-none" />
                  
                  <div className="relative z-20 mt-auto transform translate-y-4 group-hover:translate-y-0 transition-transform duration-500">
                    <h3 className="text-2xl font-black text-white mb-2">{careersCtaTitle}</h3>
                    <p className="text-zinc-300 font-medium mb-6 opacity-0 group-hover:opacity-100 transition-opacity duration-500 delay-100">
                      {careersCtaDesc}
                    </p>
                    <Link 
                      href={`/${locale}/b2b/careers`} 
                      className="inline-flex items-center gap-2 text-sm font-bold text-white bg-white/10 hover:bg-white/20 px-4 py-2 rounded-full backdrop-blur-md transition-colors"
                    >
                      {careersCtaText} <ArrowRight className={`w-4 h-4 ${isAr ? 'rotate-180' : ''}`} />
                    </Link>
                  </div>
                </div>
              )}

              {/* Feedback CTA */}
              {feedbackCtaTitle && (
                <div className="relative group overflow-hidden rounded-2xl aspect-square md:aspect-auto md:h-[400px] flex flex-col justify-end p-8 border border-zinc-800/50">
                  {cmsData?.feedbackCta?.mediaUrl && (
                    <div className="absolute inset-0 z-0">
                      <UniversalMediaRenderer 
                        src={cmsData.feedbackCta.mediaUrl}
                        type={cmsData.feedbackCta.mediaType || "IMAGE"}
                        alt="Feedback Background"
                        className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
                      />
                    </div>
                  )}
                  {/* Glassmorphism overlay */}
                  <div className="absolute inset-0 z-10 bg-gradient-to-t from-zinc-950/90 via-zinc-950/40 to-transparent pointer-events-none" />
                  <div className="absolute inset-0 z-10 bg-zinc-950/20 backdrop-blur-[2px] group-hover:backdrop-blur-0 transition-all duration-500 pointer-events-none" />
                  
                  <div className="relative z-20 mt-auto transform translate-y-4 group-hover:translate-y-0 transition-transform duration-500">
                    <h3 className="text-2xl font-black text-white mb-2">{feedbackCtaTitle}</h3>
                    <p className="text-zinc-300 font-medium mb-6 opacity-0 group-hover:opacity-100 transition-opacity duration-500 delay-100">
                      {feedbackCtaDesc}
                    </p>
                    <Link 
                      href={`/${locale}/b2b/feedback`} 
                      className="inline-flex items-center gap-2 text-sm font-bold text-white bg-white/10 hover:bg-white/20 px-4 py-2 rounded-full backdrop-blur-md transition-colors"
                    >
                      {feedbackCtaText} <ArrowRight className={`w-4 h-4 ${isAr ? 'rotate-180' : ''}`} />
                    </Link>
                  </div>
                </div>
              )}

              {/* FAQ CTA */}
              {faqCtaTitle && (
                <div className="relative group overflow-hidden rounded-2xl aspect-square md:aspect-auto md:h-[400px] flex flex-col justify-end p-8 border border-zinc-800/50">
                  {cmsData?.faqCta?.mediaUrl && (
                    <div className="absolute inset-0 z-0">
                      <UniversalMediaRenderer 
                        src={cmsData.faqCta.mediaUrl}
                        type={cmsData.faqCta.mediaType || "IMAGE"}
                        alt="FAQ Background"
                        className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
                      />
                    </div>
                  )}
                  {/* Glassmorphism overlay */}
                  <div className="absolute inset-0 z-10 bg-gradient-to-t from-zinc-950/90 via-zinc-950/40 to-transparent pointer-events-none" />
                  <div className="absolute inset-0 z-10 bg-zinc-950/20 backdrop-blur-[2px] group-hover:backdrop-blur-0 transition-all duration-500 pointer-events-none" />
                  
                  <div className="relative z-20 mt-auto transform translate-y-4 group-hover:translate-y-0 transition-transform duration-500">
                    <h3 className="text-2xl font-black text-white mb-2">{faqCtaTitle}</h3>
                    <p className="text-zinc-300 font-medium mb-6 opacity-0 group-hover:opacity-100 transition-opacity duration-500 delay-100">
                      {faqCtaDesc}
                    </p>
                    <Link 
                      href={cmsData?.faqCta?.ctaLink || '#'} 
                      className="inline-flex items-center gap-2 text-sm font-bold text-white bg-white/10 hover:bg-white/20 px-4 py-2 rounded-full backdrop-blur-md transition-colors"
                    >
                      {faqCtaText} <ArrowRight className={`w-4 h-4 ${isAr ? 'rotate-180' : ''}`} />
                    </Link>
                  </div>
                </div>
              )}

            </div>
          </div>
        </section>
      )}

    </div>
  )
}

import React from 'react'
import { db } from "@/lib/db"
import { UniversalMediaRenderer } from '@/components/shared/UniversalMediaRenderer'
import { Accordion, AccordionItem, AccordionTrigger, AccordionContent } from '@/components/ui/Accordion'

export const dynamic = 'force-dynamic'

export default async function B2BFAQsPage({ params }: { params: Promise<{ locale: string }> }) {
  const { locale } = await params;
  const isAr = locale === 'ar'

  let pageData: any = null
  try {
    pageData = await db.pages.findUnique({
      where: { slug: 'b2b-faqs' }
    })
  } catch (error) {
    console.error("Error loading b2b faqs page:", error)
  }

  const content = pageData?.content as any || {}

  const headerTitle = isAr ? (content?.header?.titleAr || "الأسئلة الشائعة") : (content?.header?.titleEn || "Frequently Asked Questions");
  const headerSubtitle = isAr ? (content?.header?.subtitleAr || "اعثر على إجابات للأسئلة المتداولة.") : (content?.header?.subtitleEn || "Find answers to commonly asked questions.");
  const mediaType = content?.header?.mediaType || "IMAGE";
  const mediaUrl = content?.header?.mediaUrl || "";

  const faqs = Array.isArray(content.items) && content.items.length > 0 ? content.items : [
    {
      questionEn: "How do I start a project with E3?",
      questionAr: "كيف أبدأ مشروعاً مع إي ثري؟",
      answerEn: "You can start by reaching out through our contact page or booking a consultation with our B2B team.",
      answerAr: "يمكنك البدء بالتواصل معنا عبر صفحة الاتصال أو حجز استشارة مع فريقنا للشركات."
    },
    {
      questionEn: "What industries do you serve?",
      questionAr: "ما هي القطاعات التي تخدمونها؟",
      answerEn: "We serve a wide range of industries including entertainment, corporate events, government sectors, and hospitality.",
      answerAr: "نحن نخدم مجموعة واسعة من القطاعات بما في ذلك الترفيه، فعاليات الشركات، القطاعات الحكومية، والضيافة."
    }
  ]

  return (
    <div className="flex flex-col w-full min-h-screen bg-zinc-950 pt-20" dir={isAr ? 'rtl' : 'ltr'}>
      
      {/* Header Section */}
      <section className="relative w-full h-[40vh] min-h-[400px] flex items-center justify-center overflow-hidden">
        {mediaUrl && (
          <div className="absolute inset-0 z-0">
            <UniversalMediaRenderer src={mediaUrl} type={mediaType} className="w-full h-full object-cover opacity-40" />
            <div className="absolute inset-0 bg-gradient-to-t from-zinc-950 via-zinc-950/80 to-transparent" />
          </div>
        )}
        <div className="relative z-10 text-center px-4 max-w-4xl mx-auto">
          <h1 className="text-4xl md:text-6xl font-bold text-white tracking-tight uppercase mb-6">
            {headerTitle}
          </h1>
          <p className="text-lg md:text-xl text-zinc-400 max-w-2xl mx-auto">
            {headerSubtitle}
          </p>
        </div>
      </section>

      {/* FAQs Section */}
      <section className="py-24 px-4 relative z-10">
        <div className="max-w-3xl mx-auto">
          <Accordion type="single" collapsible className="w-full space-y-4">
            {faqs.map((faq: any, index: number) => (
              <AccordionItem 
                key={index} 
                value={`faq-${index}`}
                className="bg-zinc-900/50 backdrop-blur-md border border-zinc-800/50 rounded-xl px-6"
              >
                <AccordionTrigger className="text-lg font-medium text-zinc-100 hover:text-white py-6">
                  {isAr ? faq.questionAr : faq.questionEn}
                </AccordionTrigger>
                <AccordionContent className="text-zinc-400 pb-6 leading-relaxed">
                  {isAr ? faq.answerAr : faq.answerEn}
                </AccordionContent>
              </AccordionItem>
            ))}
          </Accordion>
        </div>
      </section>
      
    </div>
  )
}

"use client"

import React, { useState, useEffect } from 'react'
import { useParams } from 'next/navigation'

import { Card } from '@/components/ui/Card'
import { Button } from '@/components/ui/Button'
import { Input } from '@/components/ui/Input'
import { Send, CheckCircle2 } from 'lucide-react'

export default function B2BFeedbackPage() {
  // We use "use client" because of the form interactivity and fetching
  const routeParams = useParams()
  const isAr = routeParams?.locale === 'ar'
  const [cmsData, setCmsData] = useState<any>({})
  const [submitted, setSubmitted] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    title: '', // Reusing company/title for title
    message: '',
    rating: 0
  })

  useEffect(() => {

    fetch('/api/cms/pages/b2b-feedback')
      .then(res => res.json())
      .then(json => {
        if (json && json.data && json.data.content) {
          setCmsData(json.data.content)
        } else if (json && json.content) {
          setCmsData(json.content)
        }
      })
      .catch(console.error)
  }, [])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsSubmitting(true)
    
    try {
      const res = await fetch('/api/b2b/feedback', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      })
      if (res.ok) {
        setSubmitted(true)
        setFormData({ name: '', email: '', title: '', message: '', rating: 0 })
      }
    } catch (e) {
      console.error(e)
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value })
  }

  const headerTitle = isAr ? (cmsData?.header?.titleAr || "الاقتراحات والملاحظات") : (cmsData?.header?.titleEn || "Suggestions & Feedback");
  const headerSubtitle = isAr ? (cmsData?.header?.subtitleAr || "نحن نقدر ملاحظاتك. يرجى مشاركة أفكارك معنا.") : (cmsData?.header?.subtitleEn || "We value your feedback. Please share your thoughts with us.");

  const successTitle = isAr ? (cmsData?.success?.titleAr || "شكراً لملاحظاتك!") : (cmsData?.success?.titleEn || "Thank you for your feedback!");
  const successMessage = isAr ? (cmsData?.success?.messageAr || "تم استلام رسالتك وسيتم مراجعتها من قبل فريقنا.") : (cmsData?.success?.messageEn || "Your submission has been received and will be reviewed by our team.");

  return (
    <div className="flex flex-col w-full min-h-screen bg-zinc-950 pt-32 pb-24" dir={isAr ? 'rtl' : 'ltr'}>
      
      <div className="max-w-3xl mx-auto w-full px-4">
        {/* Header Section */}
        <div className="text-center mb-16">
          <h1 className="text-4xl md:text-5xl font-bold text-white tracking-tight uppercase mb-6">
            {headerTitle}
          </h1>
          <p className="text-lg text-zinc-400">
            {headerSubtitle}
          </p>
        </div>

        {/* Form Section */}
        <Card className="bg-zinc-900/50 backdrop-blur-xl border-zinc-800/50 p-8 md:p-12 shadow-2xl">
          {submitted ? (
            <div className="flex flex-col items-center justify-center py-12 text-center space-y-6">
              <div className="w-20 h-20 bg-green-500/10 rounded-full flex items-center justify-center">
                <CheckCircle2 className="w-10 h-10 text-green-500" />
              </div>
              <h2 className="text-2xl font-bold text-white">{successTitle}</h2>
              <p className="text-zinc-400 max-w-md">{successMessage}</p>
              <Button 
                variant="outline" 
                onClick={() => setSubmitted(false)}
                className="mt-8 border-zinc-700 text-zinc-300 hover:text-white hover:bg-zinc-800"
              >
                {isAr ? "إرسال ملاحظة أخرى" : "Submit Another"}
              </Button>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-zinc-400 uppercase tracking-wider">
                    {isAr ? "الاسم" : "Name"}
                  </label>
                  <Input name="name" value={formData.name} onChange={handleChange} required placeholder={isAr ? "أدخل اسمك" : "Enter your name"} className="bg-zinc-950/50 border-zinc-800 text-white" />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-zinc-400 uppercase tracking-wider">
                    {isAr ? "البريد الإلكتروني" : "Email"}
                  </label>
                  <Input name="email" value={formData.email} onChange={handleChange} type="email" required placeholder={isAr ? "أدخل بريدك الإلكتروني" : "Enter your email"} className="bg-zinc-950/50 border-zinc-800 text-white" />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-zinc-400 uppercase tracking-wider">
                    {isAr ? "الموضوع أو العنوان" : "Subject / Title"}
                  </label>
                  <Input name="title" value={formData.title} onChange={handleChange} required placeholder={isAr ? "عنوان الرسالة" : "Message subject"} className="bg-zinc-950/50 border-zinc-800 text-white" />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-zinc-400 uppercase tracking-wider">
                    {isAr ? "نوع الملاحظة" : "Feedback Type"}
                  </label>
                  <select required className="flex h-10 w-full rounded-md border border-zinc-800 bg-zinc-950/50 px-3 py-2 text-sm text-white focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent">
                    <option value="" disabled selected>{isAr ? "اختر النوع" : "Select type"}</option>
                    <option value="suggestion">{isAr ? "اقتراح" : "Suggestion"}</option>
                    <option value="issue">{isAr ? "مشكلة" : "Report an Issue"}</option>
                    <option value="praise">{isAr ? "إشادة" : "Praise"}</option>
                    <option value="other">{isAr ? "أخرى" : "Other"}</option>
                  </select>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-bold text-zinc-400 uppercase tracking-wider">
                  {isAr ? "الرسالة" : "Message"}
                </label>
                <textarea 
                  required 
                  name="message"
                  value={formData.message}
                  onChange={handleChange}
                  rows={6}
                  placeholder={isAr ? "أخبرنا كيف يمكننا التحسين..." : "Tell us how we can improve..."}
                  className="flex w-full rounded-md border border-zinc-800 bg-zinc-950/50 px-3 py-2 text-sm text-white focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent resize-none"
                />
              </div>

              <Button type="submit" disabled={isSubmitting} className="w-full bg-white text-zinc-950 hover:bg-zinc-200">
                <Send className={`w-4 h-4 ${isAr ? 'ms-2' : 'me-2'}`} />
                {isSubmitting ? (isAr ? "جاري الإرسال..." : "Submitting...") : (isAr ? "إرسال الملاحظات" : "Submit Feedback")}
              </Button>
            </form>
          )}
        </Card>
      </div>
    </div>
  )
}

import React from 'react'
import Link from 'next/link'
import { UniversalMediaRenderer } from '@/components/shared/UniversalMediaRenderer'
import { ArrowRight, CheckCircle2 } from 'lucide-react'
import { cn } from '@/lib/utils'
import db from '@/lib/db'

export default async function B2BHomePage({ params }: { params: Promise<{ locale: string }> }) {
  const { locale } = await params;
  const isAr = locale === 'ar';

  // Fetch real data from the CMS safely
  let page: any = null
  try {
    page = await db.pages.findUnique({
      where: { slug: 'b2b-home' }
    })
  } catch (error) {
    console.error("Error loading b2b-home page:", error)
  }
  
  const content = (page?.content as any) || {}
  const hero = {
    title: isAr 
      ? (content.hero?.titleAr || content.hero?.title || "تحويل الأفكار إلى واقع") 
      : (content.hero?.titleEn || content.hero?.title || "Ideas to Life"),
    subtitle: isAr 
      ? (content.hero?.subtitleAr || content.hero?.subtitle || "نحن نصمم ونبني ونشغل ونوسع تجارب الترفيه الغامرة في جميع أنحاء قطر.") 
      : (content.hero?.subtitleEn || content.hero?.subtitle || "We design, build, operate, and scale immersive entertainment experiences across Qatar."),
    description: isAr 
      ? (content.hero?.descriptionAr || content.hero?.description || "من المفاهيم الإبداعية إلى تدفق الجماهير والتصنيع وإصدار التذاكر والتوظيف والعمليات المباشرة.") 
      : (content.hero?.descriptionEn || content.hero?.description || "From creative concepts to crowd flow, fabrication, ticketing, staffing, and live operations."),
    primaryCta: isAr 
      ? (content.hero?.primaryCtaAr || content.hero?.primaryCta || "استكشف الخدمات") 
      : (content.hero?.primaryCtaEn || content.hero?.primaryCta || "Explore Services"),
    primaryLink: content.hero?.primaryLink || `/${locale}/b2b/services`,
    secondaryCta: isAr 
      ? (content.hero?.secondaryCtaAr || content.hero?.secondaryCta || "ابدأ مشروعاً") 
      : (content.hero?.secondaryCtaEn || content.hero?.secondaryCta || "Start a Project"),
    secondaryLink: content.hero?.secondaryLink || `/${locale}/b2b/contact`,
    mediaType: content.hero?.mediaType || "IMAGE",
    mediaUrl: content.hero?.mediaUrl || ""
  }

  const stats = (content?.stats && content.stats.length > 0) 
    ? content.stats.map((s: any) => ({
        value: isAr ? (s.valueAr || s.value) : s.value,
        label: isAr ? (s.labelAr || s.label) : s.label
      }))
    : [
        { value: '50+', label: isAr ? 'سنوات من الخبرة المشتركة' : 'Years Combined Experience' },
        { value: '9+', label: isAr ? 'التخصصات الأساسية' : 'Core Specializations' },
        { value: '100%', label: isAr ? 'ملكية قطرية 100%' : 'Qatari Owned' },
        { value: '3+', label: isAr ? 'أسواق إقليمية' : 'Regional Markets' },
      ]

  const wowAndHow = {
    title: isAr 
      ? (content.wowAndHow?.titleAr || content.wowAndHow?.title || "الإبهاار والتنفيذ الاحترافي") 
      : (content.wowAndHow?.titleEn || content.wowAndHow?.title || "The WOW & The HOW"),
    description: isAr 
      ? (content.wowAndHow?.descriptionAr || content.wowAndHow?.description || "الأفكار الإبداعية تتطلب هندسة تشغيلية. نحن لا نصمم التجارب فحسب — بل نبنيها ونوظف طواقمها ونشغلها ونراقبها.") 
      : (content.wowAndHow?.descriptionEn || content.wowAndHow?.description || "Creative ideas need operational engineering. We don't just design experiences—we build, staff, operate, and monitor them."),
    wowBullets: isAr 
      ? (content.wowAndHow?.wowBulletsAr?.length > 0 ? content.wowAndHow.wowBulletsAr : ['المفاهيم الإبداعية', 'الترفيه الغامر', 'البيئات المنسقة', 'سرد القصص'])
      : (content.wowAndHow?.wowBullets || ['Creative concepts', 'Immersive entertainment', 'Themed environments', 'Storytelling']),
    howBullets: isAr 
      ? (content.wowAndHow?.howBulletsAr?.length > 0 ? content.wowAndHow.howBulletsAr : ['جدوى وسلامة المشاريع', 'التصنيع والإخراج المنصي', 'تدفق الجماهير والتوظيف', 'العمليات المباشرة والتذاكر'])
      : (content.wowAndHow?.howBullets || ['Feasibility & Safety', 'Fabrication & Staging', 'Crowd flow & Staffing', 'Live Operations & Ticketing'])
  }

  // Determine which Services to show
  const featuredServiceIds = content?.featuredServiceIds || []
  let dbServices: any[] = []
  try {
    if (featuredServiceIds.length > 0) {
      dbServices = await db.service.findMany({
        where: { id: { in: featuredServiceIds }, isVisible: true }
      })
      dbServices.sort((a, b) => featuredServiceIds.indexOf(a.id) - featuredServiceIds.indexOf(b.id))
    } else {
      dbServices = await db.service.findMany({
        where: { isVisible: true, isFeatured: true },
        orderBy: { createdAt: 'desc' },
        take: 4
      })
    }
  } catch (error) {
    console.error("Error loading services for B2B home:", error)
  }

  // Determine which Case Studies to show
  const featuredCaseStudyIds = content?.featuredCaseStudyIds || []
  let dbProjects: any[] = []
  try {
    if (featuredCaseStudyIds.length > 0) {
      dbProjects = await db.caseStudy.findMany({
        where: { id: { in: featuredCaseStudyIds }, isPublished: true }
      })
      dbProjects.sort((a, b) => featuredCaseStudyIds.indexOf(a.id) - featuredCaseStudyIds.indexOf(b.id))
    } else {
      dbProjects = await db.caseStudy.findMany({
        where: { isPublished: true },
        orderBy: { year: 'desc' },
        take: 3
      })
    }
  } catch (error) {
    console.error("Error loading case studies for B2B home:", error)
  }

  // Fetch Partners safely from DB
  let dbPartners: any[] = []
  try {
    dbPartners = await db.partner.findMany({
      where: { isVisible: true },
      orderBy: [
        { orderIndex: 'asc' },
        { createdAt: 'desc' }
      ]
    })
  } catch (error) {
    console.error("Error loading partners for B2B home:", error)
  }

  const partnersList = dbPartners.length > 0 ? dbPartners : [
    { id: '1', name: 'Visit Qatar', logoUrl: '' },
    { id: '2', name: 'Qatar Tourism', logoUrl: '' },
    { id: '3', name: 'Qatar Calendar', logoUrl: '' },
    { id: '4', name: 'UDC', logoUrl: '' },
    { id: '5', name: 'QNCC', logoUrl: '' },
    { id: '6', name: 'Doha Festival City', logoUrl: '' }
  ]

  return (
    <div className="flex flex-col w-full" dir={isAr ? 'rtl' : 'ltr'}>
      
      {/* 1. Hero: Ideas to Life */}
      <section className="relative min-h-[90vh] flex items-center justify-center overflow-hidden">
        <div className="absolute inset-0 z-0">
          <UniversalMediaRenderer 
            type={hero.mediaType || "IMAGE"} 
            src={hero.mediaUrl || (hero as any).backgroundImage || "/hero-b2b.jpg"}
            alt="Hero Background"
          />
          {/* Gradients to ensure text readability without purple/blue */}
          <div className="absolute inset-0 bg-zinc-950/70" />
          <div className="absolute inset-0 bg-gradient-to-b from-zinc-950/20 via-transparent to-zinc-950" />
          <div className="absolute inset-0 bg-[url('/noise.png')] opacity-20 mix-blend-overlay" />
        </div>

        <div className="container relative z-10 mx-auto px-4 md:px-8 pt-20">
          <div className="max-w-4xl">
            <h1 className="text-5xl md:text-7xl lg:text-8xl font-black text-zinc-100 tracking-tighter leading-[1.1] mb-6">
              {hero.title}
            </h1>
            <p className="text-xl md:text-2xl text-zinc-300 font-medium max-w-2xl mb-4">
              {hero.subtitle}
            </p>
            <p className="text-lg text-zinc-400 max-w-2xl mb-10">
              {hero.description}
            </p>
            
            <div className="flex flex-wrap items-center gap-4">
              {hero.primaryCta && (
                <Link 
                  href={hero.primaryLink || `/${locale}/b2b/services`} 
                  className="px-8 py-4 bg-emerald-500 text-zinc-950 font-bold text-lg rounded-sm hover:bg-emerald-400 transition-colors"
                >
                  {hero.primaryCta}
                </Link>
              )}
              {hero.secondaryCta && (
                <Link 
                  href={hero.secondaryLink || `/${locale}/b2b/contact`} 
                  className="px-8 py-4 bg-transparent border-2 border-zinc-700 text-zinc-100 font-bold text-lg rounded-sm hover:border-zinc-500 hover:bg-zinc-800 transition-all"
                >
                  {hero.secondaryCta}
                </Link>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* 2. Credibility Board */}
      <section className="py-20 bg-zinc-950 border-b border-zinc-900">
        <div className="container mx-auto px-4 md:px-8">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-8 md:gap-12">
            {stats.map((stat: any, i: number) => (
              <div key={i} className="flex flex-col border-s border-emerald-500/30 ps-6">
                <span className="text-4xl md:text-5xl font-black tracking-tight text-zinc-100 mb-2">
                  {isAr ? (stat.valueAr || stat.value) : stat.value}
                </span>
                <span className="text-sm font-bold text-zinc-500 uppercase tracking-wide">
                  {isAr ? (stat.labelAr || stat.label) : stat.label}
                </span>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* 3. Wow & How Split */}
      <section className="py-24 md:py-32 bg-zinc-950 relative">
        <div className="container mx-auto px-4 md:px-8">
          <div className="text-center max-w-3xl mx-auto mb-20">
            <h2 className="text-4xl md:text-5xl font-black text-zinc-100 tracking-tight mb-6">
              {wowAndHow.title}
            </h2>
            <p className="text-lg text-zinc-400">
              {wowAndHow.description}
            </p>
          </div>

          <div className="grid md:grid-cols-2 gap-12 lg:gap-20">
            {/* WOW */}
            <div className="p-10 rounded-lg bg-zinc-900 border border-zinc-800">
              <h3 className="text-3xl font-black text-emerald-400 tracking-tight mb-8">
                {isAr ? "الإبهار (The WOW)" : "The WOW"}
              </h3>
              <ul className="space-y-6">
                {(wowAndHow.wowBullets || []).map((item: string) => (
                  <li key={item} className="flex items-center gap-4 text-xl font-medium text-zinc-300">
                    <CheckCircle2 className="w-6 h-6 text-emerald-500 shrink-0" />
                    {item}
                  </li>
                ))}
              </ul>
            </div>

            {/* HOW */}
            <div className="p-10 rounded-lg bg-zinc-900 border border-zinc-800">
              <h3 className="text-3xl font-black text-amber-500 tracking-tight mb-8">
                {isAr ? "التنفيذ (The HOW)" : "The HOW"}
              </h3>
              <ul className="space-y-6">
                {(wowAndHow.howBullets || []).map((item: string) => (
                  <li key={item} className="flex items-center gap-4 text-xl font-medium text-zinc-300">
                    <CheckCircle2 className="w-6 h-6 text-amber-500 shrink-0" />
                    {item}
                  </li>
                ))}
              </ul>
            </div>
          </div>
        </div>
      </section>

      {/* 4. Core Capabilities Preview */}
      <section className="py-24 bg-zinc-900 border-y border-zinc-800">
        <div className="container mx-auto px-4 md:px-8">
          <div className="flex flex-col md:flex-row md:items-end justify-between mb-12 gap-6">
            <div>
              <h2 className="text-4xl md:text-5xl font-black text-zinc-100 tracking-tight mb-4">{isAr ? "القدرات الأساسية" : "Core Capabilities"}</h2>
              <p className="text-lg text-zinc-400">{isAr ? "كل ما يلزم لتقديم تجارب استثنائية." : "Everything required to deliver landmark experiences."}</p>
            </div>
            <Link href="/b2b/services" className="inline-flex items-center gap-2 text-emerald-400 font-bold hover:text-emerald-300 transition-colors">
              {isAr ? "عرض جميع الخدمات" : "View All Services"} <ArrowRight className="w-5 h-5 rtl:-scale-x-100" />
            </Link>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {dbServices.length > 0 ? (
              dbServices.map((service, i) => {
                const name = isAr ? (service.titleAr || service.titleEn || service.slug) : (service.titleEn || service.slug)
                const desc = isAr ? (service.taglineAr || service.contentAr?.substring(0, 150) || service.taglineEn || service.contentEn?.substring(0, 150) || "Premium entertainment service") : (service.taglineEn || service.contentEn?.substring(0, 150) || "Premium entertainment service")
                return (
                  <Link 
                    key={i} 
                    href={`/b2b/services/${service.slug}`}
                    className={cn(
                      "group relative rounded-2xl bg-zinc-950 border border-zinc-800 hover:border-emerald-500/50 transition-all overflow-hidden flex flex-col justify-between",
                      i === 0 ? "md:col-span-2 md:row-span-2 min-h-[400px]" : "min-h-[250px]"
                    )}
                  >
                    {/* Thumbnail Background */}
                    <div className="absolute inset-0 z-0">
                      {service.thumbnail ? (
                        <UniversalMediaRenderer 
                          type="IMAGE"
                          src={service.thumbnail}
                          alt={name}
                          className="w-full h-full object-cover opacity-40 group-hover:opacity-60 transition-all duration-700 group-hover:scale-105"
                        />
                      ) : (
                        <div className="w-full h-full bg-gradient-to-br from-zinc-900 to-zinc-950" />
                      )}
