                );

                if (linkHref) {
                  return (
                    <Link key={proj.id || i} href={linkHref}>
                      {cardContent}
                    </Link>
                  )
                }

                return <div key={proj.id || i}>{cardContent}</div>;
              })}
            </div>
          </div>
        </section>
      )}

      {/* 4. Gallery */}
      {service.gallery && service.gallery.length > 0 && (
