  return (
    <main className="min-h-screen bg-[#09090b] text-[#fafafa] selection:bg-emerald-500/30 selection:text-emerald-200">
      
      {/* Header Section */}
      <section className="pt-32 pb-16 px-4 sm:px-6 lg:px-8 max-w-7xl mx-auto border-b border-white/10">
