    if (!session || !['SUPER_ADMIN', 'SALES_ADMIN'].includes(userRole)) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const data = await request.json();

    const rule = await db.attractionTemporalRule.create({
      data: {
        attractionId: data.attractionId,
        ruleType: data.ruleType,
        startDate: data.startDate ? new Date(data.startDate) : null,
        endDate: data.endDate ? new Date(data.endDate) : null,
        openTime: data.openTime,
        closeTime: data.closeTime,
        daysOfWeek: data.daysOfWeek,
        notes: data.notes,
      }
    });

    await db.systemLog.create({
      data: {
        action: `TEMPORAL_RULE_CREATED`,
        entity: `Rule for Attraction ${data.attractionId}`,
        entityId: rule.id,
        userId: (session.user as any)?.id,
      }
    });

    return NextResponse.json(rule);
  } catch (error) {
    console.error('Error creating temporal rule:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';
import { redis } from '@/lib/redis';

export async function GET(_req: NextRequest // eslint-disable-line @typescript-eslint/no-unused-vars) {
  try {
    const cacheKey = `tickets:active`;
    const cached = await redis.get(cacheKey);

    if (cached) {
      return NextResponse.json(JSON.parse(cached));
    }

    const attractions = await db.attraction.findMany({
      where: {
        isPublished: true,
        isHidden: false,
      },
      include: {
        pricing: true,
        // Include today's schedules to determine general availability
        schedules: {
          where: {
            startTime: { gte: new Date(new Date().setHours(0,0,0,0)) },
            endTime: { lte: new Date(new Date().setHours(23,59,59,999)) }
          }
        }
      }
    });

    const result = attractions.map(attraction => {
      // General availability check for today
      let isAvailableToday = false;
      if (attraction.schedules && attraction.schedules.length > 0) {
         isAvailableToday = attraction.schedules.some(s => s.currentCount < s.capacityGate);
      } else {
         // If no schedules exist, we might assume it's open based on temporal rules, but for tickets, we'll default to available
         isAvailableToday = true;
      }

      // Map the pricing tiers
      const pricingTiers = attraction.pricing.map(p => ({
        id: p.id,
        ticketType: p.type,
        titleEn: p.titleEn,
        titleAr: p.titleAr,
        price: p.price,
        currency: p.currency,
        isAvailable: isAvailableToday // Could be more granular per tier if DB supported it
      }));

      return {
        attractionId: attraction.id,
        attractionNameEn: attraction.nameEn,
        attractionNameAr: attraction.nameAr,
        attractionSlug: attraction.slug,
        descriptionEn: attraction.descriptionEn,
        descriptionAr: attraction.descriptionAr,
        heroMediaUrl: attraction.heroMediaUrl,
        bookingUrl: `https://bookingqube.com/e3/${attraction.slug}`, // Standard deep link pattern
        pricingTiers,
      };
    });

    // 5 min cache
    await redis.set(cacheKey, JSON.stringify(result), 'EX', 300);

    return NextResponse.json(result);
  } catch (error: any) {
    console.error('[TICKETS_GET]', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from "next/server"
import { put } from "@vercel/blob"
import { handleUpload, type HandleUploadBody } from "@vercel/blob/client"
import { randomUUID } from "crypto"
import { auth } from "@/lib/auth"
import fs from "fs/promises"
import path from "path"

const MAX_FILE_SIZE = 50 * 1024 * 1024; // 50MB
const ALLOWED_EXTENSIONS = [
  'jpg', 'jpeg', 'png', 'gif', 'webp', 'svg', 'ico', 'avif',
  'mp4', 'webm', 'mov',
  'pdf', 'doc', 'docx',
  'glb', 'gltf'
];

const ALLOWED_TYPES = [
  'image/jpeg', 'image/png', 'image/gif', 'image/webp', 'image/svg+xml', 'image/svg',
  'video/mp4', 'video/webm', 'video/quicktime',
  'application/pdf', 'application/x-pdf',
  'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'model/gltf-binary', 'model/gltf+json',
  'application/octet-stream', 'text/xml', 'application/xml'
];

async function saveFileOrDataUrl(file: File, fileName: string, ext?: string): Promise<string> {
  const bytes = await file.arrayBuffer();
  const buffer = Buffer.from(bytes);

  // Try saving to public/uploads directory first (local dev / writable disk)
  try {
    const uploadDir = path.join(process.cwd(), "public", "uploads");
    await fs.mkdir(uploadDir, { recursive: true });
    const filePath = path.join(uploadDir, fileName);
    await fs.writeFile(filePath, buffer);
    return `/uploads/${fileName}`;
  } catch (fsErr) {
    console.warn("[UPLOAD WARNING] Disk storage failed (read-only filesystem), converting to Data URL fallback:", fsErr);
    
    let mime = file.type;
    if (ext === 'svg' || !mime || mime === 'application/octet-stream') {
      if (ext === 'svg') mime = 'image/svg+xml';
      else if (ext === 'png') mime = 'image/png';
      else if (ext === 'jpg' || ext === 'jpeg') mime = 'image/jpeg';
      else if (ext === 'webp') mime = 'image/webp';
      else if (ext === 'gif') mime = 'image/gif';
      else if (ext === 'pdf') mime = 'application/pdf';
    }

    const base64 = buffer.toString('base64');
    return `data:${mime || 'application/octet-stream'};base64,${base64}`;
  }
}

export async function POST(request: Request) {
  const contentType = request.headers.get("content-type") || "";

  // 1. Handle Vercel Blob client token generation (JSON request)
  if (contentType.includes("application/json")) {
    try {
      const body = (await request.json()) as HandleUploadBody;
      const jsonResponse = await handleUpload({
        body,
        request,
        onBeforeGenerateToken: async (pathname, clientPayload) => {
          const session = await auth();
          let context = null;
          if (clientPayload) {
            try { context = JSON.parse(clientPayload).context; } catch {}
          }
          if (!session?.user && context !== 'public_resume') {
            throw new Error("Unauthorized");
          }
          return {
            allowedContentTypes: ALLOWED_TYPES,
            maximumSizeInBytes: MAX_FILE_SIZE,
            tokenPayload: JSON.stringify({ userId: session?.user?.id || 'anonymous' })
          };
        },
        onUploadCompleted: async ({ blob }) => {
          console.log("Blob upload completed", blob.url);
        },
      });
      return NextResponse.json(jsonResponse);
    } catch (error) {
      console.error('Error in handleUpload:', error);
      return NextResponse.json({ success: false, error: (error as Error).message }, { status: 400 });
    }
  }

  // 2. Handle Direct FormData file uploads (FormData request)
  try {
    const data = await request.formData();
    const context = data.get('context') as string | null;

    const session = await auth();

    if (!session?.user && context !== 'public_resume') {
      return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
    }
    const file: File | null = data.get('file') as unknown as File;

    if (!file) {
      return NextResponse.json({ success: false, error: 'No file uploaded' }, { status: 400 });
    }

    if (file.size > MAX_FILE_SIZE) {
      return NextResponse.json({ success: false, error: 'File size exceeds 50MB limit' }, { status: 400 });
    }

    const ext = file.name.split('.').pop()?.toLowerCase();
    const isAllowedExt = ext && ALLOWED_EXTENSIONS.includes(ext);

    if (!isAllowedExt && !ALLOWED_TYPES.includes(file.type) && !file.type.startsWith('image/') && !file.type.startsWith('video/')) {
      return NextResponse.json({ success: false, error: 'Invalid file type' }, { status: 400 });
    }

    const fileName = `${randomUUID()}.${ext || 'bin'}`;
    let fileUrl = "";

    if (process.env.BLOB_READ_WRITE_TOKEN) {
      try {
        const blob = await put(`uploads/${fileName}`, file, {
          access: 'public',
          contentType: ext === 'svg' ? 'image/svg+xml' : file.type,
        });
        fileUrl = blob.url;
      } catch (blobError) {
        console.warn("[UPLOAD WARNING] Vercel Blob upload failed, falling back to disk/DataURL:", blobError);
        fileUrl = await saveFileOrDataUrl(file, fileName, ext);
      }
    } else {
      fileUrl = await saveFileOrDataUrl(file, fileName, ext);
    }

    return NextResponse.json({ 
      success: true, 
      url: fileUrl,
      fileName: file.name
    });
  } catch (error: any) {
    console.error('Error uploading file:', error);
    return NextResponse.json({ success: false, error: error?.message || 'Internal Server Error' }, { status: 500 });
  }
}

"use client"

import { useState } from "react"
import Link from "next/link"
import { ArrowLeft, CheckCircle2 } from "lucide-react"
import { Button } from "@/components/ui/Button"
import { Input } from "@/components/ui/Input"

export default function ForgotPasswordPage() {
  const [email, setEmail] = useState("")
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [isSuccess, setIsSuccess] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError(null)
    setIsSubmitting(true)

    try {
      // Simulate API call for password reset email
      await new Promise(resolve => setTimeout(resolve, 1500))
      
      if (!email.includes("@")) {
        throw new Error("Please enter a valid email address.")
      }
      
      setIsSuccess(true)
    } catch (err: any) {
      setError(err.message || "Something went wrong. Please try again.")
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-[var(--surface-default)] text-[var(--text-primary)] px-4">
      <div className="w-full max-w-md p-8 rounded-2xl bg-[var(--surface-hover)] border border-[var(--border-default)] shadow-xl relative overflow-hidden">
        
        {/* Decorative elements */}
        <div className="absolute top-0 end-0 w-32 h-32 bg-[var(--color-primary)]/10 rounded-full blur-3xl" />

        <div className="mb-8">
          <Link href="/auth/login" className="inline-flex items-center text-sm font-medium text-[var(--text-secondary)] hover:text-[var(--color-primary)] transition-colors mb-6">
            <ArrowLeft className="w-4 h-4 me-2" />
            Back to login
          </Link>
          <h1 className="text-3xl font-bold text-[var(--text-primary)] mb-2">
            Reset Password
          </h1>
          <p className="text-[var(--text-secondary)]">
            Enter your email address and we&apos;ll send you a link to reset your password.
          </p>
        </div>

        {isSuccess ? (
          <div className="bg-emerald-500/10 border border-emerald-500/20 rounded-xl p-6 text-center animate-in fade-in zoom-in duration-500">
            <CheckCircle2 className="w-12 h-12 text-emerald-500 mx-auto mb-4" />
            <h3 className="text-lg font-bold text-[var(--text-primary)] mb-2">Check your email</h3>
            <p className="text-[var(--text-secondary)] text-sm mb-6">
              We have sent a password reset link to <strong>{email}</strong>
            </p>
            <Button variant="outline" fullWidth onClick={() => setIsSuccess(false)}>
              Try another email
            </Button>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <Input
                type="email"
                label="Email Address"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                disabled={isSubmitting}
                placeholder="admin@e3qatar.com"
              />
            </div>

            {error && (
              <div className="text-[var(--color-error)] text-sm font-medium bg-[var(--color-error)]/10 p-3 rounded-lg border border-[var(--color-error)]/20 animate-in fade-in">
                {error}
              </div>
            )}

            <Button
              type="submit"
              variant="gradient"
              fullWidth
              isLoading={isSubmitting}
              disabled={isSubmitting || !email}
            >
              Send Reset Link
            </Button>
          </form>
        )}
      </div>
    </div>
  )
}

"use client"

import { useState, Suspense } from "react"
import { useRouter, useSearchParams } from "next/navigation"
import Link from "next/link"
import { ArrowLeft, CheckCircle2 } from "lucide-react"
import { Button } from "@/components/ui/Button"
import { Input } from "@/components/ui/Input"

function ResetPasswordForm() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const token = searchParams.get("token")

  const [password, setPassword] = useState("")
  const [confirmPassword, setConfirmPassword] = useState("")
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [isSuccess, setIsSuccess] = useState(false)
  const [errorState, setErrorState] = useState<string | null>(null)
  
  const error = !token ? "Invalid or missing reset token. Please request a new password reset." : errorState


  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setErrorState(null)

    if (password !== confirmPassword) {
      setErrorState("Passwords do not match.")
      return
    }

    if (password.length < 8) {
      setErrorState("Password must be at least 8 characters long.")
      return
    }

    setIsSubmitting(true)

    try {
      // Simulate API call for password reset using token
      await new Promise(resolve => setTimeout(resolve, 1500))
      
      setIsSuccess(true)
      
      // Auto redirect to login after success
      setTimeout(() => {
        router.push("/auth/login")
      }, 3000)
    } catch (err: any) {
      setErrorState(err.message || "Failed to reset password. The link may have expired.")
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div className="w-full max-w-md p-8 rounded-2xl bg-[var(--surface-hover)] border border-[var(--border-default)] shadow-xl relative overflow-hidden">
      
      {/* Decorative elements */}
      <div className="absolute top-0 end-0 w-32 h-32 bg-[var(--color-accent)]/10 rounded-full blur-3xl" />

      <div className="mb-8">
        <Link href="/auth/login" className="inline-flex items-center text-sm font-medium text-[var(--text-secondary)] hover:text-[var(--color-primary)] transition-colors mb-6">
          <ArrowLeft className="w-4 h-4 me-2" />
          Back to login
        </Link>
        <h1 className="text-3xl font-bold text-[var(--text-primary)] mb-2">
          Create New Password
        </h1>
        <p className="text-[var(--text-secondary)]">
          Your new password must be different from previous used passwords.
        </p>
      </div>

      {isSuccess ? (
        <div className="bg-emerald-500/10 border border-emerald-500/20 rounded-xl p-6 text-center animate-in fade-in zoom-in duration-500">
          <CheckCircle2 className="w-12 h-12 text-emerald-500 mx-auto mb-4" />
          <h3 className="text-lg font-bold text-[var(--text-primary)] mb-2">Password Reset Successfully</h3>
          <p className="text-[var(--text-secondary)] text-sm mb-6">
            You will be redirected to the login page momentarily.
          </p>
          <Button variant="primary" fullWidth asChild>
            <Link href="/auth/login">Return to Login</Link>
          </Button>
        </div>
      ) : (
        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <Input
              type="password"
              label="New Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              disabled={isSubmitting || !token}
            />
          </div>

          <div>
            <Input
              type="password"
              label="Confirm New Password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              required
              disabled={isSubmitting || !token}
            />
          </div>

          {error && (
            <div className="text-sm font-medium text-[var(--color-error)] bg-[var(--color-error)]/10 p-3 rounded-md">
              {error}
            </div>
          )}

          <Button 
            type="submit" 
            variant="primary" 
            fullWidth 
            disabled={isSubmitting || !token}
            className="mt-2"
          >
            {isSubmitting ? "Resetting..." : "Reset Password"}
          </Button>
        </form>
      )}
    </div>
  )
}

export default function ResetPasswordPage() {
  return (
    <div className="min-h-screen flex items-center justify-center bg-[var(--surface-default)] text-[var(--text-primary)] px-4">
      <Suspense fallback={
        <div className="w-full max-w-md p-8 rounded-2xl bg-[var(--surface-hover)] border border-[var(--border-default)] shadow-xl h-[400px] flex items-center justify-center">
          <div className="w-8 h-8 border-2 border-[var(--color-primary)] border-t-transparent rounded-full animate-spin"></div>
        </div>
      }>
        <ResetPasswordForm />
      </Suspense>
    </div>
  )
}

