    label: Record<string, string>
  }
}

interface CaseStudyCardProps {
  caseStudy: CaseStudy
  locale: string
  isFeatured?: boolean
  index?: number
}

export function CaseStudyCard({ caseStudy, locale, isFeatured = false, index = 0 }: CaseStudyCardProps) {
  const isRTL = locale === 'ar'
  const title = caseStudy.title[locale] || caseStudy.title.en
  const clientName = caseStudy.clientName[locale] || caseStudy.clientName.en
  const metricLabel = caseStudy.keyMetric?.label[locale] || caseStudy.keyMetric?.label.en

  // Animations
  const itemVariants = {
    hidden: { opacity: 0, y: 30 },
    show: { opacity: 1, y: 0, transition: { duration: 0.6, delay: Math.min(index * 0.1, 0.5) } }
  }

  if (isFeatured) {
    return (
      <motion.div 
        variants={itemVariants}
        initial="hidden"
        whileInView="show"
        viewport={{ once: true, margin: "-50px" }}
        className="group relative w-full rounded-[2rem] md:rounded-[3rem] overflow-hidden bg-[var(--surface-default)] mb-16"
      >
        <Link href={`/${locale}/b2b/case-studies/${caseStudy.slug}`} className="flex flex-col lg:flex-row relative z-10 w-full h-full min-h-[500px]">
          {/* Image Side */}
          <div className="w-full lg:w-3/5 h-[400px] lg:h-auto overflow-hidden relative">
            <img 
              src={caseStudy.thumbnailUrl} 
              alt={title}
              className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-105"
            />
            {/* View Case Study Overlay on hover */}
            <div className="absolute inset-0 bg-zinc-950/40 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-center justify-center backdrop-blur-sm">
              <span className="bg-white text-zinc-950 font-bold px-6 py-3 rounded-full flex items-center gap-2 transform translate-y-4 group-hover:translate-y-0 transition-all duration-300">
                {locale === 'ar' ? 'عرض دراسة الحالة' : 'View Case Study'}
                <ArrowRight className={`w-4 h-4 ${isRTL ? 'rotate-180' : ''}`} />
              </span>
            </div>
          </div>
          
          {/* Content Side */}
          <div className="w-full lg:w-2/5 p-8 md:p-12 lg:p-16 flex flex-col justify-center bg-[var(--surface-hover)] border-s border-t lg:border-t-0 border-[var(--border-default)]">
            <div className="flex flex-wrap items-center gap-3 mb-6">
              <Badge variant="default">{caseStudy.category}</Badge>
              <span className="text-sm font-bold text-[var(--text-tertiary)]">{caseStudy.year}</span>
            </div>
            
            <span className="text-sm font-bold text-[var(--color-primary)] uppercase tracking-widest mb-2">
              {clientName}
            </span>
            <h2 className="text-3xl md:text-5xl font-black text-[var(--text-primary)] mb-8 line-clamp-3">
              {title}
            </h2>

            {caseStudy.keyMetric && (
              <div className="mt-auto pt-8 border-t border-[var(--border-default)]">
                <p className="text-5xl font-black text-[var(--text-primary)] mb-1">
                  {caseStudy.keyMetric.value}
                </p>
                <p className="text-sm font-bold text-[var(--text-secondary)] uppercase tracking-wider">
                  {metricLabel}
                </p>
              </div>
            )}
          </div>
        </Link>
      </motion.div>
    )
  }

  // Standard Card
  return (
    <motion.div 
      variants={itemVariants}
      initial="hidden"
      whileInView="show"
      viewport={{ once: true, margin: "-50px" }}
      className="group relative w-full h-full flex flex-col"
    >
      <Link href={`/${locale}/b2b/case-studies/${caseStudy.slug}`} className="flex flex-col h-full">
        {/* Image */}
        <div className="w-full aspect-[4/3] rounded-2xl overflow-hidden relative mb-6">
          <img 
            src={caseStudy.thumbnailUrl} 
            alt={title}
            className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-105"
          />
          {/* View Case Study Overlay on hover */}
          <div className="absolute inset-0 bg-zinc-950/40 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-center justify-center backdrop-blur-[2px]">
            <span className="bg-white text-zinc-950 font-bold px-6 py-3 rounded-full flex items-center gap-2 transform translate-y-4 group-hover:translate-y-0 transition-all duration-300">
              {locale === 'ar' ? 'عرض التفاصيل' : 'View Details'}
              <ArrowRight className={`w-4 h-4 ${isRTL ? 'rotate-180' : ''}`} />
            </span>
          </div>

          <div className="absolute top-4 start-4 z-10">
            <Badge variant="default" className="bg-zinc-950/50 backdrop-blur-md text-white border-none">
              {caseStudy.category}
            </Badge>
          </div>
        </div>

        {/* Content */}
        <div className="flex flex-col flex-grow">
          <div className="flex justify-between items-start mb-2">
            <span className="text-sm font-bold text-[var(--color-primary)] tracking-widest uppercase">
              {clientName}
            </span>
            <span className="text-sm font-bold text-[var(--text-tertiary)]">
              {caseStudy.year}
            </span>
          </div>
          <h3 className="text-2xl font-bold text-[var(--text-primary)] group-hover:text-[var(--color-primary)] transition-colors line-clamp-2 mb-6">
            {title}
          </h3>

          {caseStudy.keyMetric && (
            <div className="mt-auto pt-4 border-t border-[var(--border-default)]">
              <p className="text-2xl font-black text-[var(--text-primary)] mb-1">
                {caseStudy.keyMetric.value}
              </p>
              <p className="text-xs font-bold text-[var(--text-secondary)] uppercase tracking-wider">
                {metricLabel}
              </p>
            </div>
          )}
        </div>
      </Link>
    </motion.div>
  )
}

"use client"

import { useState, useEffect } from "react"
import { motion, AnimatePresence } from "framer-motion"
import { CheckCircle2, ChevronRight, ChevronLeft, Upload } from "lucide-react"
import { Button } from "@/components/ui/Button"
import { Input } from "@/components/ui/Input"

interface MultiStepLeadFormProps {
  locale: string
  services: { id: string, name: Record<string, string> }[]
}

const STORAGE_KEY = "e3_b2b_lead_form"

export function MultiStepLeadForm({ locale, services }: MultiStepLeadFormProps) {
  const isRTL = locale === 'ar'
  
  const [step, setStep] = useState(1)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [isSuccess, setIsSuccess] = useState(false)

  // Form State
  const [formData, setFormData] = useState(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem(STORAGE_KEY)
      if (saved) {
        try {
          return JSON.parse(saved)
        } catch {
          // ignore
        }
      }
    }
    return {
      name: '',
      email: '',
      phone: '',
      company: '',
      industry: '',
      selectedServices: [] as string[],
      budget: '',
      timeline: '',
      description: '',
      source: '',
    }
  })

  // Save to LocalStorage
  useEffect(() => {
    if (!isSuccess) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(formData))
    }
  }, [formData, isSuccess])

  const toggleService = (id: string) => {
    setFormData((prev: any) => ({
      ...prev,
      selectedServices: prev.selectedServices.includes(id)
        ? prev.selectedServices.filter((s: string) => s !== id)
        : [...prev.selectedServices, id]
    }))
  }

  const handleNext = () => {
    // Basic validation
    if (step === 1 && (!formData.name || !formData.email || !formData.company)) return
    if (step === 2 && (formData.selectedServices.length === 0 || !formData.description)) return
    setStep(s => s + 1)
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsSubmitting(true)

    // Simulate API POST
    await new Promise(resolve => setTimeout(resolve, 2000))
    
    setIsSubmitting(false)
    setIsSuccess(true)
    localStorage.removeItem(STORAGE_KEY)
  }

  if (isSuccess) {
    return (
      <div className="bg-[var(--surface-default)] rounded-[3rem] border border-[var(--border-default)] p-12 text-center min-h-[500px] flex flex-col items-center justify-center">
        <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ type: "spring", bounce: 0.5 }}>
          <CheckCircle2 className="w-24 h-24 text-[var(--color-success)] mb-6 mx-auto" />
        </motion.div>
        <h3 className="text-3xl font-black text-[var(--text-primary)] mb-4">
          {locale === 'ar' ? 'تم استلام طلبك بنجاح' : 'Inquiry Received Successfully'}
        </h3>
        <p className="text-xl text-[var(--text-secondary)] mb-8 max-w-lg mx-auto">
          {locale === 'ar' 
            ? 'سيتواصل معك فريقنا خلال 24 ساعة لمناقشة مشروعك الاستثنائي القادم.' 
            : 'Our engineering team will review your requirements and get back to you within 24 hours.'}
        </p>
      </div>
    )
  }

  return (
    <div className="bg-[var(--surface-default)] rounded-[3rem] border border-[var(--border-default)] p-8 md:p-12 overflow-hidden relative">
      
      {/* Progress Indicator */}
      <div className="flex items-center justify-between mb-12 relative z-10">
        {[1, 2, 3].map((s) => (
          <div key={s} className="flex flex-col items-center relative z-10 flex-1">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-sm transition-colors duration-300 ${
              step >= s 
                ? 'bg-[var(--color-primary)] text-white' 
                : 'bg-[var(--surface-hover)] text-[var(--text-tertiary)] border border-[var(--border-default)]'
            }`}>
              {s}
            </div>
            <span className={`text-xs font-bold mt-3 uppercase tracking-wider ${step >= s ? 'text-[var(--text-primary)]' : 'text-[var(--text-tertiary)]'}`}>
              {s === 1 ? (locale === 'ar' ? 'معلوماتك' : 'About You') :
               s === 2 ? (locale === 'ar' ? 'المشروع' : 'Project Details') :
               (locale === 'ar' ? 'إضافي' : 'Additional')}
            </span>
          </div>
        ))}
        {/* Progress Line */}
        <div className="absolute top-5 start-10 end-10 h-[2px] bg-[var(--surface-hover)] -z-10">
          <div 
            className="h-full bg-[var(--color-primary)] transition-all duration-500"
            style={{ width: `${((step - 1) / 2) * 100}%` }}
          />
        </div>
      </div>

      <form onSubmit={handleSubmit} className="relative min-h-[400px]">
        <AnimatePresence mode="wait">
          
          {/* STEP 1: ABOUT YOU */}
          {step === 1 && (
            <motion.div 
              key="step1"
              initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: 20 }}
              className="space-y-6"
            >
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-bold text-[var(--text-secondary)]">{locale === 'ar' ? 'الاسم الكامل *' : 'Full Name *'}</label>
                  <Input required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-[var(--text-secondary)]">{locale === 'ar' ? 'البريد الإلكتروني *' : 'Email Address *'}</label>
                  <Input type="email" required value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} />
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-bold text-[var(--text-secondary)]">{locale === 'ar' ? 'الشركة *' : 'Company Name *'}</label>
                  <Input required value={formData.company} onChange={e => setFormData({...formData, company: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-[var(--text-secondary)]">{locale === 'ar' ? 'رقم الهاتف' : 'Phone Number'}</label>
                  <Input type="tel" value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-sm font-bold text-[var(--text-secondary)]">{locale === 'ar' ? 'القطاع / الصناعة' : 'Industry'}</label>
                <Input value={formData.industry} onChange={e => setFormData({...formData, industry: e.target.value})} />
              </div>

              <div className="flex justify-end pt-8">
                <Button 
                  type="button" 
                  size="lg" 
                  onClick={handleNext}
                  disabled={!formData.name || !formData.email || !formData.company}
                  className="gap-2"
                >
                  {locale === 'ar' ? 'التالي' : 'Next Step'}
                  <ChevronRight className={`w-5 h-5 ${isRTL ? 'rotate-180' : ''}`} />
                </Button>
              </div>
            </motion.div>
          )}

          {/* STEP 2: PROJECT DETAILS */}
          {step === 2 && (
            <motion.div 
              key="step2"
              initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: 20 }}
              className="space-y-8"
            >
              <div className="space-y-4">
                <label className="text-sm font-bold text-[var(--text-secondary)]">{locale === 'ar' ? 'الخدمات المطلوبة *' : 'Services Interested In *'}</label>
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                  {services.map(svc => (
                    <button
                      key={svc.id}
                      type="button"
                      onClick={() => toggleService(svc.id)}
                      className={`p-3 rounded-xl border text-sm font-bold text-start transition-all ${
                        formData.selectedServices.includes(svc.id)
                          ? 'bg-[var(--color-primary)]/10 border-[var(--color-primary)] text-[var(--color-primary)]'
                          : 'bg-[var(--surface-hover)] border-[var(--border-default)] text-[var(--text-secondary)] hover:border-[var(--color-primary)]/50'
                      }`}
                    >
                      {svc.name[locale] || svc.name.en}
                    </button>
                  ))}
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-bold text-[var(--text-secondary)]">{locale === 'ar' ? 'الميزانية التقديرية' : 'Estimated Budget'}</label>
                  <select 
                    value={formData.budget} 
                    onChange={e => setFormData({...formData, budget: e.target.value})}
                    className="w-full px-4 py-3 rounded-xl bg-[var(--surface-default)] border border-[var(--border-default)] text-[var(--text-primary)] focus:outline-none focus:ring-2 focus:ring-[var(--color-primary)]"
                  >
                    <option value="">{locale === 'ar' ? 'اختر النطاق' : 'Select Range'}</option>
                    <option value="10k-50k">$10,000 - $50,000</option>
                    <option value="50k-200k">$50,000 - $200,000</option>
                    <option value="200k-500k">$200,000 - $500,000</option>
                    <option value="500k+">$500,000+</option>
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-[var(--text-secondary)]">{locale === 'ar' ? 'الجدول الزمني' : 'Timeline'}</label>
                  <select 
                    value={formData.timeline} 
                    onChange={e => setFormData({...formData, timeline: e.target.value})}
                    className="w-full px-4 py-3 rounded-xl bg-[var(--surface-default)] border border-[var(--border-default)] text-[var(--text-primary)] focus:outline-none focus:ring-2 focus:ring-[var(--color-primary)]"
                  >
                    <option value="">{locale === 'ar' ? 'متى تحتاج التنفيذ؟' : 'When do you need this?'}</option>
                    <option value="ASAP">ASAP (Within 1 month)</option>
                    <option value="3months">Within 3 months</option>
                    <option value="6months+">6+ months out</option>
                  </select>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-bold text-[var(--text-secondary)]">{locale === 'ar' ? 'تفاصيل المشروع *' : 'Project Details *'}</label>
                <textarea 
                  required
                  rows={4}
                  value={formData.description}
                  onChange={e => setFormData({...formData, description: e.target.value})}
                  className="w-full px-4 py-3 rounded-xl bg-[var(--surface-default)] border border-[var(--border-default)] text-[var(--text-primary)] focus:outline-none focus:ring-2 focus:ring-[var(--color-primary)] resize-none"
                  placeholder={locale === 'ar' ? 'صِف رؤيتك ومتطلباتك...' : 'Describe your vision and requirements...'}
                />
              </div>

              <div className="flex justify-between items-center pt-8">
                <Button type="button" variant="ghost" onClick={() => setStep(1)} className="gap-2">
                  <ChevronLeft className={`w-5 h-5 ${isRTL ? 'rotate-180' : ''}`} />
                  {locale === 'ar' ? 'العودة' : 'Back'}
                </Button>
                <Button 
                  type="button" 
                  size="lg" 
                  onClick={handleNext}
                  disabled={formData.selectedServices.length === 0 || !formData.description}
                  className="gap-2"
                >
                  {locale === 'ar' ? 'التالي' : 'Next Step'}
                  <ChevronRight className={`w-5 h-5 ${isRTL ? 'rotate-180' : ''}`} />
                </Button>
              </div>
            </motion.div>
          )}

          {/* STEP 3: ADDITIONAL */}
          {step === 3 && (
            <motion.div 
              key="step3"
              initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: 20 }}
              className="space-y-8"
            >
              <div className="space-y-2">
                <label className="text-sm font-bold text-[var(--text-secondary)]">{locale === 'ar' ? 'كيف سمعت عنا؟' : 'How did you hear about us?'}</label>
                <Input value={formData.source} onChange={e => setFormData({...formData, source: e.target.value})} />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-bold text-[var(--text-secondary)]">{locale === 'ar' ? 'المرفقات (اختياري)' : 'Attachments (Optional)'}</label>
                <div className="border-2 border-dashed border-[var(--border-default)] rounded-xl p-8 text-center hover:border-[var(--color-primary)]/50 transition-colors cursor-pointer bg-[var(--surface-hover)]">
                  <Upload className="w-8 h-8 text-[var(--text-tertiary)] mx-auto mb-4" />
                  <p className="text-sm font-bold text-[var(--text-primary)] mb-1">
                    {locale === 'ar' ? 'اضغط لرفع الملفات أو اسحبها هنا' : 'Click to upload or drag and drop'}
                  </p>
                  <p className="text-xs text-[var(--text-tertiary)]">
                    {locale === 'ar' ? 'PDF، PPT، أو صور (الحد الأقصى 20 ميغابايت)' : 'PDF, PPT, or Images (Max 20MB)'}
                  </p>
                </div>
              </div>

              <div className="flex justify-between items-center pt-8">
                <Button type="button" variant="ghost" onClick={() => setStep(2)} className="gap-2">
                  <ChevronLeft className={`w-5 h-5 ${isRTL ? 'rotate-180' : ''}`} />
                  {locale === 'ar' ? 'العودة' : 'Back'}
                </Button>
                <Button 
                  type="submit" 
                  size="xl" 
                  isLoading={isSubmitting}
                >
                  {locale === 'ar' ? 'إرسال الطلب' : 'Submit Inquiry'}
                </Button>
              </div>
            </motion.div>
          )}

        </AnimatePresence>
      </form>
    </div>
  )
}

"use client"

import { motion } from "framer-motion"

interface PartnerMarqueeProps {
  logos: string[]
}

export function PartnerMarquee({ logos }: PartnerMarqueeProps) {
  // Duplicate array to ensure seamless infinite scrolling
  const duplicatedLogos = [...logos, ...logos, ...logos]

  return (
    <div className="relative w-full overflow-hidden bg-[var(--surface-hover)] border-y border-[var(--border-default)] py-12">
      {/* Fade Edges */}
      <div className="absolute inset-y-0 start-0 w-32 bg-gradient-to-r from-[var(--surface-hover)] to-transparent z-10" />
      <div className="absolute inset-y-0 end-0 w-32 bg-gradient-to-l from-[var(--surface-hover)] to-transparent z-10" />
      
      <div className="flex">
        <motion.div
          animate={{ x: ["0%", "-50%"] }}
          transition={{ ease: "linear", duration: 30, repeat: Infinity }}
          className="flex items-center gap-16 md:gap-24 whitespace-nowrap min-w-full"
        >
          {duplicatedLogos.map((logo, index) => (
            <img 
              key={index} 
              src={logo} 
              alt={`Partner Logo ${index}`} 
              className="h-12 md:h-16 w-auto object-contain opacity-50 hover:opacity-100 transition-opacity grayscale hover:grayscale-0"
            />
          ))}
        </motion.div>
      </div>
    </div>
  )
}

"use client"

import { useState } from "react"
import { motion, AnimatePresence } from "framer-motion"
import { X, Play } from "lucide-react"

export interface GalleryItem {
  id: string
  url: string
  type: 'IMAGE' | 'VIDEO'
  caption?: Record<string, string>
}

interface ServiceGalleryProps {
  items: GalleryItem[]
  locale: string
}

export function ServiceGallery({ items, locale }: ServiceGalleryProps) {
  const [activeItem, setActiveItem] = useState<GalleryItem | null>(null)

  if (!items || items.length === 0) return null

  return (
    <section className="py-24 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8" id="gallery">
      
      <div className="mb-12">
        <h2 className="text-4xl md:text-5xl font-black text-[var(--text-primary)]">
          {locale === 'ar' ? 'معرض الأعمال' : 'Gallery'}
        </h2>
      </div>

      {/* CSS Columns Masonry */}
      <div className="columns-1 sm:columns-2 lg:columns-3 gap-6 space-y-6">
        {items.map((item) => (
          <motion.div
            key={item.id}
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true, margin: "-50px" }}
            className="break-inside-avoid relative rounded-2xl overflow-hidden cursor-pointer group bg-[var(--surface-hover)] border border-[var(--border-default)]"
            onClick={() => setActiveItem(item)}
          >
            {item.type === 'IMAGE' ? (
              <img 
                src={item.url} 
                alt={item.caption?.[locale] || item.caption?.en || 'Gallery image'}
                className="w-full h-auto object-cover group-hover:scale-105 transition-transform duration-700"
              />
            ) : (
              <div className="relative">
                <video 
                  src={item.url} 
                  className="w-full h-auto object-cover"
                  muted 
                  playsInline
                />
                <div className="absolute inset-0 bg-zinc-950/30 flex items-center justify-center group-hover:bg-zinc-950/10 transition-colors">
                  <div className="w-12 h-12 rounded-full bg-white/20 backdrop-blur-sm flex items-center justify-center">
                    <Play className="w-5 h-5 text-white fill-white" />
                  </div>
                </div>
              </div>
            )}

            {/* Hover Caption */}
            {item.caption && (
              <div className="absolute bottom-0 start-0 end-0 p-4 bg-gradient-to-t from-black/80 via-black/40 to-transparent opacity-0 group-hover:opacity-100 transition-opacity">
                <p className="text-white text-sm font-medium">
                  {item.caption[locale] || item.caption.en}
                </p>
              </div>
            )}
          </motion.div>
        ))}
      </div>

      {/* Lightbox */}
      <AnimatePresence>
        {activeItem && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center bg-zinc-950/95 backdrop-blur-md p-4 md:p-8"
            onClick={() => setActiveItem(null)}
          >
            <button 
              className="absolute top-6 end-6 w-10 h-10 rounded-full bg-white/10 flex items-center justify-center text-white hover:bg-white/20 transition-colors z-50"
              onClick={(e) => { e.stopPropagation(); setActiveItem(null) }}
            >
              <X className="w-6 h-6" />
            </button>

            <motion.div 
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="relative max-w-5xl max-h-[90vh] w-full rounded-sg overflow-hidden"
              onClick={(e) => e.stopPropagation()}
