"use client"

import { motion } from "framer-motion"

export interface ProcessStep {
  id: string
  title: Record<string, string>
  description: Record<string, string>
}

interface ServiceProcessProps {
  steps: ProcessStep[]
  locale: string
}

export function ServiceProcess({ steps, locale }: ServiceProcessProps) {
  const isRTL = locale === 'ar'

  const containerVariants = {
    hidden: { opacity: 0 },
    show: {
      opacity: 1,
      transition: {
        staggerChildren: 0.3
      }
    }
  }

  const lineVariants = {
    hidden: { width: "0%" },
    show: { 
      width: "100%", 
      transition: { duration: 1.5, ease: "easeInOut" } 
    }
  }

  const itemVariants = {
    hidden: { opacity: 0, y: 30 },
    show: { opacity: 1, y: 0, transition: { type: 'spring', stiffness: 100 } }
  }

  if (!steps || steps.length === 0) return null

  return (
    <section className="py-24 bg-[var(--surface-hover)] border-y border-[var(--border-default)] overflow-hidden" id="process">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        
        <div className="mb-16">
          <h2 className="text-4xl md:text-5xl font-black text-[var(--text-primary)] mb-4">
            {locale === 'ar' ? 'كيف نقوم بذلك' : 'How We Do It'}
          </h2>
          <p className="text-xl text-[var(--text-secondary)]">
            {locale === 'ar' ? 'الشفافية الفنية والهندسية في كل خطوة.' : 'Technical transparency at every step.'}
          </p>
        </div>

        <motion.div 
          variants={containerVariants as any}
          initial="hidden"
          whileInView="show"
          viewport={{ once: true, margin: "-100px" }}
          className="relative"
        >
          {/* Background Line (Desktop) */}
          <div className="hidden md:block absolute top-[28px] start-[10%] end-[10%] h-1 bg-[var(--surface-default)] z-0 rounded-full overflow-hidden">
            <motion.div 
              variants={lineVariants as any}
              className={`h-full bg-gradient-to-r ${isRTL ? 'from-[var(--color-accent)] to-[var(--color-primary)]' : 'from-[var(--color-primary)] to-[var(--color-accent)]'}`}
              style={{ originX: isRTL ? 1 : 0 }}
            />
          </div>

          <div className="flex flex-col md:flex-row justify-between relative z-10 gap-12 md:gap-8">
            {steps.map((step, index) => {
              const num = (index + 1).toString().padStart(2, '0')
              return (
                <motion.div 
                  key={step.id} 
                  variants={itemVariants as any}
                  className="flex-1 flex flex-col md:items-center text-start md:text-center relative group"
                >
                  {/* Mobile vertical line connector */}
                  {index !== steps.length - 1 && (
                    <div className={`md:hidden absolute top-[60px] bottom-[-48px] w-[2px] bg-[var(--surface-default)] ${isRTL ? 'end-[27px]' : 'start-[27px]'}`} />
                  )}

                  <div className="flex items-center gap-6 md:gap-0 md:flex-col">
                    {/* Number Bubble */}
                    <div className="w-14 h-14 rounded-full bg-[var(--surface-default)] border-2 border-[var(--border-default)] flex items-center justify-center font-black text-xl text-[var(--text-tertiary)] group-hover:border-[var(--color-primary)] group-hover:bg-[var(--color-primary)] group-hover:text-white transition-all shadow-sm mb-0 md:mb-6 z-10 relative">
                      {num}
                    </div>

                    {/* Content */}
                    <div>
                      <h3 className="text-xl font-bold text-[var(--text-primary)] mb-2">
                        {step.title[locale] || step.title.en}
                      </h3>
                      <p className="text-sm text-[var(--text-secondary)] leading-relaxed">
                        {step.description[locale] || step.description.en}
                      </p>
                    </div>
                  </div>
                </motion.div>
              )
            })}
          </div>
        </motion.div>
        
      </div>
    </section>
  )
}

"use client"

import { motion } from "framer-motion"

// Simplified interface for CMS JSON blocks
export interface ContentBlock {
  id: string
  type: 'paragraph' | 'h2' | 'h3' | 'list' | 'quote' | 'image'
  content?: string
  items?: string[] // for lists
  url?: string // for images
  alt?: string
  author?: string // for quotes
}

interface ServiceRichTextProps {
  blocks: ContentBlock[]
  locale: string
}

export function ServiceRichText({ blocks, locale }: ServiceRichTextProps) {


  const renderBlock = (block: ContentBlock) => {
    switch (block.type) {
      case 'h2':
        return (
          <h2 key={block.id} className="text-3xl md:text-4xl font-black text-[var(--text-primary)] mt-12 mb-6">
            {block.content}
          </h2>
        )
      case 'h3':
        return (
          <h3 key={block.id} className="text-2xl font-bold text-[var(--text-primary)] mt-8 mb-4">
            {block.content}
          </h3>
        )
      case 'paragraph':
        return (
          <p key={block.id} className="text-lg text-[var(--text-secondary)] leading-relaxed mb-6" dangerouslySetInnerHTML={{ __html: block.content || '' }} />
        )
      case 'list':
        return (
          <ul key={block.id} className="list-none space-y-4 mb-8">
            {block.items?.map((item, i) => (
              <li key={i} className="flex items-start gap-3">
                <span className="w-2 h-2 mt-2 rounded-full bg-[var(--color-primary)] shrink-0" />
                <span className="text-lg text-[var(--text-secondary)]" dangerouslySetInnerHTML={{ __html: item }} />
              </li>
            ))}
          </ul>
        )
      case 'quote':
        return (
          <blockquote key={block.id} className="ps-6 border-s-4 border-[var(--color-primary)] my-8 italic">
            <p className="text-2xl text-[var(--text-primary)] mb-2 font-medium">&quot;{block.content}&quot;</p>
            {block.author && <footer className="text-sm text-[var(--text-tertiary)]">— {block.author}</footer>}
          </blockquote>
        )
      case 'image':
        return (
          <figure key={block.id} className="my-10 rounded-2xl overflow-hidden bg-[var(--surface-hover)] border border-[var(--border-default)]">
            <img src={block.url} alt={block.alt || 'Service image'} className="w-full h-auto object-cover" />
            {block.alt && <figcaption className="text-center text-sm text-[var(--text-tertiary)] p-3 border-t border-[var(--border-default)]">{block.alt}</figcaption>}
          </figure>
        )
      default:
        return null
    }
  }

  return (
    <section className="py-24 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8" id="description">
      <div className="flex flex-col lg:flex-row gap-16">
        
        {/* Left Column (Content) */}
        <motion.div 
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-100px" }}
          transition={{ duration: 0.6 }}
          className="flex-1 max-w-3xl"
        >
          {blocks.map(renderBlock)}
        </motion.div>

        {/* Right Column (Visual/Sticky element) */}
        <motion.div 
          initial={{ opacity: 0, x: 30 }}
          whileInView={{ opacity: 1, x: 0 }}
          viewport={{ once: true, margin: "-100px" }}
          transition={{ duration: 0.6, delay: 0.2 }}
          className="w-full lg:w-1/3 shrink-0"
        >
          <div className="sticky top-32 p-8 bg-[var(--surface-hover)] rounded-3xl border border-[var(--border-default)]">
            <h4 className="text-xl font-bold text-[var(--text-primary)] mb-4">
              {locale === 'ar' ? 'جاهز للبدء؟' : 'Ready to begin?'}
            </h4>
            <p className="text-[var(--text-secondary)] mb-6">
              {locale === 'ar' 
                ? 'فريقنا الهندسي مستعد لتحويل رؤيتك إلى واقع ملموس.' 
                : 'Our engineering team is ready to transform your vision into reality.'}
            </p>
            
            {/* Visual aesthetic element */}
            <div className="aspect-square rounded-2xl bg-[var(--surface-default)] border border-[var(--border-default)] overflow-hidden relative mb-6">
               <div className="absolute inset-0 bg-[url('/grid-pattern.svg')] bg-[length:20px_20px] opacity-10" />
               <div className="absolute inset-0 flex items-center justify-center">
                 <div className="w-16 h-16 border-2 border-[var(--color-primary)] rounded-full animate-[ping_3s_ease-in-out_infinite]" />
                 <div className="absolute w-8 h-8 border-2 border-[var(--color-accent)] rounded-full animate-[ping_2s_ease-in-out_infinite]" />
               </div>
            </div>
            
          </div>
        </motion.div>

      </div>
    </section>
  )
}

