                <div className="w-full h-full p-2 relative overflow-hidden shadow-[0_12px_40px_rgba(0,0,0,0.3)]">
                  <div className={`absolute top-4 ${isAr ? 'left-4' : 'right-4'} z-10 flex gap-2`}>
