"use client"

import { useState } from "react"
import { motion, AnimatePresence } from "framer-motion"
import { MessageSquare, LifeBuoy, HelpCircle } from "lucide-react"

import { FeedbackForm } from "./FeedbackForm"
import { SupportForm } from "./SupportForm"
import { FaqTab } from "./FaqTab"

type TabType = 'FEEDBACK' | 'SUPPORT' | 'FAQ'

interface ContactTabsProps {
  locale: string
  attractions: any[]
  faqs: any[]
}

export function ContactTabs({ locale, attractions, faqs }: ContactTabsProps) {

  const [activeTab, setActiveTab] = useState<TabType>('FAQ')

  const tabs: { id: TabType, icon: any, labelEn: string, labelAr: string }[] = [
    { id: 'FAQ', icon: HelpCircle, labelEn: 'FAQ', labelAr: 'الأسئلة الشائعة' },
    { id: 'SUPPORT', icon: LifeBuoy, labelEn: 'Support', labelAr: 'الدعم الفني' },
    { id: 'FEEDBACK', icon: MessageSquare, labelEn: 'Feedback', labelAr: 'الآراء والمقترحات' },
  ]

  return (
    <div className="bg-[var(--surface-default)] rounded-3xl border border-[var(--border-default)] shadow-lg overflow-hidden">
      
      {/* Tab Header */}
      <div className="flex border-b border-[var(--border-default)] overflow-x-auto no-scrollbar">
        {tabs.map((tab) => {
          const isActive = activeTab === tab.id
          const Icon = tab.icon
          return (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className="relative flex-1 flex items-center justify-center gap-2 py-6 px-4 min-w-[120px] transition-colors hover:bg-[var(--surface-hover)] focus:outline-none"
            >
              <Icon className={`w-5 h-5 transition-colors ${isActive ? 'text-[var(--color-primary)]' : 'text-[var(--text-tertiary)]'}`} />
              <span className={`font-bold transition-colors ${isActive ? 'text-[var(--text-primary)]' : 'text-[var(--text-secondary)]'}`}>
                {locale === 'ar' ? tab.labelAr : tab.labelEn}
              </span>
              
              {isActive && (
                <motion.div 
                  layoutId="activeTabIndicator"
                  className="absolute bottom-0 start-0 end-0 h-1 bg-[var(--color-primary)]"
                />
              )}
            </button>
          )
        })}
      </div>

      {/* Tab Content */}
      <div className="p-6 md:p-10 min-h-[500px]">
        <AnimatePresence mode="wait">
          
          {activeTab === 'FAQ' && (
            <motion.div
              key="FAQ"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.2 }}
            >
              <FaqTab 
                locale={locale} 
                faqs={faqs} 
                attractions={attractions} 
                onGoToSupport={() => setActiveTab('SUPPORT')} 
              />
            </motion.div>
          )}

          {activeTab === 'SUPPORT' && (
            <motion.div
              key="SUPPORT"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.2 }}
            >
              <SupportForm locale={locale} attractions={attractions} />
            </motion.div>
          )}

          {activeTab === 'FEEDBACK' && (
            <motion.div
              key="FEEDBACK"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.2 }}
            >
              <FeedbackForm locale={locale} attractions={attractions} />
            </motion.div>
          )}

        </AnimatePresence>
      </div>

    </div>
  )
}

"use client"

import { useState } from "react"
import { 
  DndContext, 
  DragOverlay, 
  closestCorners, 
  KeyboardSensor, 
  PointerSensor, 
  useSensor, 
  useSensors,
  DragStartEvent,
  DragEndEvent,
  useDroppable,
  useDraggable
} from "@dnd-kit/core"
import { sortableKeyboardCoordinates } from "@dnd-kit/sortable"
import { MoreHorizontal, Plus, X, Calendar, DollarSign, Percent, MessageSquare, ArrowRight, Save } from "lucide-react"
import { Button } from "@/components/ui/Button"
import { useRouter } from "next/navigation"
import { motion, AnimatePresence } from "framer-motion"

export type LeadStatus = "New" | "Contacted" | "Qualified" | "Proposal" | "Negotiation" | "Won" | "Lost"

export interface Lead {
  id: string
  name: string
  company: string
  value: string
  status: LeadStatus
  assigneeAvatar?: string
  probability?: number
}

interface KanbanBoardProps {
  initialLeads: Lead[]
}

const COLUMNS: LeadStatus[] = ["New", "Contacted", "Qualified", "Proposal", "Negotiation", "Won", "Lost"]

// --- Draggable Card Component ---
function KanbanCard({ lead, isOverlay, onClick }: { lead: Lead, isOverlay?: boolean, onClick?: () => void }) {
  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
    id: lead.id,
    data: { ...lead }
  })

  const style = transform ? {
    transform: `translate3d(${transform.x}px, ${transform.y}px, 0)`,
  } : undefined

  return (
    <div 
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      onClick={(_e) => {
        // Prevent click if we dragged
        if (!isDragging && onClick) onClick();
      }}
      className={`
        bg-[var(--surface-default)] p-4 rounded-xl border border-[var(--border-default)] shadow-sm cursor-grab active:cursor-grabbing
        hover:border-[var(--color-primary)]/50 transition-colors relative
        ${isDragging ? 'opacity-50' : ''}
        ${isOverlay ? 'shadow-2xl rotate-2 scale-105 opacity-100 z-50' : ''}
      `}
    >
      <div className="flex justify-between items-start mb-2">
        <h4 className="font-bold text-[var(--text-primary)] text-sm line-clamp-2 pe-6">{lead.name}</h4>
        <button 
          className="text-[var(--text-tertiary)] hover:text-[var(--text-primary)] absolute top-4 end-4"
          onClick={(e) => { e.stopPropagation(); onClick?.(); }}
        >
          <MoreHorizontal className="w-4 h-4" />
        </button>
      </div>
      <p className="text-xs text-[var(--text-secondary)] mb-4 line-clamp-1">{lead.company}</p>
      
      <div className="flex justify-between items-center mt-auto">
        <span className="text-sm font-black text-[var(--color-primary)]">{lead.value}</span>
        {lead.assigneeAvatar && (
          <img src={lead.assigneeAvatar} alt="Assignee" className="w-6 h-6 rounded-full border border-[var(--border-default)]" />
        )}
      </div>
    </div>
  )
}

// --- Droppable Column Component ---
function KanbanColumn({ id, title, leads, onLeadClick }: { id: LeadStatus, title: string, leads: Lead[], onLeadClick: (lead: Lead) => void }) {
  const { setNodeRef, isOver } = useDroppable({ id })

  return (
    <div 
      ref={setNodeRef}
