                <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Content (En)</label>
                <textarea 
                  value={data.story.contentEn}
                  onChange={e => handleChange('story', 'contentEn', e.target.value)}
                  className="w-full h-48 bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none resize-none"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Content (Ar)</label>
                <textarea 
                  dir="rtl"
                  value={data.story.contentAr}
                  onChange={e => handleChange('story', 'contentAr', e.target.value)}
                  className="w-full h-48 bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none resize-none"
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Media Type</label>
                <select 
                  value={data.story.mediaType}
                  onChange={e => handleChange('story', 'mediaType', e.target.value)}
                  className="w-full bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none"
                >
                  <option value="IMAGE">Image</option>
                  <option value="VIDEO">Video</option>
                  <option value="SPLINE">3D Model (Spline)</option>
                  <option value="IFRAME">Iframe (YouTube/Embed)</option>
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">
                  {['IMAGE', 'VIDEO'].includes(data.story.mediaType) ? 'Media Asset' : 'Media URL'}
                </label>
                {['IMAGE', 'VIDEO'].includes(data.story.mediaType) ? (
                  <AdminMediaPicker 
                    value={data.story.mediaUrl}
                    onChange={url => handleChange('story', 'mediaUrl', url)}
                    accept={data.story.mediaType === 'VIDEO' ? 'video/*' : 'image/*'}
                  />
                ) : (
                  <input 
                    type="url" 
                    value={data.story.mediaUrl}
                    onChange={e => handleChange('story', 'mediaUrl', e.target.value)}
                    placeholder={data.story.mediaType === 'IFRAME' ? "https://..." : "https://prod.spline.design/..."}
                    className="w-full h-[42px] bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none"
                  />
                )}
              </div>
            </div>

            {data.story.mediaType !== 'IMAGE' && (
              <div className="grid grid-cols-2 gap-6 mt-4">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">
                    Fallback Image / Poster
                  </label>
                  <p className="text-xs text-text-tertiary mb-2">Shows while loading, or as a poster frame.</p>
                  <AdminMediaPicker 
                    value={data.story.fallbackImageUrl}
                    onChange={url => handleChange('story', 'fallbackImageUrl', url)}
                    accept="image/*"
                  />
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Values Section */}
        <div className="bg-surface-default border border-border-default rounded-xl p-6 space-y-6">
          <div className="flex justify-between items-center">
            <h2 className="text-lg font-bold text-text-primary">Core Values</h2>
            <button 
              onClick={addValue}
              className="px-4 py-2 bg-surface-hover border border-border-default text-text-primary rounded-lg text-sm font-bold flex items-center hover:bg-surface-active"
            >
              <Plus size={16} className="me-2" />
              Add Value
            </button>
          </div>
          
          <div className="space-y-4">
            {data.values.map((val: any, idx: number) => (
              <div key={idx} className="p-4 bg-surface-hover border border-border-default rounded-lg relative">
                <button 
                  onClick={() => removeValue(idx)}
                  className="absolute top-4 end-4 p-2 text-text-tertiary hover:text-error hover:bg-error/10 rounded-md transition-colors"
                >
                  <Trash2 size={16} />
                </button>
                <div className="grid grid-cols-2 gap-4 pe-12">
                  <div className="space-y-2">
                    <label className="text-[10px] font-bold text-text-secondary uppercase tracking-wider">Title (En)</label>
                    <input 
                      type="text" 
                      value={val.titleEn}
                      onChange={e => updateValue(idx, 'titleEn', e.target.value)}
                      className="w-full bg-surface-default border border-border-default rounded-lg px-3 py-2 text-sm focus:border-primary focus:outline-none"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-bold text-text-secondary uppercase tracking-wider">Title (Ar)</label>
                    <input 
                      type="text" 
                      dir="rtl"
                      value={val.titleAr}
                      onChange={e => updateValue(idx, 'titleAr', e.target.value)}
                      className="w-full bg-surface-default border border-border-default rounded-lg px-3 py-2 text-sm focus:border-primary focus:outline-none"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-bold text-text-secondary uppercase tracking-wider">Description (En)</label>
                    <textarea 
                      value={val.descEn}
                      onChange={e => updateValue(idx, 'descEn', e.target.value)}
                      className="w-full h-20 bg-surface-default border border-border-default rounded-lg px-3 py-2 text-sm focus:border-primary focus:outline-none resize-none"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-bold text-text-secondary uppercase tracking-wider">Description (Ar)</label>
                    <textarea 
                      dir="rtl"
                      value={val.descAr}
                      onChange={e => updateValue(idx, 'descAr', e.target.value)}
                      className="w-full h-20 bg-surface-default border border-border-default rounded-lg px-3 py-2 text-sm focus:border-primary focus:outline-none resize-none"
                    />
                  </div>
                </div>
              </div>
            ))}
            {data.values.length === 0 && (
              <div className="text-center py-8 text-text-tertiary text-sm">
                No values added.
              </div>
            )}
          </div>
        </div>

        {/* SEO Customizer */}
        <AdminSeoCustomizer seo={seo} setSeo={setSeo} formData={null} setFormData={() => {}} />

      </AdminFormLayout>
    </div>
  )
}

"use client"

import { useState } from "react"
import { AdminFormLayout } from "../ui/AdminFormLayout"
import { AdminPageHeader } from "../ui/AdminPageHeader"
import { AdminButton } from "../ui/AdminButton"
import { useToast } from "@/components/dashboard/ui/ToastProvider"
import { MediaUploader } from "@/components/shared/MediaUploader"
import { Plus, Trash2 } from "lucide-react"

export function B2BFAQsEditor({ initialData }: { initialData: any }) {
  const [data, setData] = useState({
    header: {
      titleEn: initialData?.header?.titleEn || "Frequently Asked Questions",
      titleAr: initialData?.header?.titleAr || "الأسئلة الشائعة",
      subtitleEn: initialData?.header?.subtitleEn || "Find answers to commonly asked questions.",
      subtitleAr: initialData?.header?.subtitleAr || "اعثر على إجابات للأسئلة المتداولة.",
      mediaType: initialData?.header?.mediaType || "IMAGE",
      mediaUrl: initialData?.header?.mediaUrl || "",
    },
    items: Array.isArray(initialData?.items) ? initialData.items : []
  })

  const { toast } = useToast()
  const [saving, setSaving] = useState(false)

  const handleSave = async () => {
    setSaving(true)
    try {
      const res = await fetch('/api/cms/pages/b2b-faqs', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ content: data })
      })
      if (!res.ok) throw new Error("Failed to save")
      toast("B2B FAQs page updated successfully.", "success")
    } catch (e) {
      console.error(e)
      toast("Failed to save B2B FAQs page.", "error")
    } finally {
      setSaving(false)
    }
  }

  const handleHeaderChange = (field: string, value: any) => {
    setData(prev => ({
      ...prev,
      header: { ...prev.header, [field]: value }
    }))
  }

  const addFaq = () => {
    setData(prev => ({
      ...prev,
      items: [...prev.items, { questionEn: "", questionAr: "", answerEn: "", answerAr: "" }]
    }))
  }

  const removeFaq = (index: number) => {
    setData(prev => {
      const newItems = [...prev.items]
      newItems.splice(index, 1)
      return { ...prev, items: newItems }
    })
  }

  const updateFaq = (index: number, field: string, value: string) => {
    setData(prev => {
      const newItems = [...prev.items]
      newItems[index] = { ...newItems[index], [field]: value }
      return { ...prev, items: newItems }
    })
  }

  return (
    <div className="flex flex-col gap-6 h-full p-6">
      <AdminPageHeader 
        title="B2B FAQs Editor"
        description="Manage the Frequently Asked Questions for the B2B portal."
        action={
          <AdminButton variant="primary" onClick={handleSave} disabled={saving}>
            {saving ? "Saving..." : "Save Changes"}
          </AdminButton>
        }
      />

      <AdminFormLayout>
        {/* Header Section */}
        <div className="bg-surface-default border border-border-default rounded-xl p-6 space-y-6">
          <h2 className="text-lg font-bold text-text-primary">Header Section</h2>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <div className="space-y-4">
              <div className="space-y-2">
                <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Title (En)</label>
                <input type="text" value={data.header.titleEn} onChange={e => handleHeaderChange('titleEn', e.target.value)} className="w-full bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none" />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Title (Ar)</label>
                <input type="text" dir="rtl" value={data.header.titleAr} onChange={e => handleHeaderChange('titleAr', e.target.value)} className="w-full bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none" />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Subtitle (En)</label>
                <textarea value={data.header.subtitleEn} onChange={e => handleHeaderChange('subtitleEn', e.target.value)} className="w-full h-24 bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none resize-none" />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Subtitle (Ar)</label>
                <textarea dir="rtl" value={data.header.subtitleAr} onChange={e => handleHeaderChange('subtitleAr', e.target.value)} className="w-full h-24 bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none resize-none" />
              </div>
            </div>
            
            <div className="space-y-4 border-t lg:border-t-0 lg:border-s border-border-default pt-4 lg:pt-0 lg:ps-6">
              <div className="space-y-2">
                <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Background Media Type</label>
                <select value={data.header.mediaType} onChange={e => handleHeaderChange('mediaType', e.target.value)} className="w-full bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none">
                  <option value="IMAGE">Image</option>
                  <option value="VIDEO">Video</option>
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Upload Background</label>
                <MediaUploader value={data.header.mediaUrl} onChange={(url) => handleHeaderChange('mediaUrl', url)} accept={data.header.mediaType === 'VIDEO' ? "video/*" : "image/*"} />
              </div>
            </div>
          </div>
        </div>

        {/* FAQs Section */}
        <div className="bg-surface-default border border-border-default rounded-xl p-6 space-y-6">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-bold text-text-primary">FAQ Items</h2>
            <AdminButton variant="outline" size="sm" onClick={addFaq}>
              <Plus className="w-4 h-4 me-2" />
              Add FAQ
            </AdminButton>
          </div>
          
          <div className="space-y-4">
            {data.items.length === 0 ? (
              <div className="text-center py-8 text-text-secondary border border-dashed border-border-default rounded-lg">
                No FAQs added yet.
              </div>
            ) : (
              data.items.map((item: any, index: number) => (
                <div key={index} className="border border-border-default rounded-lg p-4 bg-surface-hover space-y-4 relative group">
                  <button onClick={() => removeFaq(index)} className="absolute top-4 end-4 text-text-secondary hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100">
                    <Trash2 className="w-4 h-4" />
                  </button>
                  <h3 className="text-sm font-bold text-text-secondary uppercase tracking-wider">Question {index + 1}</h3>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Question (En)</label>
                      <input type="text" value={item.questionEn} onChange={e => updateFaq(index, 'questionEn', e.target.value)} className="w-full bg-surface-default border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Question (Ar)</label>
                      <input type="text" dir="rtl" value={item.questionAr} onChange={e => updateFaq(index, 'questionAr', e.target.value)} className="w-full bg-surface-default border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Answer (En)</label>
                      <textarea value={item.answerEn} onChange={e => updateFaq(index, 'answerEn', e.target.value)} className="w-full h-24 bg-surface-default border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none resize-none" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Answer (Ar)</label>
                      <textarea dir="rtl" value={item.answerAr} onChange={e => updateFaq(index, 'answerAr', e.target.value)} className="w-full h-24 bg-surface-default border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none resize-none" />
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

      </AdminFormLayout>
    </div>
  )
}

"use client"

import * as React from "react"
import { AdminFormLayout } from "@/components/dashboard/ui/AdminFormLayout"
import { AdminFormSection, AdminFormGrid } from "@/components/dashboard/ui/AdminFormSection"
import { AdminInput } from "@/components/dashboard/ui/AdminInput"
import { AdminTextarea } from "@/components/dashboard/ui/AdminTextarea"
import { AdminButton } from "@/components/dashboard/ui/AdminButton"
import { AdminMediaPicker } from "@/components/dashboard/ui/AdminMediaPicker"
import { useToast } from "@/components/dashboard/ui/ToastProvider"
import { Save } from "lucide-react"

import { AdminPageHeader } from "@/components/dashboard/ui/AdminPageHeader"
import { AdminSeoCustomizer } from "@/components/dashboard/ui/AdminSeoCustomizer"

export function B2BHomeEditor({ 
  initialData,
  services = [],
  caseStudies = []
}: { 
  initialData: any
  services?: any[]
  caseStudies?: any[]
}) {
  const [isSaving, setIsSaving] = React.useState(false)
  const { toast } = useToast()

  // State
  const [activeLang, setActiveLang] = React.useState<'en' | 'ar'>('en')
  const [hero, setHero] = React.useState(initialData.content?.hero || {})
  const [stats, setStats] = React.useState<any[]>(initialData.content?.stats || [])
  const [wowAndHow, setWowAndHow] = React.useState(initialData.content?.wowAndHow || {})
  const [featuredServiceIds, setFeaturedServiceIds] = React.useState<string[]>(initialData.content?.featuredServiceIds || [])
  const [featuredCaseStudyIds, setFeaturedCaseStudyIds] = React.useState<string[]>(initialData.content?.featuredCaseStudyIds || [])
  const [seo, setSeo] = React.useState<any>(initialData.seo || {})

  const handleSave = async () => {
    setIsSaving(true)
    try {
      const res = await fetch('/api/cms/pages/b2b-home', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          content: { 
            hero, 
            stats, 
            wowAndHow,
            featuredServiceIds,
            featuredCaseStudyIds
          },
          seo
        })
      })

      if (!res.ok) throw new Error("Failed to save")
      
      toast("Homepage content updated successfully", "success")
    } catch {
      toast("Failed to update homepage content", "error")
    } finally {
      setIsSaving(false)
    }
  }

  return (
    <div className="flex flex-col w-full h-full gap-6">
      <AdminPageHeader
        title="B2B Homepage Editor"
        description="Manage the content blocks on the main B2B corporate portal."
        action={
          <AdminButton 
            variant="primary" 
            leftIcon={<Save className="w-4 h-4" />}
            onClick={handleSave}
            isLoading={isSaving}
          >
            Save Changes
          </AdminButton>
        }
      />
      <AdminFormLayout>
      <div className="space-y-8">
        {/* LANGUAGE SWITCHER */}
        <div className="flex bg-surface-default p-1 rounded-md w-fit border border-border-default">
          <button
            type="button"
            onClick={() => setActiveLang('en')}
            className={`px-4 py-2 text-sm font-semibold rounded-sm transition-colors ${activeLang === 'en' ? 'bg-primary text-white' : 'text-text-secondary hover:text-text-primary'}`}
          >
            English
          </button>
          <button
            type="button"
            onClick={() => setActiveLang('ar')}
            className={`px-4 py-2 text-sm font-semibold rounded-sm transition-colors ${activeLang === 'ar' ? 'bg-primary text-white' : 'text-text-secondary hover:text-text-primary'}`}
          >
            العربية
          </button>
        </div>

        {/* HERO SECTION */}
        <AdminFormSection id="hero" title="Hero Section" description="The main introduction at the top of the page.">
          <AdminFormGrid>
            <div className="sm:col-span-2 space-y-2">
              <label className="block text-sm font-semibold text-text-primary">Hero Background Media Type</label>
              <select
                value={hero.mediaType || "IMAGE"}
                onChange={e => setHero({ ...hero, mediaType: e.target.value })}
                className="w-full bg-surface-hover border border-border-default rounded-md px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none mb-2"
              >
                <option value="IMAGE">Image</option>
                <option value="VIDEO">Video</option>
                <option value="IFRAME">External iFrame</option>
                <option value="SPLINE">Spline / 3D Scene</option>
              </select>

              {(hero.mediaType === 'IFRAME' || hero.mediaType === 'SPLINE') ? (
                <input 
                  type="text" 
                  value={hero.mediaUrl || ''} 
                  onChange={e => setHero({ ...hero, mediaUrl: e.target.value })} 
                  placeholder="https://..." 
                  className="w-full bg-surface-hover border border-border-default rounded-md px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none"
                />
              ) : (
                <AdminMediaPicker
                  label="Upload Media"
                  value={hero.mediaUrl || hero.backgroundImage || ""}
                  onChange={url => setHero({ ...hero, mediaUrl: url, backgroundImage: url })}
                  accept={hero.mediaType === 'VIDEO' ? 'video/*' : 'image/*'}
                />
              )}
            </div>
            <div className="sm:col-span-2">
              <AdminInput 
                label="Headline" 
                value={activeLang === 'en' ? (hero.title || "") : (hero.titleAr || "")} 
                onChange={e => setHero({ ...hero, [activeLang === 'en' ? 'title' : 'titleAr']: e.target.value })} 
                placeholder="e.g. Ideas to Life"
              />
            </div>
            <div className="sm:col-span-2">
              <AdminTextarea 
                label="Subtitle" 
                value={activeLang === 'en' ? (hero.subtitle || "") : (hero.subtitleAr || "")} 
                onChange={e => setHero({ ...hero, [activeLang === 'en' ? 'subtitle' : 'subtitleAr']: e.target.value })} 
                placeholder="Short punchy text"
                rows={2}
              />
            </div>
            <div className="sm:col-span-2">
              <AdminTextarea 
                label="Description" 
                value={activeLang === 'en' ? (hero.description || "") : (hero.descriptionAr || "")} 
                onChange={e => setHero({ ...hero, [activeLang === 'en' ? 'description' : 'descriptionAr']: e.target.value })} 
                placeholder="Longer descriptive text..."
                rows={3}
              />
            </div>
            <AdminInput 
              label="Primary CTA Label" 
              value={activeLang === 'en' ? (hero.primaryCta || "") : (hero.primaryCtaAr || "")} 
              onChange={e => setHero({ ...hero, [activeLang === 'en' ? 'primaryCta' : 'primaryCtaAr']: e.target.value })} 
            />
            <AdminInput 
              label="Primary CTA Link" 
              value={hero.primaryLink || ""} 
              onChange={e => setHero({ ...hero, primaryLink: e.target.value })} 
            />
            <AdminInput 
              label="Secondary CTA Label" 
              value={activeLang === 'en' ? (hero.secondaryCta || "") : (hero.secondaryCtaAr || "")} 
              onChange={e => setHero({ ...hero, [activeLang === 'en' ? 'secondaryCta' : 'secondaryCtaAr']: e.target.value })} 
            />
            <AdminInput 
              label="Secondary CTA Link" 
              value={hero.secondaryLink || ""} 
              onChange={e => setHero({ ...hero, secondaryLink: e.target.value })} 
            />
          </AdminFormGrid>
        </AdminFormSection>

        {/* STATS SECTION */}
        <AdminFormSection id="stats" title="Credibility Stats" description="The statistics displayed prominently on the board.">
          <div className="space-y-4">
            <div className="flex justify-end mb-2">
              <button 
                onClick={() => setStats([...stats, { value: '', label: '' }])}
                className="text-xs font-bold bg-primary text-white px-3 py-1.5 rounded-md hover:bg-primary/90 transition-colors"
              >
                + Add Stat
              </button>
            </div>
            {stats.map((stat, idx) => (
              <div key={idx} className="flex gap-4 p-4 border border-border-default rounded-md bg-surface-active relative">
                <button 
                  onClick={() => {
                    const newStats = [...stats]
                    newStats.splice(idx, 1)
                    setStats(newStats)
                  }}
                  className="absolute top-2 end-2 text-text-tertiary hover:text-error transition-colors"
                >
                  &times;
                </button>
                <div className="w-1/3">
                  <AdminInput 
                    label="Value" 
                    value={activeLang === 'en' ? (stat.value || "") : (stat.valueAr || stat.value || "")} 
                    onChange={e => {
                      const newStats = [...stats]
                      newStats[idx][activeLang === 'en' ? 'value' : 'valueAr'] = e.target.value
                      setStats(newStats)
                    }} 
                    placeholder="e.g. 50+"
                  />
                </div>
                <div className="w-2/3">
                  <AdminInput 
                    label="Label" 
                    value={activeLang === 'en' ? (stat.label || "") : (stat.labelAr || stat.label || "")} 
                    onChange={e => {
                      const newStats = [...stats]
                      newStats[idx][activeLang === 'en' ? 'label' : 'labelAr'] = e.target.value
                      setStats(newStats)
                    }} 
                    placeholder="e.g. Years Experience"
                  />
                </div>
              </div>
            ))}
          </div>
        </AdminFormSection>

