"use client"

import { useState } from "react"
import { AdminFormLayout } from "../ui/AdminFormLayout"
import { AdminPageHeader } from "../ui/AdminPageHeader"
import { AdminButton } from "../ui/AdminButton"
import { useToast } from "@/components/dashboard/ui/ToastProvider"
import { MediaUploader } from "@/components/shared/MediaUploader"

export function B2BPartnersEditor({ initialData }: { initialData: any }) {
  const [data, setData] = useState({
    hero: {
      titleEn: initialData?.hero?.titleEn || "Trusted by the Best.",
      titleAr: initialData?.hero?.titleAr || "يحظى بثقة الأفضل.",
      subtitleEn: initialData?.hero?.subtitleEn || "We partner with ambitious government entities, global brands, and premier destinations to deliver experiences that matter.",
      subtitleAr: initialData?.hero?.subtitleAr || "نحن نتشارك مع هيئات حكومية طموحة، وعلامات تجارية عالمية، ووجهات رائدة لتقديم تجارب تهم.",
      mediaType: initialData?.hero?.mediaType || "IMAGE",
      mediaUrl: initialData?.hero?.mediaUrl || "",
    }
  })

  const { toast } = useToast()
  const [saving, setSaving] = useState(false)

  const handleSave = async () => {
    setSaving(true)
    try {
      const res = await fetch('/api/cms/pages/b2b-partners', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ content: data })
      })
      if (!res.ok) throw new Error("Failed to save")
      toast("B2B Partners page updated successfully.", "success")
    } catch (e) {
      console.error(e)
      toast("Failed to save B2B Partners page.", "error")
    } finally {
      setSaving(false)
    }
  }

  const handleChange = (section: keyof typeof data, field: string, value: any) => {
    setData(prev => ({
      ...prev,
      [section]: {
        ...(prev[section] as any),
        [field]: value
      }
    }))
  }

  return (
    <div className="flex flex-col gap-6 h-full p-6">
      <AdminPageHeader 
        title="Client Page Editor"
        description="Manage the main clients index page hero section."
        action={
          <AdminButton variant="primary" onClick={handleSave} disabled={saving}>
            {saving ? "Saving..." : "Save Changes"}
          </AdminButton>
        }
      />

      <AdminFormLayout>
        {/* Hero Section */}
        <div className="bg-surface-default border border-border-default rounded-xl p-6 space-y-6">
          <h2 className="text-lg font-bold text-text-primary">Hero Section</h2>
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Title (En)</label>
                <input 
                  type="text" 
                  value={data.hero.titleEn}
                  onChange={e => handleChange('hero', 'titleEn', e.target.value)}
                  className="w-full bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Title (Ar)</label>
                <input 
                  type="text" 
                  dir="rtl"
                  value={data.hero.titleAr}
                  onChange={e => handleChange('hero', 'titleAr', e.target.value)}
                  className="w-full bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Subtitle (En)</label>
                <textarea 
                  value={data.hero.subtitleEn}
                  onChange={e => handleChange('hero', 'subtitleEn', e.target.value)}
                  className="w-full h-24 bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none resize-none"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Subtitle (Ar)</label>
                <textarea 
                  dir="rtl"
                  value={data.hero.subtitleAr}
                  onChange={e => handleChange('hero', 'subtitleAr', e.target.value)}
                  className="w-full h-24 bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none resize-none"
                />
              </div>
            </div>
            
            <div className="grid grid-cols-2 gap-6 pt-4 border-t border-border-default">
              <div className="space-y-2">
                <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Background Media Type</label>
                <select 
                  value={data.hero.mediaType}
                  onChange={e => handleChange('hero', 'mediaType', e.target.value)}
                  className="w-full bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none"
                >
                  <option value="IMAGE">Image</option>
                  <option value="VIDEO">Video</option>
                  <option value="SPLINE">Spline / 3D Scene</option>
                  <option value="IFRAME">iFrame Embed</option>
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Media URL / Source</label>
                {['IFRAME', 'SPLINE'].includes(data.hero.mediaType) ? (
                  <input 
                    type="text" 
                    value={data.hero.mediaUrl}
                    onChange={e => handleChange('hero', 'mediaUrl', e.target.value)}
                    placeholder="https://..."
                    className="w-full bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none"
                  />
                ) : (
                  <MediaUploader 
                    value={data.hero.mediaUrl} 
                    onChange={url => handleChange('hero', 'mediaUrl', url)} 
                    accept={data.hero.mediaType === 'VIDEO' ? "video/*" : "image/*"}
                  />
                )}
              </div>
            </div>
          </div>
        </div>
      </AdminFormLayout>
    </div>
  )
}

"use client"

import { useState, useRef, useEffect, useCallback } from "react"
import { Sparkles } from "lucide-react"

interface BeforeAfterSliderProps {
  beforeImage: string
  afterImage: string
  beforeLabel?: string
  afterLabel?: string
}

export function BeforeAfterSlider({
  beforeImage,
  afterImage,
  beforeLabel = "Before",
  afterLabel = "After"
}: BeforeAfterSliderProps) {
  const [sliderPosition, setSliderPosition] = useState(50)
  const [isDragging, setIsDragging] = useState(false)
  const containerRef = useRef<HTMLDivElement>(null)

  const handleMove = useCallback((clientX: number) => {
    if (!containerRef.current) return
    const rect = containerRef.current.getBoundingClientRect()
    const x = clientX - rect.left
    let position = (x / rect.width) * 100
    if (position < 0) position = 0
    if (position > 100) position = 100
    setSliderPosition(position)
  }, [])

  const handleTouchMove = useCallback((e: TouchEvent) => {
    if (!isDragging) return
    handleMove(e.touches[0].clientX)
  }, [isDragging, handleMove])

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!isDragging) return
    handleMove(e.clientX)
  }, [isDragging, handleMove])

  const handleMouseUp = useCallback(() => {
    setIsDragging(false)
  }, [])

  useEffect(() => {
    if (isDragging) {
      window.addEventListener("mousemove", handleMouseMove)
      window.addEventListener("mouseup", handleMouseUp)
      window.addEventListener("touchmove", handleTouchMove)
      window.addEventListener("touchend", handleMouseUp)
    }

    return () => {
      window.removeEventListener("mousemove", handleMouseMove)
      window.removeEventListener("mouseup", handleMouseUp)
      window.removeEventListener("touchmove", handleTouchMove)
      window.removeEventListener("touchend", handleMouseUp)
    }
  }, [isDragging, handleMouseMove, handleMouseUp, handleTouchMove])

  const [containerWidth, setContainerWidth] = useState<number | string>('100%')

  useEffect(() => {
    if (!containerRef.current) return
    const observer = new ResizeObserver((entries) => {
      for (const entry of entries) {
        setContainerWidth(entry.contentRect.width)
      }
    })
    observer.observe(containerRef.current)
    return () => observer.disconnect()
  }, [])

  return (
    <div 
      ref={containerRef}
      className="relative w-full overflow-hidden select-none touch-none rounded-xl border border-border-default shadow-inner"
      style={{ aspectRatio: '16/9' }}
      onMouseMove={handleMouseMove as any}
      onTouchMove={(e) => handleMove(e.touches[0].clientX)}
      onMouseDown={() => setIsDragging(true)}
      onMouseUp={() => setIsDragging(false)}
      onMouseLeave={() => setIsDragging(false)}
      onTouchStart={(e) => {
        setIsDragging(true)
        handleMove(e.touches[0].clientX)
      }}
    >
      {/* After Image (Background) */}
      <img 
        src={afterImage} 
        alt="After" 
        className="absolute inset-0 w-full h-full object-cover pointer-events-none"
      />
      <div className="absolute top-4 end-4 bg-zinc-950/60 backdrop-blur-md text-white px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider z-10 pointer-events-none">
        {afterLabel}
      </div>

      {/* Before Image (Foreground, clipped) */}
      <div 
        className="absolute inset-0 overflow-hidden pointer-events-none"
        style={{ width: `${sliderPosition}%` }}
      >
        <img 
          src={beforeImage} 
          alt="Before" 
          className="absolute inset-0 h-full object-cover"
          style={{ width: containerWidth, maxWidth: 'none' }}
        />
        <div className="absolute top-4 start-4 bg-white/80 backdrop-blur-md text-zinc-950 px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider z-10">
          {beforeLabel}
        </div>
      </div>

      {/* Slider Handle Divider */}
      <div 
        className="absolute top-0 bottom-0 w-1 bg-white hover:bg-accent cursor-ew-resize z-20"
        style={{ left: `${sliderPosition}%`, transform: "translateX(-50%)" }}
      >
        <div className="absolute top-1/2 start-1/2 -translate-x-1/2 -translate-y-1/2 w-8 h-8 rounded-full bg-white hover:bg-accent hover:text-white text-text-secondary shadow-md border border-border-default flex items-center justify-center transition-colors">
          <Sparkles className="w-4 h-4 animate-pulse" />
        </div>
      </div>
    </div>
  )
}

"use client"

import { useState } from "react"
import Link from "next/link"
import { Plus, Search, Edit2, Trash2, Globe, Sparkles, FolderKanban } from "lucide-react"
import { Button } from "@/components/ui/Button"
import { Badge } from "@/components/ui/Badge"
import { useRouter } from "next/navigation"

interface CaseStudy {
  id: string
  slug: string
  title: any // JSON { en: string, ar: string }
  clientName: string
  category: any // JSON string[]
  year: number
  isPublished: boolean
  isFeatured: boolean
}

interface CasesListProps {
  initialCases: CaseStudy[]
}

export function CasesList({ initialCases }: CasesListProps) {
  const [cases, setCases] = useState<CaseStudy[]>(initialCases)
  const [searchTerm, setSearchTerm] = useState("")
  const [isDeletingId, setIsDeletingId] = useState<string | null>(null)
  const router = useRouter()

  const handleToggle = async (id: string, field: "isPublished" | "isFeatured", currentValue: boolean) => {
    // Optimistic Update
    setCases(prev => prev.map(c => c.id === id ? { ...c, [field]: !currentValue } : c))

    try {
      const res = await fetch(`/api/cases/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ [field]: !currentValue })
      })

      if (!res.ok) throw new Error()
      router.refresh()
    } catch {
      // Revert if error
      setCases(prev => prev.map(c => c.id === id ? { ...c, [field]: currentValue } : c))
    }
  }

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this case study?")) return

    setIsDeletingId(id)
    try {
      const res = await fetch(`/api/cases/${id}`, { method: "DELETE" })
      if (!res.ok) throw new Error()
      setCases(prev => prev.filter(c => c.id !== id))
      router.refresh()
    } catch {
      alert("Failed to delete case study")
    } finally {
      setIsDeletingId(null)
    }
  }

  const filteredCases = cases.filter(c => {
    const titleEn = c.title?.en || ""
    const titleAr = c.title?.ar || ""
    const tags = Array.isArray(c.category) ? c.category.join(" ") : ""
    const matchString = `${titleEn} ${titleAr} ${c.clientName} ${tags} ${c.year}`.toLowerCase()
    return matchString.includes(searchTerm.toLowerCase())
  })

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-text-primary">Case Studies & Portfolios</h1>
          <p className="text-sm text-text-secondary">Manage E3&apos;s corporate credibility proofs and event engineering portfolio.</p>
        </div>
        <Link href="/dashboard/b2b/cases/new">
          <Button className="gap-2">
            <Plus className="w-4 h-4" /> Create Case Study
          </Button>
        </Link>
      </div>

      {/* Filter and Search Bar */}
      <div className="flex gap-4 items-center bg-surface-default p-4 rounded-xl border border-border-default">
        <div className="relative flex-1">
          <Search className="absolute start-3 top-2.5 h-4 w-4 text-text-tertiary" />
          <input
            type="text"
            placeholder="Search by title, client, tags, or execution year..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-surface-hover border border-border-default rounded-lg py-2 ps-10 pe-4 text-sm focus:border-accent outline-none text-text-primary"
          />
        </div>
      </div>

      {/* Case Studies Grid/List */}
      {filteredCases.length === 0 ? (
        <div className="border border-dashed border-border-default rounded-xl p-12 text-center bg-surface-default">
          <FolderKanban className="w-12 h-12 mx-auto text-text-tertiary mb-4" />
          <p className="text-sm font-bold text-text-primary mb-1">No case studies found</p>
          <p className="text-xs text-text-secondary">Get started by building E3&apos;s first activation showcase.</p>
        </div>
      ) : (
        <div className="bg-surface-default border border-border-default rounded-xl overflow-hidden shadow-sm">
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="border-b border-border-default bg-surface-hover text-text-secondary text-xs font-bold uppercase">
                  <th className="px-6 py-4">Showcase Info</th>
                  <th className="px-6 py-4">Client</th>
                  <th className="px-6 py-4">Year</th>
                  <th className="px-6 py-4">Tags</th>
                  <th className="px-6 py-4 text-center">Status</th>
                  <th className="px-6 py-4 text-center">Featured</th>
                  <th className="px-6 py-4 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border-default text-sm text-text-primary">
                {filteredCases.map(c => {
                  const titleEn = c.title?.en || "Untitled Showcase"
                  const titleAr = c.title?.ar || ""
                  const tags = Array.isArray(c.category) ? c.category : []

                  return (
                    <tr key={c.id} className="hover:bg-surface-hover transition-colors">
                      <td className="px-6 py-4">
                        <div className="font-bold">{titleEn}</div>
                        {titleAr && <div className="text-xs text-text-tertiary text-right font-medium" dir="rtl">{titleAr}</div>}
                        <div className="text-xs text-text-secondary font-mono">/{c.slug}</div>
                      </td>
                      <td className="px-6 py-4 font-medium text-text-secondary">
                        {c.clientName}
                      </td>
                      <td className="px-6 py-4 font-mono font-bold">
                        {c.year}
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex flex-wrap gap-1">
                          {tags.slice(0, 3).map((tag, idx) => (
                            <Badge key={idx} variant="default" className="text-xs">
                              {tag}
                            </Badge>
                          ))}
                          {tags.length > 3 && <span className="text-xs text-text-tertiary">+{tags.length - 3}</span>}
                        </div>
                      </td>
                      <td className="px-6 py-4 text-center">
                        <button
                          onClick={() => handleToggle(c.id, "isPublished", c.isPublished)}
                          className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold transition-all
                            ${c.isPublished
                              ? "bg-green-500/10 text-green-500 border border-green-500/20"
                              : "bg-border-default text-text-tertiary border border-transparent"
                            }
                          `}
                        >
                          <Globe className="w-3.5 h-3.5" />
                          {c.isPublished ? "Live" : "Draft"}
                        </button>
                      </td>
                      <td className="px-6 py-4 text-center">
                        <button
                          onClick={() => handleToggle(c.id, "isFeatured", c.isFeatured)}
                          className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold transition-all
                            ${c.isFeatured
                              ? "bg-amber-500/10 text-amber-500 border border-amber-500/20"
                              : "bg-border-default text-text-tertiary border border-transparent"
                            }
                          `}
                        >
                          <Sparkles className="w-3.5 h-3.5" />
                          {c.isFeatured ? "Featured" : "Standard"}
                        </button>
                      </td>
                      <td className="px-6 py-4 text-right">
                        <div className="flex justify-end gap-2">
                          <Link href={`/dashboard/b2b/cases/${c.id}/edit`}>
                            <button className="p-2 text-text-secondary hover:text-accent transition-colors rounded-lg hover:bg-surface-hover">
                              <Edit2 className="w-4 h-4" />
                            </button>
                          </Link>
                          <button
                            onClick={() => handleDelete(c.id)}
                            disabled={isDeletingId === c.id}
                            className="p-2 text-text-secondary hover:text-red-500 transition-colors rounded-lg hover:bg-surface-hover disabled:opacity-50"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import { useState } from "react"
import { useRouter } from "next/navigation"
import { Plus, Trash2, Edit2, CheckCircle2, XCircle, Search, ExternalLink, Briefcase } from "lucide-react"
import { AdminButton } from "../ui/AdminButton"
import { AdminPageHeader } from "../ui/AdminPageHeader"
import { MediaUploader } from "@/components/shared/MediaUploader"

export function PartnersClient({ initialData }: { initialData: any[] }) {
  const router = useRouter()
  const [partners, setPartners] = useState(initialData)
  const [search, setSearch] = useState("")
  const [isEditing, setIsEditing] = useState<string | null>(null)
  const [editForm, setEditForm] = useState<any>({})
  const [isSaving, setIsSaving] = useState(false)

  const filteredPartners = partners.filter(p => 
    p.name.toLowerCase().includes(search.toLowerCase()) || 
    p.category.toLowerCase().includes(search.toLowerCase())
  )

  const handleAddNew = () => {
    setEditForm({
      name: "",
      website: "",
      category: "TECHNOLOGY",
      description: "",
      logoUrl: "",
      isVisible: true,
      orderIndex: 0
    })
    setIsEditing("new")
  }

  const handleEdit = (partner: any) => {
    setEditForm({ ...partner })
    setIsEditing(partner.id)
  }

  const handleSave = async () => {
    if (!editForm.name) {
      alert("Name is required")
      return
    }

    setIsSaving(true)
    try {
      const isNew = isEditing === "new"
      const url = isNew ? `/api/b2b/partners` : `/api/b2b/partners/${isEditing}`
      const method = isNew ? "POST" : "PUT"

      const res = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(editForm)
      })

      if (!res.ok) throw new Error("Failed to save")

      const data = await res.json()
      
      if (isNew) {
        setPartners([...partners, data.partner])
      } else {
        setPartners(partners.map(p => p.id === isEditing ? data.partner : p))
      }

      setIsEditing(null)
      router.refresh()
    } catch {
      alert("Failed to save partner")
    } finally {
      setIsSaving(false)
    }
  }

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this partner?")) return

    try {
      const res = await fetch(`/api/b2b/partners/${id}`, { method: "DELETE" })
      if (!res.ok) throw new Error("Failed to delete")
      
      setPartners(partners.filter(p => p.id !== id))
      router.refresh()
    } catch {
      alert("Failed to delete partner")
    }
  }

  return (
    <div className="flex flex-col gap-6 h-full p-6">
      <AdminPageHeader 
        title="Clients CMS"
        description="Manage corporate clients, government partners, and agencies."
        action={
          <AdminButton variant="primary" leftIcon={<Plus className="w-4 h-4" />} onClick={handleAddNew}>
            Add Client
          </AdminButton>
        }
      />

      <div className="relative">
        <Search className="absolute start-3 top-1/2 -translate-y-1/2 w-5 h-5 text-text-tertiary" />
        <input 
          type="text" 
          value={search}
          onChange={e => setSearch(e.target.value)}
          placeholder="Search partners..."
          className="w-full bg-surface-default border border-border-default rounded-xl py-3 ps-10 pe-4 text-text-primary focus:outline-none focus:border-primary transition-colors"
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredPartners.map(partner => (
          <div key={partner.id} className="bg-surface-default border border-border-default rounded-2xl overflow-hidden hover:border-primary/30 transition-colors flex flex-col group relative">
            <div className="aspect-[3/2] bg-surface-hover flex items-center justify-center p-6 relative border-b border-border-default">
              {partner.logoUrl ? (
                <img src={partner.logoUrl} alt={partner.name} className="max-w-full max-h-full object-contain grayscale opacity-70 group-hover:grayscale-0 group-hover:opacity-100 transition-all" />
              ) : (
                <div className="text-text-tertiary font-bold flex flex-col items-center gap-2">
                  <Briefcase className="w-8 h-8 opacity-50" />
                  <span>{partner.name}</span>
                </div>
              )}
              <div className="absolute top-3 end-3 flex items-center gap-2">
                {partner.isVisible ? (
                  <CheckCircle2 className="w-5 h-5 text-emerald-500 bg-surface-active rounded-full" />
                ) : (
                  <XCircle className="w-5 h-5 text-text-tertiary bg-surface-active rounded-full" />
                )}
              </div>
            </div>
            
            <div className="p-5 flex-1 flex flex-col">
              <div className="flex items-start justify-between gap-4 mb-2">
                <div>
                  <h3 className="font-bold text-text-primary line-clamp-1">{partner.name}</h3>
                  <div className="text-xs font-bold text-primary mt-1 tracking-wider uppercase">{partner.category.replace(/_/g, ' ')}</div>
                </div>
              </div>
              
              {partner.description && (
                <p className="text-sm text-text-secondary line-clamp-2 mt-2">{partner.description}</p>
              )}
              
              <div className="mt-auto pt-4 flex items-center justify-between border-t border-border-default">
                {partner.website ? (
                  <a href={partner.website} target="_blank" rel="noreferrer" className="text-xs text-text-tertiary hover:text-primary flex items-center gap-1">
                    <ExternalLink className="w-3 h-3" /> Visit Site
                  </a>
                ) : <span />}
                
                <div className="flex items-center gap-1">
                  <button onClick={() => handleEdit(partner)} className="p-2 text-text-secondary hover:text-primary bg-surface-subtle hover:bg-primary/10 rounded-lg transition-colors">
                    <Edit2 className="w-4 h-4" />
                  </button>
                  <button onClick={() => handleDelete(partner.id)} className="p-2 text-text-secondary hover:text-error bg-surface-subtle hover:bg-error/10 rounded-lg transition-colors">
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </div>
            </div>
          </div>
        ))}

        {filteredPartners.length === 0 && (
          <div className="col-span-full py-12 text-center text-text-tertiary border-2 border-dashed border-border-default rounded-2xl font-medium">
            No partners found. Click &quot;Add Client&quot; to get started.
          </div>
        )}
      </div>

      {isEditing && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-zinc-950/80 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-surface-default border border-border-default rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="sticky top-0 bg-surface-default/80 backdrop-blur-md border-b border-border-default px-6 py-4 flex items-center justify-between z-10">
              <h2 className="text-xl font-bold text-text-primary">
                {isEditing === "new" ? "Add Client" : "Edit Client"}
              </h2>
              <button onClick={() => setIsEditing(null)} className="p-2 text-text-tertiary hover:text-text-primary rounded-lg transition-colors">
                <XCircle className="w-6 h-6" />
              </button>
            </div>
            
            <div className="p-6 space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-bold text-text-secondary">Name *</label>
                  <input 
                    type="text" 
                    value={editForm.name} 
                    onChange={e => setEditForm({...editForm, name: e.target.value})}
                    className="w-full bg-surface-hover border border-border-default rounded-xl px-4 py-3 focus:outline-none focus:border-primary text-text-primary" 
                    placeholder="e.g. Qatar Tourism"
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-text-secondary">Category</label>
                  <select 
                    value={editForm.category} 
                    onChange={e => setEditForm({...editForm, category: e.target.value})}
                    className="w-full bg-surface-hover border border-border-default rounded-xl px-4 py-3 focus:outline-none focus:border-primary text-text-primary appearance-none"
                  >
                    <option value="GOVERNMENT">Government & Tourism</option>
                    <option value="CORPORATE">Corporate & Brands</option>
                    <option value="VENUE">Venues & Destinations</option>
                    <option value="AGENCY">Agencies</option>
                    <option value="TECHNOLOGY">Technology</option>
                    <option value="OTHER">Other</option>
                  </select>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-bold text-text-secondary">Logo Image</label>
                <div className="bg-surface-hover p-4 rounded-xl border border-border-default">
                  <MediaUploader 
                    value={editForm.logoUrl} 
                    onChange={(url) => setEditForm({...editForm, logoUrl: url})} 
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-bold text-text-secondary">Website URL (Optional)</label>
                <input 
                  type="url" 
                  value={editForm.website || ""} 
                  onChange={e => setEditForm({...editForm, website: e.target.value})}
                  className="w-full bg-surface-hover border border-border-default rounded-xl px-4 py-3 focus:outline-none focus:border-primary text-text-primary" 
                  placeholder="https://"
                />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-bold text-text-secondary">Description (Optional)</label>
                <textarea 
                  value={editForm.description || ""} 
                  onChange={e => setEditForm({...editForm, description: e.target.value})}
                  rows={3}
                  className="w-full bg-surface-hover border border-border-default rounded-xl px-4 py-3 focus:outline-none focus:border-primary text-text-primary resize-none" 
                  placeholder="Brief description about the partnership..."
                />
              </div>

              <div className="flex items-center gap-6 pt-4 border-t border-border-default">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input 
                    type="checkbox" 
                    checked={editForm.isVisible} 
                    onChange={e => setEditForm({...editForm, isVisible: e.target.checked})}
                    className="w-5 h-5 rounded border-border-default text-primary focus:ring-primary bg-surface-hover"
                  />
                  <span className="text-sm font-bold text-text-primary">Visible on Website</span>
                </label>
                
                <div className="flex items-center gap-2">
                  <label className="text-sm font-bold text-text-secondary">Order</label>
                  <input 
                    type="number" 
                    value={editForm.orderIndex} 
                    onChange={e => setEditForm({...editForm, orderIndex: parseInt(e.target.value) || 0})}
                    className="w-20 bg-surface-hover border border-border-default rounded-lg px-3 py-1.5 focus:outline-none focus:border-primary text-text-primary" 
                  />
                </div>
              </div>
            </div>

            <div className="sticky bottom-0 bg-surface-default border-t border-border-default px-6 py-4 flex items-center justify-end gap-3 z-10">
              <AdminButton variant="secondary" onClick={() => setIsEditing(null)} disabled={isSaving}>
                Cancel
              </AdminButton>
              <AdminButton variant="primary" onClick={handleSave} isLoading={isSaving}>
                {isSaving ? "Saving..." : "Save Client"}
              </AdminButton>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import { useState } from "react"
import { 
  Building2, Plus, ArrowUp, ArrowDown, Trash2, 
  ToggleLeft, ToggleRight 
} from "lucide-react"
import { Button } from "@/components/ui/Button"
import { Badge } from "@/components/ui/Badge"
import { useRouter } from "next/navigation"

interface Partner {
  id: string
  name: string
  website?: string | null
  category: string
  description?: string | null
  logoUrl?: string | null
  isVisible: boolean
  orderIndex: number
}

interface PartnersManagerProps {
  initialPartners: Partner[]
}

const CATEGORIES = [
  "SPONSOR", "VENUE", "TECHNOLOGY", "MEDIA", "GOVERNMENT", "VENDOR"
]

export function PartnersManager({ initialPartners }: PartnersManagerProps) {
  const [partners, setPartners] = useState<Partner[]>(
    [...initialPartners].sort((a, b) => a.orderIndex - b.orderIndex)
  )
  const [showAddModal, setShowAddModal] = useState(false)
  const [isSaving, setIsSaving] = useState(false)
  const [newPartner, setNewPartner] = useState({
    name: "",
    website: "",
    category: "SPONSOR",
    description: "",
    logoUrl: "https://images.unsplash.com/photo-1516321318423-f06f85e504b3?q=80&w=120&auto=format&fit=crop",
    isVisible: true
  })
  const router = useRouter()

  const handleToggleVisibility = async (id: string, currentVal: boolean) => {
    setPartners(prev => prev.map(p => p.id === id ? { ...p, isVisible: !currentVal } : p))
    
    try {
      const res = await fetch(`/api/partners/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ isVisible: !currentVal })
      })
      if (!res.ok) throw new Error()
      router.refresh()
    } catch {
      setPartners(prev => prev.map(p => p.id === id ? { ...p, isVisible: currentVal } : p))
      alert("Failed to update visibility")
    }
  }

  const handleMove = async (index: number, direction: "up" | "down") => {
    const nextIndex = direction === "up" ? index - 1 : index + 1
    if (nextIndex < 0 || nextIndex >= partners.length) return

    const newPartners = [...partners]
    const temp = newPartners[index]
    newPartners[index] = newPartners[nextIndex]
    newPartners[nextIndex] = temp

    // Re-index
    const updatedPartners = newPartners.map((p, idx) => ({ ...p, orderIndex: idx }))
    setPartners(updatedPartners)

    try {
      const res = await fetch("/api/partners/reorder", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          orders: updatedPartners.map(p => ({ id: p.id, orderIndex: p.orderIndex }))
        })
      })
      if (!res.ok) throw new Error()
      router.refresh()
    } catch {
      alert("Failed to save new order index")
    }
  }

  const handleAddPartner = async () => {
    if (!newPartner.name) return
    setIsSaving(true)

    try {
      const res = await fetch("/api/partners", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...newPartner,
          orderIndex: partners.length
        })
      })
      if (!res.ok) throw new Error()
      const data = await res.json()
      setPartners(prev => [...prev, data].sort((a, b) => a.orderIndex - b.orderIndex))
      setShowAddModal(false)
      setNewPartner({
        name: "",
        website: "",
        category: "SPONSOR",
        description: "",
        logoUrl: "https://images.unsplash.com/photo-1516321318423-f06f85e504b3?q=80&w=120&auto=format&fit=crop",
        isVisible: true
      })
      router.refresh()
    } catch {
      alert("Failed to add partner")
    } finally {
      setIsSaving(false)
    }
  }

  const handleDeletePartner = async (id: string) => {
    if (!confirm("Are you sure you want to remove this partner?")) return

    try {
      const res = await fetch(`/api/partners/${id}`, { method: "DELETE" })
      if (!res.ok) throw new Error()
      setPartners(prev => prev.filter(p => p.id !== id))
      router.refresh()
    } catch {
      alert("Failed to delete partner")
    }
  }

  return (
    <div className="space-y-6 p-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-text-primary">Corporate Partners Directory</h1>
          <p className="text-sm text-text-secondary">Manage relationships and marketing logos for sponsors and venue hosts.</p>
        </div>
        <Button className="gap-2" onClick={() => setShowAddModal(true)}>
          <Plus className="w-4 h-4" /> Add Partner Link
        </Button>
      </div>

      {partners.length === 0 ? (
        <div className="border border-dashed border-border-default rounded-xl p-12 text-center bg-surface-default">
          <Building2 className="w-12 h-12 mx-auto text-text-tertiary mb-4" />
          <p className="text-sm font-bold text-text-primary mb-1">No partners added</p>
          <p className="text-xs text-text-secondary">Add corporate entities like Qatar Tourism or UDC to begin.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          
          {/* Re-order & Quick Control Roster (Left/2 Cols) */}
          <div className="lg:col-span-2 space-y-4">
            <div className="bg-surface-default rounded-xl border border-border-default shadow-sm overflow-hidden">
              <div className="p-4 bg-surface-hover border-b border-border-default flex items-center justify-between">
                <span className="text-xs font-bold uppercase tracking-wider text-text-secondary">Priority Sorting & Status</span>
                <Badge variant="default" className="font-mono text-xs">{partners.length} Entities</Badge>
              </div>

              <div className="divide-y divide-border-default">
                {partners.map((partner, idx) => (
                  <div key={partner.id} className="p-4 flex items-center gap-4 hover:bg-surface-hover transition-colors">
                    {/* Re-order controls */}
                    <div className="flex flex-col gap-1">
                      <button 
                        onClick={() => handleMove(idx, "up")}
                        disabled={idx === 0}
                        className="p-1 text-text-tertiary hover:text-accent disabled:opacity-30 rounded hover:bg-surface-hover"
                      >
                        <ArrowUp className="w-4 h-4" />
                      </button>
                      <button 
                        onClick={() => handleMove(idx, "down")}
                        disabled={idx === partners.length - 1}
                        className="p-1 text-text-tertiary hover:text-accent disabled:opacity-30 rounded hover:bg-surface-hover"
                      >
                        <ArrowDown className="w-4 h-4" />
                      </button>
                    </div>

                    {/* Logo & Info */}
                    <img 
                      src={partner.logoUrl || "/placeholder-logo.png"} 
                      alt={partner.name} 
                      className="w-12 h-12 rounded-lg object-contain bg-surface-hover p-2 border border-border-default"
                    />
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="font-bold text-sm text-text-primary truncate">{partner.name}</span>
                        <Badge className="text-[10px] font-black uppercase tracking-wider">{partner.category}</Badge>
                      </div>
                      <div className="text-xs text-text-secondary truncate">{partner.website || "No website listed"}</div>
                    </div>

                    {/* Actions */}
                    <div className="flex items-center gap-4">
                      {/* Publish Switch */}
                      <button 
                        onClick={() => handleToggleVisibility(partner.id, partner.isVisible)}
                        className="flex items-center gap-1 text-text-secondary hover:text-text-primary"
                      >
                        {partner.isVisible ? (
                          <ToggleRight className="w-9 h-9 text-green-500 transition-colors" />
                        ) : (
                          <ToggleLeft className="w-9 h-9 text-text-tertiary transition-colors" />
                        )}
                      </button>

                      {/* Delete */}
                      <button 
                        onClick={() => handleDeletePartner(partner.id)}
                        className="p-2 text-text-tertiary hover:text-red-500 rounded-lg hover:bg-surface-hover transition-colors"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Dynamic Public Ribbons Preview (Right/1 Col) */}
          <div className="space-y-6">
            <div className="bg-surface-default p-6 rounded-xl border border-border-default space-y-4">
              <h3 className="font-black text-xs text-text-secondary uppercase tracking-wider border-b border-border-default pb-2">
                Public Ribbon Preview
              </h3>
              <p className="text-xs text-text-secondary">Simulated public site footer ribbon showing only visible partners sorted by priority index.</p>
              
              <div className="p-4 bg-surface-hover rounded-lg border border-border-default flex flex-wrap gap-3 items-center justify-center min-h-24">
                {partners.filter(p => p.isVisible).map(p => (
                  <img 
                    key={p.id}
                    src={p.logoUrl || ""}
                    alt={p.name}
                    className="h-8 max-w-20 object-contain grayscale hover:grayscale-0 opacity-60 hover:opacity-100 transition-all duration-300"
                    title={p.name}
                  />
                ))}
              </div>
            </div>
          </div>

        </div>
      )}

      {/* Add Partner Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-zinc-950/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-surface-default border border-border-default rounded-xl shadow-xl w-full max-w-md overflow-hidden">
            <div className="p-6 border-b border-border-default">
              <h3 className="text-lg font-black text-text-primary">Add Corporate Partner</h3>
              <p className="text-xs text-text-secondary">Create sponsor, venue, or media links</p>
            </div>

            <div className="p-6 space-y-4">
              <div className="space-y-1">
                <label className="text-xs font-bold text-text-secondary">Company Name</label>
                <input 
                  type="text" 
                  value={newPartner.name}
                  onChange={e => setNewPartner(prev => ({ ...prev, name: e.target.value }))}
                  className="w-full bg-surface-hover border border-border-default rounded-lg p-2.5 text-sm outline-none text-text-primary"
                  placeholder="e.g. Qatar Tourism"
                />
              </div>

              <div className="space-y-1">
                <label className="text-xs font-bold text-text-secondary">Website URL</label>
                <input 
                  type="text" 
                  value={newPartner.website}
                  onChange={e => setNewPartner(prev => ({ ...prev, website: e.target.value }))}
                  className="w-full bg-surface-hover border border-border-default rounded-lg p-2.5 text-sm outline-none text-text-primary"
                  placeholder="https://example.qa"
                />
              </div>

              <div className="space-y-1">
                <label className="text-xs font-bold text-text-secondary">Category</label>
                <select 
                  value={newPartner.category}
                  onChange={e => setNewPartner(prev => ({ ...prev, category: e.target.value }))}
                  className="w-full bg-surface-hover border border-border-default rounded-lg p-2.5 text-sm outline-none text-text-primary"
                >
                  {CATEGORIES.map(cat => (
                    <option key={cat} value={cat}>{cat}</option>
                  ))}
                </select>
              </div>

              <div className="space-y-1">
                <label className="text-xs font-bold text-text-secondary">Logo URL</label>
                <input 
                  type="text" 
                  value={newPartner.logoUrl}
                  onChange={e => setNewPartner(prev => ({ ...prev, logoUrl: e.target.value }))}
                  className="w-full bg-surface-hover border border-border-default rounded-lg p-2.5 text-sm outline-none text-text-primary font-mono"
                />
              </div>

              <div className="space-y-1">
                <label className="text-xs font-bold text-text-secondary">Description</label>
                <textarea 
                  rows={2}
                  value={newPartner.description}
                  onChange={e => setNewPartner(prev => ({ ...prev, description: e.target.value }))}
                  className="w-full bg-surface-hover border border-border-default rounded-lg p-2.5 text-sm outline-none text-text-primary resize-none"
                  placeholder="Short description of partnership..."
                />
              </div>
            </div>

            <div className="p-6 bg-surface-hover border-t border-border-default flex justify-end gap-3">
              <Button variant="outline" onClick={() => setShowAddModal(false)} disabled={isSaving}>
                Cancel
              </Button>
              <Button onClick={handleAddPartner} disabled={isSaving}>
                {isSaving ? "Saving..." : "Add Partner"}
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import { useState } from "react"
import { useRouter } from "next/navigation"
import { Plus, Trash2, Edit2, Search, Settings } from "lucide-react"
import { AdminButton } from "@/components/dashboard/ui/AdminButton"
import { AdminPageHeader } from "@/components/dashboard/ui/AdminPageHeader"
import { 
  AdminTable, 
  AdminTableHeader, 
  AdminTableBody, 
  AdminTableRow, 
  AdminTableHead, 
  AdminTableCell 
} from "@/components/dashboard/ui/AdminTable"

export function ServicesListClient({ initialData }: { initialData: any[] }) {
  const router = useRouter()
  const [services, setServices] = useState(initialData)
  const [search, setSearch] = useState("")

  const filteredServices = services.filter(s => 
    s.titleEn.toLowerCase().includes(search.toLowerCase()) || 
    s.slug.toLowerCase().includes(search.toLowerCase())
  )

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this service?")) return

    try {
      const res = await fetch(`/api/b2b/services/${id}`, { method: "DELETE" })
      if (!res.ok) throw new Error("Failed to delete")
      
      setServices(services.filter(s => s.id !== id))
      router.refresh()
    } catch {
      alert("Failed to delete service")
    }
  }

  return (
    <div className="p-4 md:p-8 max-w-[1600px] mx-auto space-y-6 animate-fade-in-up">
      <AdminPageHeader 
        title="B2B Services"
        description="Manage corporate services and offerings."
        breadcrumbs={[
          { label: "Dashboard", href: "/dashboard" },
          { label: "B2B Portal" },
          { label: "Services" }
        ]}
        action={
          <AdminButton onClick={() => router.push("/dashboard/b2b/services/new")} variant="primary" leftIcon={<Plus className="w-4 h-4" />}>
            Add Service
          </AdminButton>
        }
      />

      <div className="flex flex-col sm:flex-row items-center gap-4 mb-2">
        <div className="relative w-full sm:max-w-md group">
          <Search className="absolute start-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-tertiary group-focus-within:text-primary transition-colors" />
          <input 
            type="text" 
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Search services..."
            className="w-full bg-surface-default border border-border-default rounded-md py-2 ps-9 pe-4 text-sm font-medium text-text-primary focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary transition-all placeholder:text-text-tertiary shadow-sm"
          />
        </div>
      </div>

      <AdminTable>
        <AdminTableHeader>
          <AdminTableRow>
            <AdminTableHead>Service</AdminTableHead>
            <AdminTableHead>Status</AdminTableHead>
            <AdminTableHead className="text-right">Actions</AdminTableHead>
          </AdminTableRow>
        </AdminTableHeader>
        <AdminTableBody>
          {filteredServices.map(service => (
            <AdminTableRow key={service.id} className="group">
              <AdminTableCell>
                <div className="flex items-center gap-4">
                  {service.thumbnail ? (
                    <img src={service.thumbnail} alt={service.titleEn} className="w-12 h-12 rounded-lg object-cover border border-border-default shadow-sm" />
                  ) : (
                    <div className="w-12 h-12 rounded-lg bg-surface-active border border-border-default flex items-center justify-center text-text-tertiary shadow-sm">
                      <Settings className="w-5 h-5" />
                    </div>
                  )}
                  <div>
                    <div className="font-bold text-text-primary line-clamp-1">{service.titleEn}</div>
                    <div className="text-xs text-text-tertiary mt-0.5">/{service.slug}</div>
                  </div>
                </div>
              </AdminTableCell>
              <AdminTableCell>
                <div className="flex flex-col gap-1.5">
                  {service.isVisible ? (
                    <span className="inline-flex w-fit px-2 py-0.5 rounded text-[10px] font-bold tracking-wider uppercase bg-success/10 text-success">Visible</span>
                  ) : (
                    <span className="inline-flex w-fit px-2 py-0.5 rounded text-[10px] font-bold tracking-wider uppercase bg-surface-hover text-text-secondary border border-border-default">Hidden</span>
                  )}
                  {service.isFeatured && (
                    <span className="inline-flex w-fit px-2 py-0.5 rounded text-[10px] font-bold tracking-wider uppercase bg-warning/10 text-warning">Featured</span>
                  )}
                </div>
              </AdminTableCell>
              <AdminTableCell className="text-right">
                <div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                  <AdminButton onClick={() => router.push(`/dashboard/b2b/services/${service.slug}`)} variant="outline" size="sm" leftIcon={<Edit2 className="w-3.5 h-3.5" />}>
                    Edit
                  </AdminButton>
                  <button onClick={() => handleDelete(service.id)} className="p-2 text-text-secondary hover:text-error bg-surface-active hover:bg-error/10 border border-transparent hover:border-error/20 rounded-md transition-colors">
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </AdminTableCell>
            </AdminTableRow>
          ))}
          {filteredServices.length === 0 && (
            <AdminTableRow>
              <AdminTableCell colSpan={3} className="h-32 text-center text-text-tertiary font-medium">
                No services found. Click &quot;Add Service&quot; to create one.
              </AdminTableCell>
            </AdminTableRow>
          )}
        </AdminTableBody>
      </AdminTable>
    </div>
  )
}

"use client"

import { useState } from "react"
import { motion, AnimatePresence } from "framer-motion"
import { 
  Users, Calendar, Clock, Plus, Trash2, 
  ChevronRight, CalendarDays, CheckCircle2 
} from "lucide-react"
import { Button } from "@/components/ui/Button"
import { Badge } from "@/components/ui/Badge"
import { useRouter } from "next/navigation"

interface TeamMember {
  id: string
  firstName: string
  lastName: string
  firstNameAr?: string | null
  lastNameAr?: string | null
  designation: string
  designationAr?: string | null
  aboutSummary?: string | null
  aboutSummaryAr?: string | null
  profileImage?: string | null
  availability: {
    id: string
    startTime: string
    endTime: string
    isBooked: boolean
  }[]
}

interface TeamManagerProps {
  initialMembers: TeamMember[]
}

export function TeamManager({ initialMembers }: TeamManagerProps) {
  const [members, setMembers] = useState<TeamMember[]>(initialMembers)
  const [selectedMemberId, setSelectedMemberId] = useState<string>(initialMembers[0]?.id || "")
  const [activeTab, setActiveTab] = useState<"roster" | "availability" | "meetings">("roster")
  const [isSaving, setIsSaving] = useState(false)
  const router = useRouter()

  // New Member State
  const [showAddModal, setShowAddModal] = useState(false)
  const [newMember, setNewMember] = useState({
    firstName: "",
    lastName: "",
    firstNameAr: "",
    lastNameAr: "",
    designation: "",
    designationAr: "",
    aboutSummary: "",
    aboutSummaryAr: "",
    profileImage: "https://images.unsplash.com/photo-1534528741775-53994a69daeb?q=80&w=120"
  })

  // Slot Config State
  const [daysOfWeek, setDaysOfWeek] = useState<number[]>([1, 2, 3, 4, 5]) // Mon-Fri
  const [startTime, setStartTime] = useState("09:00")
  const [endTime, setEndTime] = useState("17:00")
  const [duration, setDuration] = useState(30)
  const [buffer, setBuffer] = useState(15)

  const handleAddMember = async () => {
    if (!newMember.firstName || !newMember.lastName || !newMember.designation) return
    setIsSaving(true)

    try {
      const res = await fetch("/api/team", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newMember)
      })

      if (!res.ok) throw new Error()
      const data = await res.json()
      setMembers(prev => [...prev, { ...data, availability: [] }])
      setSelectedMemberId(data.id)
      setShowAddModal(false)
      setNewMember({
        firstName: "",
        lastName: "",
        firstNameAr: "",
        lastNameAr: "",
        designation: "",
        designationAr: "",
        aboutSummary: "",
        aboutSummaryAr: "",
        profileImage: "https://images.unsplash.com/photo-1534528741775-53994a69daeb?q=80&w=120"
      })
      router.refresh()
    } catch {
      alert("Failed to add team member")
    } finally {
      setIsSaving(false)
    }
  }

  const handleDeleteMember = async (id: string) => {
    if (!confirm("Are you sure you want to delete this staff member?")) return
    
    try {
      const res = await fetch(`/api/team?id=${id}`, { method: "DELETE" })
      if (!res.ok) throw new Error()
      setMembers(prev => prev.filter(m => m.id !== id))
      if (selectedMemberId === id) {
        setSelectedMemberId(members.find(m => m.id !== id)?.id || "")
      }
      router.refresh()
    } catch {
      alert("Failed to delete team member")
    }
  }

  const handleGenerateSlots = async () => {
    if (!selectedMemberId) return
    setIsSaving(true)

    try {
      const res = await fetch(`/api/team/${selectedMemberId}/availability`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          daysOfWeek,
          startTime,
          endTime,
          duration,
          buffer
        })
      })

      if (!res.ok) throw new Error()
      alert("Slots generated successfully for the upcoming 7 days!")
      router.refresh()
    } catch {
      alert("Failed to generate availability slots")
    } finally {
      setIsSaving(false)
    }
  }

  const selectedMember = members.find(m => m.id === selectedMemberId)

  return (
    <div className="flex h-[calc(100vh-6rem)] -m-6 bg-bg-base">
      
      {/* Sidebar - Roster Registry */}
      <div className="w-80 border-e border-border-default bg-surface-default p-4 flex flex-col">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h2 className="text-lg font-black text-text-primary">Roster Directory</h2>
            <p className="text-xs text-text-secondary">Event Engineering Roster</p>
          </div>
          <button 
            onClick={() => setShowAddModal(true)}
            className="p-2 bg-accent text-white hover:bg-accent/90 transition-colors rounded-lg"
          >
            <Plus className="w-4 h-4" />
          </button>
        </div>

        {/* Members List */}
        <div className="flex-1 overflow-y-auto space-y-2 pe-1">
          {members.map(member => {
            const isSelected = selectedMemberId === member.id
            const fullNameEn = `${member.firstName} ${member.lastName}`
            return (
              <div
                key={member.id}
                onClick={() => setSelectedMemberId(member.id)}
                className={`p-3 rounded-xl border transition-all cursor-pointer flex items-center gap-3
                  ${isSelected 
                    ? 'bg-surface-hover border-accent shadow-sm' 
                    : 'border-border-default hover:bg-surface-hover'
                  }
                `}
              >
                <img 
                  src={member.profileImage || "https://images.unsplash.com/photo-1534528741775-53994a69daeb?q=80&w=120"} 
                  alt={fullNameEn} 
                  className="w-10 h-10 rounded-full object-cover border border-border-default"
                />
                <div className="flex-1 min-w-0">
                  <div className="font-bold text-sm text-text-primary truncate">{fullNameEn}</div>
                  <div className="text-xs text-text-secondary truncate">{member.designation}</div>
                </div>
                <ChevronRight className={`w-4 h-4 text-text-tertiary ${isSelected ? 'translate-x-1' : ''} transition-transform`} />
              </div>
            )
          })}
        </div>
      </div>

      {/* Main Console */}
      <div className="flex-1 flex flex-col overflow-hidden">
        {selectedMember ? (
          <>
            {/* Header / Sub-Nav */}
            <div className="border-b border-border-default bg-surface-default p-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div className="flex items-center gap-4">
                <img 
                  src={selectedMember.profileImage || ""} 
                  alt={`${selectedMember.firstName} ${selectedMember.lastName}`} 
                  className="w-16 h-16 rounded-full object-cover border-2 border-accent"
                />
                <div>
                  <h1 className="text-2xl font-black text-text-primary flex items-center gap-2">
                    {selectedMember.firstName} {selectedMember.lastName}
                    <span className="text-sm font-medium text-text-tertiary" dir="rtl">{selectedMember.firstNameAr} {selectedMember.lastNameAr}</span>
                  </h1>
                  <p className="text-sm text-text-secondary">{selectedMember.designation} • <span dir="rtl">{selectedMember.designationAr}</span></p>
                </div>
              </div>

              <div className="flex gap-1.5 p-1 bg-surface-hover rounded-lg border border-border-default">
                {(["roster", "availability", "meetings"] as const).map(tab => (
                  <button
                    key={tab}
                    onClick={() => setActiveTab(tab)}
                    className={`px-4 py-2 rounded-md text-xs font-bold transition-all uppercase tracking-wider
                      ${activeTab === tab 
                        ? 'bg-surface-default text-text-primary shadow-sm' 
                        : 'text-text-secondary hover:text-text-primary'
                      }
                    `}
                  >
                    {tab}
                  </button>
                ))}
              </div>
            </div>

            {/* Content Tabs */}
            <div className="flex-1 overflow-y-auto p-8 bg-bg-base">
              {activeTab === "roster" && (
                <div className="max-w-2xl space-y-6">
                  <div className="bg-surface-default p-6 rounded-xl border border-border-default space-y-4">
                    <div className="flex items-center justify-between border-b border-border-default pb-2">
                      <h3 className="font-black text-xs text-text-secondary uppercase tracking-wider">Biography & Experience</h3>
                      <button 
                        onClick={() => handleDeleteMember(selectedMember.id)}
                        className="text-red-500 hover:bg-red-500/10 p-2 rounded-lg transition-colors flex items-center gap-1 text-xs font-bold"
                      >
                        <Trash2 className="w-3.5 h-3.5" /> Remove Staff
                      </button>
                    </div>

                    <div className="space-y-4">
                      <div>
                        <div className="text-xs font-bold text-text-secondary mb-1">Bio (English)</div>
                        <p className="text-sm text-text-primary bg-surface-hover p-3 rounded-lg border border-border-default">
                          {selectedMember.aboutSummary || "No English biography set."}
                        </p>
                      </div>
                      <div dir="rtl">
                        <div className="text-xs font-bold text-text-secondary text-right mb-1">السيرة الذاتية (عربي)</div>
                        <p className="text-sm text-text-primary bg-surface-hover p-3 rounded-lg border border-border-default text-right">
                          {selectedMember.aboutSummaryAr || "لا توجد سيرة ذاتية بالعربية."}
                        </p>
                      </div>
                    </div>
                  </div>
                </div>
              )}

              {activeTab === "availability" && (
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                  {/* Configuration */}
                  <div className="bg-surface-default p-6 rounded-xl border border-border-default space-y-6">
                    <div>
                      <h3 className="text-lg font-black text-text-primary mb-1">Configure Slot Matrix</h3>
                      <p className="text-xs text-text-secondary">Define standard working parameters to generate upcoming slots.</p>
                    </div>

                    {/* Weekday Selection */}
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-text-secondary">Working Days</label>
                      <div className="flex justify-between gap-1 bg-surface-hover p-2 rounded-lg border border-border-default">
                        {["S", "M", "T", "W", "T", "F", "S"].map((day, idx) => {
                          const isSelected = daysOfWeek.includes(idx)
                          return (
                            <button
                              key={idx}
                              onClick={() => {
                                setDaysOfWeek(prev => 
                                  prev.includes(idx) ? prev.filter(d => d !== idx) : [...prev, idx]
                                )
                              }}
                              className={`w-8 h-8 rounded-full text-xs font-bold transition-all
                                ${isSelected 
                                  ? 'bg-accent text-white' 
                                  : 'text-text-secondary hover:bg-surface-hover'
                                }
                              `}
                            >
                              {day}
                            </button>
                          )
                        })}
                      </div>
                    </div>

                    {/* Hours Range */}
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <label className="text-xs font-bold text-text-secondary">Start Time</label>
                        <input 
                          type="time" 
                          value={startTime}
                          onChange={e => setStartTime(e.target.value)}
                          className="w-full bg-surface-hover border border-border-default rounded-lg p-2.5 text-sm outline-none text-text-primary"
                        />
                      </div>
                      <div className="space-y-1">
                        <label className="text-xs font-bold text-text-secondary">End Time</label>
                        <input 
                          type="time" 
                          value={endTime}
                          onChange={e => setEndTime(e.target.value)}
                          className="w-full bg-surface-hover border border-border-default rounded-lg p-2.5 text-sm outline-none text-text-primary"
                        />
                      </div>
                    </div>

                    {/* Duration / Buffer */}
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <label className="text-xs font-bold text-text-secondary">Slot Duration (Mins)</label>
                        <select 
                          value={duration}
                          onChange={e => setDuration(parseInt(e.target.value))}
                          className="w-full bg-surface-hover border border-border-default rounded-lg p-2.5 text-sm outline-none text-text-primary"
                        >
                          <option value={15}>15 mins</option>
                          <option value={30}>30 mins</option>
                          <option value={45}>45 mins</option>
                          <option value={60}>60 mins</option>
                        </select>
                      </div>
                      <div className="space-y-1">
                        <label className="text-xs font-bold text-text-secondary">Post-Meeting Buffer (Mins)</label>
                        <select 
                          value={buffer}
                          onChange={e => setBuffer(parseInt(e.target.value))}
                          className="w-full bg-surface-hover border border-border-default rounded-lg p-2.5 text-sm outline-none text-text-primary"
                        >
                          <option value={0}>No buffer</option>
                          <option value={10}>10 mins</option>
                          <option value={15}>15 mins</option>
                          <option value={30}>30 mins</option>
                        </select>
                      </div>
                    </div>

                    <Button 
                      className="w-full gap-2" 
                      onClick={handleGenerateSlots}
                      disabled={isSaving}
                    >
                      <Clock className="w-4 h-4" /> 
                      {isSaving ? "Generating..." : "Generate 7-Day Slot Matrix"}
                    </Button>
                  </div>

                  {/* Active Slots Preview */}
                  <div className="bg-surface-default p-6 rounded-xl border border-border-default space-y-4">
                    <div>
                      <h3 className="text-lg font-black text-text-primary mb-1">Active Slots Preview</h3>
                      <p className="text-xs text-text-secondary">Currently generated slots for the upcoming week.</p>
                    </div>

                    {selectedMember.availability.length === 0 ? (
                      <div className="border border-dashed border-border-default rounded-lg p-8 text-center bg-surface-hover">
                        <CalendarDays className="w-8 h-8 mx-auto text-text-tertiary mb-2" />
                        <p className="text-xs font-bold text-text-secondary">No active availability slots found</p>
                      </div>
                    ) : (
                      <div className="grid grid-cols-2 gap-2 max-h-80 overflow-y-auto pe-1">
                        {selectedMember.availability.map(slot => (
                          <div 
                            key={slot.id} 
                            className={`p-2.5 rounded-lg border text-xs flex justify-between items-center font-mono
                              ${slot.isBooked 
                                ? 'bg-red-500/10 border-red-500/20 text-red-500' 
                                : 'bg-green-500/10 border-green-500/20 text-green-600'
                              }
                            `}
                          >
                            <div>
                              <div className="font-bold">
                                {new Date(slot.startTime).toLocaleDateString([], { weekday: 'short', month: 'short', day: 'numeric' })}
                              </div>
                              <div>
                                {new Date(slot.startTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} - {new Date(slot.endTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                              </div>
                            </div>
                            <Badge variant={slot.isBooked ? 'error' : 'success'} className="text-[10px] uppercase font-bold tracking-wider">
                              {slot.isBooked ? 'Booked' : 'Free'}
                            </Badge>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              )}

              {activeTab === "meetings" && (
                <div className="bg-surface-default p-6 rounded-xl border border-border-default space-y-6">
                  <div>
                    <h3 className="text-lg font-black text-text-primary mb-1">Conflict-Prevention Grid</h3>
                    <p className="text-xs text-text-secondary">Visual validation of consultations against staff vectors.</p>
                  </div>

                  <div className="border border-dashed border-border-default rounded-xl p-12 text-center bg-surface-hover">
                    <Calendar className="w-12 h-12 mx-auto text-text-tertiary mb-4" />
                    <p className="text-sm font-bold text-text-primary mb-1">Double-Booking Engine Active</p>
                    <p className="text-xs text-text-secondary mb-4">All meetings are automatically locked on staff availability matrices.</p>
                    <div className="inline-flex items-center gap-1.5 bg-green-500/10 text-green-500 px-3 py-1.5 rounded-full text-xs font-bold">
                      <CheckCircle2 className="w-4 h-4" /> Real-time Prevention Guard Online
                    </div>
                  </div>
                </div>
              )}
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-center p-8">
            <Users className="w-12 h-12 text-text-tertiary mb-4" />
            <h2 className="text-lg font-bold text-text-primary">Roster Empty</h2>
            <p className="text-sm text-text-secondary">Add a staff member to begin scheduling.</p>
          </div>
        )}
      </div>

      {/* Add Staff Modal */}
      <AnimatePresence>
        {showAddModal && (
          <div className="fixed inset-0 bg-zinc-950/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <motion.div 
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.95, opacity: 0 }}
              className="bg-surface-default border border-border-default rounded-xl shadow-xl w-full max-w-lg overflow-hidden"
            >
              <div className="p-6 border-b border-border-default">
                <h3 className="text-lg font-black text-text-primary">Add Team Member</h3>
                <p className="text-xs text-text-secondary">Incorporate event engineers & consultants into roster</p>
              </div>

              <div className="p-6 space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-xs font-bold text-text-secondary">First Name (English)</label>
                    <input 
                      type="text" 
                      value={newMember.firstName}
                      onChange={e => setNewMember(prev => ({ ...prev, firstName: e.target.value }))}
                      className="w-full bg-surface-hover border border-border-default rounded-lg p-2.5 text-sm outline-none text-text-primary"
                      placeholder="e.g. John"
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs font-bold text-text-secondary">Last Name (English)</label>
                    <input 
                      type="text" 
                      value={newMember.lastName}
                      onChange={e => setNewMember(prev => ({ ...prev, lastName: e.target.value }))}
                      className="w-full bg-surface-hover border border-border-default rounded-lg p-2.5 text-sm outline-none text-text-primary"
                      placeholder="e.g. Doe"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4" dir="rtl">
                  <div className="space-y-1">
                    <label className="text-xs font-bold text-text-secondary text-right block">الاسم الأول (عربي)</label>
                    <input 
                      type="text" 
                      value={newMember.firstNameAr}
                      onChange={e => setNewMember(prev => ({ ...prev, firstNameAr: e.target.value }))}
                      className="w-full bg-surface-hover border border-border-default rounded-lg p-2.5 text-sm outline-none text-text-primary text-right"
                      placeholder="الاسم الأول"
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs font-bold text-text-secondary text-right block">اسم العائلة (عربي)</label>
                    <input 
                      type="text" 
                      value={newMember.lastNameAr}
                      onChange={e => setNewMember(prev => ({ ...prev, lastNameAr: e.target.value }))}
                      className="w-full bg-surface-hover border border-border-default rounded-lg p-2.5 text-sm outline-none text-text-primary text-right"
                      placeholder="اسم العائلة"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-xs font-bold text-text-secondary">Designation (English)</label>
                    <input 
                      type="text" 
                      value={newMember.designation}
                      onChange={e => setNewMember(prev => ({ ...prev, designation: e.target.value }))}
                      className="w-full bg-surface-hover border border-border-default rounded-lg p-2.5 text-sm outline-none text-text-primary"
                      placeholder="e.g. Technical Director"
                    />
                  </div>
                  <div className="space-y-1" dir="rtl">
                    <label className="text-xs font-bold text-text-secondary text-right block">المنصب (عربي)</label>
                    <input 
                      type="text" 
                      value={newMember.designationAr}
                      onChange={e => setNewMember(prev => ({ ...prev, designationAr: e.target.value }))}
                      className="w-full bg-surface-hover border border-border-default rounded-lg p-2.5 text-sm outline-none text-text-primary text-right"
                      placeholder="المنصب بالعربية"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-xs font-bold text-text-secondary">Biography (English)</label>
                    <textarea 
                      rows={3}
                      value={newMember.aboutSummary}
                      onChange={e => setNewMember(prev => ({ ...prev, aboutSummary: e.target.value }))}
                      className="w-full bg-surface-hover border border-border-default rounded-lg p-2.5 text-sm outline-none text-text-primary resize-none"
                    />
                  </div>
                  <div className="space-y-1" dir="rtl">
                    <label className="text-xs font-bold text-text-secondary text-right block">السيرة (عربي)</label>
                    <textarea 
                      rows={3}
                      value={newMember.aboutSummaryAr}
                      onChange={e => setNewMember(prev => ({ ...prev, aboutSummaryAr: e.target.value }))}
                      className="w-full bg-surface-hover border border-border-default rounded-lg p-2.5 text-sm outline-none text-text-primary text-right resize-none"
                    />
                  </div>
                </div>
              </div>

              <div className="p-6 bg-surface-hover border-t border-border-default flex justify-end gap-3">
                <Button variant="outline" onClick={() => setShowAddModal(false)} disabled={isSaving}>
                  Cancel
                </Button>
                <Button onClick={handleAddMember} disabled={isSaving}>
                  {isSaving ? "Saving..." : "Add Member"}
                </Button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  )
}

"use client"

import { useState, useEffect } from "react"
import { useRouter } from "next/navigation"
import { 
  Save, 
  Eye, 
  ArrowLeft,
  Settings,
  Image as ImageIcon,
  Images,
  Ticket,
  Gift,
  Share2,
  MapPin,
  Clock,
  HelpCircle,
  Search,
  Box
} from "lucide-react"
import { Button } from "@/components/ui/Button"
import { TipTapEditor } from "@/components/shared/TipTapEditor"
import { MediaUploader } from "@/components/shared/MediaUploader"
import { RepeaterField } from "@/components/shared/RepeaterField"

export function AttractionEditForm({ initialData }: { initialData: any }) {
  const router = useRouter()
  const [activeTab, setActiveTab] = useState("basic")
  const [isSaving, setIsSaving] = useState(false)
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false)

  // Form State
  const [formData, setFormData] = useState({
    nameEn: initialData.nameEn || "",
    nameAr: initialData.nameAr || "",
    slug: initialData.slug || "",
    descriptionEn: initialData.descriptionEn || "",
    descriptionAr: initialData.descriptionAr || "",
    isPublished: initialData.isPublished || false,
    isFeatured: initialData.isFeatured || false,
    isHidden: initialData.isHidden || false,
    heroMediaType: initialData.heroMediaType || "IMAGE",
    heroMediaUrl: initialData.heroMediaUrl || "",
    coordinates: initialData.coordinates || { lat: 0, lng: 0 },
    features: initialData.features || []
  })

  // Repeaters
  const [gallery, setGallery] = useState<any[]>(() =>
    Array.isArray(initialData.gallery) ? initialData.gallery.map((g: any) => ({ id: Math.random().toString(), ...g })) : []
  )
  const [pricing, setPricing] = useState<any[]>(() =>
    Array.isArray(initialData.pricing) ? initialData.pricing.map((p: any) => ({ id: Math.random().toString(), ...p })) : []
  )
  const [offers] = useState<any[]>(() =>
    Array.isArray(initialData.offers) ? initialData.offers.map((o: any) => ({ id: Math.random().toString(), ...o })) : []
  )
  const [faqs, setFaqs] = useState<any[]>(() =>
    Array.isArray(initialData.faqs) ? initialData.faqs.map((f: any) => ({ id: Math.random().toString(), ...f })) : []
  )
  const [socialLinks] = useState<any[]>(() =>
    Array.isArray(initialData.socialLinks) ? initialData.socialLinks.map((s: any) => ({ id: Math.random().toString(), ...s })) : []
  )
  const [temporalRules] = useState<any[]>(() =>
    Array.isArray(initialData.temporalRules) ? initialData.temporalRules.map((t: any) => ({ id: Math.random().toString(), ...t })) : []
  )

  // Warn on unsaved changes
  useEffect(() => {
    const handleBeforeUnload = (e: BeforeUnloadEvent) => {
      if (hasUnsavedChanges) {
        e.preventDefault()
        e.returnValue = ""
      }
    }
    window.addEventListener("beforeunload", handleBeforeUnload)
    return () => window.removeEventListener("beforeunload", handleBeforeUnload)
  }, [hasUnsavedChanges])

  const handleChange = (key: string, value: any) => {
    setFormData(prev => ({ ...prev, [key]: value }))
    setHasUnsavedChanges(true)
  }

  const handleSave = async () => {
    setIsSaving(true)
    try {
      const payload = {
        ...formData,
        gallery,
        pricing,
        offers,
        faqs,
        socialLinks,
        temporalRules
      }
      
      const res = await fetch(`/api/b2c/attractions/${initialData.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      })

      if (!res.ok) throw new Error("Failed to save")
      
      setHasUnsavedChanges(false)
    } catch (error) {
      console.error(error)
    } finally {
      setIsSaving(false)
    }
  }

  const tabs = [
    { id: "basic", label: "Basic Details", icon: Settings },
    { id: "features", label: "What's Inside", icon: Box },
    { id: "hero", label: "Hero Media", icon: ImageIcon },
    { id: "gallery", label: "Gallery", icon: Images },
    { id: "pricing", label: "Pricing & Tickets", icon: Ticket },
    { id: "offers", label: "Partner Offers", icon: Gift },
    { id: "social", label: "Social Links", icon: Share2 },
    { id: "maps", label: "Booking & Maps", icon: MapPin },
    { id: "rules", label: "Temporal Rules", icon: Clock },
    { id: "faq", label: "FAQ", icon: HelpCircle },
    { id: "seo", label: "SEO", icon: Search },
  ]

  return (
    <div className="flex flex-col h-[calc(100vh-4rem)]">
      {/* Sticky Header */}
      <div className="flex items-center justify-between p-4 md:p-6 bg-[var(--surface-default)] border-b border-[var(--border-default)] shrink-0 z-10">
        <div className="flex items-center gap-4">
          <Button variant="outline" size="sm" onClick={() => router.push('/dashboard/b2c/attractions')}>
            <ArrowLeft className="w-4 h-4 me-2" /> Back
          </Button>
          <div>
            <h1 className="text-xl font-black text-[var(--text-primary)]">Edit Attraction: {formData.nameEn}</h1>
            {hasUnsavedChanges && <span className="text-xs font-bold text-[var(--color-warning)]">Unsaved changes</span>}
          </div>
        </div>
        <div className="flex items-center gap-3">
          <Button variant="outline" asChild>
            <a href={`/en/b2c/attractions/${formData.slug}`} target="_blank" rel="noreferrer">
              <Eye className="w-4 h-4 me-2" /> Preview
            </a>
          </Button>
          <Button onClick={handleSave} disabled={isSaving}>
            <Save className="w-4 h-4 me-2" /> {isSaving ? "Saving..." : "Save Changes"}
          </Button>
        </div>
      </div>

      <div className="flex flex-1 overflow-hidden">
        {/* Sidebar Tabs */}
        <div className="w-64 bg-[var(--surface-default)] border-e border-[var(--border-default)] p-4 overflow-y-auto hidden md:block shrink-0">
          <div className="space-y-1">
            {tabs.map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-colors ${activeTab === tab.id ? 'bg-[var(--color-primary)]/10 text-[var(--color-primary)]' : 'text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]'}`}
              >
                <tab.icon className="w-4 h-4" />
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        {/* Form Content Area */}
        <div className="flex-1 overflow-y-auto p-6 md:p-8 bg-[var(--surface-hover)]">
          <div className="max-w-4xl mx-auto space-y-8">
            
            {/* TAB: BASIC */}
            {activeTab === "basic" && (
              <div className="bg-[var(--surface-default)] border border-[var(--border-default)] rounded-2xl p-6 md:p-8 space-y-6">
                <h2 className="text-lg font-black text-[var(--text-primary)] mb-4">Basic Details</h2>
                
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-sm font-bold">Name (EN)</label>
                    <input type="text" value={formData.nameEn} onChange={e => handleChange('nameEn', e.target.value)} className="w-full px-4 py-2 rounded-xl bg-[var(--surface-hover)] border border-[var(--border-default)]" />
                  </div>
                  <div className="space-y-2" dir="rtl">
                    <label className="text-sm font-bold">Name (AR)</label>
                    <input type="text" value={formData.nameAr} onChange={e => handleChange('nameAr', e.target.value)} className="w-full px-4 py-2 rounded-xl bg-[var(--surface-hover)] border border-[var(--border-default)] text-right" />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-bold">URL Slug</label>
                  <input type="text" value={formData.slug} onChange={e => handleChange('slug', e.target.value)} className="w-full px-4 py-2 rounded-xl bg-[var(--surface-hover)] border border-[var(--border-default)]" />
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-bold">Description (EN)</label>
                  <TipTapEditor value={formData.descriptionEn} onChange={v => handleChange('descriptionEn', v)} dir="ltr" />
                </div>

                <div className="space-y-2" dir="rtl">
                  <label className="text-sm font-bold">Description (AR)</label>
                  <TipTapEditor value={formData.descriptionAr} onChange={v => handleChange('descriptionAr', v)} dir="rtl" />
                </div>

                <div className="flex gap-8 pt-4 border-t border-[var(--border-default)]">
                  <label className="flex items-center gap-3 cursor-pointer">
                    <input type="checkbox" checked={formData.isPublished} onChange={e => handleChange('isPublished', e.target.checked)} className="w-5 h-5 rounded border-[var(--border-default)] text-[var(--color-primary)]" />
                    <span className="font-bold">Published</span>
                  </label>
                  <label className="flex items-center gap-3 cursor-pointer">
                    <input type="checkbox" checked={formData.isHidden} onChange={e => handleChange('isHidden', e.target.checked)} className="w-5 h-5 rounded border-[var(--border-default)] text-[var(--color-primary)]" />
                    <span className="font-bold">Hidden from Listings</span>
                  </label>
                  <label className="flex items-center gap-3 cursor-pointer">
                    <input type="checkbox" checked={formData.isFeatured} onChange={e => handleChange('isFeatured', e.target.checked)} className="w-5 h-5 rounded border-[var(--border-default)] text-[var(--color-primary)]" />
                    <span className="font-bold">Featured Attraction</span>
                  </label>
                </div>
              </div>
            )}

            {/* TAB: HERO MEDIA */}
            {activeTab === "hero" && (
              <div className="bg-[var(--surface-default)] border border-[var(--border-default)] rounded-2xl p-6 md:p-8 space-y-6">
                <h2 className="text-lg font-black text-[var(--text-primary)] mb-4">Hero Media</h2>
                <div className="space-y-2">
                  <label className="text-sm font-bold">Media Type</label>
                  <select 
                    value={formData.heroMediaType} 
                    onChange={e => handleChange('heroMediaType', e.target.value)}
                    className="w-full px-4 py-2 rounded-xl bg-[var(--surface-hover)] border border-[var(--border-default)]"
                  >
                    <option value="IMAGE">Image</option>
                    <option value="VIDEO">Video</option>
                    <option value="MODEL_3D">3D Model</option>
                  </select>
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-bold">Media Source (Upload or URL)</label>
                  {formData.heroMediaType === 'IFRAME' ? (
                    <input 
                      type="text" 
                      value={formData.heroMediaUrl} 
                      onChange={e => handleChange('heroMediaUrl', e.target.value)} 
                      placeholder="https://..." 
                      className="w-full px-4 py-2 rounded-xl bg-[var(--surface-hover)] border border-[var(--border-default)]" 
                    />
                  ) : (
                    <div className="space-y-4">
                      <MediaUploader 
                        value={formData.heroMediaUrl} 
                        onChange={url => handleChange('heroMediaUrl', url)} 
                        accept={formData.heroMediaType === 'VIDEO' ? "video/*" : formData.heroMediaType === 'MODEL_3D' ? ".glb,.gltf" : "image/*"}
                      />
                      <div className="flex items-center gap-2">
                        <span className="text-xs text-[var(--text-secondary)] font-bold whitespace-nowrap">OR EXTERNAL URL:</span>
                        <input 
                          type="text" 
                          value={formData.heroMediaUrl} 
                          onChange={e => handleChange('heroMediaUrl', e.target.value)} 
                          placeholder="https://..." 
                          className="flex-1 px-4 py-2 text-sm rounded-xl bg-[var(--surface-hover)] border border-[var(--border-default)]" 
                        />
                      </div>
                    </div>
                  )}
                </div>
              </div>
            )}

            {/* TAB: GALLERY */}
            {activeTab === "gallery" && (
              <div className="bg-[var(--surface-default)] border border-[var(--border-default)] rounded-2xl p-6 md:p-8">
                <h2 className="text-lg font-black text-[var(--text-primary)] mb-6">Gallery Images</h2>
                <RepeaterField
                  items={gallery}
                  setItems={(items) => { setGallery(items); setHasUnsavedChanges(true) }}
                  onAdd={() => {
                    setGallery([...gallery, { id: Math.random().toString(), url: "", captionEn: "", captionAr: "" }])
                    setHasUnsavedChanges(true)
                  }}
                  addLabel="Add Image"
                  renderItem={(item, index, update) => (
                    <div className="flex flex-col md:flex-row gap-4 w-full">
                      <div className="w-full md:w-48 shrink-0">
                        <MediaUploader value={item.url} onChange={url => update({ url })} />
                      </div>
                      <div className="flex-1 space-y-4">
                        <input placeholder="Caption (EN)" value={item.captionEn} onChange={e => update({ captionEn: e.target.value })} className="w-full px-3 py-2 rounded bg-[var(--surface-hover)] border border-[var(--border-default)]" />
                        <input placeholder="Caption (AR)" value={item.captionAr} onChange={e => update({ captionAr: e.target.value })} dir="rtl" className="w-full px-3 py-2 rounded bg-[var(--surface-hover)] border border-[var(--border-default)] text-right" />
                      </div>
                    </div>
                  )}
                />
              </div>
            )}

            {/* TAB: PRICING */}
            {activeTab === "pricing" && (
              <div className="bg-[var(--surface-default)] border border-[var(--border-default)] rounded-2xl p-6 md:p-8">
                <h2 className="text-lg font-black text-[var(--text-primary)] mb-6">Pricing & Tickets</h2>
                <RepeaterField
                  items={pricing}
                  setItems={(items) => { setPricing(items); setHasUnsavedChanges(true) }}
                  onAdd={() => {
                    setPricing([...pricing, { id: Math.random().toString(), titleEn: "", titleAr: "", price: 0, currency: "QAR", type: "GENERAL" }])
                    setHasUnsavedChanges(true)
                  }}
                  addLabel="Add Ticket Tier"
                  renderItem={(item, index, update) => (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full">
                      <input placeholder="Tier Title (EN)" value={item.titleEn} onChange={e => update({ titleEn: e.target.value })} className="w-full px-3 py-2 rounded bg-[var(--surface-hover)] border border-[var(--border-default)]" />
                      <input placeholder="Tier Title (AR)" value={item.titleAr} onChange={e => update({ titleAr: e.target.value })} dir="rtl" className="w-full px-3 py-2 rounded bg-[var(--surface-hover)] border border-[var(--border-default)] text-right" />
                      <div className="flex items-center gap-2">
                        <input type="number" placeholder="Price" value={item.price} onChange={e => update({ price: e.target.value })} className="w-full px-3 py-2 rounded bg-[var(--surface-hover)] border border-[var(--border-default)]" />
                        <select value={item.currency} onChange={e => update({ currency: e.target.value })} className="px-3 py-2 rounded bg-[var(--surface-hover)] border border-[var(--border-default)]">
                          <option value="QAR">QAR</option>
                          <option value="USD">USD</option>
                        </select>
                      </div>
                      <select value={item.type} onChange={e => update({ type: e.target.value })} className="px-3 py-2 rounded bg-[var(--surface-hover)] border border-[var(--border-default)]">
                        <option value="GENERAL">General Admission</option>
                        <option value="VIP">VIP</option>
                        <option value="CHILD">Child</option>
                        <option value="FAMILY">Family Package</option>
                      </select>
                    </div>
                  )}
                />
              </div>
            )}

            {/* TAB: FAQ */}
            {activeTab === "faq" && (
              <div className="bg-[var(--surface-default)] border border-[var(--border-default)] rounded-2xl p-6 md:p-8">
                <h2 className="text-lg font-black text-[var(--text-primary)] mb-6">Frequently Asked Questions</h2>
                <RepeaterField
                  items={faqs}
                  setItems={(items) => { setFaqs(items); setHasUnsavedChanges(true) }}
                  onAdd={() => {
                    setFaqs([...faqs, { id: Math.random().toString(), questionEn: "", questionAr: "", answerEn: "", answerAr: "" }])
                    setHasUnsavedChanges(true)
                  }}
                  addLabel="Add FAQ"
                  renderItem={(item, index, update) => (
                    <div className="grid grid-cols-1 gap-4 w-full">
                      <input placeholder="Question (EN)" value={item.questionEn} onChange={e => update({ questionEn: e.target.value })} className="w-full px-3 py-2 rounded bg-[var(--surface-hover)] border border-[var(--border-default)] font-bold" />
                      <TipTapEditor value={item.answerEn} onChange={v => update({ answerEn: v })} dir="ltr" placeholder="Answer (EN)" />
                      <div className="h-px bg-[var(--border-default)] my-2" />
                      <input placeholder="Question (AR)" value={item.questionAr} onChange={e => update({ questionAr: e.target.value })} dir="rtl" className="w-full px-3 py-2 rounded bg-[var(--surface-hover)] border border-[var(--border-default)] text-right font-bold" />
                      <TipTapEditor value={item.answerAr} onChange={v => update({ answerAr: v })} dir="rtl" placeholder="Answer (AR)" />
                    </div>
                  )}
                />
              </div>
            )}

          </div>
        </div>
      </div>
    </div>
  )
}

"use client"

import { useState } from "react"
import { useRouter } from "next/navigation"
import { 
  Save, ArrowLeft, Settings, DollarSign, HelpCircle, 
  Plus, Trash2, Image as ImageIcon, MapPin, Share2, 
  Users, List, Calendar
} from "lucide-react"
import { Button } from "@/components/ui/Button"
import { MediaUploader } from "@/components/ui/MediaUploader"
import { cn } from "@/lib/utils"
import { motion } from "framer-motion"
import { useEffect } from "react"
import { AdminSeoCustomizer } from "@/components/dashboard/ui/AdminSeoCustomizer"
import { uploadFile } from "@/lib/upload"

export function AttractionEditor({ initialData }: { initialData?: any }) {
  const router = useRouter()
  const isEditing = !!initialData
  
  const [activeTab, setActiveTab] = useState("general")
  const [isSaving, setIsSaving] = useState(false)
  
  // 1. Core Details
  const [nameEn, setNameEn] = useState(initialData?.nameEn || "")
  const [nameAr, setNameAr] = useState(initialData?.nameAr || "")
  const [slug, setSlug] = useState(initialData?.slug || "")
  const [taglineEn, setTaglineEn] = useState(initialData?.taglineEn || "")
  const [taglineAr, setTaglineAr] = useState(initialData?.taglineAr || "")
  const [descriptionEn, setDescriptionEn] = useState(initialData?.descriptionEn || "")
  const [descriptionAr, setDescriptionAr] = useState(initialData?.descriptionAr || "")
  const [isPublished, setIsPublished] = useState(initialData?.isPublished ?? false)
  const [isFeatured] = useState(initialData?.isFeatured ?? false)
  const [isHidden] = useState(initialData?.isHidden ?? false)

  // 2. Hero Media
  const [heroMediaType, setHeroMediaType] = useState(initialData?.heroMediaType || "IMAGE")
  const [heroMediaUrl, setHeroMediaUrl] = useState(initialData?.heroMediaUrl || "")
  const [heroFallbackUrl, setHeroFallbackUrl] = useState(initialData?.heroFallbackUrl || "")
  const [heroThumbnailUrl, setHeroThumbnailUrl] = useState(initialData?.heroThumbnailUrl || "")
  const [logoUrl, setLogoUrl] = useState(initialData?.logoUrl || "")

  // 3. What&apos;s Inside (Features)
  const [features, setFeatures] = useState<any[]>(
    Array.isArray(initialData?.features) ? initialData.features : []
  )

  // 4. Pricing & Tickets
  const [pricing, setPricing] = useState<any[]>(initialData?.pricing || [])

  // 5. Partners
  const [partnerOffers, setPartnerOffers] = useState<any[]>(
    Array.isArray(initialData?.partnerOffers) ? initialData.partnerOffers : []
  )
  const [partners, setPartners] = useState<any[]>(
    Array.isArray(initialData?.partners) ? initialData.partners : []
  )

  // 6. Social & News
  const [socialLinks, setSocialLinks] = useState<any[]>(initialData?.socialLinks || [])
  const [socialPreviews, setSocialPreviews] = useState<any[]>(
    Array.isArray(initialData?.socialPreviews) ? initialData.socialPreviews : []
  )
  const [newsCoverage, setNewsCoverage] = useState<any[]>(
    Array.isArray(initialData?.newsCoverage) ? initialData.newsCoverage : []
  )

  // 7. Booking & Ops
  const [mapUrl, setMapUrl] = useState(initialData?.mapUrl || "")
  const [ticketingUrl, setTicketingUrl] = useState(initialData?.ticketingUrl || "")
  const [operations, setOperations] = useState<any>(
    initialData?.operations || { venueName: "", ageGroup: "", hours: "", schedules: [], contactDetails: { phone: "", email: "", whatsapp: "", chatLink: "" } }
  )
  const [temporalStatus, setTemporalStatus] = useState<any>(
    initialData?.temporalStatus || { isPermanent: true, startDate: "", endDate: "", statusOverride: "", isSpecialEvent: false }
  )
  const [testimonials, setTestimonials] = useState<any[]>(
    Array.isArray(initialData?.testimonials) ? initialData.testimonials : []
  )

  // 8. FAQs
  const [faqs, setFaqs] = useState<any[]>(initialData?.faqs || [])

  // 9. Gallery
  const [gallery, setGallery] = useState<any[]>(initialData?.gallery || [])

  const [seo, setSeo] = useState<any>(initialData?.seo || {})

  const [errors, setErrors] = useState<string[]>([])

  const currentData = JSON.stringify({
    nameEn, nameAr, slug, taglineEn, taglineAr, descriptionEn, descriptionAr,
    isPublished, isFeatured, isHidden,
    heroMediaType, heroMediaUrl, heroFallbackUrl, heroThumbnailUrl, logoUrl,
    features, pricing, partnerOffers, partners, socialLinks, socialPreviews, newsCoverage,
    mapUrl, ticketingUrl, operations, temporalStatus, faqs, testimonials, gallery
  })
  const [initialDataStr] = useState(currentData)
  const isDirty = currentData !== initialDataStr

  useEffect(() => {
    if (!isDirty) return
    const handleBeforeUnload = (e: BeforeUnloadEvent) => {
      e.preventDefault()
      e.returnValue = ''
    }
    window.addEventListener('beforeunload', handleBeforeUnload)
    return () => window.removeEventListener('beforeunload', handleBeforeUnload)
  }, [isDirty])

  const handleSave = async () => {
    const newErrors = []
    if (!nameEn) newErrors.push("nameEn")
    if (!slug) newErrors.push("slug")
    
    if (newErrors.length > 0) {
      setActiveTab("general")
      setErrors(newErrors)
      setTimeout(() => setErrors([]), 800)
      return
    }
    
    setIsSaving(true)
    try {
      const payload = {
        nameEn, nameAr, slug, taglineEn, taglineAr, descriptionEn, descriptionAr,
        isPublished, isFeatured, isHidden,
        heroMediaType, heroMediaUrl, heroFallbackUrl, heroThumbnailUrl, logoUrl,
        features,
        pricing,
        partnerOffers, partners,
        socialLinks, socialPreviews, newsCoverage,
        mapUrl, ticketingUrl, operations, temporalStatus,
        faqs, testimonials, gallery, seo
      }
      
      const url = isEditing 
        ? `/api/b2c/attractions/${initialData.id}/full` 
        : `/api/b2c/attractions`
        
      const res = await fetch(url, {
        method: isEditing ? "PUT" : "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      })
      
      if (!res.ok) throw new Error("Failed to save")
      
      router.push("/dashboard/b2c/attractions")
      router.refresh()
    } catch {
      alert("Error saving attraction")
    } finally {
      setIsSaving(false)
    }
  }

  const tabs = [
    { id: "general", label: "Core Details", icon: Settings },
    { id: "hero", label: "Hero Media", icon: ImageIcon },
    { id: "features", label: "What&apos;s Inside", icon: List },
    { id: "pricing", label: "Pricing & Tickets", icon: DollarSign },
    { id: "partners", label: "Partners", icon: Users },
    { id: "social", label: "Social & News", icon: Share2 },
    { id: "ops", label: "Booking & Ops", icon: MapPin },
    { id: "visibility", label: "Visibility", icon: Calendar },
    { id: "gallery", label: "Gallery", icon: ImageIcon },
    { id: "faqs", label: "FAQs", icon: HelpCircle },
    { id: "seo", label: "SEO Settings", icon: Settings },
  ]

  // Helper for generic array updates
  const updateArrayItem = (setter: any, array: any[], index: number, field: string, value: any) => {
    const newArr = [...array]
    newArr[index][field] = value
    setter(newArr)
  }

  return (
    <div className="space-y-6 max-w-6xl mx-auto pb-24">
      {/* Header */}
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between bg-[var(--surface-default)] p-4 rounded-2xl border border-[var(--border-default)] shadow-sm sticky top-6 z-30 gap-4">
        <div className="flex items-center gap-4">
          <button 
            onClick={() => {
              if (isDirty && !window.confirm("You have unsaved changes. Discard them?")) return;
              router.back()
            }}
            className="p-2 hover:bg-[var(--surface-hover)] rounded-xl transition-colors text-[var(--text-secondary)]"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-xl font-bold text-[var(--text-primary)]">
              {isEditing ? "Edit Attraction Microsite" : "New Attraction Microsite"}
            </h1>
            <p className="text-xs text-[var(--text-secondary)] mt-0.5">{nameEn || "Untitled"}</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <label className="flex items-center gap-2 cursor-pointer bg-[var(--surface-subtle)] px-4 py-2 rounded-xl border border-[var(--border-default)]">
            <input 
              type="checkbox" 
              checked={isPublished}
              onChange={e => setIsPublished(e.target.checked)}
              className="w-4 h-4 rounded border-gray-300 text-[var(--color-primary)] focus:ring-[var(--color-primary)]"
            />
            <span className="text-sm font-bold text-[var(--text-primary)]">Published</span>
          </label>
          <Button onClick={handleSave} disabled={isSaving} className="gap-2">
            {isSaving ? <div className="w-4 h-4 rounded-full border-2 border-white/20 border-t-white animate-spin" /> : <Save className="w-4 h-4" />}
            Save Changes
          </Button>
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-6">
        {/* Navigation Sidebar */}
        <div className="w-full lg:w-64 shrink-0 space-y-1">
          {tabs.map(tab => {
            const Icon = tab.icon
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={cn(
                  "w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all text-left",
                  activeTab === tab.id 
                    ? "bg-[var(--color-primary)] text-white shadow-md shadow-[var(--color-primary)]/20 translate-x-1" 
                    : "text-[var(--text-secondary)] hover:bg-[var(--surface-hover)] hover:text-[var(--text-primary)]"
                )}
              >
                <Icon className="w-4 h-4" />
                {tab.label}
              </button>
            )
          })}
        </div>

        {/* Content Area */}
        <div className="flex-1 bg-[var(--surface-default)] border border-[var(--border-default)] rounded-2xl shadow-sm p-6 md:p-8 min-h-[600px]">
          
          {/* 1. CORE DETAILS */}
          {activeTab === "general" && (
            <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
              <h2 className="text-lg font-black mb-6">Core Details</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <motion.div animate={{ x: errors.includes("nameEn") ? [0, -10, 10, -10, 10, 0] : 0 }} transition={{ duration: 0.4 }} className="space-y-2">
                  <label className="text-xs font-bold text-[var(--text-secondary)] uppercase tracking-wider">Attraction Name (EN) *</label>
                  <input type="text" value={nameEn}
                    onChange={e => {
                      setNameEn(e.target.value)
                      if (!isEditing) setSlug(e.target.value.toLowerCase().replace(/[^a-z0-9]+/g, "-"))
                    }}
                    className={cn(
                      "w-full bg-[var(--surface-subtle)] border rounded-xl px-4 py-3 text-sm focus:outline-none transition-colors",
                      errors.includes("nameEn") ? "border-[var(--color-error)] focus:border-[var(--color-error)]" : "border-[var(--border-default)] focus:border-[var(--color-primary)]"
                    )}
                  />
                </motion.div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-[var(--text-secondary)] uppercase tracking-wider">Attraction Name (AR)</label>
                  <input type="text" dir="rtl" value={nameAr} onChange={e => setNameAr(e.target.value)}
                    className="w-full bg-[var(--surface-subtle)] border border-[var(--border-default)] rounded-xl px-4 py-3 text-sm focus:border-[var(--color-primary)] focus:outline-none transition-colors text-right"
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-[var(--text-secondary)] uppercase tracking-wider">Tagline (EN)</label>
                  <input type="text" value={taglineEn} onChange={e => setTaglineEn(e.target.value)}
                    className="w-full bg-[var(--surface-subtle)] border border-[var(--border-default)] rounded-xl px-4 py-3 text-sm focus:border-[var(--color-primary)] focus:outline-none transition-colors"
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-[var(--text-secondary)] uppercase tracking-wider">Tagline (AR)</label>
                  <input type="text" dir="rtl" value={taglineAr} onChange={e => setTaglineAr(e.target.value)}
                    className="w-full bg-[var(--surface-subtle)] border border-[var(--border-default)] rounded-xl px-4 py-3 text-sm focus:border-[var(--color-primary)] focus:outline-none transition-colors text-right"
                  />
                </div>
                <motion.div animate={{ x: errors.includes("slug") ? [0, -10, 10, -10, 10, 0] : 0 }} transition={{ duration: 0.4 }} className="space-y-2 md:col-span-2">
                  <label className="text-xs font-bold text-[var(--text-secondary)] uppercase tracking-wider">URL Slug *</label>
                  <input type="text" value={slug} onChange={e => setSlug(e.target.value)}
                    className={cn(
                      "w-full bg-[var(--surface-subtle)] border rounded-xl px-4 py-3 text-sm font-mono focus:outline-none transition-colors",
                      errors.includes("slug") ? "border-[var(--color-error)] focus:border-[var(--color-error)]" : "border-[var(--border-default)] focus:border-[var(--color-primary)]"
                    )}
                  />
                </motion.div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-[var(--text-secondary)] uppercase tracking-wider">Description (EN)</label>
                  <textarea value={descriptionEn} onChange={e => setDescriptionEn(e.target.value)} rows={5}
                    className="w-full bg-[var(--surface-subtle)] border border-[var(--border-default)] rounded-xl px-4 py-3 text-sm focus:border-[var(--color-primary)] focus:outline-none resize-y"
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-[var(--text-secondary)] uppercase tracking-wider">Description (AR)</label>
                  <textarea dir="rtl" value={descriptionAr} onChange={e => setDescriptionAr(e.target.value)} rows={5}
                    className="w-full bg-[var(--surface-subtle)] border border-[var(--border-default)] rounded-xl px-4 py-3 text-sm focus:border-[var(--color-primary)] focus:outline-none resize-y text-right"
                  />
                </div>
              </div>
            </div>
          )}

          {/* 2. HERO MEDIA */}
          {activeTab === "hero" && (
            <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
              <h2 className="text-lg font-black mb-6">Hero Media Controller</h2>
              <div className="space-y-6">
                <div>
                  <label className="text-xs font-bold text-[var(--text-secondary)] uppercase tracking-wider mb-3 block">Media Type</label>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                    {["IMAGE", "VIDEO", "MODEL_3D", "IFRAME"].map(type => (
                      <button key={type} onClick={() => setHeroMediaType(type)}
                        className={`p-3 rounded-xl border text-sm font-bold transition-all ${
                          heroMediaType === type 
                          ? 'bg-[var(--color-primary)]/10 border-[var(--color-primary)] text-[var(--color-primary)]' 
                          : 'bg-[var(--surface-subtle)] border-[var(--border-default)] text-[var(--text-secondary)] hover:border-[var(--color-primary)]/50'
                        }`}
                      >
                        {type.replace("_", " ")}
                      </button>
                    ))}
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-[var(--text-secondary)] uppercase tracking-wider">Primary Media Source (Upload or URL)</label>
                  {heroMediaType === 'IFRAME' ? (
                    <input 
                      type="text" 
                      value={heroMediaUrl || ''} 
                      onChange={e => setHeroMediaUrl(e.target.value)} 
                      placeholder="https://my.spline.design/..." 
                      className="w-full bg-[var(--surface-default)] border border-[var(--border-default)] rounded-xl px-4 py-3 text-sm focus:border-[var(--color-primary)] focus:outline-none"
                    />
                  ) : (
                    <div className="space-y-4">
                      <MediaUploader 
                        value={heroMediaUrl} 
                        onChange={(url) => {
                          setHeroMediaUrl(url);
                          // Distribute accordingly
                          if (heroMediaType === 'IMAGE') {
                            if (!heroFallbackUrl) setHeroFallbackUrl(url);
                            if (!heroThumbnailUrl) setHeroThumbnailUrl(url);
                            if (!logoUrl) setLogoUrl(url);
                          } else if (heroMediaType === 'VIDEO' || heroMediaType === 'MODEL_3D') {
                            // Even if it's video/3D, they might want the URL for thumbnail or we don't overwrite if it's not an image.
                            // But usually, video is just the primary media.
                          }
                        }}
                        accept={heroMediaType === 'VIDEO' ? "video/*" : heroMediaType === 'MODEL_3D' ? ".glb,.gltf" : "image/*"}
                      />
                      <div className="flex items-center gap-2">
                        <span className="text-[10px] text-[var(--text-secondary)] font-bold uppercase whitespace-nowrap">OR EXTERNAL URL:</span>
                        <input 
                          type="text" 
                          value={heroMediaUrl || ''} 
                          onChange={e => setHeroMediaUrl(e.target.value)} 
                          onBlur={e => {
                            const url = e.target.value;
                            if (url && heroMediaType === 'IMAGE') {
                              if (!heroFallbackUrl) setHeroFallbackUrl(url);
                              if (!heroThumbnailUrl) setHeroThumbnailUrl(url);
                              if (!logoUrl) setLogoUrl(url);
                            }
                          }}
                          placeholder="https://..." 
                          className="flex-1 bg-[var(--surface-default)] border border-[var(--border-default)] rounded-xl px-4 py-2 text-sm focus:border-[var(--color-primary)] focus:outline-none" 
                        />
                      </div>
                    </div>
                  )}
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-[var(--text-secondary)] uppercase tracking-wider">Fallback Image URL</label>
                    <MediaUploader value={heroFallbackUrl} onChange={setHeroFallbackUrl} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-[var(--text-secondary)] uppercase tracking-wider">Thumbnail Image URL</label>
                    <MediaUploader value={heroThumbnailUrl} onChange={setHeroThumbnailUrl} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-bold text-[var(--text-secondary)] uppercase">Attraction Logo URL</label>
                    <MediaUploader value={logoUrl} onChange={setLogoUrl} />
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* 3. WHAT'S INSIDE */}
          {activeTab === "features" && (
            <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-lg font-black">What&apos;s Inside</h2>
                <Button type="button" onClick={() => setFeatures([...features, { id: Date.now(), title: "", description: "", imageUrl: "" }])} variant="outline" size="sm" className="gap-2 rounded-xl">
                  <Plus className="w-4 h-4" /> Add Item
                </Button>
              </div>
              
              <div className="space-y-4">
                {features.map((item, index) => (
                  <div key={item.id || index} className="p-4 border border-[var(--border-default)] rounded-xl bg-[var(--surface-subtle)] relative">
                    <button type="button" onClick={() => setFeatures(features.filter((_, i) => i !== index))} className="absolute top-4 end-4 p-1.5 text-red-500 hover:bg-red-500/10 rounded-lg">
                      <Trash2 className="w-4 h-4" />
                    </button>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pe-10">
                      <div className="space-y-2">
                        <label className="text-[10px] font-bold text-[var(--text-secondary)] uppercase">Item Title</label>
                        <input type="text" value={item.title} onChange={e => updateArrayItem(setFeatures, features, index, "title", e.target.value)}
                          className="w-full bg-[var(--surface-default)] border border-[var(--border-default)] rounded-lg px-3 py-2 text-sm focus:border-[var(--color-primary)] focus:outline-none"
                        />
                      </div>
                      <div className="space-y-2">
                        <label className="text-[10px] font-bold text-[var(--text-secondary)] uppercase">Media URL</label>
                        <MediaUploader value={item.imageUrl} onChange={val => updateArrayItem(setFeatures, features, index, "imageUrl", val)} />
                      </div>
                      <div className="space-y-2 md:col-span-2">
                        <label className="text-[10px] font-bold text-[var(--text-secondary)] uppercase">Short Description</label>
                        <textarea value={item.description} onChange={e => updateArrayItem(setFeatures, features, index, "description", e.target.value)} rows={2}
                          className="w-full bg-[var(--surface-default)] border border-[var(--border-default)] rounded-lg px-3 py-2 text-sm focus:border-[var(--color-primary)] focus:outline-none resize-none"
                        />
                      </div>
                    </div>
                  </div>
                ))}
                {features.length === 0 && <div className="text-center py-12 border-2 border-dashed border-[var(--border-default)] rounded-xl text-[var(--text-tertiary)] font-medium">No items added.</div>}
              </div>
            </div>
          )}

          {/* 4. PRICING */}
          {activeTab === "pricing" && (
            <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-lg font-black">Pricing & Tickets</h2>
                <Button type="button" onClick={() => setPricing([...pricing, { id: Date.now().toString(), titleEn: "", titleAr: "", descriptionEn: "", descriptionAr: "", price: 0, discount: 0, currency: "QAR", type: "GENERAL" }])} variant="outline" size="sm" className="gap-2 rounded-xl">
                  <Plus className="w-4 h-4" /> Add Tier
                </Button>
              </div>

              <div className="space-y-4">
                {pricing.map((tier, index) => (
                  <div key={tier.id || index} className="p-5 border border-[var(--border-default)] rounded-xl bg-[var(--surface-subtle)] relative">
                    <button type="button" onClick={() => setPricing(pricing.filter((_, i) => i !== index))} className="absolute top-4 end-4 p-1.5 text-red-500 hover:bg-red-500/10 rounded-lg">
                      <Trash2 className="w-4 h-4" />
                    </button>
                    <div className="grid grid-cols-1 md:grid-cols-12 gap-4 pe-10">
                      <div className="md:col-span-4 space-y-3">
                        <div>
                          <label className="text-[10px] font-bold text-[var(--text-secondary)] uppercase mb-1 block">Tier Title (EN)</label>
                          <input type="text" value={tier.titleEn} onChange={e => updateArrayItem(setPricing, pricing, index, "titleEn", e.target.value)}
                            className="w-full bg-[var(--surface-default)] border border-[var(--border-default)] rounded-lg px-3 py-2 text-sm focus:border-[var(--color-primary)] focus:outline-none"
                          />
                        </div>
                        <div>
                          <label className="text-[10px] font-bold text-[var(--text-secondary)] uppercase mb-1 block">Tier Title (AR)</label>
                          <input type="text" dir="rtl" value={tier.titleAr} onChange={e => updateArrayItem(setPricing, pricing, index, "titleAr", e.target.value)}
                            className="w-full bg-[var(--surface-default)] border border-[var(--border-default)] rounded-lg px-3 py-2 text-sm focus:border-[var(--color-primary)] focus:outline-none text-right"
                          />
                        </div>
                      </div>
                      <div className="md:col-span-4 space-y-3">
                        <div>
                          <label className="text-[10px] font-bold text-[var(--text-secondary)] uppercase mb-1 block">Base Price</label>
                          <input type="number" value={tier.price} onChange={e => updateArrayItem(setPricing, pricing, index, "price", parseFloat(e.target.value))}
                            className="w-full bg-[var(--surface-default)] border border-[var(--border-default)] rounded-lg px-3 py-2 text-sm focus:border-[var(--color-primary)] focus:outline-none"
                          />
                        </div>
                        <div>
                          <label className="text-[10px] font-bold text-[var(--text-secondary)] uppercase mb-1 block">Discount %</label>
                          <input type="number" value={tier.discount || ''} onChange={e => updateArrayItem(setPricing, pricing, index, "discount", parseFloat(e.target.value))}
                            className="w-full bg-[var(--surface-default)] border border-[var(--border-default)] rounded-lg px-3 py-2 text-sm focus:border-[var(--color-primary)] focus:outline-none"
                          />
                        </div>
                      </div>
                      <div className="md:col-span-4 space-y-3">
                         <div>
                          <label className="text-[10px] font-bold text-[var(--text-secondary)] uppercase mb-1 block">Ticket Type</label>
                          <input type="text" placeholder="e.g. VIP, General, Family" value={tier.type} onChange={e => updateArrayItem(setPricing, pricing, index, "type", e.target.value)}
                            className="w-full bg-[var(--surface-default)] border border-[var(--border-default)] rounded-lg px-3 py-2 text-sm focus:border-[var(--color-primary)] focus:outline-none"
                          />
                        </div>
                      </div>
                      <div className="md:col-span-12 space-y-3 mt-2">
                        <label className="text-[10px] font-bold text-[var(--text-secondary)] uppercase">Short Description (EN & AR)</label>
                        <div className="grid grid-cols-2 gap-4">
                          <input type="text" placeholder="EN Description" value={tier.descriptionEn || ''} onChange={e => updateArrayItem(setPricing, pricing, index, "descriptionEn", e.target.value)}
                            className="w-full bg-[var(--surface-default)] border border-[var(--border-default)] rounded-lg px-3 py-2 text-sm focus:border-[var(--color-primary)] focus:outline-none"
                          />
                           <input type="text" placeholder="AR Description" dir="rtl" value={tier.descriptionAr || ''} onChange={e => updateArrayItem(setPricing, pricing, index, "descriptionAr", e.target.value)}
                            className="w-full bg-[var(--surface-default)] border border-[var(--border-default)] rounded-lg px-3 py-2 text-sm focus:border-[var(--color-primary)] focus:outline-none text-right"
                          />
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
                {pricing.length === 0 && <div className="text-center py-12 border-2 border-dashed border-[var(--border-default)] rounded-xl text-[var(--text-tertiary)] font-medium">No pricing tiers defined.</div>}
              </div>
            </div>
          )}

          {/* 5. PARTNERS */}
          {activeTab === "partners" && (
            <div className="space-y-12 animate-in fade-in slide-in-from-bottom-2 duration-300">
              
              {/* Partner Offers */}
              <div>
                <div className="flex items-center justify-between mb-6">
