              />
            </div>
          </div>
        </div>

        {/* Corporate & Team Section */}
        <div className="bg-surface-default border border-border-default rounded-xl p-6 space-y-6">
          <h2 className="text-lg font-bold text-text-primary">Corporate Roster</h2>
          
          <div className="grid grid-cols-2 gap-6 pb-6 border-b border-border-default">
            <div className="space-y-2">
              <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Section Title (En)</label>
              <input 
                type="text" 
                value={data.corporate.titleEn}
                onChange={e => handleChange('corporate', 'titleEn', e.target.value)}
                className="w-full bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none"
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Section Title (Ar)</label>
              <input 
                type="text" 
                dir="rtl"
                value={data.corporate.titleAr}
                onChange={e => handleChange('corporate', 'titleAr', e.target.value)}
                className="w-full bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none"
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Subtitle (En)</label>
              <input 
                type="text" 
                value={data.corporate.subtitleEn}
                onChange={e => handleChange('corporate', 'subtitleEn', e.target.value)}
                className="w-full bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none"
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Subtitle (Ar)</label>
              <input 
                type="text" 
                dir="rtl"
                value={data.corporate.subtitleAr}
                onChange={e => handleChange('corporate', 'subtitleAr', e.target.value)}
                className="w-full bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none"
              />
            </div>
          </div>

          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h3 className="font-bold text-text-primary">Team Members</h3>
              <AdminButton variant="outline" onClick={addTeamMember} type="button">Add Member</AdminButton>
            </div>
            
            {data.team.map((member: any, idx: number) => {
              const safeMember: any = {
                nameEn: member.nameEn || (member as any).name || "",
                nameAr: member.nameAr || "",
                roleEn: member.roleEn || (member as any).role || "",
                roleAr: member.roleAr || "",
                descEn: member.descEn || (member as any).desc || "",
                descAr: member.descAr || "",
                imageUrl: member.imageUrl || ""
              };
              return (
              <div key={idx} className="border border-border-default p-4 rounded-lg relative space-y-4">
                <button type="button" onClick={() => removeTeamMember(idx)} className="absolute top-4 right-4 text-red-500 text-xs font-bold">Remove</button>
                <h4 className="font-bold text-text-secondary text-sm">Member {idx + 1}</h4>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Name (En)</label>
                    <input 
                      type="text" 
                      value={safeMember.nameEn}
                      onChange={e => handleTeamChange(idx, 'nameEn', e.target.value)}
                      className="w-full bg-surface-hover border border-border-default rounded-lg px-3 py-1.5 text-sm text-text-primary focus:border-primary focus:outline-none"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Name (Ar)</label>
                    <input 
                      type="text" 
                      dir="rtl"
                      value={safeMember.nameAr}
                      onChange={e => handleTeamChange(idx, 'nameAr', e.target.value)}
                      className="w-full bg-surface-hover border border-border-default rounded-lg px-3 py-1.5 text-sm text-text-primary focus:border-primary focus:outline-none"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Role (En)</label>
                    <input 
                      type="text" 
                      value={safeMember.roleEn}
                      onChange={e => handleTeamChange(idx, 'roleEn', e.target.value)}
                      className="w-full bg-surface-hover border border-border-default rounded-lg px-3 py-1.5 text-sm text-text-primary focus:border-primary focus:outline-none"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Role (Ar)</label>
                    <input 
                      type="text" 
                      dir="rtl"
                      value={safeMember.roleAr}
                      onChange={e => handleTeamChange(idx, 'roleAr', e.target.value)}
                      className="w-full bg-surface-hover border border-border-default rounded-lg px-3 py-1.5 text-sm text-text-primary focus:border-primary focus:outline-none"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Description (En)</label>
                    <textarea 
                      value={safeMember.descEn}
                      onChange={e => handleTeamChange(idx, 'descEn', e.target.value)}
                      className="w-full h-20 bg-surface-hover border border-border-default rounded-lg px-3 py-1.5 text-sm text-text-primary focus:border-primary focus:outline-none resize-none"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Description (Ar)</label>
                    <textarea 
                      dir="rtl"
                      value={safeMember.descAr}
                      onChange={e => handleTeamChange(idx, 'descAr', e.target.value)}
                      className="w-full h-20 bg-surface-hover border border-border-default rounded-lg px-3 py-1.5 text-sm text-text-primary focus:border-primary focus:outline-none resize-none"
                    />
                  </div>
                  <div className="space-y-2 col-span-2 border-t border-border-default pt-4 mt-2">
                    <label className="text-xs font-bold text-text-secondary uppercase tracking-wider mb-2 block">Profile Image (Optional)</label>
                    <AdminMediaPicker 
                      value={safeMember.imageUrl} 
                      onChange={url => handleTeamChange(idx, 'imageUrl', url)}
                    />
                  </div>
                </div>
              </div>
            )})}
          </div>
        </div>

        {/* SEO Customizer */}
        <AdminSeoCustomizer seo={seo} setSeo={setSeo} formData={null} setFormData={() => {}} />

      </AdminFormLayout>
    </div>
  )
}

"use client"

import React, { useState } from "react"
import { AdminPageHeader } from "../ui/AdminPageHeader"
import { AdminButton } from "../ui/AdminButton"
import { useToast } from "@/components/dashboard/ui/ToastProvider"
import { FileText, Download, Cpu, Search, Filter } from "lucide-react"

export function ApplicationsManager({ initialApplications }: { initialApplications: any[] }) {
  const [applications, setApplications] = useState(initialApplications)
  const [selectedAppId, setSelectedAppId] = useState<string | null>(null)
  const [parsing, setParsing] = useState(false)
  const [updating, setUpdating] = useState(false)
  const { toast } = useToast()

  const selectedApp = applications.find(a => a.id === selectedAppId)

  const handleParseCV = async (id: string) => {
    setParsing(true)
    try {
      const res = await fetch(`/api/careers/${id}/parse`, { method: 'POST' })
      const json = await res.json()
      
      if (!res.ok) throw new Error(json.error || "Failed to parse CV")
      
      setApplications(prev => prev.map(app => app.id === id ? json.application : app))
      toast("CV parsed successfully.", "success")
    } catch (e: any) {
      console.error(e)
      toast(e.message || "Failed to parse CV.", "error")
    } finally {
      setParsing(false)
    }
  }

  const handleUpdateStatus = async (id: string, newStatus: string) => {
    setUpdating(true)
    try {
      const res = await fetch(`/api/careers/${id}/status`, { 
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus })
      })
      const json = await res.json()
      
      if (!res.ok) throw new Error(json.error || "Failed to update status")
      
      setApplications(prev => prev.map(app => app.id === id ? { ...app, status: newStatus } : app))
      toast("Application status updated.", "success")
    } catch (e: any) {
      console.error(e)
      toast(e.message || "Failed to update status.", "error")
    } finally {
      setUpdating(false)
    }
  }

  const getStatusColor = (status: string) => {
    switch(status) {
      case 'NEW': return 'bg-blue-500/10 text-blue-500 border-blue-500/20'
      case 'REVIEWING': return 'bg-yellow-500/10 text-yellow-500 border-yellow-500/20'
      case 'REJECTED': return 'bg-red-500/10 text-red-500 border-red-500/20'
      case 'HIRED': return 'bg-green-500/10 text-green-500 border-green-500/20'
      default: return 'bg-zinc-500/10 text-zinc-400 border-zinc-500/20'
    }
  }

  return (
    <div className="flex flex-col gap-6 h-full p-6">
      <AdminPageHeader 
        title="Global Job Applications"
        description="Review incoming applications across all B2B and B2C portals and use AI to parse CVs."
      />

      <div className="flex flex-col lg:flex-row gap-6 h-[calc(100vh-200px)]">
        {/* Applications List */}
        <div className="w-full lg:w-1/3 flex flex-col gap-4 bg-surface-default border border-border-default rounded-xl overflow-hidden">
          <div className="p-4 border-b border-border-default space-y-4">
            <div className="relative">
              <Search className="absolute start-3 top-2.5 h-4 w-4 text-text-secondary" />
              <input 
                placeholder="Search candidates..." 
                className="w-full ps-9 pe-4 py-2 bg-surface-hover border border-border-default rounded-lg text-sm text-text-primary focus:border-primary focus:outline-none"
              />
            </div>
            <div className="flex gap-2">
              <button className="text-xs flex items-center px-3 py-1.5 bg-surface-hover rounded-md border border-border-default text-text-secondary hover:text-white transition-colors">
                <Filter className="w-3 h-3 me-1" /> All Portals
              </button>
              <button className="text-xs flex items-center px-3 py-1.5 bg-surface-hover rounded-md border border-border-default text-text-secondary hover:text-white transition-colors">
                <Filter className="w-3 h-3 me-1" /> Status
              </button>
            </div>
          </div>
          
          <div className="flex-1 overflow-y-auto">
            {applications.length === 0 ? (
              <div className="p-8 text-center text-text-secondary">
                No applications found.
              </div>
            ) : (
              applications.map((app) => (
                <button
                  key={app.id}
                  onClick={() => setSelectedAppId(app.id)}
                  className={`w-full text-left p-4 border-b border-border-default hover:bg-surface-hover transition-colors ${selectedAppId === app.id ? 'bg-surface-hover border-s-2 border-s-primary' : ''}`}
                >
                  <div className="flex justify-between items-start mb-1">
                    <span className="font-bold text-text-primary">{app.firstName} {app.lastName}</span>
                    <span className={`text-[10px] uppercase font-bold px-2 py-0.5 rounded-full border ${getStatusColor(app.status)}`}>
                      {app.status}
                    </span>
                  </div>
                  <div className="text-sm text-text-secondary mb-2">{app.jobTitle}</div>
                  <div className="flex items-center justify-between text-xs text-text-secondary">
                    <span>{new Date(app.createdAt).toLocaleDateString()}</span>
                    <span className="bg-zinc-800 px-2 py-0.5 rounded text-[10px]">{app.portal}</span>
                  </div>
                </button>
              ))
            )}
          </div>
        </div>

        {/* Detail View */}
        <div className="w-full lg:w-2/3 bg-surface-default border border-border-default rounded-xl flex flex-col overflow-hidden">
          {selectedApp ? (
            <div className="flex-1 overflow-y-auto p-6 space-y-8">
              {/* Header Info */}
              <div className="flex justify-between items-start">
                <div>
                  <h2 className="text-2xl font-bold text-white mb-1">{selectedApp.firstName} {selectedApp.lastName}</h2>
                  <p className="text-primary font-medium">{selectedApp.jobTitle} {selectedApp.department ? `· ${selectedApp.department}` : ''}</p>
                </div>
                <div className="flex gap-2 items-center">
                  <select 
                    value={selectedApp.status}
                    onChange={(e) => handleUpdateStatus(selectedApp.id, e.target.value)}
                    disabled={updating}
                    className="bg-surface-hover border border-border-default rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-primary disabled:opacity-50"
                  >
                    <option value="NEW">New</option>
                    <option value="REVIEWING">Reviewing</option>
                    <option value="INTERVIEW">Interview</option>
                    <option value="HIRED">Hired</option>
                    <option value="REJECTED">Rejected</option>
                  </select>

                  <a href={selectedApp.cvUrl} target="_blank" rel="noopener noreferrer" className="flex items-center px-4 py-2 bg-surface-hover border border-border-default rounded-lg text-sm font-medium hover:bg-zinc-800 transition-colors">
                    <Download className="w-4 h-4 me-2" /> Download CV
                  </a>
                  {!selectedApp.cvParsedData && (
                    <AdminButton variant="primary" onClick={() => handleParseCV(selectedApp.id)} disabled={parsing}>
                      <Cpu className="w-4 h-4 me-2" /> {parsing ? "Parsing..." : "AI Parse CV"}
                    </AdminButton>
                  )}
                </div>
              </div>

              {/* Contact Info */}
              <div className="grid grid-cols-2 gap-4 p-4 rounded-xl bg-surface-hover border border-border-default">
                <div>
                  <div className="text-xs font-bold text-text-secondary uppercase tracking-wider mb-1">Email</div>
                  <div className="text-sm text-white">{selectedApp.email}</div>
                </div>
                <div>
                  <div className="text-xs font-bold text-text-secondary uppercase tracking-wider mb-1">Phone</div>
                  <div className="text-sm text-white">{selectedApp.phone || "N/A"}</div>
                </div>
                <div>
                  <div className="text-xs font-bold text-text-secondary uppercase tracking-wider mb-1">Applied via</div>
                  <div className="text-sm text-white">{selectedApp.portal} Portal</div>
                </div>
                <div>
                  <div className="text-xs font-bold text-text-secondary uppercase tracking-wider mb-1">Applied on</div>
                  <div className="text-sm text-white">{new Date(selectedApp.createdAt).toLocaleString()}</div>
                </div>
              </div>

              {/* Parsed Data / AI Analysis */}
              <div className="space-y-4">
                <h3 className="text-lg font-bold text-white flex items-center">
                  <Cpu className="w-5 h-5 me-2 text-primary" /> AI Candidate Analysis
                </h3>
                
                {selectedApp.cvParsedData ? (
                  <div className="space-y-6">
                    <div className="p-4 bg-primary/5 border border-primary/20 rounded-xl">
                      <h4 className="text-xs font-bold text-primary uppercase tracking-wider mb-2">Executive Summary</h4>
                      <p className="text-sm text-zinc-300 leading-relaxed">
                        {selectedApp.cvParsedData.summary}
                      </p>
                    </div>
                    
                    <div className="grid grid-cols-2 gap-6">
                      <div className="p-4 bg-surface-hover border border-border-default rounded-xl">
                        <h4 className="text-xs font-bold text-text-secondary uppercase tracking-wider mb-3">Extracted Skills</h4>
                        <div className="flex flex-wrap gap-2">
                          {(selectedApp.cvParsedData.skills || []).map((skill: string, i: number) => (
                            <span key={i} className="px-2 py-1 bg-zinc-800 text-xs rounded-md text-zinc-300 border border-zinc-700">
                              {skill}
                            </span>
                          ))}
                        </div>
                      </div>
                      
                      <div className="space-y-4">
                        <div className="p-4 bg-surface-hover border border-border-default rounded-xl">
                          <h4 className="text-xs font-bold text-text-secondary uppercase tracking-wider mb-1">Years of Experience</h4>
                          <p className="text-2xl font-bold text-white">{selectedApp.cvParsedData.experienceYears} Years</p>
                        </div>
                        <div className="p-4 bg-surface-hover border border-border-default rounded-xl">
                          <h4 className="text-xs font-bold text-text-secondary uppercase tracking-wider mb-1">Education</h4>
                          <p className="text-sm text-white">{selectedApp.cvParsedData.education}</p>
                        </div>
                      </div>
                    </div>
                  </div>
                ) : (
                  <div className="p-8 text-center border border-dashed border-border-default rounded-xl bg-surface-hover/50">
                    <FileText className="w-12 h-12 text-zinc-600 mx-auto mb-4" />
                    <h4 className="text-white font-medium mb-2">CV Not Parsed Yet</h4>
                    <p className="text-sm text-zinc-400 mb-6 max-w-md mx-auto">
                      Use the AI parser to automatically extract skills, years of experience, and generate an executive summary from the uploaded CV document.
                    </p>
                    <AdminButton variant="outline" onClick={() => handleParseCV(selectedApp.id)} disabled={parsing}>
                      <Cpu className="w-4 h-4 me-2" /> {parsing ? "Analyzing CV..." : "Run AI Analysis"}
                    </AdminButton>
                  </div>
                )}
              </div>
            </div>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center text-text-secondary p-8">
              <FileText className="w-16 h-16 text-zinc-800 mb-4" />
              <p>Select an application to view details.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

"use client"

import { useState, useEffect } from 'react'
import { AdminPageHeader } from "@/components/dashboard/ui/AdminPageHeader"
import { AdminButton } from "@/components/dashboard/ui/AdminButton"
import { AdminFormLayout } from "@/components/dashboard/ui/AdminFormLayout"
import { useToast } from "@/components/dashboard/ui/ToastProvider"

export function CMSPagesClient() {
  const [pages, setPages] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [editingPage, setEditingPage] = useState<any | null>(null)
  const [saving, setSaving] = useState(false)
  const { toast } = useToast()

  const fetchPages = async () => {
    setLoading(true)
    try {
      const res = await fetch("/api/cms/pages")
      const json = await res.json()
      if (json.data) {
        setPages(json.data)
      }
    } catch (e) {
      console.error(e)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- Expected pattern for data synchronization
  fetchPages()
  }, [])

  const handleSave = async () => {
    if (!editingPage?.slug) {
      toast("Slug is required", "error")
      return
    }
    
    setSaving(true)
    try {
      const res = await fetch(`/api/cms/pages/${editingPage.slug}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          title: editingPage.title,
          content: editingPage.content,
          seo: editingPage.seo 
        })
      })
      if (!res.ok) throw new Error("Failed to save")
      toast(`Page ${editingPage.slug} saved successfully.`, "success")
      setEditingPage(null)
      fetchPages()
    } catch (e) {
      console.error(e)
      toast("Failed to save page.", "error")
    } finally {
      setSaving(false)
    }
  }

  const handleContentChange = (val: string) => {
    try {
      const parsed = JSON.parse(val)
      setEditingPage({ ...editingPage, content: parsed })
    } catch {
      // Allow invalid JSON while typing, maybe store as string in a separate state if needed,
      // but for simplicity, we just won't update the object until valid.
    }
  }

  if (editingPage) {
    return (
      <div className="flex flex-col gap-6 h-full p-6">
        <AdminPageHeader 
          title={editingPage.id ? `Edit Page: ${editingPage.slug}` : "Create New Page"}
          description="Edit the raw JSON content of the CMS page."
          action={
            <div className="flex items-center gap-3">
              <AdminButton variant="outline" onClick={() => setEditingPage(null)} disabled={saving}>
                Cancel
              </AdminButton>
              <AdminButton variant="primary" onClick={handleSave} disabled={saving}>
                {saving ? "Saving..." : "Save Page"}
              </AdminButton>
            </div>
          }
        />
        
        <AdminFormLayout>
          <div className="bg-surface-default border border-border-default rounded-xl p-6 space-y-6">
            <div className="space-y-4">
              <div className="space-y-2">
                <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Slug</label>
                <input 
                  type="text" 
                  value={editingPage.slug || ''}
                  onChange={e => setEditingPage({ ...editingPage, slug: e.target.value })}
                  disabled={!!editingPage.id} // cannot edit slug of existing page easily in this simple UI
                  className="w-full bg-surface-hover border border-border-default rounded-lg px-4 py-2 text-sm text-text-primary focus:border-primary focus:outline-none disabled:opacity-50"
                  placeholder="e.g. new-page-slug"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">JSON Content</label>
                <textarea 
                  defaultValue={JSON.stringify(editingPage.content || {}, null, 2)}
                  onChange={e => handleContentChange(e.target.value)}
                  className="w-full h-96 font-mono text-xs bg-surface-hover border border-border-default rounded-lg px-4 py-4 text-text-primary focus:border-primary focus:outline-none resize-none"
                />
              </div>
            </div>
          </div>
        </AdminFormLayout>
      </div>
    )
  }

  return (
    <div className="flex flex-col h-full">
      <AdminPageHeader 
        title="CMS Pages" 
        description="Manage dynamic pages stored in the CMS."
        action={
          <AdminButton 
            variant="primary" 
            onClick={() => setEditingPage({ slug: '', title: {}, content: {}, seo: {} })}
          >
            Create New Page
          </AdminButton>
        }
      />

      <div className="p-8 flex-1 overflow-y-auto">
        {loading ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
          </div>
        ) : pages.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-64 border-2 border-dashed border-border-default rounded-xl">
            <h3 className="text-lg font-bold text-text-primary mb-2">No pages found</h3>
            <p className="text-text-secondary mb-6 text-center max-w-sm">
              Create your first dynamic page to store content.
            </p>
            <AdminButton 
              variant="outline" 
              onClick={() => setEditingPage({ slug: '', title: {}, content: {}, seo: {} })}
            >
              Create Page
            </AdminButton>
          </div>
        ) : (
          <div className="bg-surface-default border border-border-default rounded-xl overflow-hidden">
            <table className="w-full text-left text-sm text-text-secondary">
              <thead className="bg-surface-hover border-b border-border-default text-xs uppercase text-text-tertiary">
                <tr>
                  <th className="px-6 py-4 font-bold">Slug</th>
                  <th className="px-6 py-4 font-bold">Status</th>
                  <th className="px-6 py-4 font-bold">Updated</th>
                  <th className="px-6 py-4 font-bold text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border-default">
                {pages.map((page) => (
                  <tr key={page.id} className="hover:bg-surface-hover/50 transition-colors">
                    <td className="px-6 py-4 font-medium text-text-primary">
                      {page.slug}
                    </td>
                    <td className="px-6 py-4">
                      {page.status}
                    </td>
                    <td className="px-6 py-4">
                      {new Date(page.updatedAt).toLocaleDateString()}
                    </td>
                    <td className="px-6 py-4 text-right">
                      <button 
                        onClick={() => setEditingPage(page)}
                        className="text-primary hover:text-primary-hover font-medium"
                      >
                        Edit
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  )
}

"use client"

import { useState } from "react"
import { useRouter } from "next/navigation"
import { Search, MessageSquare, CheckCircle, UserPlus, Trash2, Clock, CheckCircle2, XCircle, Mail, Phone } from "lucide-react"
import { AdminPageHeader } from "@/components/dashboard/ui/AdminPageHeader"
import { AdminButton } from "@/components/dashboard/ui/AdminButton"
import { AdminStatusBadge } from "@/components/dashboard/ui/AdminStatusBadge"
import { cn } from "@/lib/utils"

type Inquiry = {
  id: string
  type: string
  subject: string | null
  name: string
  email: string
  phone: string | null
  message: string
  status: string
  createdAt: string
  lead: { id: string; name: string } | null
}

export function InquiriesInbox({ initialInquiries }: { initialInquiries: Inquiry[] }) {
  const router = useRouter()
  const [inquiries, setInquiries] = useState(initialInquiries)
  const [search, setSearch] = useState("")
  const [statusFilter, setStatusFilter] = useState("ALL")
  const [selected, setSelected] = useState<Inquiry | null>(null)

  const filtered = inquiries.filter(i => {
    const matchesSearch = 
      i.name.toLowerCase().includes(search.toLowerCase()) || 
      i.email.toLowerCase().includes(search.toLowerCase()) || 
      (i.subject?.toLowerCase().includes(search.toLowerCase()) || false) ||
      i.message.toLowerCase().includes(search.toLowerCase())
      
    const matchesStatus = statusFilter === "ALL" || i.status === statusFilter
    
    return matchesSearch && matchesStatus
  })

  const updateStatus = async (id: string, newStatus: string) => {
    try {
      const res = await fetch(`/api/crm/inquiries/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: newStatus })
      })
      if (!res.ok) throw new Error()
      
      setInquiries(prev => prev.map(i => i.id === id ? { ...i, status: newStatus } : i))
      if (selected?.id === id) setSelected({ ...selected, status: newStatus })
      router.refresh()
    } catch {
      alert("Failed to update status")
    }
  }

  const convertToLead = async (inquiry: Inquiry) => {
    try {
      const leadRes = await fetch("/api/crm/leads", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: inquiry.name,
          email: inquiry.email,
          phone: inquiry.phone,
        })
      })
      if (!leadRes.ok) throw new Error("Failed to create lead")
      const newLead = await leadRes.json()

      const inqRes = await fetch(`/api/crm/inquiries/${inquiry.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "RESOLVED", leadId: newLead.id })
      })
      if (!inqRes.ok) throw new Error("Failed to link inquiry")

      router.push(`/dashboard/crm/leads/${newLead.id}`)
    } catch (err: any) {
      alert(err.message || "Failed to convert to lead")
    }
  }

  const deleteInquiry = async (id: string) => {
    if (!confirm("Delete this inquiry?")) return
    try {
      const res = await fetch(`/api/crm/inquiries/${id}`, { method: "DELETE" })
      if (!res.ok) throw new Error()
      
      setInquiries(prev => prev.filter(i => i.id !== id))
      setSelected(null)
      router.refresh()
    } catch {
      alert("Failed to delete inquiry")
    }
  }

  return (
    <div className="flex flex-col h-full bg-bg-base overflow-hidden">
      <div className="px-8 pt-8 pb-4 shrink-0">
        <AdminPageHeader 
          title="Inquiries Inbox" 
          description="Manage incoming requests, contact forms, and convert them to leads."
          action={
            <div className="flex items-center gap-3">
              <div className="relative">
                <Search className="absolute start-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-tertiary" />
                <input 
                  type="text" 
                  placeholder="Search inquiries..." 
                  value={search}
                  onChange={e => setSearch(e.target.value)}
                  className="ps-9 pe-4 py-2 bg-surface-default border border-border-default rounded-lg text-sm text-text-primary focus:outline-none focus:border-accent w-full md:w-64"
                />
              </div>
              <select 
                value={statusFilter}
                onChange={e => setStatusFilter(e.target.value)}
                className="px-4 py-2 bg-surface-default border border-border-default rounded-lg text-sm text-text-primary focus:outline-none focus:border-accent appearance-none cursor-pointer"
              >
                <option value="ALL">All Status</option>
                <option value="NEW">New</option>
                <option value="IN_PROGRESS">In Progress</option>
                <option value="RESOLVED">Resolved</option>
              </select>
            </div>
          }
        />
      </div>

      <div className="flex-1 flex overflow-hidden px-8 pb-8 gap-6">
        {/* Inbox List Pane */}
        <div className={cn(
          "flex flex-col bg-bg-level-1 border border-border-default rounded-2xl overflow-hidden shadow-sm h-full transition-all duration-300",
          selected ? "w-1/3 hidden lg:flex" : "w-full"
        )}>
          <div className="overflow-y-auto flex-1 custom-scrollbar">
            {filtered.length === 0 ? (
              <div className="p-8 text-center text-text-tertiary flex flex-col items-center justify-center h-full">
                <MessageSquare className="w-12 h-12 mb-3 opacity-20" />
                <p>No inquiries found.</p>
              </div>
            ) : (
              <div className="divide-y divide-border-default">
                {filtered.map(inq => (
                  <button 
                    key={inq.id}
                    onClick={() => setSelected(inq)}
                    className={cn(
                      "w-full text-left p-5 hover:bg-surface-hover transition-all relative group flex flex-col gap-2",
                      selected?.id === inq.id ? "bg-surface-active" : ""
                    )}
                  >
                    {selected?.id === inq.id && (
                      <div className="absolute left-0 top-0 bottom-0 w-1 bg-accent rounded-r-full" />
                    )}
                    
                    <div className="flex justify-between items-start">
                      <div className="font-bold text-sm text-text-primary truncate pe-2">
                        {inq.name}
                      </div>
                      <AdminStatusBadge 
                        variant={inq.status === "NEW" ? "info" : inq.status === "RESOLVED" ? "success" : "warning"}
                      >
                        {inq.status}
                      </AdminStatusBadge>
                    </div>
                    
                    <div className="flex items-center gap-2 text-[11px] text-text-secondary font-medium tracking-wide uppercase">
                      <span>{inq.type}</span>
                      <span className="w-1 h-1 rounded-full bg-border-strong" />
                      <span>{new Date(inq.createdAt).toLocaleDateString()}</span>
                    </div>
                    
                    <div className="text-sm text-text-secondary line-clamp-2 mt-1">
                      {inq.subject ? <span className="font-medium text-text-primary mr-1">{inq.subject}</span> : null}
                      {inq.message}
                    </div>
                    
                    {inq.lead && (
                      <div className="mt-2 text-[11px] font-bold text-accent bg-accent/10 px-2 py-1 rounded-md self-start flex items-center gap-1">
                        <CheckCircle2 className="w-3 h-3" />
                        Linked to Lead: {inq.lead.name}
                      </div>
                    )}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Detail Pane */}
        {selected && (
          <div className="flex-1 flex flex-col bg-bg-level-1 border border-border-default rounded-2xl shadow-lg h-full overflow-hidden animate-in slide-in-from-right-8 duration-300">
            <div className="p-6 border-b border-border-default flex items-center justify-between bg-surface-default shrink-0">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-full bg-accent/10 text-accent flex items-center justify-center font-bold text-xl uppercase">
                  {selected.name.charAt(0)}
                </div>
                <div>
                  <h3 className="font-bold text-lg text-text-primary leading-tight">{selected.name}</h3>
                  <div className="flex flex-wrap items-center gap-x-3 gap-y-1 mt-1 text-sm text-text-secondary">
                    <a href={`mailto:${selected.email}`} className="hover:text-accent transition-colors flex items-center gap-1.5">
                      <Mail className="w-3.5 h-3.5" /> {selected.email}
                    </a>
                    {selected.phone && (
                      <span className="flex items-center gap-1.5">
                        <Phone className="w-3.5 h-3.5" /> {selected.phone}
                      </span>
                    )}
                  </div>
                </div>
              </div>
              <button 
                onClick={() => setSelected(null)}
                className="p-2 text-text-tertiary hover:bg-surface-hover rounded-lg transition-colors"
              >
                <XCircle className="w-6 h-6" />
              </button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 custom-scrollbar bg-bg-base">
              <div className="max-w-3xl">
                <div className="flex items-center gap-3 mb-6">
                  <span className="px-3 py-1 bg-surface-default border border-border-default rounded-lg text-xs font-bold text-text-secondary uppercase tracking-wider">
                    {selected.type}
                  </span>
                  <span className="flex items-center gap-1.5 text-xs font-medium text-text-tertiary">
                    <Clock className="w-3.5 h-3.5" />
                    Received {new Date(selected.createdAt).toLocaleString()}
                  </span>
                </div>

                {selected.subject && (
                  <h2 className="text-2xl font-bold text-text-primary mb-4 leading-snug">{selected.subject}</h2>
                )}
                
                <div className="bg-surface-default border border-border-default rounded-xl p-6 shadow-sm">
                  <p className="text-text-primary text-[15px] leading-relaxed whitespace-pre-wrap">
                    {selected.message}
                  </p>
                </div>
              </div>
            </div>

            <div className="p-4 bg-surface-default border-t border-border-default flex flex-col sm:flex-row items-center justify-between gap-4 shrink-0">
              <div className="flex flex-wrap items-center gap-2">
                <AdminButton 
                  size="sm" 
                  variant={selected.status === "IN_PROGRESS" ? "primary" : "outline"}
                  onClick={() => updateStatus(selected.id, "IN_PROGRESS")}
                  disabled={selected.status === "IN_PROGRESS"}
                >
                  <MessageSquare className="w-4 h-4 me-2" /> In Progress
                </AdminButton>
                <AdminButton 
                  size="sm"
                  variant={selected.status === "RESOLVED" ? "primary" : "outline"}
                  onClick={() => updateStatus(selected.id, "RESOLVED")}
                  disabled={selected.status === "RESOLVED"}
                >
                  <CheckCircle className="w-4 h-4 me-2" /> Mark Resolved
                </AdminButton>
                
                {!selected.lead && (
                  <>
                    <div className="w-px h-6 bg-border-default mx-2 hidden sm:block" />
                    <AdminButton
                      size="sm"
                      variant="primary"
                      onClick={() => convertToLead(selected)}
                    >
                      <UserPlus className="w-4 h-4 me-2" /> Convert to Lead
                    </AdminButton>
                  </>
                )}
              </div>
              <AdminButton 
                size="sm" 
                variant="outline" 
                className="text-error hover:bg-error/10 hover:border-error/30" 
                onClick={() => deleteInquiry(selected.id)}
              >
                <Trash2 className="w-4 h-4 me-2" /> Delete
              </AdminButton>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

"use client"

import { useState } from "react"
import { useRouter } from "next/navigation"
import Link from "next/link"
import { 
  ArrowLeft, 
  Building, 
  Mail, 
  Phone, 
  Plus, 
  MessageSquare,
  Video,
  FileText
} from "lucide-react"
import { Button } from "@/components/ui/Button"
import { format } from "date-fns"
import { useSession } from "next-auth/react"

const STAGES = [
  { id: "NEW", label: "New Leads", color: "bg-blue-600" },
  { id: "CONTACTED", label: "Contacted", color: "bg-amber-600" },
  { id: "QUALIFIED", label: "Qualified", color: "bg-accent" },
  { id: "PROPOSAL", label: "Proposal", color: "bg-orange-600" },
  { id: "WON", label: "Won", color: "bg-[var(--color-success)]" },
  { id: "LOST", label: "Lost", color: "bg-error" }
]

export function LeadDetailView({ initialLead, salesTeam }: { initialLead: any, salesTeam: any[] }) {
  const router = useRouter()
  const { data: session } = useSession()
  const [lead, setLead] = useState(initialLead)
  const [isUpdating, setIsUpdating] = useState(false)
  
  const [activityType, setActivityType] = useState("NOTE")
  const [activityDesc, setActivityDesc] = useState("")

  const handleUpdate = async (data: any) => {
    setIsUpdating(true)
    try {
      const res = await fetch(`/api/crm/leads/${lead.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data)
      })
      if (res.ok) {
        const { lead: updatedLead } = await res.json()
        setLead(updatedLead)
        router.refresh()
      }
    } finally {
      setIsUpdating(false)
    }
  }

  const handleAddActivity = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!activityDesc.trim()) return

    await handleUpdate({
      activity: {
        type: activityType,
        description: activityDesc,
        author: session?.user?.name || "Unknown User"
      }
    })
    
    setActivityDesc("")
  }

  const getActivityIcon = (type: string) => {
    switch (type) {
      case "EMAIL": return <Mail className="w-4 h-4 text-blue-500" />
      case "CALL": return <Phone className="w-4 h-4 text-green-500" />
      case "MEETING": return <Video className="w-4 h-4 text-accent" />
      case "NOTE": return <FileText className="w-4 h-4 text-amber-500" />
    }
  }

  return (
    <div className="flex flex-col h-full w-full max-w-[1600px] mx-auto p-4 md:p-8">
      
      {/* Header */}
      <div className="flex items-center gap-4 mb-8">
        <Link href="/dashboard/crm/leads" className="p-2 hover:bg-surface-hover rounded-xl transition-colors">
          <ArrowLeft className="w-5 h-5 text-text-secondary" />
        </Link>
        <div>
          <h1 className="text-3xl font-black text-text-primary">{lead.name}</h1>
          <div className="flex items-center gap-3 mt-2 text-text-secondary text-sm">
            {lead.company && <span className="flex items-center"><Building className="w-4 h-4 me-1" /> {lead.company}</span>}
            <span className="flex items-center"><Mail className="w-4 h-4 me-1" /> {lead.email}</span>
            {lead.phone && <span className="flex items-center"><Phone className="w-4 h-4 me-1" /> {lead.phone}</span>}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        
        {/* Left Col: Details & Controls */}
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-surface-default border border-border-default rounded-2xl p-6 shadow-sm">
            <h3 className="font-bold text-text-primary mb-4">Lead Status</h3>
            
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-text-secondary mb-1">Stage</label>
                <select 
                  className="w-full bg-surface-hover border border-border-default rounded-xl px-3 py-2 text-sm text-text-primary focus:outline-none focus:border-accent"
                  value={lead.status}
                  onChange={(e) => handleUpdate({ status: e.target.value })}
                  disabled={isUpdating}
                >
                  {STAGES.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold text-text-secondary mb-1">Assigned To</label>
                <select 
                  className="w-full bg-surface-hover border border-border-default rounded-xl px-3 py-2 text-sm text-text-primary focus:outline-none focus:border-accent"
                  value={lead.assignedToId || ""}
                  onChange={(e) => handleUpdate({ assignedToId: e.target.value || null })}
                  disabled={isUpdating}
                >
                  <option value="">Unassigned</option>
                  {salesTeam.map(u => <option key={u.id} value={u.id}>{u.name}</option>)}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-text-secondary mb-1">Value (QAR)</label>
                  <input 
                    type="number"
                    className="w-full bg-surface-hover border border-border-default rounded-xl px-3 py-2 text-sm text-text-primary focus:outline-none focus:border-accent"
                    defaultValue={lead.value || ""}
                    onBlur={(e) => handleUpdate({ value: e.target.value })}
                    disabled={isUpdating}
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-text-secondary mb-1">Probability (%)</label>
                  <input 
                    type="number"
                    min="0"
                    max="100"
                    className="w-full bg-surface-hover border border-border-default rounded-xl px-3 py-2 text-sm text-text-primary focus:outline-none focus:border-accent"
                    defaultValue={lead.probability || ""}
                    onBlur={(e) => handleUpdate({ probability: e.target.value })}
                    disabled={isUpdating}
                  />
                </div>
              </div>

            </div>
          </div>

          <div className="bg-surface-default border border-border-default rounded-2xl p-6 shadow-sm">
            <h3 className="font-bold text-text-primary mb-4">Original Inquiries</h3>
            {lead.inquiries?.length > 0 ? (
              <div className="space-y-3">
                {lead.inquiries.map((inq: any) => (
                  <div key={inq.id} className="p-3 bg-surface-hover rounded-xl text-sm text-text-secondary">
                    <div className="flex justify-between items-center mb-1">
                      <span className="font-bold text-text-primary">{inq.type}</span>
                      <span className="text-xs">{format(new Date(inq.createdAt), "MMM d")}</span>
                    </div>
                    <p className="line-clamp-2">{inq.message}</p>
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-sm text-text-tertiary italic">No inquiries linked to this lead.</p>
            )}
          </div>
        </div>

        {/* Right Col: Activity Timeline */}
        <div className="lg:col-span-2 flex flex-col h-[700px]">
          <div className="bg-surface-default border border-border-default rounded-2xl flex flex-col h-full shadow-sm overflow-hidden">
            <div className="p-4 border-b border-border-default bg-surface-hover">
              <h3 className="font-bold text-text-primary">Activity Timeline</h3>
            </div>
            
            <div className="flex-1 overflow-y-auto p-6 space-y-6">
              {lead.activities?.length > 0 ? (
                lead.activities.map((activity: any, index: number) => (
                  <div key={activity.id} className="flex gap-4 relative">
                    {index !== lead.activities.length - 1 && (
                      <div className="absolute top-8 bottom-[-24px] start-[15px] w-[2px] bg-border-default" />
                    )}
                    <div className="w-8 h-8 rounded-full bg-surface-hover border border-border-default flex items-center justify-center shrink-0 z-10">
                      {getActivityIcon(activity.type)}
                    </div>
                    <div className="bg-surface-hover p-4 rounded-xl flex-1 border border-border-default">
                      <div className="flex justify-between items-center mb-2">
                        <span className="font-bold text-sm text-text-primary">{activity.author}</span>
                        <span className="text-xs text-text-tertiary">{format(new Date(activity.timestamp), 'MMM d, yyyy h:mm a')}</span>
                      </div>
                      <p className="text-sm text-text-secondary whitespace-pre-wrap">{activity.description}</p>
                    </div>
                  </div>
                ))
              ) : (
                <div className="flex flex-col items-center justify-center h-full text-text-tertiary">
                  <MessageSquare className="w-8 h-8 mb-2 opacity-50" />
                  <p>No activity recorded yet.</p>
                </div>
              )}
            </div>

            <div className="p-4 border-t border-border-default bg-surface-hover">
              <form onSubmit={handleAddActivity} className="flex flex-col gap-3">
                <div className="flex gap-2">
                  {["NOTE", "CALL", "EMAIL", "MEETING"].map(type => (
                    <button
                      key={type}
                      type="button"
                      onClick={() => setActivityType(type)}
                      className={`px-3 py-1 text-xs font-bold rounded-full transition-colors ${activityType === type ? 'bg-accent text-white' : 'bg-surface-default text-text-secondary hover:bg-surface-active'}`}
                    >
                      {type}
                    </button>
                  ))}
                </div>
                <div className="flex gap-2">
                  <input
                    type="text"
                    placeholder="Log an activity..."
                    value={activityDesc}
                    onChange={(e) => setActivityDesc(e.target.value)}
                    className="flex-1 bg-surface-default border border-border-default rounded-xl px-4 py-2 text-sm text-text-primary focus:outline-none focus:border-accent"
                  />
                  <Button type="submit" disabled={isUpdating || !activityDesc.trim()}>
                    <Plus className="w-4 h-4 me-2" /> Log
                  </Button>
                </div>
              </form>
            </div>
          </div>
        </div>

      </div>
    </div>
  )
}

"use client"

import { useState } from "react"
import { useRouter } from "next/navigation"
import { motion } from "framer-motion"
import { Search, Plus, Mail, Building, XCircle, ArrowRight } from "lucide-react"
import { AdminPageHeader } from "@/components/dashboard/ui/AdminPageHeader"
import { AdminButton } from "@/components/dashboard/ui/AdminButton"
import Link from "next/link"

type Lead = {
  id: string
  name: string
  company: string | null
  email: string
  phone: string | null
  status: string
  value: number | null
  createdAt: string
  activities: { timestamp: string }[]
}

const COLUMNS = [
  { id: "NEW", title: "New", color: "bg-blue-500", borderColor: "border-blue-500/30" },
  { id: "CONTACTED", title: "Contacted", color: "bg-amber-500", borderColor: "border-amber-500/30" },
  { id: "QUALIFIED", title: "Qualified", color: "bg-purple-500", borderColor: "border-purple-500/30" },
  { id: "PROPOSAL", title: "Proposal", color: "bg-indigo-500", borderColor: "border-indigo-500/30" },
  { id: "WON", title: "Won", color: "bg-emerald-500", borderColor: "border-emerald-500/30" },
  { id: "LOST", title: "Lost", color: "bg-red-500", borderColor: "border-red-500/30" }
]

export function LeadsBoard({ initialLeads }: { initialLeads: Lead[] }) {
  const router = useRouter()
  const [leads, setLeads] = useState(initialLeads)
  const [search, setSearch] = useState("")
  const [isAdding, setIsAdding] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)

  const handleAddLead = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault()
    setIsSubmitting(true)

    const formData = new FormData(e.currentTarget)
    const data = {
      name: formData.get("name"),
      company: formData.get("company"),
      email: formData.get("email"),
      phone: formData.get("phone"),
      value: formData.get("value"),
      probability: formData.get("probability"),
    }

    try {
      const res = await fetch("/api/crm/leads", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data)
      })

      if (!res.ok) throw new Error()
      
      const newLead = await res.json()
      setLeads(prev => [newLead, ...prev])
      setIsAdding(false)
      router.refresh()
    } catch {
      alert("Failed to add lead")
    } finally {
      setIsSubmitting(false)
    }
  }

  const filteredLeads = leads.filter(l => 
    l.name.toLowerCase().includes(search.toLowerCase()) || 
    (l.company && l.company.toLowerCase().includes(search.toLowerCase())) ||
    l.email.toLowerCase().includes(search.toLowerCase())
  )

  const handleDragStart = (e: React.DragEvent, id: string) => {
    e.dataTransfer.setData("leadId", id)
  }

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
  }

  const handleDrop = async (e: React.DragEvent, targetStatus: string) => {
    e.preventDefault()
    const leadId = e.dataTransfer.getData("leadId")
    if (!leadId) return

    const lead = leads.find(l => l.id === leadId)
    if (!lead || lead.status === targetStatus) return

    // Optimistic UI update
    setLeads(prev => prev.map(l => l.id === leadId ? { ...l, status: targetStatus } : l))

    // API Call
    try {
      const res = await fetch(`/api/crm/leads/${leadId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: targetStatus })
      })
      if (!res.ok) throw new Error()
      router.refresh()
    } catch {
      // Revert on error
      setLeads(initialLeads)
      alert("Failed to move lead")
    }
  }

  return (
    <div className="flex flex-col h-[calc(100vh-4rem)] bg-bg-base overflow-hidden">
      <div className="px-8 pt-8 pb-4">
        <AdminPageHeader 
          title="Sales Pipeline" 
          description="Manage your B2B leads and track sales opportunities."
          action={
            <div className="flex items-center gap-3">
              <div className="relative">
                <Search className="absolute start-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-tertiary" />
                <input 
                  type="text" 
                  placeholder="Search leads..." 
                  value={search}
                  onChange={e => setSearch(e.target.value)}
                  className="ps-9 pe-4 py-2 bg-surface-default border border-border-default rounded-lg text-sm text-text-primary focus:outline-none focus:border-accent w-full md:w-64"
                />
              </div>
              <AdminButton variant="primary" onClick={() => setIsAdding(true)}>
                <Plus className="w-4 h-4 me-2" /> Add Lead
              </AdminButton>
            </div>
          }
        />
      </div>

      {isAdding && (
        <div className="fixed inset-0 z-50 bg-zinc-950/80 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-200">
          <form 
            onSubmit={handleAddLead}
            className="bg-surface-default rounded-2xl w-full max-w-xl border border-border-default shadow-2xl animate-in zoom-in-95 duration-200 flex flex-col"
          >
            <div className="flex justify-between items-center px-6 py-4 border-b border-border-default">
              <h2 className="text-xl font-bold text-text-primary">New Lead</h2>
              <button type="button" onClick={() => setIsAdding(false)} className="text-text-tertiary hover:text-text-primary transition-colors">
                <XCircle className="w-6 h-6" />
              </button>
            </div>

            <div className="p-6 space-y-6">
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Name *</label>
                  <input required name="name" className="w-full px-4 py-3 bg-surface-hover border border-border-default rounded-xl text-sm text-text-primary focus:outline-none focus:border-accent" />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Company</label>
                  <input name="company" className="w-full px-4 py-3 bg-surface-hover border border-border-default rounded-xl text-sm text-text-primary focus:outline-none focus:border-accent" />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Email *</label>
                  <input required type="email" name="email" className="w-full px-4 py-3 bg-surface-hover border border-border-default rounded-xl text-sm text-text-primary focus:outline-none focus:border-accent" />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Phone</label>
                  <input name="phone" className="w-full px-4 py-3 bg-surface-hover border border-border-default rounded-xl text-sm text-text-primary focus:outline-none focus:border-accent" />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Value (QAR)</label>
                  <input type="number" name="value" className="w-full px-4 py-3 bg-surface-hover border border-border-default rounded-xl text-sm text-text-primary focus:outline-none focus:border-accent" />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-text-secondary uppercase tracking-wider">Probability (%)</label>
                  <input type="number" min="0" max="100" name="probability" className="w-full px-4 py-3 bg-surface-hover border border-border-default rounded-xl text-sm text-text-primary focus:outline-none focus:border-accent" />
                </div>
              </div>
            </div>

            <div className="px-6 py-4 bg-bg-level-1 border-t border-border-default flex justify-end gap-3 rounded-b-2xl">
              <AdminButton type="button" variant="outline" onClick={() => setIsAdding(false)}>Cancel</AdminButton>
              <AdminButton type="submit" variant="primary" isLoading={isSubmitting}>
                {isSubmitting ? "Creating..." : "Create Lead"}
              </AdminButton>
            </div>
          </form>
        </div>
      )}

      <div className="flex-1 flex gap-4 overflow-x-auto px-8 pb-8 custom-scrollbar">
        {COLUMNS.map(col => {
          const columnLeads = filteredLeads.filter(l => l.status === col.id)
          const totalValue = columnLeads.reduce((acc, l) => acc + (l.value || 0), 0)

          return (
            <div 
              key={col.id} 
              className={`w-[320px] shrink-0 flex flex-col bg-surface-default rounded-2xl border-t-[3px] border-x border-b border-border-default shadow-sm overflow-hidden`}
              style={{ borderTopColor: `var(--${col.color.split('-')[1]}-500, currentColor)` }}
              onDragOver={handleDragOver}
              onDrop={(e) => handleDrop(e, col.id)}
            >
              <div className="p-4 border-b border-border-default flex items-center justify-between bg-surface-hover/50 shrink-0">
                <div className="flex items-center gap-2">
                  <span className={`w-2 h-2 rounded-full ${col.color}`} />
                  <h3 className="font-bold text-text-primary">{col.title}</h3>
                  <span className="bg-bg-level-2 border border-border-default text-text-secondary text-xs px-2 py-0.5 rounded-full font-medium">
                    {columnLeads.length}
                  </span>
                </div>
                {totalValue > 0 && (
                  <span className="text-xs font-bold text-text-tertiary uppercase tracking-wider">
                    QAR {(totalValue / 1000).toFixed(1)}k
                  </span>
                )}
              </div>

              <div className="flex-1 p-3 space-y-3 overflow-y-auto custom-scrollbar">
                {columnLeads.map(lead => (
                  <motion.div 
                    layout
                    layoutId={lead.id}
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    whileHover={{ scale: 1.02 }}
                    key={lead.id}
                    draggable
                    onDragStart={(e: any) => handleDragStart(e, lead.id)}
                    className="bg-bg-level-1 p-4 rounded-xl border border-border-default shadow-sm cursor-grab active:cursor-grabbing hover:border-accent/50 hover:shadow-md transition-all group"
                  >
                    <div className="flex justify-between items-start mb-3">
                      <Link href={`/dashboard/crm/leads/${lead.id}`} className="font-bold text-sm text-text-primary hover:text-accent transition-colors line-clamp-1 flex-1">
                        {lead.name}
                      </Link>
                      {lead.value && (
                        <span className="text-[10px] font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-1.5 py-0.5 rounded whitespace-nowrap ml-2 uppercase tracking-wider">
                          {(lead.value / 1000).toFixed(1)}k
                        </span>
                      )}
                    </div>

                    <div className="space-y-2">
                      {lead.company && (
                        <div className="flex items-center gap-2 text-xs text-text-secondary">
                          <Building className="w-3.5 h-3.5 text-text-tertiary shrink-0" />
                          <span className="truncate font-medium">{lead.company}</span>
                        </div>
                      )}
                      <div className="flex items-center gap-2 text-xs text-text-secondary">
                        <Mail className="w-3.5 h-3.5 text-text-tertiary shrink-0" />
                        <span className="truncate font-medium">{lead.email}</span>
                      </div>
                    </div>

                    <div className="mt-4 pt-3 border-t border-border-default flex justify-between items-center text-[11px] font-medium text-text-tertiary">
                      <span>
                        {lead.activities.length > 0 
                          ? new Date(lead.activities[0].timestamp).toLocaleDateString()
                          : new Date(lead.createdAt).toLocaleDateString()}
                      </span>
                      <Link href={`/dashboard/crm/leads/${lead.id}`} className="flex items-center gap-1 text-text-tertiary group-hover:text-accent transition-colors">
                        Details <ArrowRight className="w-3 h-3" />
                      </Link>
                    </div>
                  </motion.div>
                ))}
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

"use client"

import { useState } from "react"
import Link from "next/link"
import { useRouter } from "next/navigation"
import { 
  Plus, 
  Search, 
  LayoutGrid, 
  List,
  Building,
  Mail
} from "lucide-react"
import { Button } from "@/components/ui/Button"
import {
  DndContext,
  closestCorners,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core"
import { SortableContext, sortableKeyboardCoordinates, useSortable, verticalListSortingStrategy } from "@dnd-kit/sortable"
import { CSS } from "@dnd-kit/utilities"
import { format } from "date-fns"

const STAGES = [
  { id: "NEW", label: "New Leads", color: "bg-blue-600" },
  { id: "CONTACTED", label: "Contacted", color: "bg-amber-600" },
  { id: "QUALIFIED", label: "Qualified", color: "bg-accent" },
  { id: "PROPOSAL", label: "Proposal", color: "bg-orange-600" },
  { id: "WON", label: "Won", color: "bg-[var(--color-success)]" },
  { id: "LOST", label: "Lost", color: "bg-error" }
]

function SortableLeadCard({ lead }: { lead: any }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: lead.id })
  
  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  }

  return (
    <div 
      ref={setNodeRef} 
      style={style} 
      {...attributes} 
      {...listeners}
      className={`bg-surface-default border border-border-default p-4 rounded-xl shadow-sm cursor-grab active:cursor-grabbing hover:border-accent transition-colors ${isDragging ? 'shadow-xl scale-105 z-50 relative' : ''}`}
    >
      <div className="flex justify-between items-start mb-2">
        <h4 className="font-bold text-text-primary text-sm">{lead.name}</h4>
        <Link href={`/dashboard/crm/leads/${lead.id}`} className="p-1 hover:bg-surface-hover rounded-md text-text-tertiary" onPointerDown={(e) => e.stopPropagation()}>
          <EyeIcon />
        </Link>
      </div>
      {lead.company && (
        <div className="flex items-center text-xs text-text-secondary mb-1">
          <Building className="w-3 h-3 me-1" /> {lead.company}
        </div>
      )}
      <div className="flex items-center text-xs text-text-secondary mb-3">
        <Mail className="w-3 h-3 me-1" /> {lead.email}
      </div>
      <div className="flex justify-between items-center text-xs border-t border-border-default pt-2 mt-2">
        <span className="font-bold text-accent">
          {lead.value ? `${lead.value.toLocaleString()} QAR` : '---'}
        </span>
        <span className="text-text-tertiary">{format(new Date(lead.createdAt), 'MMM d, yyyy')}</span>
      </div>
    </div>
  )
}

function EyeIcon() {
  return <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/></svg>
}

export function LeadsPipeline({ initialLeads }: { initialLeads: any[] }) {
  const router = useRouter()
  const [view, setView] = useState<"kanban" | "table">("kanban")
  const [leads, setLeads] = useState(initialLeads)
  const [search, setSearch] = useState("")

  const filteredLeads = leads.filter(l => 
    l.name.toLowerCase().includes(search.toLowerCase()) || 
    (l.company && l.company.toLowerCase().includes(search.toLowerCase())) ||
    l.email.toLowerCase().includes(search.toLowerCase())
  )

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  )

  const handleDragEnd = async (event: any) => {
    const { active, over } = event
    if (!over) return

    const leadId = active.id
    const overId = over.id // This could be another lead ID or a column ID

    // Find current lead and determine new status
    const lead = leads.find(l => l.id === leadId)
    if (!lead) return

    let newStatus = lead.status

    if (STAGES.find(s => s.id === overId)) {
      // Dropped directly on a column
      newStatus = overId
    } else {
      // Dropped on another card, adopt its column
      const overLead = leads.find(l => l.id === overId)
      if (overLead) newStatus = overLead.status
    }

    if (lead.status !== newStatus) {
      // Optimistic update
      setLeads(leads.map(l => l.id === leadId ? { ...l, status: newStatus } : l))
      
      // Persist
      await fetch(`/api/crm/leads/${leadId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: newStatus })
      })
      router.refresh()
    }
  }

  // Group leads for Kanban
  const getLeadsByStage = (stageId: string) => filteredLeads.filter(l => l.status === stageId)

  return (
    <div className="flex flex-col h-full w-full max-w-[1600px] mx-auto p-4 md:p-8">
      
      {/* Header & Controls */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <div>
          <h1 className="text-3xl font-black text-text-primary">Lead Pipeline</h1>
          <p className="text-text-secondary mt-1">Manage inbound inquiries and track conversion progress.</p>
        </div>
        
        <div className="flex items-center gap-3 w-full md:w-auto">
          <div className="relative flex-1 md:w-64">
            <Search className="absolute start-3 top-1/2 -translate-y-1/2 text-text-tertiary w-4 h-4" />
            <input 
              type="text" 
              placeholder="Search leads..." 
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full ps-9 pe-4 py-2 rounded-xl bg-surface-default border border-border-default focus:outline-none focus:border-accent text-sm"
            />
          </div>
          <div className="flex bg-surface-default rounded-xl border border-border-default p-1">
            <button onClick={() => setView('kanban')} className={`p-1.5 rounded-lg transition-colors ${view === 'kanban' ? 'bg-surface-hover text-text-primary' : 'text-text-tertiary hover:text-text-secondary'}`}><LayoutGrid className="w-4 h-4" /></button>
            <button onClick={() => setView('table')} className={`p-1.5 rounded-lg transition-colors ${view === 'table' ? 'bg-surface-hover text-text-primary' : 'text-text-tertiary hover:text-text-secondary'}`}><List className="w-4 h-4" /></button>
          </div>
          <Button asChild>
            <Link href="/dashboard/crm/leads/new"><Plus className="w-4 h-4 me-2" /> Add Lead</Link>
          </Button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 min-h-0">
        {view === "kanban" ? (
          <div className="h-full overflow-x-auto pb-4">
            <div className="flex gap-4 h-full min-w-max">
              <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
                {STAGES.map(stage => (
                  <div key={stage.id} className="flex flex-col w-72 bg-surface-hover rounded-2xl border border-border-default shrink-0 max-h-full">
                    <div className="p-4 border-b border-border-default flex items-center justify-between sticky top-0 bg-surface-hover z-10 rounded-t-2xl">
                      <div className="flex items-center gap-2">
                        <div className={`w-3 h-3 rounded-full ${stage.color}`} />
                        <h3 className="font-bold text-sm text-text-primary">{stage.label}</h3>
                      </div>
                      <span className="bg-surface-active text-text-secondary text-xs font-bold px-2 py-0.5 rounded-full">
                        {getLeadsByStage(stage.id).length}
                      </span>
                    </div>
                    
                    <div className="flex-1 overflow-y-auto p-3 space-y-3">
                      <SortableContext items={getLeadsByStage(stage.id).map(l => l.id)} strategy={verticalListSortingStrategy}>
                        {getLeadsByStage(stage.id).map(lead => (
                          <SortableLeadCard key={lead.id} lead={lead} />
                        ))}
                      </SortableContext>
                    </div>
                  </div>
                ))}
              </DndContext>
            </div>
          </div>
        ) : (
          <div className="bg-surface-default border border-border-default rounded-2xl overflow-hidden shadow-sm">
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm whitespace-nowrap">
                <thead className="bg-surface-hover border-b border-border-default text-text-secondary">
                  <tr>
                    <th className="p-4 font-bold">Name</th>
                    <th className="p-4 font-bold">Company</th>
                    <th className="p-4 font-bold">Email</th>
                    <th className="p-4 font-bold">Stage</th>
                    <th className="p-4 font-bold text-right">Value</th>
                    <th className="p-4 font-bold">Date</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border-default">
                  {filteredLeads.map(lead => (
                    <tr key={lead.id} className="hover:bg-surface-hover transition-colors cursor-pointer" onClick={() => router.push(`/dashboard/crm/leads/${lead.id}`)}>
                      <td className="p-4 font-bold text-text-primary">{lead.name}</td>
                      <td className="p-4 text-text-secondary">{lead.company || '-'}</td>
                      <td className="p-4 text-text-secondary">{lead.email}</td>
                      <td className="p-4">
                        <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-bold bg-surface-active text-text-secondary">
                          {STAGES.find(s => s.id === lead.status)?.label}
                        </span>
                      </td>
                      <td className="p-4 text-right font-mono text-xs">{lead.value ? `${lead.value.toLocaleString()} QAR` : '-'}</td>
                      <td className="p-4 text-text-tertiary text-xs">{format(new Date(lead.createdAt), 'MMM d, yyyy')}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

"use client"

import { useState } from "react"
import { useRouter } from "next/navigation"
import { Search, Mail, Phone, CheckCircle, XCircle, Trash2 } from "lucide-react"
import { Badge } from "@/components/ui/Badge"
import { Button } from "@/components/ui/Button"

type Subscriber = {
  id: string
  email: string | null
  phone: string | null
  isVerified: boolean
  verifiedAt: string | null
  preferences: any | null
  createdAt: string
}

export function SubscribersList({ initialSubscribers }: { initialSubscribers: Subscriber[] }) {
  const router = useRouter()
  const [subscribers, setSubscribers] = useState(initialSubscribers)
  const [search, setSearch] = useState("")

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this subscriber?")) return
    try {
      const res = await fetch(`/api/crm/subscribers/${id}`, { method: "DELETE" })
      if (!res.ok) throw new Error()

      setSubscribers(prev => prev.filter(s => s.id !== id))
      router.refresh()
    } catch {
      alert("Failed to delete subscriber")
    }
  }

  const filtered = subscribers.filter(s => 
    (s.email?.toLowerCase().includes(search.toLowerCase()) || false) || 
    (s.phone?.includes(search) || false)
  )

  const renderPreferences = (prefs: any) => {
    if (!prefs) return <span className="text-text-tertiary">-</span>
    let parsed: any = {}
    if (typeof prefs === "string") {
      try { parsed = JSON.parse(prefs) } catch { parsed = {} }
    } else {
      parsed = prefs
    }
    
    return (
      <div className="flex flex-wrap gap-1">
        {Object.entries(parsed).map(([key, val]) => (
          val ? <Badge key={key} variant="default" className="text-[10px] bg-transparent border border-border-default">{key}</Badge> : null
        ))}
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-text-primary">Subscribers</h1>
          <p className="text-sm text-text-secondary">Manage newsletter and event subscribers.</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="relative">
            <Search className="w-4 h-4 absolute start-3 top-1/2 -translate-y-1/2 text-text-tertiary" />
            <input 
              type="text" 
              placeholder="Search email/phone..." 
              value={search}
              onChange={e => setSearch(e.target.value)}
              className="ps-9 pe-4 py-2 bg-surface-default border border-border-default rounded-lg text-sm focus:outline-none focus:border-accent w-full md:w-64"
            />
          </div>
          <Button variant="outline" className="gap-2" onClick={() => {
            const csv = [
              ["Email", "Phone", "Verified", "Verified At", "Preferences", "Subscribed On"].join(","),
              ...subscribers.map(s => [
                s.email || "",
                s.phone || "",
                s.isVerified ? "Yes" : "No",
                s.verifiedAt ? new Date(s.verifiedAt).toLocaleDateString() : "",
                s.preferences ? JSON.stringify(s.preferences).replace(/,/g, ";") : "",
                new Date(s.createdAt).toLocaleDateString()
              ].join(","))
            ].join("\n")
            const blob = new Blob([csv], { type: "text/csv" })
            const url = URL.createObjectURL(blob)
            const a = document.createElement("a")
            a.href = url
            a.download = "subscribers.csv"
            document.body.appendChild(a)
            a.click()
            document.body.removeChild(a)
            URL.revokeObjectURL(url)
          }}>
            Export CSV
          </Button>
        </div>
      </div>

      <div className="bg-surface-default border border-border-default rounded-xl shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm whitespace-nowrap">
            <thead className="bg-surface-hover border-b border-border-default text-text-secondary">
              <tr>
                <th className="px-6 py-4 font-medium">Contact</th>
                <th className="px-6 py-4 font-medium">Verification</th>
                <th className="px-6 py-4 font-medium">Preferences</th>
                <th className="px-6 py-4 font-medium">Subscribed On</th>
                <th className="px-6 py-4 font-medium text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border-default">
              {filtered.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center text-text-tertiary">
                    No subscribers found.
                  </td>
                </tr>
              ) : (
                filtered.map(s => (
                  <tr key={s.id} className="hover:bg-surface-hover transition-colors">
                    <td className="px-6 py-4">
                      {s.email && (
                        <div className="flex items-center gap-2 text-text-primary font-medium">
                          <Mail className="w-4 h-4 text-text-tertiary" /> {s.email}
                        </div>
                      )}
                      {s.phone && (
                        <div className="flex items-center gap-2 text-text-primary font-medium mt-1">
                          <Phone className="w-4 h-4 text-text-tertiary" /> {s.phone}
                        </div>
                      )}
                    </td>
                    <td className="px-6 py-4">
                      {s.isVerified ? (
                        <div className="flex items-center gap-1.5 text-[var(--color-success)]">
                          <CheckCircle className="w-4 h-4" /> Verified
                        </div>
                      ) : (
                        <div className="flex items-center gap-1.5 text-text-tertiary">
                          <XCircle className="w-4 h-4" /> Unverified
                        </div>
                      )}
                      {s.verifiedAt && <div className="text-xs text-text-tertiary mt-1">{new Date(s.verifiedAt).toLocaleDateString()}</div>}
                    </td>
                    <td className="px-6 py-4">
                      {renderPreferences(s.preferences)}
                    </td>
                    <td className="px-6 py-4 text-text-secondary">
                      {new Date(s.createdAt).toLocaleDateString()}
                    </td>
                    <td className="px-6 py-4 text-right">
                      <Button variant="ghost" size="sm" onClick={() => handleDelete(s.id)} className="text-red-500 hover:text-red-600 hover:bg-red-500/10">
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  )
}

"use client"

import { useState } from "react"
import { useRouter } from "next/navigation"
import { ArrowLeft, Save, Mail, Phone, Briefcase, Download, CheckCircle } from "lucide-react"
import { AdminButton } from "@/components/dashboard/ui/AdminButton"
import { AdminInput } from "@/components/dashboard/ui/AdminInput"
import { AdminSelect } from "@/components/dashboard/ui/AdminSelect"
import { AdminTextarea } from "@/components/dashboard/ui/AdminTextarea"

export type Talent = {
  id: string
  name: string
  email: string
  phone: string | null
  position: string | null
  department: string | null
  experienceLevel: string | null
  status: string
  rating: number | null
  appliedDate: string
  resumeUrl: string | null
  skills: any | null
  languages: any | null
  education: any | null
  certifications: any | null
  notes: string | null
  job: { title: string } | null
}

export function TalentDetail({ initialTalent, onClose }: { initialTalent: Talent; onClose?: () => void }) {
  const router = useRouter()
  const [talent] = useState(initialTalent)
  const [isSaving, setIsSaving] = useState(false)
  const [success, setSuccess] = useState(false)

  const [form, setForm] = useState({
    status: talent.status,
    rating: talent.rating?.toString() || "",
    notes: talent.notes || ""
  })

  const handleSave = async () => {
    setIsSaving(true)
    try {
      const res = await fetch(`/api/crm/talent/${talent.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          status: form.status,
          rating: form.rating === "" ? null : Number(form.rating),
          notes: form.notes
        })
      })
      if (!res.ok) throw new Error()
      setSuccess(true)
      setTimeout(() => setSuccess(false), 3000)
      router.refresh()
    } catch {
      alert("Failed to update candidate")
    } finally {
      setIsSaving(false)
    }
  }

  // Helper to parse JSON arrays safely
  const renderList = (data: any) => {
    if (!data) return <p className="text-text-tertiary text-sm">Not provided</p>
    let list: string[] = []
    if (typeof data === "string") {
      try { list = JSON.parse(data) } catch { list = [] }
    } else if (Array.isArray(data)) {
      list = data
    }
    
    if (list.length === 0) return <p className="text-text-tertiary text-sm">Not provided</p>
    
    return (
      <div className="flex flex-wrap gap-2">
        {list.map((item, i) => (
          <span key={i} className="px-3 py-1 bg-surface-hover border border-border-default rounded-md text-xs font-medium text-text-secondary">
            {item}
          </span>
        ))}
      </div>
    )
  }

  return (
    <div className="flex flex-col h-full bg-bg-base">
      <div className="flex items-center justify-between px-8 py-6 border-b border-border-default bg-surface-default shrink-0">
        <div className="flex items-center gap-4">
          <button 
            onClick={onClose ? onClose : () => router.push("/dashboard/crm/talent")}
            className="p-2 bg-surface-hover hover:bg-surface-active rounded-lg transition-colors text-text-secondary"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-xl font-bold text-text-primary">{talent.name}</h1>
            <p className="text-xs text-text-secondary mt-1">Applied: {new Date(talent.appliedDate).toLocaleDateString()}</p>
          </div>
        </div>
        <AdminButton onClick={handleSave} isLoading={isSaving} variant={success ? "outline" : "primary"}>
          {success ? (
            <span className="flex items-center text-emerald-500 gap-2"><CheckCircle className="w-4 h-4" /> Saved Successfully</span>
          ) : (
            <span className="flex items-center gap-2"><Save className="w-4 h-4" /> Save Evaluation</span>
          )}
        </AdminButton>
      </div>

      <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Left Column - Applicant Overview */}
          <div className="lg:col-span-2 space-y-8">
            <div className="bg-surface-default p-8 rounded-2xl border border-border-default shadow-sm space-y-6">
              <h2 className="text-sm font-bold text-text-secondary uppercase tracking-wider border-b border-border-default pb-4">Applicant Overview</h2>
              
              <div className="grid grid-cols-1 md:grid-cols-2 gap-y-6 gap-x-8 text-sm">
                <div>
                  <span className="text-text-tertiary block mb-1">Email</span>
                  <a href={`mailto:${talent.email}`} className="font-medium text-accent hover:underline flex items-center gap-2">
                    <Mail className="w-4 h-4 text-text-tertiary" /> {talent.email}
                  </a>
                </div>
                <div>
                  <span className="text-text-tertiary block mb-1">Phone</span>
                  <span className="font-medium text-text-primary flex items-center gap-2">
                    <Phone className="w-4 h-4 text-text-tertiary" /> {talent.phone || "N/A"}
                  </span>
                </div>
                <div>
                  <span className="text-text-tertiary block mb-1">Position Applied</span>
                  <span className="font-medium text-text-primary flex items-center gap-2">
                    <Briefcase className="w-4 h-4 text-text-tertiary" /> {talent.position || talent.job?.title || "General Application"}
                  </span>
                </div>
                <div>
                  <span className="text-text-tertiary block mb-1">Experience Level</span>
                  <span className="font-medium text-text-primary">{talent.experienceLevel || "N/A"}</span>
                </div>
                <div>
                  <span className="text-text-tertiary block mb-1">Resume</span>
                  {talent.resumeUrl ? (
                    <AdminButton variant="outline" size="sm" className="mt-1 w-full sm:w-auto" onClick={() => window.open(talent.resumeUrl!, "_blank")}>
                      <Download className="w-4 h-4 me-2" /> Download CV
                    </AdminButton>
                  ) : (
                    <span className="text-text-secondary italic">No resume uploaded</span>
                  )}
                </div>
              </div>
            </div>

            <div className="bg-surface-default p-8 rounded-2xl border border-border-default shadow-sm space-y-8">
              <h2 className="text-sm font-bold text-text-secondary uppercase tracking-wider border-b border-border-default pb-4">Parsed CV Data</h2>
              
              <div className="space-y-8">
                <div>
                  <h3 className="text-xs font-bold text-text-secondary uppercase mb-3">Skills</h3>
                  {renderList(talent.skills)}
                </div>
                <div>
                  <h3 className="text-xs font-bold text-text-secondary uppercase mb-3">Languages</h3>
                  {renderList(talent.languages)}
                </div>
                <div>
                  <h3 className="text-xs font-bold text-text-secondary uppercase mb-3">Education</h3>
                  {renderList(talent.education)}
                </div>
                <div>
                  <h3 className="text-xs font-bold text-text-secondary uppercase mb-3">Certifications</h3>
                  {renderList(talent.certifications)}
                </div>
              </div>
            </div>
          </div>

          {/* Right Column - Status & Internal Notes */}
          <div className="space-y-8">
            <div className="bg-surface-default p-8 rounded-2xl border border-border-default shadow-sm space-y-6 sticky top-0">
              <h2 className="text-sm font-bold text-text-secondary uppercase tracking-wider border-b border-border-default pb-4">Evaluation</h2>
              
              <div className="space-y-6">
                <AdminSelect
                  label="Application Status"
                  value={form.status}
                  onChange={(e) => setForm({...form, status: e.target.value})}
                >
                  <option value="NEW">New Application</option>
                  <option value="SCREENING">Screening</option>
                  <option value="INTERVIEW">Interviewing</option>
                  <option value="OFFERED">Offer Extended</option>
                  <option value="HIRED">Hired</option>
                  <option value="REJECTED">Rejected</option>
                </AdminSelect>

                <AdminInput
                  label="Rating (1-5)"
                  type="number"
                  min={1}
                  max={5}
                  value={form.rating}
                  onChange={(e) => setForm({...form, rating: e.target.value})}
                  placeholder="e.g. 4"
                />

                <AdminTextarea
                  label="Internal Notes"
                  value={form.notes}
                  onChange={(e) => setForm({...form, notes: e.target.value})}
                  placeholder="Add interview feedback or internal notes here..."
                  rows={8}
                />
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

"use client"

import { useState } from "react"
import Link from "next/link"
import { useRouter } from "next/navigation"
import { ArrowLeft, Mail, Phone, Briefcase, GraduationCap, Award, Globe } from "lucide-react"
import { Button } from "@/components/ui/Button"
const STATUS_OPTIONS = [
  "NEW", "SCREENING", "INTERVIEW", "OFFERED", "HIRED", "REJECTED"
]

export function TalentDetailView({ initialData, team }: { initialData: any, team: any[] }) {
  const router = useRouter()
  const [talent, setTalent] = useState(initialData)
  const [isUpdating, setIsUpdating] = useState(false)

  const handleUpdate = async (data: any) => {
    setIsUpdating(true)
    try {
      const res = await fetch(`/api/crm/talent/${talent.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data)
      })
      if (res.ok) {
        const updated = await res.json()
        setTalent(updated)
        router.refresh()
      }
    } finally {
      setIsUpdating(false)
    }
  }

  return (
    <div className="flex flex-col h-full w-full max-w-[1600px] mx-auto p-4 md:p-8">
      {/* Header */}
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-4">
          <Link href="/dashboard/crm/talent" className="p-2 hover:bg-surface-hover rounded-xl transition-colors">
            <ArrowLeft className="w-5 h-5 text-text-secondary" />
          </Link>
          <div>
            <h1 className="text-3xl font-black text-text-primary">{talent.name}</h1>
            <div className="flex flex-wrap items-center gap-3 mt-2 text-text-secondary text-sm">
              <span className="flex items-center"><Mail className="w-4 h-4 me-1" /> {talent.email}</span>
              {talent.phone && <span className="flex items-center"><Phone className="w-4 h-4 me-1" /> {talent.phone}</span>}
              <span className="flex items-center"><Briefcase className="w-4 h-4 me-1" /> {talent.experienceLevel || "Unknown"} Experience</span>
            </div>
          </div>
        </div>
        
        <div className="flex gap-2">
          <Button variant="outline" asChild>
            <a href={talent.resumeUrl || "#"} target="_blank" rel="noreferrer" className={!talent.resumeUrl ? "opacity-50 pointer-events-none" : ""}>
              View Original CV
            </a>
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        
        {/* Left Column */}
        <div className="lg:col-span-1 space-y-6">
          
          <div className="bg-surface-default border border-border-default rounded-2xl p-6 shadow-sm">
            <h3 className="font-bold text-text-primary mb-4">Application Details</h3>
            
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-text-secondary mb-1">Status</label>
                <select 
                  className="w-full bg-surface-hover border border-border-default rounded-xl px-3 py-2 text-sm text-text-primary focus:outline-none focus:border-accent"
                  value={talent.status}
                  onChange={(e) => handleUpdate({ status: e.target.value })}
                  disabled={isUpdating}
                >
                  {STATUS_OPTIONS.map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold text-text-secondary mb-1">Rating</label>
                <select 
                  className="w-full bg-surface-hover border border-border-default rounded-xl px-3 py-2 text-sm text-text-primary focus:outline-none focus:border-accent"
                  value={talent.rating || 0}
                  onChange={(e) => handleUpdate({ rating: parseInt(e.target.value) })}
                  disabled={isUpdating}
                >
                  <option value="0">Unrated</option>
                  {[1, 2, 3, 4, 5].map(r => <option key={r} value={r}>{r} Stars</option>)}
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold text-text-secondary mb-1">Assign to Team Member</label>
                <select 
                  className="w-full bg-surface-hover border border-border-default rounded-xl px-3 py-2 text-sm text-text-primary focus:outline-none focus:border-accent"
                  value={talent.assignedToId || ""}
                  onChange={(e) => handleUpdate({ assignedToId: e.target.value || null })}
                  disabled={isUpdating}
                >
                  <option value="">Unassigned</option>
                  {team.map(u => <option key={u.id} value={u.id}>{u.name}</option>)}
                </select>
              </div>
            </div>
          </div>
          
          <div className="bg-surface-default border border-border-default rounded-2xl p-6 shadow-sm">
            <h3 className="font-bold text-text-primary flex items-center mb-4">
              <Globe className="w-5 h-5 me-2 text-blue-500" /> Languages
            </h3>
            <ul className="space-y-2">
              {(talent.languages || []).map((l: any, i: number) => (
                <li key={i} className="flex justify-between items-center text-sm">
                  <span className="font-bold text-text-primary">{l.language || l}</span>
                  <span className="text-text-secondary text-xs bg-surface-hover px-2 py-1 rounded-md">{l.level || "Unknown"}</span>
                </li>
              ))}
              {(!talent.languages || talent.languages.length === 0) && (
                <li className="text-sm text-text-tertiary italic">No languages parsed.</li>
              )}
            </ul>
          </div>

        </div>

        {/* Right Column */}
        <div className="lg:col-span-2 space-y-6">
          
          <div className="bg-surface-default border border-border-default rounded-2xl p-6 shadow-sm">
            <h3 className="font-bold text-text-primary flex items-center mb-4">
              <Award className="w-5 h-5 me-2 text-amber-500" /> Skills
            </h3>
            <div className="flex flex-wrap gap-2">
              {(talent.skills || []).map((skill: string, i: number) => (
                <span key={i} className="px-3 py-1 bg-surface-hover border border-border-default rounded-full text-sm font-bold text-text-primary">
                  {skill}
                </span>
              ))}
              {(!talent.skills || talent.skills.length === 0) && (
                <span className="text-sm text-text-tertiary italic">No skills parsed.</span>
              )}
            </div>
          </div>

          <div className="bg-surface-default border border-border-default rounded-2xl p-6 shadow-sm">
            <h3 className="font-bold text-text-primary flex items-center mb-4">
              <GraduationCap className="w-5 h-5 me-2 text-emerald-500" /> Education
            </h3>
            <div className="space-y-4">
              {(talent.education || []).map((edu: any, i: number) => (
                <div key={i} className="flex gap-4">
                  <div className="w-12 h-12 rounded-full bg-surface-hover flex items-center justify-center shrink-0">
                    <GraduationCap className="w-6 h-6 text-text-secondary" />
                  </div>
                  <div>
                    <h4 className="font-bold text-text-primary">{edu.degree || edu}</h4>
                    {edu.institution && <p className="text-sm text-text-secondary">{edu.institution}</p>}
                    {edu.year && <p className="text-xs text-text-tertiary">{edu.year}</p>}
                  </div>
                </div>
              ))}
              {(!talent.education || talent.education.length === 0) && (
                <span className="text-sm text-text-tertiary italic">No education details parsed.</span>
              )}
            </div>
          </div>

          <div className="bg-surface-default border border-border-default rounded-2xl p-6 shadow-sm">
            <h3 className="font-bold text-text-primary flex items-center mb-4">
              <Briefcase className="w-5 h-5 me-2 text-green-500" /> Certifications
            </h3>
            <ul className="list-disc ps-5 space-y-1">
              {(talent.certifications || []).map((cert: any, i: number) => (
                <li key={i} className="text-sm text-text-secondary">
                  <span className="font-bold text-text-primary">{cert.name || cert}</span>
                </li>
              ))}
              {(!talent.certifications || talent.certifications.length === 0) && (
                <li className="text-sm text-text-tertiary italic list-none -ms-5">No certifications parsed.</li>
              )}
            </ul>
          </div>

        </div>

      </div>
    </div>
  )
}

"use client"

import { useState } from "react"
import "next/link"
import { useRouter } from "next/navigation"
import { 
  Search,
  Upload,
  Star
} from "lucide-react"
import { Button } from "@/components/ui/Button"
import { format } from "date-fns"
import {
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from "@tanstack/react-table"

export function TalentTable({ initialData }: { initialData: any[] }) {
  const router = useRouter()
  const [data] = useState(initialData)
  const [globalFilter, setGlobalFilter] = useState("")
  const [isParsing, setIsParsing] = useState(false)
  const [sorting, setSorting] = useState([])

  const columns = [
    {
      accessorKey: "name",
      header: "Applicant Name",
      cell: (info: any) => (
        <div className="font-bold text-text-primary">{info.getValue()}</div>
      )
    },
    {
      accessorKey: "position",
      header: "Applied For",
      cell: (info: any) => (
        <div className="text-text-secondary">
          {info.getValue() || "-"}
          {info.row.original.department && (
            <span className="block text-xs text-text-tertiary">{info.row.original.department}</span>
          )}
        </div>
      )
    },
    {
      accessorKey: "status",
      header: "Status",
      cell: (info: any) => (
        <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-bold bg-surface-active text-text-secondary">
          {info.getValue()}
        </span>
      )
    },
    {
      accessorKey: "experienceLevel",
      header: "Experience",
    },
    {
      accessorKey: "rating",
      header: "Rating",
      cell: (info: any) => (
        <div className="flex text-amber-500">
          {[...Array(5)].map((_, i) => (
            <Star key={i} className={`w-3 h-3 ${i < (info.getValue() || 0) ? "fill-current" : "text-surface-active"}`} />
          ))}
        </div>
      )
    },
    {
      accessorKey: "appliedDate",
      header: "Date Applied",
      cell: (info: any) => format(new Date(info.getValue()), 'MMM d, yyyy')
    }
  ]

  // eslint-disable-next-line react-hooks/incompatible-library -- TanStack Table useReactTable is known to conflict with React Compiler rules
  const table = useReactTable({
    data,
    columns,
    state: { globalFilter, sorting },
    onGlobalFilterChange: setGlobalFilter,
    onSortingChange: setSorting as any,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
  })

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    
    setIsParsing(true)
    const formData = new FormData()
    formData.append("resume", file)

    try {
      const res = await fetch("/api/crm/talent/parse-resume", {
        method: "POST",
        body: formData
      })
      if (res.ok) {
        const parsedData = await res.json()
        
        // Save to DB
        const saveRes = await fetch("/api/crm/talent", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(parsedData)
        })

        if (saveRes.ok) {
          router.refresh()
        }
      } else {
        alert("Failed to parse resume.")
      }
    } catch (err) {
      console.error(err)
      alert("An error occurred.")
    } finally {
      setIsParsing(false)
      if (e.target) e.target.value = ''
    }
  }

  return (
    <div className="flex flex-col h-full w-full max-w-[1600px] mx-auto p-4 md:p-8">
      
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <div>
          <h1 className="text-3xl font-black text-text-primary">Talent Pool</h1>
          <p className="text-text-secondary mt-1">Manage applicants and parsed CV data.</p>
        </div>
        
        <div className="flex items-center gap-3 w-full md:w-auto">
          <div className="relative flex-1 md:w-64">
            <Search className="absolute start-3 top-1/2 -translate-y-1/2 text-text-tertiary w-4 h-4" />
            <input 
              type="text" 
              placeholder="Search talent..." 
              value={globalFilter ?? ""}
              onChange={(e) => setGlobalFilter(e.target.value)}
              className="w-full ps-9 pe-4 py-2 rounded-xl bg-surface-default border border-border-default focus:outline-none focus:border-accent text-sm"
            />
          </div>
          
          <div className="relative">
            <input 
              type="file" 
              accept=".pdf" 
              className="absolute inset-0 opacity-0 cursor-pointer"
              onChange={handleFileUpload}
              disabled={isParsing}
            />
            <Button disabled={isParsing}>
              {isParsing ? <div className="w-4 h-4 me-2 border-2 border-white border-t-transparent rounded-full animate-spin" /> : <Upload className="w-4 h-4 me-2" />}
              {isParsing ? "Parsing AI..." : "Upload CV (PDF)"}
            </Button>
          </div>
        </div>
      </div>

      {/* Table */}
      <div className="bg-surface-default border border-border-default rounded-2xl overflow-hidden shadow-sm flex-1">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm whitespace-nowrap">
            <thead className="bg-surface-hover border-b border-border-default text-text-secondary">
              {table.getHeaderGroups().map(headerGroup => (
                <tr key={headerGroup.id}>
                  {headerGroup.headers.map(header => (
                    <th 
                      key={header.id} 
                      className={`p-4 font-bold ${header.column.getCanSort() ? 'cursor-pointer select-none hover:text-text-primary' : ''}`}
                      onClick={header.column.getToggleSortingHandler()}
                    >
                      {flexRender(
                        header.column.columnDef.header,
                        header.getContext()
                      )}
                      {{
                        asc: ' ↑',
                        desc: ' ↓',
                      }[header.column.getIsSorted() as string] ?? null}
                    </th>
                  ))}
                </tr>
              ))}
            </thead>
            <tbody className="divide-y divide-border-default">
              {table.getRowModel().rows.map(row => (
                <tr 
                  key={row.id} 
                  className="hover:bg-surface-hover transition-colors cursor-pointer"
                  onClick={() => router.push(`/dashboard/crm/talent/${(row.original as any).id}`)}
                >
                  {row.getVisibleCells().map(cell => (
                    <td key={cell.id} className="p-4">
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </td>
                  ))}
                </tr>
              ))}
              {table.getRowModel().rows.length === 0 && (
                <tr>
                  <td colSpan={columns.length} className="p-8 text-center text-text-tertiary">
                    No talent found. Try uploading a CV.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
        
        {/* Pagination */}
        <div className="p-4 border-t border-border-default flex items-center justify-between">
          <div className="text-sm text-text-secondary">
            Showing {table.getRowModel().rows.length} of {data.length} entries
          </div>
          <div className="flex gap-2">
            <Button 
              variant="outline" 
              onClick={() => table.previousPage()} 
              disabled={!table.getCanPreviousPage()}
            >
              Previous
            </Button>
            <Button 
              variant="outline" 
              onClick={() => table.nextPage()} 
              disabled={!table.getCanNextPage()}
            >
              Next
            </Button>
          </div>
        </div>
      </div>
    </div>
  )
}

"use client"

import { useState } from "react"
import { useRouter } from "next/navigation"
import { Plus, ToggleRight, ToggleLeft, Trash2 } from "lucide-react"
import { Button } from "@/components/ui/Button"
import { format } from "date-fns"

export function BroadcastManager({ initialBroadcasts }: { initialBroadcasts: any[] }) {
  const router = useRouter()
  const [broadcasts, setBroadcasts] = useState(initialBroadcasts)
  const [isAdding, setIsAdding] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Form state
  const [titleEn, setTitleEn] = useState("")
  const [titleAr, setTitleAr] = useState("")
  const [messageEn, setMessageEn] = useState("")
  const [messageAr, setMessageAr] = useState("")
  const [type, setType] = useState("INFO")
  const [isActive, setIsActive] = useState(true)

  const handleAddBroadcast = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsSubmitting(true)

    try {
      const res = await fetch("/api/operations/broadcasts", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          titleEn,
          titleAr,
          messageEn,
          messageAr,
          type,
          isActive
        })
      })

      if (!res.ok) throw new Error("Failed to create broadcast")
      
      const newBroadcast = await res.json()
      setBroadcasts(prev => [newBroadcast, ...prev])
      setIsAdding(false)
      
      // Reset form
      setTitleEn("")
      setTitleAr("")
      setMessageEn("")
      setMessageAr("")
      setType("INFO")
      setIsActive(true)

      router.refresh()
    } catch {
      alert("Failed to add broadcast.")
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleToggle = async (id: string, currentStatus: boolean) => {
    // Optimistic UI update
    setBroadcasts(prev => prev.map(b => b.id === id ? { ...b, isActive: !currentStatus } : b))
    
    try {
      const res = await fetch(`/api/operations/broadcasts/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ isActive: !currentStatus })
      })

      if (!res.ok) throw new Error("Failed to toggle")
      router.refresh()
    } catch {
      // Revert on failure
      setBroadcasts(prev => prev.map(b => b.id === id ? { ...b, isActive: currentStatus } : b))
      alert("Failed to update broadcast status.")
    }
  }

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this broadcast?")) return
    try {
      const res = await fetch(`/api/operations/broadcasts/${id}`, { method: "DELETE" })
      if (!res.ok) throw new Error("Failed to delete")

      setBroadcasts(prev => prev.filter(b => b.id !== id))
      router.refresh()
    } catch {
      alert("Failed to delete broadcast.")
    }
  }

  return (
    <div className="flex flex-col h-full w-full max-w-[1600px] mx-auto p-4 md:p-8">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <div>
          <h1 className="text-3xl font-black text-[var(--text-primary)]">System Broadcasts</h1>
          <p className="text-[var(--text-secondary)] mt-1">Manage platform-wide announcements and alerts.</p>
        </div>
        
        <Button onClick={() => setIsAdding(!isAdding)} className="gap-2">
          {isAdding ? "Cancel" : <><Plus className="w-4 h-4" /> New Broadcast</>}
        </Button>
      </div>

      {isAdding && (
        <form onSubmit={handleAddBroadcast} className="bg-[var(--surface-default)] p-6 rounded-xl border border-[var(--border-default)] shadow-sm mb-8 space-y-6 animate-in fade-in zoom-in duration-200">
          <h2 className="font-bold text-[var(--text-primary)]">New Broadcast Details</h2>
          
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-4">
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-[var(--text-secondary)]">Title (English) *</label>
                <input 
                  type="text" value={titleEn} onChange={e => setTitleEn(e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--surface-subtle)] border border-[var(--border-default)] rounded-lg text-sm"
                  required
                />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-[var(--text-secondary)]">Message (English) *</label>
                <textarea 
                  value={messageEn} onChange={e => setMessageEn(e.target.value)} rows={3}
                  className="w-full px-3 py-2 bg-[var(--surface-subtle)] border border-[var(--border-default)] rounded-lg text-sm resize-none"
                  required
                />
              </div>
            </div>

            <div className="space-y-4">
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-[var(--text-secondary)]">Title (Arabic)</label>
                <input 
                  type="text" value={titleAr} onChange={e => setTitleAr(e.target.value)} dir="rtl"
                  className="w-full px-3 py-2 bg-[var(--surface-subtle)] border border-[var(--border-default)] rounded-lg text-sm"
                  placeholder="Leave blank to use English"
                />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-[var(--text-secondary)]">Message (Arabic)</label>
                <textarea 
                  value={messageAr} onChange={e => setMessageAr(e.target.value)} rows={3} dir="rtl"
                  className="w-full px-3 py-2 bg-[var(--surface-subtle)] border border-[var(--border-default)] rounded-lg text-sm resize-none"
                  placeholder="Leave blank to use English"
                />
              </div>
            </div>
          </div>

          <div className="flex flex-col sm:flex-row gap-4 pt-4 border-t border-[var(--border-default)]">
            <div className="space-y-1.5 flex-1 max-w-xs">
              <label className="text-xs font-bold text-[var(--text-secondary)]">Type *</label>
              <select 
                value={type} onChange={e => setType(e.target.value)}
                className="w-full px-3 py-2 bg-[var(--surface-subtle)] border border-[var(--border-default)] rounded-lg text-sm"
                required
              >
                <option value="INFO">Information</option>
                <option value="WARNING">Warning</option>
                <option value="ERROR">Critical / Error</option>
              </select>
            </div>
            
            <div className="space-y-1.5 flex flex-col justify-center">
              <label className="text-xs font-bold text-[var(--text-secondary)]">Active Immediately</label>
              <button 
                type="button"
                onClick={() => setIsActive(!isActive)}
                className="p-1 rounded-full hover:bg-[var(--surface-active)] transition-colors self-start"
              >
                {isActive ? (
                  <ToggleRight className="w-8 h-8 text-[var(--color-primary)]" />
                ) : (
                  <ToggleLeft className="w-8 h-8 text-[var(--text-tertiary)]" />
                )}
              </button>
            </div>
          </div>

          <div className="pt-2 flex justify-end">
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting ? "Creating..." : "Create Broadcast"}
            </Button>
          </div>
        </form>
      )}

      <div className="bg-[var(--surface-default)] border border-[var(--border-default)] rounded-2xl overflow-hidden shadow-sm flex-1">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm whitespace-nowrap">
            <thead className="bg-[var(--surface-hover)] border-b border-[var(--border-default)] text-[var(--text-secondary)]">
              <tr>
                <th className="p-4 font-bold">Message</th>
                <th className="p-4 font-bold">Type</th>
                <th className="p-4 font-bold">Status</th>
                <th className="p-4 font-bold">Created</th>
                <th className="p-4 font-bold text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[var(--border-default)]">
              {broadcasts.length === 0 && (
                <tr>
                  <td colSpan={5} className="p-8 text-center text-[var(--text-tertiary)]">
                    No active broadcasts.
                  </td>
                </tr>
              )}
              {broadcasts.map(msg => (
                <tr key={msg.id} className="hover:bg-[var(--surface-hover)] transition-colors">
                  <td className="p-4 max-w-sm truncate">
                    <div className="font-bold text-[var(--text-primary)] mb-1">{msg.titleEn}</div>
                    <div className="text-xs text-[var(--text-secondary)] truncate">{msg.messageEn}</div>
                  </td>
                  <td className="p-4">
                    <span className={`inline-flex items-center px-2 py-1 rounded-md text-[10px] font-bold ${msg.type === 'INFO' ? 'bg-blue-500/10 text-blue-500' : msg.type === 'WARNING' ? 'bg-amber-500/10 text-amber-500' : 'bg-red-500/10 text-red-500'}`}>
                      {msg.type}
                    </span>
                  </td>
                  <td className="p-4">
                    <button 
                      onClick={() => handleToggle(msg.id, msg.isActive)}
                      className="p-2 -ms-2 rounded-full hover:bg-[var(--surface-active)] transition-colors"
                    >
                      {msg.isActive ? (
                        <ToggleRight className="w-6 h-6 text-[var(--color-primary)]" />
                      ) : (
                        <ToggleLeft className="w-6 h-6 text-[var(--text-tertiary)]" />
                      )}
                    </button>
                  </td>
                  <td className="p-4 text-[var(--text-tertiary)] text-xs">
                    {format(new Date(msg.createdAt), 'MMM d, yyyy h:mm a')}
                  </td>
                  <td className="p-4 text-right">
                    <Button variant="ghost" size="sm" onClick={() => handleDelete(msg.id)} className="text-red-500 hover:text-red-600 hover:bg-red-500/10">
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
