        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          template,
          serviceIds: selectedServices
        })
      })

      setCatalogData({
        template,
        items: services.filter(s => selectedServices.includes(s.id))
      })
