"use client"

import { useState } from "react"
import { useRouter } from "next/navigation"
import { Plus, Clock, AlertTriangle, CalendarDays, Trash2 } from "lucide-react"
import { Button } from "@/components/ui/Button"
import { format } from "date-fns"

export function TemporalRulesManager({ 
  initialRules,
  attractions
}: { 
  initialRules: any[]
  attractions: any[]
}) {
  const router = useRouter()
  const [rules, setRules] = useState(initialRules)
  const [isAdding, setIsAdding] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Form state
  const [attractionId, setAttractionId] = useState(attractions[0]?.id || "")
  const [ruleType, setRuleType] = useState("CLOSURE")
  const [startDate, setStartDate] = useState("")
  const [endDate, setEndDate] = useState("")
  const [openTime, setOpenTime] = useState("")
  const [closeTime, setCloseTime] = useState("")
  const [daysOfWeek, setDaysOfWeek] = useState<number[]>([])

  const getRuleIcon = (type: string) => {
    switch (type) {
      case 'RECURRING': return <Clock className="w-5 h-5 text-[var(--color-primary)]" />;
      case 'CLOSURE': return <AlertTriangle className="w-5 h-5 text-[var(--color-error)]" />;
      case 'OVERRIDE': return <CalendarDays className="w-5 h-5 text-yellow-500" />;
      default: return <Clock className="w-5 h-5" />;
    }
  }

  const handleAddRule = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsSubmitting(true)

    try {
      const res = await fetch("/api/temporal-rules", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          attractionId,
          ruleType,
          startDate: startDate || null,
          endDate: endDate || null,
          openTime: openTime || null,
          closeTime: closeTime || null,
          daysOfWeek: daysOfWeek.length > 0 ? daysOfWeek : null
        })
      })

      if (!res.ok) throw new Error("Failed to create rule")
      
      const newRule = await res.json()
      
      // We need to fetch the attraction details so it displays correctly
      const attraction = attractions.find(a => a.id === attractionId)
      newRule.attraction = attraction
      
      setRules(prev => [newRule, ...prev])
      setIsAdding(false)
      
      // Reset form
      setStartDate("")
      setEndDate("")
      setOpenTime("")
      setCloseTime("")
      setDaysOfWeek([])
      
      router.refresh()
    } catch {
      alert("Failed to add temporal rule.")
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this rule?")) return
    try {
      const res = await fetch(`/api/temporal-rules/${id}`, { method: "DELETE" })
      if (!res.ok) throw new Error("Failed to delete")

      setRules(prev => prev.filter(r => r.id !== id))
      router.refresh()
    } catch {
      alert("Failed to delete temporal rule.")
    }
  }

  const handleDayToggle = (day: number) => {
    setDaysOfWeek(prev => 
      prev.includes(day) 
        ? prev.filter(d => d !== day)
        : [...prev, day].sort()
    )
  }

  const days = [
    { label: "Sun", value: 0 },
    { label: "Mon", value: 1 },
    { label: "Tue", value: 2 },
    { label: "Wed", value: 3 },
    { label: "Thu", value: 4 },
    { label: "Fri", value: 5 },
    { label: "Sat", value: 6 }
  ]

  return (
    <div className="space-y-8 pb-24">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-[var(--text-primary)]">Temporal Rules</h1>
          <p className="text-[var(--text-secondary)]">Manage opening hours, seasonal closures, and special events.</p>
        </div>
        <Button onClick={() => setIsAdding(!isAdding)} className="gap-2">
          {isAdding ? "Cancel" : <><Plus className="w-4 h-4" /> Create Rule</>}
        </Button>
      </div>

      {isAdding && (
        <form onSubmit={handleAddRule} className="bg-[var(--surface-default)] p-6 rounded-xl border border-[var(--border-default)] shadow-sm space-y-6 animate-in fade-in zoom-in duration-200">
          <h2 className="font-bold text-[var(--text-primary)]">New Temporal Rule</h2>
          
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-xs font-bold text-[var(--text-secondary)]">Attraction</label>
              <select 
                value={attractionId} onChange={e => setAttractionId(e.target.value)}
                className="w-full px-3 py-2 bg-[var(--surface-subtle)] border border-[var(--border-default)] rounded-lg text-sm"
                required
              >
                {attractions.map(a => <option key={a.id} value={a.id}>{a.nameEn}</option>)}
              </select>
            </div>
            
            <div className="space-y-1.5">
              <label className="text-xs font-bold text-[var(--text-secondary)]">Rule Type</label>
              <select 
                value={ruleType} onChange={e => setRuleType(e.target.value)}
                className="w-full px-3 py-2 bg-[var(--surface-subtle)] border border-[var(--border-default)] rounded-lg text-sm"
                required
              >
                <option value="CLOSURE">Closure</option>
                <option value="RECURRING">Recurring Hours</option>
                <option value="OVERRIDE">Special Override</option>
              </select>
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-bold text-[var(--text-secondary)]">Start Date (Optional)</label>
              <input 
                type="date" value={startDate} onChange={e => setStartDate(e.target.value)}
                className="w-full px-3 py-2 bg-[var(--surface-subtle)] border border-[var(--border-default)] rounded-lg text-sm"
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-bold text-[var(--text-secondary)]">End Date (Optional)</label>
              <input 
                type="date" value={endDate} onChange={e => setEndDate(e.target.value)}
                className="w-full px-3 py-2 bg-[var(--surface-subtle)] border border-[var(--border-default)] rounded-lg text-sm"
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-bold text-[var(--text-secondary)]">Open Time (Optional)</label>
              <input 
                type="time" value={openTime} onChange={e => setOpenTime(e.target.value)}
                className="w-full px-3 py-2 bg-[var(--surface-subtle)] border border-[var(--border-default)] rounded-lg text-sm"
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-bold text-[var(--text-secondary)]">Close Time (Optional)</label>
              <input 
                type="time" value={closeTime} onChange={e => setCloseTime(e.target.value)}
                className="w-full px-3 py-2 bg-[var(--surface-subtle)] border border-[var(--border-default)] rounded-lg text-sm"
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-xs font-bold text-[var(--text-secondary)]">Days of Week (Optional)</label>
            <div className="flex flex-wrap gap-2">
              {days.map(d => (
                <button
                  key={d.value}
                  type="button"
                  onClick={() => handleDayToggle(d.value)}
                  className={`px-3 py-1.5 rounded text-xs font-bold border transition-colors ${
                    daysOfWeek.includes(d.value) 
                      ? 'bg-[var(--color-primary)] text-white border-[var(--color-primary)]' 
                      : 'bg-[var(--surface-subtle)] border-[var(--border-default)] text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]'
                  }`}
                >
                  {d.label}
                </button>
              ))}
            </div>
          </div>

          <div className="pt-2 flex justify-end">
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting ? "Saving..." : "Save Rule"}
            </Button>
          </div>
        </form>
      )}

      {/* Rules List */}
      <div className="bg-[var(--surface-default)] rounded-2xl border border-[var(--border-default)] overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-[var(--surface-hover)] border-b border-[var(--border-default)]">
                <th className="p-4 text-xs font-bold text-[var(--text-tertiary)] uppercase tracking-wider">Type</th>
                <th className="p-4 text-xs font-bold text-[var(--text-tertiary)] uppercase tracking-wider">Attraction</th>
                <th className="p-4 text-xs font-bold text-[var(--text-tertiary)] uppercase tracking-wider">Schedule</th>
                <th className="p-4 text-xs font-bold text-[var(--text-tertiary)] uppercase tracking-wider">Dates</th>
                <th className="p-4 text-xs font-bold text-[var(--text-tertiary)] uppercase tracking-wider text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[var(--border-default)]">
              {rules.length === 0 && (
                <tr>
                  <td colSpan={5} className="p-8 text-center text-[var(--text-secondary)]">
                    No temporal rules configured yet.
                  </td>
                </tr>
              )}
              {rules.map((rule) => (
                <tr key={rule.id} className="hover:bg-[var(--surface-hover)]/50 transition-colors">
                  <td className="p-4">
                    <div className="flex items-center gap-2">
                      {getRuleIcon(rule.ruleType)}
                      <span className="font-bold text-sm text-[var(--text-primary)]">{rule.ruleType}</span>
                    </div>
                  </td>
                  <td className="p-4 text-sm font-bold text-[var(--text-primary)]">
                    {rule.attraction?.nameEn || "Global"}
                  </td>
                  <td className="p-4 text-sm text-[var(--text-secondary)]">
                    {rule.openTime && rule.closeTime ? `${rule.openTime} - ${rule.closeTime}` : "All Day"}
                    {rule.daysOfWeek && rule.daysOfWeek.length > 0 && (
                      <div className="mt-1 text-xs text-[var(--text-tertiary)]">
                        Days: {(rule.daysOfWeek as number[]).join(', ')}
                      </div>
                    )}
                  </td>
                  <td className="p-4 text-sm text-[var(--text-secondary)]">
                    {rule.startDate ? format(new Date(rule.startDate), "MMM dd, yyyy") : "Always"} 
                    {rule.endDate ? ` to ${format(new Date(rule.endDate), "MMM dd, yyyy")}` : ""}
                  </td>
                  <td className="p-4 text-right">
                    <Button variant="ghost" size="sm" onClick={() => handleDelete(rule.id)} className="text-red-500 hover:text-red-600 hover:bg-red-500/10">
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  )
}

"use client"

import { useState, useEffect } from "react"
import { useRouter } from "next/navigation"
import { Save, Eye, ArrowLeft, Image as ImageIcon, Settings, LayoutTemplate, Layers, Link as LinkIcon, Search, X } from "lucide-react"
import { Button } from "@/components/ui/Button"
import { Input } from "@/components/ui/Input"
import { Tabs, TabsContent } from "@/components/dashboard/ui/Tabs"
import { BilingualInput } from "@/components/dashboard/ui/BilingualInput"
import { RichTextEditor } from "@/components/dashboard/ui/RichTextEditor"
import { MediaUploader } from "@/components/dashboard/ui/MediaUploader"
import { Repeater } from "@/components/dashboard/ui/Repeater"

interface ServiceFormProps {
  initialData?: any
  isEdit?: boolean
}

const TABS = [
  { id: "basic", label: "Basic Details", icon: <Settings className="w-4 h-4" /> },
  { id: "content", label: "Content", icon: <LayoutTemplate className="w-4 h-4" /> },
  { id: "process", label: "Process", icon: <Layers className="w-4 h-4" /> },
  { id: "hero", label: "Hero Media", icon: <ImageIcon className="w-4 h-4" /> },
  { id: "gallery", label: "Gallery", icon: <ImageIcon className="w-4 h-4" /> },
  { id: "projects", label: "Projects", icon: <LinkIcon className="w-4 h-4" /> },
  { id: "cta", label: "CTA", icon: <LinkIcon className="w-4 h-4" /> },
  { id: "seo", label: "SEO", icon: <Search className="w-4 h-4" /> },
]

export function ServiceForm({ initialData, isEdit }: ServiceFormProps) {
  const router = useRouter()
  const [activeTab, setActiveTab] = useState("basic")
  const [isSaving, setIsSaving] = useState(false)
  const [isDirty, setIsDirty] = useState(false)

  // Form State
  const [formData, setFormData] = useState(initialData || {
    nameEn: "", nameAr: "",
    slug: "",
    taglineEn: "", taglineAr: "",
    status: "Hidden", featured: false, order: 0,
    descriptionEn: "", descriptionAr: "",
    processSteps: [],
    heroType: "IMAGE", heroMediaUrl: "",
    gallery: [],
    similarProjects: [],
    ctaLabelEn: "", ctaLabelAr: "", ctaType: "Contact",
    seoTitleEn: "", seoTitleAr: "", seoDescEn: "", seoDescAr: "", seoOgImage: ""
  })

  // Prevent accidental navigation
  useEffect(() => {
    const handleBeforeUnload = (e: BeforeUnloadEvent) => {
      if (isDirty) {
        e.preventDefault()
        e.returnValue = ""
      }
    }
    window.addEventListener("beforeunload", handleBeforeUnload)
    return () => window.removeEventListener("beforeunload", handleBeforeUnload)
  }, [isDirty])

  const updateField = (field: string, value: any) => {
    setFormData((prev: any) => ({ ...prev, [field]: value }))
    setIsDirty(true)
  }

  const handleSave = async () => {
    setIsSaving(true)
    try {
      const isNew = !isEdit
      const url = isNew ? '/api/b2b/services' : `/api/b2b/services/${initialData?.id}`
      const method = isNew ? 'POST' : 'PUT'
      
      const payload = {
        slug: formData.slug,
        titleEn: formData.nameEn,
        titleAr: formData.nameAr,
        taglineEn: formData.taglineEn,
        taglineAr: formData.taglineAr,
        isFeatured: formData.featured,
        isVisible: formData.status === "Visible",
        isPublished: true,
        heroMediaType: formData.heroType,
        heroMediaUrl: formData.heroMediaUrl,
        contentEn: formData.descriptionEn,
        contentAr: formData.descriptionAr,
        process: formData.processSteps,
        ctaPrimary: formData.ctaLabelEn,
        ctaSecondary: formData.ctaLabelAr, // mapping to secondary for Ar (temporary)
        seo: {
          titleEn: formData.seoTitleEn,
          titleAr: formData.seoTitleAr,
          descEn: formData.seoDescEn,
          descAr: formData.seoDescAr,
          ogImage: formData.seoOgImage
        },
        gallery: formData.gallery,
        projects: formData.similarProjects
      }

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      })

      if (!res.ok) throw new Error("Failed to save service")
      
      setIsDirty(false)
      router.push("/dashboard/b2b/services")
    } catch (e) {
      console.error(e)
      alert("Failed to save service")
    } finally {
      setIsSaving(false)
    }
  }

  return (
    <div className="max-w-[1200px] mx-auto pb-32">
      
      {/* Header Actions */}
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-4">
          <Button variant="ghost" onClick={() => router.back()} className="p-2">
            <ArrowLeft className="w-5 h-5" />
          </Button>
          <div>
            <h1 className="text-2xl font-black text-[var(--text-primary)]">
              {isEdit ? 'Edit Service' : 'New Service'}
            </h1>
            <p className="text-sm text-[var(--text-secondary)]">
              {isDirty ? 'Unsaved changes' : 'All changes saved'}
            </p>
          </div>
        </div>
        
        <div className="flex items-center gap-3">
          {isEdit && (
            <Button variant="outline" className="gap-2" onClick={() => window.open(`/en/b2b/services/${formData.slug}`, '_blank')}>
              <Eye className="w-4 h-4" /> Preview
            </Button>
          )}
          <Button onClick={handleSave} isLoading={isSaving} className="gap-2">
            <Save className="w-4 h-4" /> Save Service
          </Button>
        </div>
      </div>

      <div className="bg-[var(--surface-default)] rounded-2xl border border-[var(--border-default)]">
        <Tabs tabs={TABS} activeTab={activeTab} onChange={setActiveTab} />
        
        <div className="p-6 md:p-8">
          
          {/* TAB 1: BASIC DETAILS */}
          <TabsContent value="basic" activeTab={activeTab}>
            <div className="space-y-8 max-w-3xl">
              <BilingualInput 
                label="Service Name" required
                valueEn={formData.nameEn} onChangeEn={v => {
                  updateField('nameEn', v)
                  if (!isEdit) updateField('slug', v.toLowerCase().replace(/[^a-z0-9]+/g, '-'))
                }}
                valueAr={formData.nameAr} onChangeAr={v => updateField('nameAr', v)}
              />
              
              <div className="space-y-3">
                <label className="block text-sm font-bold text-[var(--text-secondary)]">URL Slug</label>
                <Input 
                  value={formData.slug} 
                  onChange={e => updateField('slug', e.target.value)} 
                  placeholder="e.g. event-engineering" 
                />
              </div>

              <BilingualInput 
                label="Tagline" type="textarea"
                valueEn={formData.taglineEn} onChangeEn={v => updateField('taglineEn', v)}
                valueAr={formData.taglineAr} onChangeAr={v => updateField('taglineAr', v)}
              />

              <div className="grid grid-cols-3 gap-6 pt-4 border-t border-[var(--border-default)]">
                <div className="space-y-3">
                  <label className="block text-sm font-bold text-[var(--text-secondary)]">Status</label>
                  <select 
                    value={formData.status} onChange={e => updateField('status', e.target.value)}
                    className="w-full px-4 py-3 bg-[var(--surface-hover)] border border-[var(--border-default)] rounded-xl text-sm"
                  >
                    <option value="Visible">Visible</option>
                    <option value="Hidden">Hidden</option>
                  </select>
                </div>
                <div className="space-y-3">
                  <label className="block text-sm font-bold text-[var(--text-secondary)]">Featured</label>
                  <select 
                    value={formData.featured ? "Yes" : "No"} onChange={e => updateField('featured', e.target.value === "Yes")}
                    className="w-full px-4 py-3 bg-[var(--surface-hover)] border border-[var(--border-default)] rounded-xl text-sm"
                  >
                    <option value="No">No</option>
                    <option value="Yes">Yes</option>
                  </select>
                </div>
                <div className="space-y-3">
                  <label className="block text-sm font-bold text-[var(--text-secondary)]">Sort Order</label>
                  <Input type="number" value={formData.order} onChange={e => updateField('order', parseInt(e.target.value))} />
                </div>
              </div>
            </div>
          </TabsContent>

          {/* TAB 2: CONTENT */}
          <TabsContent value="content" activeTab={activeTab}>
            <div className="space-y-8">
              <div className="space-y-3">
                <label className="block text-sm font-bold text-[var(--text-secondary)]">English Description</label>
                <RichTextEditor value={formData.descriptionEn} onChange={v => updateField('descriptionEn', v)} />
              </div>
              <div className="space-y-3">
                <label className="block text-sm font-bold text-[var(--text-secondary)]">Arabic Description</label>
                <RichTextEditor value={formData.descriptionAr} onChange={v => updateField('descriptionAr', v)} dir="rtl" />
              </div>
            </div>
          </TabsContent>

          {/* TAB 3: PROCESS */}
          <TabsContent value="process" activeTab={activeTab}>
            <div className="max-w-4xl">
              <Repeater 
                items={formData.processSteps}
                onReorder={items => updateField('processSteps', items)}
                onAdd={() => updateField('processSteps', [...formData.processSteps, { id: Math.random().toString(), titleEn: "", titleAr: "", descEn: "", descAr: "" }])}
                onRemove={id => updateField('processSteps', formData.processSteps.filter((i: any) => i.id !== id))}
                addLabel="Add Process Step"
                renderItem={(item: any, index) => (
                  <div className="space-y-4">
                    <h4 className="text-sm font-bold text-[var(--text-primary)]">Step {index + 1}</h4>
                    <BilingualInput 
                      label="Title"
                      valueEn={item.titleEn} onChangeEn={v => {
                        const newSteps = [...formData.processSteps]; newSteps[index].titleEn = v; updateField('processSteps', newSteps)
                      }}
                      valueAr={item.titleAr} onChangeAr={v => {
                        const newSteps = [...formData.processSteps]; newSteps[index].titleAr = v; updateField('processSteps', newSteps)
                      }}
                    />
                    <BilingualInput 
                      label="Description" type="textarea"
                      valueEn={item.descEn} onChangeEn={v => {
                        const newSteps = [...formData.processSteps]; newSteps[index].descEn = v; updateField('processSteps', newSteps)
                      }}
                      valueAr={item.descAr} onChangeAr={v => {
                        const newSteps = [...formData.processSteps]; newSteps[index].descAr = v; updateField('processSteps', newSteps)
                      }}
                    />
                  </div>
                )}
              />
            </div>
          </TabsContent>

          {/* TAB 4: HERO MEDIA */}
          <TabsContent value="hero" activeTab={activeTab}>
            <div className="space-y-8 max-w-2xl">
              <div className="space-y-3">
                <label className="block text-sm font-bold text-[var(--text-secondary)]">Media Type</label>
                <select 
                  value={formData.heroType} onChange={e => updateField('heroType', e.target.value)}
                  className="w-full px-4 py-3 bg-[var(--surface-hover)] border border-[var(--border-default)] rounded-xl text-sm"
                >
                  <option value="IMAGE">Image</option>
                  <option value="VIDEO">Video</option>
                  <option value="MODEL_3D">3D Model (.glb/.gltf)</option>
                  <option value="IFRAME">External iFrame</option>
                </select>
              </div>

              {formData.heroType === "IFRAME" ? (
                <div className="space-y-3">
                  <label className="block text-sm font-bold text-[var(--text-secondary)]">iFrame URL</label>
                  <Input value={formData.heroMediaUrl} onChange={e => updateField('heroMediaUrl', e.target.value)} placeholder="https://..." />
                </div>
              ) : (
                <div className="space-y-3">
                  <label className="block text-sm font-bold text-[var(--text-secondary)]">Upload Media</label>
                  <MediaUploader onUploadComplete={(urls) => updateField('heroMediaUrl', urls[0])} />
                  {formData.heroMediaUrl && (
                    <div className="mt-4 p-4 rounded-xl border border-[var(--border-default)] bg-[var(--surface-hover)] flex items-center justify-between">
                      <span className="text-sm truncate">{formData.heroMediaUrl}</span>
                      <Button variant="ghost" size="sm" onClick={() => updateField('heroMediaUrl', '')}>Clear</Button>
                    </div>
                  )}
                </div>
              )}
            </div>
          </TabsContent>

          {/* TAB 5-8: Placeholders for brevity but following same patterns */}
          <TabsContent value="gallery" activeTab={activeTab}>
            <div className="max-w-2xl">
              <MediaUploader multiple onUploadComplete={(urls) => updateField('gallery', [...formData.gallery, ...urls])} />
              <div className="grid grid-cols-3 gap-4 mt-8">
                {formData.gallery.map((url: string, i: number) => (
                  <div key={i} className="aspect-square bg-[var(--surface-hover)] rounded-xl border border-[var(--border-default)] overflow-hidden relative group">
                    <img src={url} alt="" className="w-full h-full object-cover" />
                    <button 
                      onClick={() => updateField('gallery', formData.gallery.filter((_: any, idx: number) => idx !== i))}
                      className="absolute top-2 end-2 bg-red-500 text-white p-1 rounded opacity-0 group-hover:opacity-100 transition-opacity"
                    >
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                ))}
              </div>
            </div>
          </TabsContent>

          <TabsContent value="projects" activeTab={activeTab}>
            <p className="text-[var(--text-secondary)]">Link existing case studies here using the Repeater component.</p>
          </TabsContent>

          <TabsContent value="cta" activeTab={activeTab}>
            <div className="max-w-2xl space-y-6">
              <BilingualInput 
                label="Primary CTA Label"
                valueEn={formData.ctaLabelEn} onChangeEn={v => updateField('ctaLabelEn', v)}
                valueAr={formData.ctaLabelAr} onChangeAr={v => updateField('ctaLabelAr', v)}
              />
            </div>
          </TabsContent>

          <TabsContent value="seo" activeTab={activeTab}>
            <div className="max-w-3xl space-y-8">
              <BilingualInput 
                label="Meta Title"
                valueEn={formData.seoTitleEn} onChangeEn={v => updateField('seoTitleEn', v)}
                valueAr={formData.seoTitleAr} onChangeAr={v => updateField('seoTitleAr', v)}
              />
              <BilingualInput 
                label="Meta Description" type="textarea"
                valueEn={formData.seoDescEn} onChangeEn={v => updateField('seoDescEn', v)}
                valueAr={formData.seoDescAr} onChangeAr={v => updateField('seoDescAr', v)}
              />
            </div>
          </TabsContent>

        </div>
      </div>
    </div>
  )
}

"use client";

import { useState, useEffect } from 'react';
import { Modal } from "@/components/ui/Modal";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import { Loader2, User, Image as ImageIcon, Code } from "lucide-react";
import { MediaUploader } from "@/components/shared/MediaUploader";
type Tab = "basic" | "media" | "advanced";

export function EmployeeFormModal({ isOpen, onClose, employee, onSuccess }: { isOpen: boolean; onClose: () => void; employee: any; onSuccess: () => void }) {
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<Tab>("basic");
  
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    slug: "",
    designation: "",
    department: "",
    yearsOfExperience: 0,
    tagline: "",
    profileImage: "",
    aboutSummary: "",
    careerJourney: "",
    keyStrengths: "",
    expertiseTags: "[]",
    coreCompetencies: "[]",
    experience: "[]",
    projects: "[]",
    certifications: "[]",
    education: "[]",
    awards: "[]",
    skillsMatrix: "[]",
    mediaGallery: "[]",
    testimonials: "[]",
    contactEmail: "",
    linkedinUrl: "",
    isActive: true,
    order: 0,
  });

  useEffect(() => {
    if (employee) {
      // eslint-disable-next-line react-hooks/set-state-in-effect -- Expected pattern for data synchronization
  setFormData({
        ...employee,
        expertiseTags: JSON.stringify(employee.expertiseTags || []),
        coreCompetencies: JSON.stringify(employee.coreCompetencies || []),
        experience: JSON.stringify(employee.experience || []),
        projects: JSON.stringify(employee.projects || []),
        certifications: JSON.stringify(employee.certifications || []),
        education: JSON.stringify(employee.education || []),
        awards: JSON.stringify(employee.awards || []),
        skillsMatrix: JSON.stringify(employee.skillsMatrix || []),
        mediaGallery: JSON.stringify(employee.mediaGallery || []),
        testimonials: JSON.stringify(employee.testimonials || []),
      });
    } else {
      setFormData({
        firstName: "", lastName: "", slug: "", designation: "", department: "", yearsOfExperience: 0, tagline: "", profileImage: "",
        aboutSummary: "", careerJourney: "", keyStrengths: "", expertiseTags: "[]", coreCompetencies: "[]", experience: "[]",
        projects: "[]", certifications: "[]", education: "[]", awards: "[]", skillsMatrix: "[]", mediaGallery: "[]", testimonials: "[]",
        contactEmail: "", linkedinUrl: "", isActive: true, order: 0,
      });
    }
    setActiveTab("basic");
  }, [employee, isOpen]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const payload = {
        ...formData,
        yearsOfExperience: parseInt(formData.yearsOfExperience.toString()),
        order: parseInt(formData.order.toString()),
        expertiseTags: JSON.parse(formData.expertiseTags),
        coreCompetencies: JSON.parse(formData.coreCompetencies),
        experience: JSON.parse(formData.experience),
        projects: JSON.parse(formData.projects),
        certifications: JSON.parse(formData.certifications),
        education: JSON.parse(formData.education),
        awards: JSON.parse(formData.awards),
        skillsMatrix: JSON.parse(formData.skillsMatrix),
        mediaGallery: JSON.parse(formData.mediaGallery),
        testimonials: JSON.parse(formData.testimonials),
      };

      const res = await fetch(employee ? `/api/employees/${employee.id}` : `/api/employees`, {
        method: employee ? "PUT" : "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      if (res.ok) {
        onSuccess();
      } else {
        const data = await res.json();
        alert("Error: " + data.error);
      }
    } catch (err) {
      console.error(err);
      alert("Submission failed. Please check your inputs, particularly the Advanced Data JSON formatting.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title={employee ? "Edit Team Member" : "Add Team Member"} size="xl">
      <div className="flex flex-col md:flex-row max-h-[85vh] overflow-hidden bg-zinc-950/50 backdrop-blur-xl">
        
        {/* Sidebar Nav */}
        <div className="w-full md:w-64 border-e border-zinc-800/50 bg-zinc-900/30 p-4 flex flex-col gap-2 shrink-0 overflow-y-auto">
          <div className="px-3 py-2 text-xs font-bold text-zinc-500 uppercase tracking-widest mb-2">Sections</div>
          <button
            type="button"
            onClick={() => setActiveTab("basic")}
            className={`flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ${
              activeTab === "basic" 
                ? "bg-amber-500/10 text-amber-500 border border-amber-500/20" 
                : "text-zinc-400 hover:text-zinc-200 hover:bg-zinc-800/50 border border-transparent"
            }`}
          >
            <User className="w-4 h-4" /> Basic Info
          </button>
          <button
            type="button"
            onClick={() => setActiveTab("media")}
            className={`flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ${
              activeTab === "media" 
                ? "bg-amber-500/10 text-amber-500 border border-amber-500/20" 
                : "text-zinc-400 hover:text-zinc-200 hover:bg-zinc-800/50 border border-transparent"
            }`}
          >
            <ImageIcon className="w-4 h-4" /> Media & Bio
          </button>
          <button
            type="button"
            onClick={() => setActiveTab("advanced")}
            className={`flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ${
              activeTab === "advanced" 
                ? "bg-amber-500/10 text-amber-500 border border-amber-500/20" 
                : "text-zinc-400 hover:text-zinc-200 hover:bg-zinc-800/50 border border-transparent"
            }`}
          >
            <Code className="w-4 h-4" /> Advanced Data
          </button>

          <div className="mt-auto pt-8">
            <div className="flex items-center gap-3 p-4 rounded-xl bg-zinc-900/50 border border-zinc-800">
              <input 
                type="checkbox" 
                id="isActive" 
                checked={formData.isActive} 
                onChange={e => setFormData({...formData, isActive: e.target.checked})} 
                className="w-5 h-5 rounded bg-zinc-800 border border-zinc-700 accent-amber-500" 
              />
              <label htmlFor="isActive" className="text-sm font-bold text-zinc-300 cursor-pointer">Profile Active</label>
            </div>
          </div>
        </div>

        {/* Form Content */}
        <form onSubmit={handleSubmit} className="flex-1 flex flex-col h-full overflow-hidden relative">
          
          <div className="flex-1 overflow-y-auto p-6 md:p-8 custom-scrollbar">
            {activeTab === "basic" && (
              <div className="space-y-6 animate-in fade-in slide-in-from-end-4 duration-300">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-xs font-bold uppercase tracking-wider text-zinc-500 mb-2">First Name</label>
                    <Input required value={formData.firstName} onChange={e => setFormData({...formData, firstName: e.target.value})} className="bg-zinc-900/50" />
                  </div>
                  <div>
                    <label className="block text-xs font-bold uppercase tracking-wider text-zinc-500 mb-2">Last Name</label>
                    <Input required value={formData.lastName} onChange={e => setFormData({...formData, lastName: e.target.value})} className="bg-zinc-900/50" />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-xs font-bold uppercase tracking-wider text-zinc-500 mb-2">Slug (URL)</label>
                    <Input required value={formData.slug} onChange={e => setFormData({...formData, slug: e.target.value})} placeholder="e.g. john-doe" className="bg-zinc-900/50 font-mono text-sm" />
                  </div>
                  <div>
                    <label className="block text-xs font-bold uppercase tracking-wider text-zinc-500 mb-2">Department</label>
                    <Input required value={formData.department} onChange={e => setFormData({...formData, department: e.target.value})} className="bg-zinc-900/50" />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-xs font-bold uppercase tracking-wider text-zinc-500 mb-2">Designation</label>
                    <Input required value={formData.designation} onChange={e => setFormData({...formData, designation: e.target.value})} className="bg-zinc-900/50" />
                  </div>
                  <div>
                    <label className="block text-xs font-bold uppercase tracking-wider text-zinc-500 mb-2">Years of Exp</label>
                    <Input type="number" required value={formData.yearsOfExperience} onChange={e => setFormData({...formData, yearsOfExperience: parseInt(e.target.value) || 0})} className="bg-zinc-900/50" />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-xs font-bold uppercase tracking-wider text-zinc-500 mb-2">LinkedIn URL</label>
                    <Input value={formData.linkedinUrl} onChange={e => setFormData({...formData, linkedinUrl: e.target.value})} className="bg-zinc-900/50" placeholder="https://linkedin.com/in/..." />
                  </div>
                  <div>
                    <label className="block text-xs font-bold uppercase tracking-wider text-zinc-500 mb-2">Contact Email</label>
                    <Input value={formData.contactEmail} onChange={e => setFormData({...formData, contactEmail: e.target.value})} className="bg-zinc-900/50" placeholder="hello@example.com" />
                  </div>
                </div>
              </div>
            )}

            {activeTab === "media" && (
              <div className="space-y-8 animate-in fade-in slide-in-from-end-4 duration-300">
                
                <div>
                  <label className="block text-xs font-bold uppercase tracking-wider text-zinc-500 mb-3">Profile Portrait / Video</label>
                  <MediaUploader 
                    value={formData.profileImage} 
                    onChange={url => setFormData({...formData, profileImage: url})} 
                    accept="image/*,video/*"
                  />
                  <p className="text-xs text-zinc-500 mt-2">Upload a high-res portrait image or a short looping video (.mp4).</p>
                </div>

                <div>
                  <label className="block text-xs font-bold uppercase tracking-wider text-zinc-500 mb-2">Hero Tagline</label>
                  <Input required value={formData.tagline} onChange={e => setFormData({...formData, tagline: e.target.value})} className="bg-zinc-900/50" placeholder="Visionary leader with 20+ years of experience..." />
                </div>

                <div>
                  <label className="block text-xs font-bold uppercase tracking-wider text-zinc-500 mb-2">About Summary (Bio)</label>
                  <textarea 
                    required 
                    className="w-full bg-zinc-900/50 border border-zinc-800 rounded-xl px-4 py-3 text-zinc-200 min-h-[150px] focus:outline-none focus:border-amber-500/50 transition-colors"
                    value={formData.aboutSummary} 
                    onChange={e => setFormData({...formData, aboutSummary: e.target.value})}
                    placeholder="Write a detailed professional summary..."
                  />
                </div>
              </div>
            )}

            {activeTab === "advanced" && (
              <div className="space-y-6 animate-in fade-in slide-in-from-end-4 duration-300">
                <div className="bg-amber-500/10 border border-amber-500/20 rounded-xl p-4 mb-6">
                  <h4 className="text-amber-500 font-bold text-sm mb-1">JSON Array Formatting</h4>
                  <p className="text-xs text-zinc-400">These fields accept strict JSON arrays. Ensure they are valid or the save will fail.</p>
                </div>
                
                <div>
                  <label className="block text-xs font-bold uppercase tracking-wider text-zinc-500 mb-2 flex justify-between">
                    <span>Expertise Tags</span>
                    <span className="text-zinc-600 normal-case font-mono">{"e.g. [\"Events\", \"Logistics\"]"}</span>
                  </label>
                  <Input value={formData.expertiseTags} onChange={e => setFormData({...formData, expertiseTags: e.target.value})} className="bg-zinc-900/50 font-mono text-sm" />
                </div>
                <div>
                  <label className="block text-xs font-bold uppercase tracking-wider text-zinc-500 mb-2 flex justify-between">
                    <span>Experience Timeline</span>
                    <span className="text-zinc-600 normal-case font-mono">{'[{"role": "...", "company": "..."}]'}</span>
                  </label>
                  <textarea className="w-full bg-zinc-900/50 border border-zinc-800 rounded-xl px-4 py-3 text-zinc-200 font-mono text-xs min-h-[120px] focus:outline-none focus:border-amber-500/50 transition-colors" value={formData.experience} onChange={e => setFormData({...formData, experience: e.target.value})} />
                </div>
                <div>
                  <label className="block text-xs font-bold uppercase tracking-wider text-zinc-500 mb-2 flex justify-between">
                    <span>Projects Portfolio</span>
                    <span className="text-zinc-600 normal-case font-mono">{'[{"name": "...", "role": "..."}]'}</span>
                  </label>
                  <textarea className="w-full bg-zinc-900/50 border border-zinc-800 rounded-xl px-4 py-3 text-zinc-200 font-mono text-xs min-h-[120px] focus:outline-none focus:border-amber-500/50 transition-colors" value={formData.projects} onChange={e => setFormData({...formData, projects: e.target.value})} />
                </div>
              </div>
            )}
          </div>

          {/* Footer Actions */}
          <div className="p-4 md:p-6 border-t border-zinc-800/50 bg-zinc-900/30 flex justify-end gap-3 shrink-0">
            <Button type="button" variant="ghost" onClick={onClose} className="hover:bg-zinc-800 text-zinc-400">Cancel</Button>
            <Button type="submit" disabled={loading} className="bg-amber-500 hover:bg-amber-600 text-zinc-950 font-black tracking-wide px-8">
              {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : "Save Profile"}
            </Button>
          </div>
        </form>
      </div>
    </Modal>
  );
}

"use client";

import { useState } from "react";
import { Plus, Search, Edit2, Trash2, Check, X as XIcon, User } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import { EmployeeFormModal } from "./EmployeeFormModal";
import { useRouter } from "next/navigation";

export function TeamManagerClient({ initialEmployees }: { initialEmployees: any[] }) {
  const router = useRouter();
  const [employees, setEmployees] = useState(initialEmployees);
  const [searchTerm, setSearchTerm] = useState("");
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<any | null>(null);

  const filteredEmployees = employees.filter(emp => 
    emp.firstName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.lastName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.designation.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.department.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this team member?")) return;
    try {
      const res = await fetch(`/api/employees/${id}`, { method: 'DELETE' });
      if (res.ok) {
        setEmployees(prev => prev.filter(e => e.id !== id));
        router.refresh();
      }
    } catch (e) {
      console.error(e);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-3xl font-black text-[var(--text-primary)]">Team Management</h1>
          <p className="text-[var(--text-secondary)]">Manage employee profiles and microsites.</p>
        </div>
        <Button onClick={() => { setEditingEmployee(null); setIsModalOpen(true); }} className="gap-2 bg-[var(--color-primary)] hover:bg-[var(--color-primary)]/90 text-white font-bold">
          <Plus className="w-4 h-4" /> Add Team Member
        </Button>
      </div>

      <div className="glass rounded-2xl border-gradient overflow-hidden">
        <div className="p-4 border-b border-[var(--border-level-2)] flex flex-col sm:flex-row gap-4 justify-between items-center bg-[var(--surface-default)]/50">
          <div className="relative w-full sm:w-72">
            <Search className="absolute start-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[var(--text-tertiary)]" />
            <Input 
              placeholder="Search team..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="ps-9 w-full"
            />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="bg-[var(--surface-hover)]/50 text-[var(--text-secondary)] uppercase text-xs font-bold">
              <tr>
                <th className="px-6 py-4">Profile</th>
                <th className="px-6 py-4">Name</th>
                <th className="px-6 py-4">Designation</th>
                <th className="px-6 py-4">Department</th>
                <th className="px-6 py-4 text-center">Active</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredEmployees.length === 0 ? (
                <tr>
                  <td colSpan={6} className="px-6 py-8 text-center text-[var(--text-tertiary)]">
                    No team members found.
                  </td>
                </tr>
              ) : (
                filteredEmployees.map(emp => (
                  <tr key={emp.id} className="border-b border-[var(--border-level-2)] hover:bg-[var(--surface-hover)]/30 transition-colors">
                    <td className="px-6 py-4">
                      <div className="w-10 h-10 rounded-full overflow-hidden bg-[var(--surface-hover)] flex items-center justify-center">
                        {emp.profileImage ? (
                          <img src={emp.profileImage} alt={emp.firstName} className="w-full h-full object-cover" />
                        ) : (
                          <User className="w-5 h-5 text-[var(--text-tertiary)]" />
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4 font-bold text-[var(--text-primary)] whitespace-nowrap">
                      {emp.firstName} {emp.lastName}
                    </td>
                    <td className="px-6 py-4 text-[var(--text-secondary)]">{emp.designation}</td>
                    <td className="px-6 py-4 text-[var(--text-secondary)]">
                      <span className="px-2 py-1 bg-[var(--surface-hover)] rounded-md text-xs font-bold">{emp.department}</span>
                    </td>
                    <td className="px-6 py-4 text-center">
                      {emp.isActive ? <Check className="w-4 h-4 text-emerald-500 mx-auto" /> : <XIcon className="w-4 h-4 text-red-500 mx-auto" />}
                    </td>
                    <td className="px-6 py-4 text-right space-x-2">
                      <Button variant="ghost" className="p-2" onClick={() => { setEditingEmployee(emp); setIsModalOpen(true); }}>
                        <Edit2 className="w-4 h-4 text-blue-400" />
                      </Button>
                      <Button variant="ghost" className="p-2" onClick={() => handleDelete(emp.id)}>
                        <Trash2 className="w-4 h-4 text-red-400" />
                      </Button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      <EmployeeFormModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        employee={editingEmployee}
        onSuccess={() => {
          setIsModalOpen(false);
          router.refresh();
          // To update local state without full reload we could fetch again, or just rely on router.refresh() if page is server component.
          // Since we passed initialEmployees, router.refresh() will fetch new data and pass it as props, updating the state.
          // Wait, router.refresh() doesn't update the local useState immediately, so we could just reload.
          window.location.reload();
        }}
      />
    </div>
  );
}

"use client"

import { useState, useEffect } from 'react'
import { SlideOver } from "./SlideOver"
import { AdminButton } from "./AdminButton"
import { Image as ImageIcon, Video, FileText, UploadCloud, Check, Trash2 } from "lucide-react"

interface Media {
  id: string
  url: string
  type: string
  alt: string
}

interface AdminMediaPickerProps {
  value: string | null
  onChange: (url: string) => void
  label?: string
  accept?: string
}

export function AdminMediaPicker({ value, onChange, label = "Media", accept = "image/*" }: AdminMediaPickerProps) {
  const [isOpen, setIsOpen] = useState(false)
  const [mediaList, setMediaList] = useState<Media[]>([])
  const [loading, setLoading] = useState(false)
  const [uploading, setUploading] = useState(false)

  const fetchMedia = async () => {
    setLoading(true)
    try {
      const res = await fetch("/api/cms/media")
      const json = await res.json()
      if (json.data) {
        setMediaList(json.data)
      }
    } catch (e) {
      console.error(e)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (isOpen) {
      // eslint-disable-next-line react-hooks/set-state-in-effect -- Expected pattern for data synchronization
  fetchMedia()
    }
  }, [isOpen])

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    setUploading(true)
    const formData = new FormData()
    formData.append("file", file)

    try {
      const res = await fetch("/api/cms/media", {
        method: "POST",
        body: formData
      })
      const data = await res.json()
      if (data.url) {
        setMediaList(prev => [data, ...prev])
      }
    } catch (e) {
      console.error(e)
    } finally {
      setUploading(false)
    }
  }

  const handleSelect = (url: string) => {
    onChange(url)
    setIsOpen(false)
  }

  const handleDelete = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation()
    if (!confirm("Are you sure you want to delete this media? This cannot be undone.")) return
    
    try {
      const mediaToDelete = mediaList.find(m => m.id === id)
      setMediaList(prev => prev.filter(m => m.id !== id))
      if (mediaToDelete && mediaToDelete.url === value) {
        onChange("")
      }
      await fetch(`/api/cms/media/${id}`, { method: "DELETE" })
    } catch (err) {
      console.error(err)
      // Refresh on error
      fetchMedia()
    }
  }

  return (
    <div className="flex flex-col gap-2">
      <span className="text-sm font-bold text-[var(--text-primary)]">{label}</span>
      
      {value ? (
        <div className="relative w-full max-w-sm rounded-xl overflow-hidden border border-[var(--border-default)] group bg-[var(--surface-default)] aspect-video flex items-center justify-center">
          {value.match(/\.(mp4|webm|mov)$/i) ? (
            <video src={value} className="w-full h-full object-cover" controls />
          ) : value.match(/\.(pdf|doc)$/i) ? (
            <FileText className="w-10 h-10 text-[var(--text-tertiary)]" />
          ) : (
            <img src={value} alt="Selected Media" className="w-full h-full object-cover" />
          )}
          <div className="absolute inset-0 bg-zinc-950/50 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center gap-2">
            <AdminButton variant="outline" size="sm" onClick={() => setIsOpen(true)}>
              Change Media
            </AdminButton>
            <AdminButton variant="danger" size="sm" onClick={() => onChange("")}>
              Remove
            </AdminButton>
          </div>
        </div>
      ) : (
        <div 
          onClick={() => setIsOpen(true)}
          className="w-full max-w-sm aspect-video border-2 border-dashed border-[var(--border-default)] rounded-xl flex flex-col items-center justify-center gap-2 cursor-pointer hover:border-[var(--color-primary)] hover:bg-[var(--color-primary)]/5 transition-colors group"
        >
          <div className="w-12 h-12 rounded-full bg-[var(--surface-default)] flex items-center justify-center group-hover:bg-[var(--color-primary)]/10">
            <UploadCloud className="w-6 h-6 text-[var(--text-tertiary)] group-hover:text-[var(--color-primary)] transition-colors" />
          </div>
          <span className="text-sm font-bold text-[var(--text-secondary)]">Click to browse media</span>
        </div>
      )}

      <SlideOver isOpen={isOpen} onClose={() => setIsOpen(false)} title="Media Library">
        <div className="flex flex-col gap-6">
          <div className="flex items-center justify-between">
            <p className="text-sm text-[var(--text-secondary)]">Select a file from your library or upload a new one.</p>
            <div className="relative">
              <input 
                type="file" 
                id="media-upload" 
                className="hidden" 
                onChange={handleUpload}
                accept={accept}
                disabled={uploading}
              />
              <AdminButton 
                variant="primary" 
                onClick={() => document.getElementById("media-upload")?.click()}
                disabled={uploading}
              >
                {uploading ? "Uploading..." : "Upload New File"}
              </AdminButton>
            </div>
          </div>

          {loading ? (
            <div className="h-40 flex items-center justify-center text-[var(--text-tertiary)] text-sm font-bold">
              Loading library...
            </div>
          ) : (
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
              {mediaList.map((media) => (
                <div 
                  key={media.id}
                  onClick={() => handleSelect(media.url)}
                  className={`group relative aspect-square rounded-xl overflow-hidden border-2 cursor-pointer transition-all ${value === media.url ? 'border-[var(--color-primary)]' : 'border-transparent hover:border-[var(--border-strong)]'}`}
                >
                  <div className="w-full h-full bg-[var(--surface-default)] flex items-center justify-center p-2">
                    {media.type === 'VIDEO' ? (
                      <div className="relative w-full h-full flex flex-col items-center justify-center">
                        <Video className="w-8 h-8 text-[var(--text-tertiary)] mb-2" />
                        <span className="text-xs font-mono text-[var(--text-tertiary)] truncate w-full text-center">{media.url.split('/').pop()}</span>
                      </div>
                    ) : media.type === 'DOCUMENT' ? (
                      <div className="relative w-full h-full flex flex-col items-center justify-center">
                        <FileText className="w-8 h-8 text-[var(--text-tertiary)] mb-2" />
                        <span className="text-xs font-mono text-[var(--text-tertiary)] truncate w-full text-center">{media.url.split('/').pop()}</span>
                      </div>
                    ) : (
                      <img src={media.url} alt={media.alt || 'Media'} className="w-full h-full object-contain" />
                    )}
                  </div>
                  {value === media.url && (
                    <div className="absolute top-2 end-2 w-6 h-6 bg-[var(--color-primary)] text-white rounded-full flex items-center justify-center shadow-md">
                      <Check className="w-4 h-4" />
                    </div>
                  )}
                  <button
                    onClick={(e) => handleDelete(e, media.id)}
                    className="absolute top-2 start-2 w-7 h-7 bg-red-500/90 hover:bg-red-600 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity shadow-md"
                    title="Delete Media"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              ))}
              
              {mediaList.length === 0 && (
                <div className="col-span-full py-12 flex flex-col items-center justify-center text-[var(--text-tertiary)] border border-dashed border-[var(--border-default)] rounded-xl">
                  <ImageIcon className="w-8 h-8 mb-2 opacity-50" />
                  <span className="text-sm font-bold">No media found</span>
                </div>
              )}
            </div>
          )}
        </div>
      </SlideOver>
    </div>
  )
}

import React from "react"

interface AdminSeoCustomizerProps {
  formData: any;
  setFormData: (data: any) => void;
  // If the editor has a separate seo object (like ServicesEditor)
  seo?: any;
  setSeo?: (seo: any) => void;
}

export function AdminSeoCustomizer({ formData, setFormData, seo, setSeo }: AdminSeoCustomizerProps) {
  // If the component passes a dedicated `seo` state, use it.
  // Otherwise, fallback to formData.seo (if it exists) or formData directly.
  const seoData = seo || formData?.seo || formData;

  const handleChange = (field: string, value: string) => {
    if (setSeo) {
      setSeo({ ...seoData, [field]: value });
    } else {
      setFormData({
        ...formData,
        seo: { ...seoData, [field]: value }
      });
    }
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col">
        <h2 className="text-lg font-black text-[var(--text-primary)]">SEO Settings</h2>
        <p className="text-sm text-[var(--text-secondary)]">Customize search engine metadata for this page.</p>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="space-y-4 border p-4 rounded-xl border-border-default bg-surface-default">
          <div className="flex items-center justify-between border-b border-border-default pb-2">
            <h4 className="font-bold text-emerald-500">English (EN)</h4>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-text-secondary">Meta Title</label>
            <input 
              type="text" 
              value={seoData?.metaTitleEn || ""} 
              onChange={e => handleChange("metaTitleEn", e.target.value)} 
              className="w-full bg-surface-hover border border-border-default rounded-xl px-4 py-2 text-sm focus:border-accent focus:outline-none" 
              placeholder="e.g. Services | E3" 
            />
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-text-secondary">Meta Description</label>
            <textarea 
              value={seoData?.metaDescriptionEn || ""} 
              onChange={e => handleChange("metaDescriptionEn", e.target.value)} 
              rows={3} 
              className="w-full bg-surface-hover border border-border-default rounded-xl px-4 py-2 text-sm focus:border-accent focus:outline-none resize-none" 
              placeholder="Brief description for search engines..." 
            />
          </div>
        </div>

        <div className="space-y-4 border p-4 rounded-xl border-border-default bg-surface-default">
          <div className="flex items-center justify-between border-b border-border-default pb-2">
            <h4 className="font-bold text-emerald-500 font-arabic" dir="rtl">العربية (AR)</h4>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-text-secondary text-right block font-arabic" dir="rtl">عنوان الميتا</label>
            <input 
              type="text" 
              dir="rtl" 
              value={seoData?.metaTitleAr || ""} 
              onChange={e => handleChange("metaTitleAr", e.target.value)} 
              className="w-full bg-surface-hover border border-border-default rounded-xl px-4 py-2 text-sm focus:border-accent focus:outline-none font-arabic" 
              placeholder="مثال: الخدمات | إي ثري" 
            />
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-text-secondary text-right block font-arabic" dir="rtl">وصف الميتا</label>
            <textarea 
              dir="rtl" 
              value={seoData?.metaDescriptionAr || ""} 
              onChange={e => handleChange("metaDescriptionAr", e.target.value)} 
              rows={3} 
              className="w-full bg-surface-hover border border-border-default rounded-xl px-4 py-2 text-sm focus:border-accent focus:outline-none resize-none font-arabic" 
              placeholder="وصف موجز لمحركات البحث..." 
            />
          </div>
        </div>
      </div>
    </div>
  )
