          const isBaseActive = pathname === item.href || pathname.startsWith(`${item.href}/`);
          const isSubItemActive = item.subItems ? item.subItems.some(sub => pathname === sub.href || pathname.startsWith(`${sub.href}/`)) : false;
          const isActive = isBaseActive || isSubItemActive;
          return (
            <div key={item.href} className="flex flex-col relative z-10">
              <MotionLink
                href={item.href}
                whileHover={!isActive ? { x: 4 } : {}}
                className={cn(
                  "relative flex items-center gap-3 px-3 py-3 rounded-xl transition-all group overflow-hidden",
                  isActive 
                    ? "glass bg-[var(--surface-selected)] border-[var(--color-primary)]/20 shadow-[0_0_15px_rgba(0,0,0,0.05)] text-[var(--color-primary)]" 
                    : "text-[var(--text-secondary)] hover:bg-[var(--surface-hover)] hover:text-[var(--text-primary)] border border-transparent",
                  collapsed && !mobileOpen ? "justify-center px-0" : ""
                )}
                title={collapsed && !mobileOpen ? item.label : undefined}
              >
                {isActive && (
                  <motion.div
                    layoutId="active-sidebar-tab"
                    className="absolute start-0 top-2 bottom-2 w-1.5 bg-[var(--color-primary)] rounded-e-md glow"
                  />
                )}
                
                <item.icon size={20} className={cn("shrink-0 relative z-10", isActive ? "text-[var(--color-primary)]" : "")} />
                
                {(!collapsed || mobileOpen) && (
                  <span className={cn(
                    "whitespace-nowrap flex-1 relative z-10 transition-all",
                    isActive ? "font-bold" : "font-medium"
                  )}>{item.label}</span>
                )}

                {(!collapsed || mobileOpen) && item.badge && (
                  <span className="relative z-10 flex items-center justify-center px-2 h-5 rounded-full bg-[var(--color-primary)] text-white text-[10px] font-black shadow-md">
                    {item.badge}
                  </span>
                )}
                
                {collapsed && !mobileOpen && item.badge && (
                  <span className="absolute top-2 end-2 w-2.5 h-2.5 border-2 border-[var(--bg-level-1)] rounded-full bg-[var(--color-primary)] shadow-sm" />
                )}
              </MotionLink>
              
              <AnimatePresence>
                {isActive && (!collapsed || mobileOpen) && (item as any).subItems && (
                  <motion.div 
                    initial={{ opacity: 0, height: 0 }}
                    animate={{ opacity: 1, height: "auto" }}
                    exit={{ opacity: 0, height: 0 }}
                    className="flex flex-col gap-1 mt-2 ps-9 pe-2 overflow-hidden"
                  >
                    {(item as any).subItems.map((sub: any) => {
                      const isSubActive = pathname === sub.href;
                      return (
                        <MotionLink
                          key={sub.href}
                          href={sub.href}
                          whileHover={!isSubActive ? { x: 2 } : {}}
                          className={cn(
                            "text-sm py-2 px-3 rounded-lg transition-colors relative flex items-center",
                            isSubActive 
                              ? "bg-[var(--surface-active)] text-[var(--color-primary)] font-bold shadow-inner" 
                              : "text-[var(--text-tertiary)] hover:bg-[var(--surface-hover)] hover:text-[var(--text-primary)] font-medium"
                          )}
                        >
                          {isSubActive && <span className="absolute start-0 top-2.5 bottom-2.5 w-1 bg-[var(--color-primary)]/60 rounded-e-md" />}
                          {sub.label}
                        </MotionLink>
                      )
                    })}
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          );
        })}
      </div>

      <div className="p-4 border-t border-[var(--border-level-2)] flex flex-col gap-4 z-10 relative bg-[var(--bg-level-1)]">
        {(!collapsed || mobileOpen) && (
          <div className="flex items-center gap-3 glass bg-[var(--surface-active)] p-3 rounded-2xl border-gradient">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-[var(--color-accent)] to-[var(--color-primary)] text-white flex items-center justify-center shrink-0 shadow-md font-bold">
              {userInitials}
            </div>
            <div className="flex flex-col flex-1 min-w-0">
              <span className="text-sm font-black text-[var(--text-primary)] truncate tracking-tight">{userName}</span>
              <span className="text-xs text-[var(--text-tertiary)] truncate font-medium">{userRole.replace('_', ' ')}</span>
            </div>
          </div>
        )}
        
        {collapsed && !mobileOpen && (
          <div className="w-full flex justify-center">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-[var(--color-accent)] to-[var(--color-primary)] text-white flex items-center justify-center shadow-md font-bold" title={userName}>
              {userInitials}
            </div>
          </div>
        )}
        
        <MotionLink 
          href="#"
          onClick={(e) => { e.preventDefault(); signOut({ callbackUrl: "/auth/login" }) }}
          whileHover={{ scale: 1.02 }}
          whileTap={{ scale: 0.98 }}
          className={cn(
            "flex items-center gap-3 px-3 py-2.5 text-sm font-bold text-[var(--color-error)] hover:bg-[#EF444415] rounded-xl transition-colors border border-transparent hover:border-[var(--color-error)]/20",
            collapsed && !mobileOpen ? "justify-center px-0" : ""
          )} 
          title={collapsed && !mobileOpen ? "Logout" : undefined}
        >
          <LogOut size={18} />
          {(!collapsed || mobileOpen) && <span>Logout</span>}
        </MotionLink>
      </div>
    </>
  );

  if (!isClient) return null;

  return (
    <>
      {/* Mobile Top Bar */}
      <div className="md:hidden fixed top-0 start-0 end-0 h-16 glass z-30 flex items-center justify-between px-4 border-b border-[var(--border-level-2)]">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-[var(--gradient-start)] to-[var(--gradient-end)] flex items-center justify-center glow">
            <span className="text-white font-black text-sm tracking-tighter">E3</span>
          </div>
          <span className="font-black text-[var(--text-primary)] tracking-tight">Admin</span>
        </div>
        <div className="flex items-center gap-2">
          <button className="p-2 text-[var(--text-secondary)] hover:bg-[var(--surface-hover)] hover:text-[var(--text-primary)] rounded-full transition-colors relative">
            <Bell size={20} />
            <span className="absolute top-2 end-2.5 w-2 h-2 rounded-full bg-[var(--color-primary)] animate-pulse-glow" />
          </button>
          <button 
            onClick={() => setMobileOpen(true)}
            className="p-2 text-[var(--text-primary)] hover:bg-[var(--surface-hover)] rounded-full transition-colors"
          >
            <Menu size={24} />
          </button>
        </div>
      </div>

      {/* Desktop Sidebar */}
      <motion.aside
        animate={{ width: collapsed ? 80 : 280 }}
        transition={{ type: "spring", stiffness: 300, damping: 30 }}
        className="hidden md:flex flex-col fixed start-0 top-0 bottom-0 bg-[var(--bg-level-1)] noise-bg border-e border-[var(--border-level-2)] z-40 overflow-hidden shadow-[2px_0_20px_rgba(0,0,0,0.02)]"
      >
        {sidebarContent}
      </motion.aside>

      {/* Mobile Drawer */}
      <AnimatePresence>
        {mobileOpen && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setMobileOpen(false)}
              className="fixed inset-0 bg-zinc-950/60 backdrop-blur-md z-40 md:hidden"
            />
            <motion.aside
              initial={{ x: "-100%" }}
              animate={{ x: 0 }}
              exit={{ x: "-100%" }}
              transition={{ type: "spring", stiffness: 300, damping: 30 }}
              className="fixed start-0 top-0 bottom-0 w-[280px] bg-[var(--bg-level-1)] noise-bg z-50 flex flex-col md:hidden shadow-2xl border-e border-[var(--border-level-2)]"
            >
              {sidebarContent}
            </motion.aside>
          </>
        )}
      </AnimatePresence>
      
      {/* Spacer for desktop layout */}
      <div className={cn("hidden md:block shrink-0 transition-all duration-300", collapsed ? "w-[80px]" : "w-[280px]")} />
    </>
  );
}

"use client";

import * as React from "react";

type Theme = "light" | "dark" | "system";

interface ThemeProviderProps {
  children: React.ReactNode;
  defaultTheme?: Theme;
  enableSystem?: boolean;
}

type ThemeProviderState = {
  theme: Theme;
  setTheme: (theme: Theme) => void;
};

const initialState: ThemeProviderState = {
  theme: "system",
  setTheme: () => null,
};

const ThemeProviderContext = React.createContext<ThemeProviderState>(initialState);

export function ThemeProvider({
  children,
  defaultTheme = "system",
  enableSystem = true,
}: ThemeProviderProps) {
  const theme = React.useSyncExternalStore(
    (callback) => {
      window.addEventListener('storage', callback);
      return () => window.removeEventListener('storage', callback);
    },
    () => (typeof window !== "undefined" ? window.localStorage.getItem("theme") as Theme | null : null) || defaultTheme,
    () => defaultTheme
  );

  const setThemeState = React.useCallback((newTheme: Theme) => {
    window.localStorage.setItem("theme", newTheme);
    window.dispatchEvent(new Event('storage'));
  }, []);

  const setTheme = setThemeState;

  React.useEffect(() => {
    const root = window.document.documentElement;

    // Remove previous theme class/data-attribute
    root.removeAttribute("data-theme");

    if (theme === "system" && enableSystem) {
      const systemTheme = window.matchMedia("(prefers-color-scheme: dark)").matches
        ? "dark"
        : "light";

      // We don't set data-theme for system if it falls back to prefers-color-scheme 
      // based on our globals.css design, but explicitly setting it helps with JS logic.
      root.setAttribute("data-theme", systemTheme);
      return;
    }

    root.setAttribute("data-theme", theme);
  }, [theme, enableSystem]);

  const value = React.useMemo(
    () => ({
      theme,
      setTheme: (theme: Theme) => {
        localStorage.setItem("theme", theme);
        setTheme(theme);
      },
    }),
    [theme]
  );

  return (
    <ThemeProviderContext.Provider value={value}>

      {children}
    </ThemeProviderContext.Provider>
  );
}

export const useTheme = () => {
  const context = React.useContext(ThemeProviderContext);
  if (context === undefined)
    throw new Error("useTheme must be used within a ThemeProvider");
  return context;
};

"use client"

import React, { useState, useEffect, useRef, Suspense } from 'react'
import { Canvas } from '@react-three/fiber'
import { useGLTF, OrbitControls, Html, useProgress, ContactShadows, Grid } from '@react-three/drei'
import * as THREE from 'three'
import { XR, createXRStore, useXRHitTest } from '@react-three/xr'
import { Camera, RefreshCcw, X, Info } from 'lucide-react'

// Create XR store outside the component
const store = createXRStore()

// ----------------------------------------------------------------------
// TYPES & PROPS
// ----------------------------------------------------------------------
interface ARViewerProps {
  modelUrl: string
  modelName: string
  dimensions?: { w: number, h: number, d: number }
  powerReq?: string
  onClose?: () => void
}

// ----------------------------------------------------------------------
// MODEL LOADER COMPONENT
// ----------------------------------------------------------------------
function _Loader() {
  const { progress } = useProgress()
  return (
    <Html center>
      <div className="flex flex-col items-center justify-center p-4 bg-zinc-950/80 backdrop-blur rounded-xl border border-white/10 w-48">
        <div className="text-white font-bold text-sm mb-2">Loading Model</div>
        <div className="w-full bg-white/20 rounded-full h-1.5 overflow-hidden">
          <div className="bg-[var(--color-primary)] h-full transition-all" style={{ width: `${progress}%` }} />
        </div>
        <div className="text-white/50 text-xs mt-2">{Math.round(progress)}%</div>
      </div>
    </Html>
  )
}

class ModelErrorBoundary extends React.Component<{ children: React.ReactNode }, { hasError: boolean }> {
  constructor(props: { children: React.ReactNode }) {
    super(props)
    this.state = { hasError: false }
  }
  static getDerivedStateFromError(_error: any) {
    return { hasError: true }
  }
  componentDidCatch(_error: any, _errorInfo: any) {
    console.error("Model load failed:", error)
  }
  render() {
    if (this.state.hasError) {
      return (
        <mesh>
          <boxGeometry args={[1, 1, 1]} />
          <meshStandardMaterial color="#3f3f46" wireframe />
          <Html center>
            <div className="text-xs text-white/50 bg-black/50 px-2 py-1 rounded backdrop-blur">Model Unavailable</div>
          </Html>
        </mesh>
      )
    }
    return this.props.children
  }
}

function Model({ url, position, rotation, scale }: { url: string, position: THREE.Vector3, rotation: THREE.Euler, scale: number }) {
  const { scene } = useGLTF(url)
  return <primitive object={scene.clone()} position={position} rotation={rotation} scale={scale} />
}

// ----------------------------------------------------------------------
// AR HIT TESTER COMPONENT
// ----------------------------------------------------------------------
function HitTestReticle({ onPlace }: { onPlace: (pos: THREE.Vector3) => void }) {
  const reticleRef = useRef<THREE.Mesh>(null)
  
  // @ts-expect-error - Ignoring type error due to v6 signature changes
  useXRHitTest((hitMatrix: THREE.Matrix4) => {
    if (reticleRef.current) {
      hitMatrix.decompose(
        reticleRef.current.position,
        reticleRef.current.quaternion,
        reticleRef.current.scale
      )
    }
  })

  // Hook into pointer down (tap) on the canvas to place the model at the reticle
  useEffect(() => {
    const handlePointerDown = () => {
      if (reticleRef.current && reticleRef.current.visible) {
        onPlace(reticleRef.current.position.clone())
      }
    }
    // We bind to document because useHitTest operates on XR session
    document.addEventListener('pointerdown', handlePointerDown)
    return () => document.removeEventListener('pointerdown', handlePointerDown)
  }, [onPlace])

  return (
    <mesh ref={reticleRef} rotation={[-Math.PI / 2, 0, 0]}>
      <ringGeometry args={[0.1, 0.15, 32]} />
      <meshBasicMaterial color="#00e676" opacity={0.8} transparent />
    </mesh>
  )
}

// ----------------------------------------------------------------------
// MAIN VIEWER COMPONENT
// ----------------------------------------------------------------------
export default function ARViewer({ modelUrl, modelName, dimensions, powerReq, onClose }: ARViewerProps) {
  const [xrSupported, setXrSupported] = useState(false)
  const [inAR, setInAR] = useState(false)
  const [modelPlaced, setModelPlaced] = useState(false)
  const [modelPosition, setModelPosition] = useState(new THREE.Vector3(0, 0, 0))
  const [showTooltip, setShowTooltip] = useState(true)
  const canvasRef = useRef<HTMLCanvasElement>(null)

  useEffect(() => {
    if ('xr' in navigator) {
      navigator.xr?.isSessionSupported('immersive-ar').then((supported) => {
        setXrSupported(supported)
      })
    }
    
    // Hide tooltip after 5 seconds
    const t = setTimeout(() => setShowTooltip(false), 5000)
    return () => clearTimeout(t)
  }, [])

  const handlePlace = (pos: THREE.Vector3) => {
    setModelPosition(pos)
    setModelPlaced(true)
  }

  const handleReset = () => {
    setModelPlaced(false)
  }

  const takeScreenshot = () => {
    if (canvasRef.current) {
      const link = document.createElement('a')
      link.download = `E3_${modelName.replace(/\s+/g, '_')}_AR.png`
      link.href = canvasRef.current.toDataURL('image/png')
      link.click()
    }
  }

  return (
    <div className="relative w-full h-[60vh] bg-zinc-950/90 rounded-2xl overflow-hidden border border-white/10 font-sans flex flex-col">
      
      {/* HEADER */}
      <div className="absolute top-0 start-0 end-0 p-4 flex justify-between items-start z-10 pointer-events-none">
        <div className="bg-zinc-950/80 backdrop-blur border border-white/10 rounded-xl p-3 pointer-events-auto">
          <h3 className="text-white font-black text-sm">{modelName}</h3>
          {dimensions && (
            <p className="text-white/70 text-xs mt-1">
              W: {dimensions.w}m × H: {dimensions.h}m × D: {dimensions.d}m
            </p>
          )}
          {powerReq && (
            <p className="text-yellow-500 font-bold text-[10px] mt-1">POWER: {powerReq}</p>
          )}
        </div>
        
        {onClose && (
          <button onClick={onClose} className="p-2 bg-zinc-950/80 border border-white/10 rounded-full text-white/70 hover:text-white pointer-events-auto">
            <X className="w-5 h-5" />
          </button>
        )}
      </div>

      {/* CANVAS */}
      <div className="flex-1 relative">
        <Suspense fallback={
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="w-8 h-8 rounded-full border-2 border-white/20 border-t-[var(--color-primary)] animate-spin" />
          </div>
        }>
          <Canvas ref={canvasRef} gl={{ preserveDrawingBuffer: true }}>
            <ambientLight intensity={0.5} />
            <directionalLight position={[10, 10, 5]} intensity={1} castShadow />
            
            {xrSupported ? (
              <XR store={store}>
                {inAR && !modelPlaced && <HitTestReticle onPlace={handlePlace} />}
                {(!inAR || modelPlaced) && (
                  <ModelErrorBoundary>
                    <Model 
                      url={modelUrl} 
                      position={inAR ? modelPosition : new THREE.Vector3(0, 0, 0)} 
                      rotation={new THREE.Euler(0, 0, 0)} 
                      scale={1} 
                    />
                  </ModelErrorBoundary>
                )}
                {!inAR && (
                  <>
                    <OrbitControls makeDefault minDistance={2} maxDistance={20} />
                    <Grid position={[0, -0.01, 0]} args={[10, 10]} cellColor="#333" sectionColor="#666" />
                    <ContactShadows position={[0, -0.01, 0]} opacity={0.4} scale={10} blur={2} far={4} />
                  </>
                )}
              </XR>
            ) : (
              // Fallback 3D Preview (No XR)
              <>
                <ModelErrorBoundary>
                  <Model url={modelUrl} position={new THREE.Vector3(0, 0, 0)} rotation={new THREE.Euler(0, 0, 0)} scale={1} />
                </ModelErrorBoundary>
                <OrbitControls makeDefault autoRotate autoRotateSpeed={1} minDistance={2} maxDistance={20} />
                <Grid position={[0, -0.01, 0]} args={[10, 10]} cellColor="#333" sectionColor="#666" />
                <ContactShadows position={[0, -0.01, 0]} opacity={0.4} scale={10} blur={2} far={4} />
              </>
            )}
          </Canvas>
        </Suspense>
      </div>

      {/* FOOTER CONTROLS */}
      <div className="absolute bottom-4 start-4 end-4 flex justify-between items-end z-10 pointer-events-none">
        
        <div className="flex gap-2 pointer-events-auto">
          {inAR && modelPlaced && (
            <button onClick={handleReset} className="p-3 bg-zinc-950/80 backdrop-blur border border-white/10 rounded-full text-white hover:bg-white/10 transition-colors tooltip-trigger relative group">
              <RefreshCcw className="w-5 h-5" />
              <span className="absolute -top-8 start-1/2 -translate-x-1/2 bg-zinc-950 text-xs px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity">Reset</span>
            </button>
          )}
          
          <button onClick={takeScreenshot} className="p-3 bg-zinc-950/80 backdrop-blur border border-white/10 rounded-full text-white hover:bg-white/10 transition-colors tooltip-trigger relative group">
            <Camera className="w-5 h-5" />
            <span className="absolute -top-8 start-1/2 -translate-x-1/2 bg-zinc-950 text-xs px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity">Snapshot</span>
          </button>
        </div>

        <div className="pointer-events-auto flex flex-col items-end">
          {showTooltip && xrSupported && !inAR && (
            <div className="bg-[var(--color-primary)] text-zinc-950 text-xs font-bold px-3 py-2 rounded-lg mb-2 shadow-lg animate-bounce flex items-center">
              <Info className="w-4 h-4 me-1" /> Tap to view in your space
            </div>
          )}
          
          {xrSupported ? (
            <div className="xr-button-container">
              <button 
                onClick={() => {
                  setInAR(true)
                  store.enterAR()
                }}
                className="flex items-center gap-2 px-6 py-3 bg-white text-zinc-950 font-black text-sm rounded-xl hover:bg-gray-200 transition-colors shadow-xl"
              >
                Enter AR
              </button>
            </div>
          ) : (
            <div className="px-4 py-2 bg-white/10 backdrop-blur border border-white/10 text-white/50 font-bold text-xs rounded-lg">
              AR Not Supported on this Device
            </div>
          )}
        </div>

      </div>
    </div>
  )
}

"use client"

import React, { useState, useRef } from "react"
import { UploadCloud, X, File as FileIcon, Loader2, Box } from "lucide-react"

import { uploadFile } from "@/lib/upload"

interface MediaUploaderProps {
  value?: string | null
  onChange: (url: string) => void
  onRemove?: () => void
  accept?: string
  className?: string
  context?: string
}

export function MediaUploader({ value, onChange, onRemove, accept = "image/*,.svg,image/svg+xml", className = "", context }: MediaUploaderProps) {
  const [isDragging, setIsDragging] = useState(false)
  const [isUploading, setIsUploading] = useState(false)
  const [progress, setProgress] = useState(0)
  const [error, setError] = useState<string | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleUpload = async (file: File) => {
    setError(null)
    setIsUploading(true)
    setProgress(0)

    try {
      const progressInterval = setInterval(() => {
        setProgress(p => Math.min(p + 10, 90))
      }, 100)

      const result = await uploadFile(file, context)

      clearInterval(progressInterval)
      setProgress(100)

      onChange(result.url)
    } catch (err: any) {
      setError(err.message || "Something went wrong")
    } finally {
      setIsUploading(false)
      setTimeout(() => setProgress(0), 1000)
    }
  }

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragging(true)
  }

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragging(false)
  }

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragging(false)
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      handleUpload(e.dataTransfer.files[0])
    }
  }

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      handleUpload(e.target.files[0])
    }
  }

  if (value) {
    return (
      <div className={`relative rounded-xl border border-[var(--border-default)] overflow-hidden group ${className}`}>
        {value.match(/\.(mp4|webm)$/i) ? (
          <video src={value} className="w-full h-48 object-cover" controls />
        ) : value.match(/\.(glb|gltf)$/i) ? (
          <div className="w-full h-48 bg-[var(--surface-hover)] flex flex-col items-center justify-center text-[var(--text-secondary)]">
            <Box className="w-12 h-12 mb-2 text-[var(--color-primary)] opacity-50" />
            <span className="text-sm font-bold">3D Model Uploaded</span>
            <span className="text-xs max-w-[80%] truncate mt-1">{value.split('/').pop()}</span>
          </div>
        ) : value.match(/\.(pdf)$/i) ? (
          <div className="w-full h-48 bg-[var(--surface-hover)] flex flex-col items-center justify-center text-[var(--text-secondary)]">
            <FileIcon className="w-12 h-12 mb-2 text-red-500" />
            <span className="text-sm font-bold text-white">PDF Document</span>
            <span className="text-xs max-w-[80%] truncate mt-1 text-zinc-400">{value.split('/').pop()}</span>
          </div>
        ) : value.match(/\.(doc|docx)$/i) ? (
          <div className="w-full h-48 bg-[var(--surface-hover)] flex flex-col items-center justify-center text-[var(--text-secondary)]">
            <FileIcon className="w-12 h-12 mb-2 text-blue-500" />
            <span className="text-sm font-bold text-white">Word Document</span>
            <span className="text-xs max-w-[80%] truncate mt-1 text-zinc-400">{value.split('/').pop()}</span>
          </div>
        ) : (
          <div className="w-full h-48 bg-zinc-950/80 p-4 flex items-center justify-center">
            <img src={value} alt="Uploaded Media" className="max-w-full max-h-full object-contain" />
          </div>
        )}
        
        <div className="absolute inset-0 bg-zinc-950/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2">
          <button 
            type="button"
            onClick={() => fileInputRef.current?.click()}
            className="p-2 bg-white/20 hover:bg-white/40 rounded-full text-white backdrop-blur-md transition-colors"
          >
            <UploadCloud size={20} />
          </button>
          
          <button 
            type="button"
            onClick={() => {
              if (onRemove) onRemove()
              else onChange("")
            }}
            className="p-2 bg-red-500/80 hover:bg-red-500 rounded-full text-white backdrop-blur-md transition-colors"
          >
            <X size={20} />
          </button>
        </div>
        <input 
          type="file" 
          ref={fileInputRef} 
          onChange={handleChange} 
          accept={accept} 
          className="hidden" 
        />
      </div>
    )
  }

  return (
    <div 
      className={`relative rounded-xl border-2 border-dashed transition-all p-8 flex flex-col items-center justify-center text-center cursor-pointer min-h-[12rem]
        ${isDragging ? "border-[var(--color-primary)] bg-[var(--color-primary)]/5" : "border-[var(--border-default)] hover:border-[var(--color-primary)]/50 hover:bg-[var(--surface-hover)]"}
        ${className}
      `}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      onClick={() => !isUploading && fileInputRef.current?.click()}
    >
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleChange} 
        accept={accept} 
        className="hidden" 
        disabled={isUploading}
      />

      {isUploading ? (
        <div className="flex flex-col items-center w-full max-w-xs">
          <Loader2 className="w-8 h-8 text-[var(--color-primary)] animate-spin mb-4" />
          <div className="w-full h-2 bg-[var(--surface-active)] rounded-full overflow-hidden">
            <div 
              className="h-full bg-[var(--color-primary)] transition-all duration-300"
              style={{ width: `${progress}%` }}
            />
          </div>
          <span className="text-xs font-bold text-[var(--text-secondary)] mt-2">Uploading {progress}%</span>
        </div>
      ) : (
        <>
          <div className="w-12 h-12 rounded-full bg-[var(--surface-active)] flex items-center justify-center mb-4 text-[var(--text-secondary)]">
            <UploadCloud size={24} />
          </div>
          <h4 className="font-bold text-[var(--text-primary)] mb-1">Click to upload or drag and drop</h4>
          <p className="text-xs text-[var(--text-secondary)] mb-4">
            {accept === "image/*" ? "SVG, PNG, JPG, GIF or MP4" : accept.replace(/,/g, ", ").toUpperCase()} (max. 50MB)
          </p>
          
          {error && (
            <div className="text-xs font-bold text-[var(--color-error)] bg-[var(--color-error)]/10 px-3 py-1.5 rounded-full">
              {error}
            </div>
          )}
        </>
      )}
    </div>
  )
}

import React from 'react';

type SchemaType = 
  | 'Organization' 
  | 'WebSite' 
  | 'LocalBusiness' 
  | 'Service' 
  | 'Event' 
  | 'FAQPage' 
  | 'Person' 
  | 'BreadcrumbList';

interface SEOProps {
  type: SchemaType;
  data: Record<string, any>;
}

export function SEO({ type, data }: SEOProps) {
  const schema = {
    '@context': 'https://schema.org',
    '@type': type,
    ...data,
  };

  return (
    <script
      type="application/ld+json"
      dangerouslySetInnerHTML={{ __html: JSON.stringify(schema) }}
    />
  );
}

"use client"

import React, { useState, useEffect, useRef, useMemo, Suspense } from 'react'
import { Canvas, useFrame, useThree } from '@react-three/fiber'
import { OrbitControls, Html } from '@react-three/drei'
import * as THREE from 'three'

// ----------------------------------------------------------------------
// TYPES & DATA
// ----------------------------------------------------------------------
export type AttractionMarker = {
  id: string
  name: string
  slug: string
  tagline: string
  lat: number
  lng: number
  status: 'ACTIVE' | 'UPCOMING' | 'COMING_SOON'
  capacityLevel: number // 1 to 5
}

interface SpatialHubProps {
  attractions: AttractionMarker[]
  onAttractionClick?: (slug: string) => void
}

// Center of Qatar (approx Doha)
const CENTER_LAT = 25.3
const CENTER_LNG = 51.5
const MAP_SCALE = 15

// Simplified Qatar coastline for a flat geometric mesh
const QATAR_COASTLINE = [
  [26.15, 51.25], // North
  [25.9, 51.55],
  [25.6, 51.6],
  [25.3, 51.6],   // Doha
  [24.9, 51.65],  // Mesaieed
  [24.6, 51.4],   // South East
  [24.6, 50.8],   // South West
  [25.1, 50.75],
  [25.4, 50.8],   // Dukhan
  [25.8, 51.0],
]

// Convert lat/lng to local 3D coordinates (x, z)
const getCoords = (lat: number, lng: number) => {
  const x = (lng - CENTER_LNG) * MAP_SCALE
  const z = -(lat - CENTER_LAT) * MAP_SCALE
  return new THREE.Vector3(x, 0, z)
}

// ----------------------------------------------------------------------
// 3D COMPONENTS
// ----------------------------------------------------------------------
function GroundMap() {
  const shape = useMemo(() => {
    const s = new THREE.Shape()
    QATAR_COASTLINE.forEach((point, i) => {
      const pos = getCoords(point[0], point[1])
      if (i === 0) s.moveTo(pos.x, pos.z)
      else s.lineTo(pos.x, pos.z)
    })
    s.closePath()
    return s
  }, [])

  return (
    <group rotation={[-Math.PI / 2, 0, 0]}>
      {/* Base Map */}
      <mesh>
        <shapeGeometry args={[shape]} />
        <meshStandardMaterial color="#050505" emissive="#09090b" />
      </mesh>
      {/* Edge highlight */}
      <lineSegments>
        <edgesGeometry args={[new THREE.ShapeGeometry(shape)]} />
        <lineBasicMaterial color="#333333" linewidth={2} />
      </lineSegments>
      {/* Tron Grid */}
      <gridHelper args={[50, 50, '#111111', '#0a0a0a']} rotation={[Math.PI / 2, 0, 0]} position={[0, 0, -0.01]} />
    </group>
  )
}

function Markers({ attractions, onMarkerClick, hoveredId, setHoveredId }: any) {
  const meshRef = useRef<THREE.InstancedMesh>(null)
  const dummy = useMemo(() => new THREE.Object3D(), [])
  
  // Base geometry for markers (Hexagonal pillar)
  const geometry = useMemo(() => new THREE.CylinderGeometry(0.1, 0.1, 1, 6), [])
  const material = useMemo(() => new THREE.MeshStandardMaterial({ 
    color: '#ffffff',
    emissive: '#00e676',
    emissiveIntensity: 1,
    transparent: true,
    opacity: 0.9
  }), [])

  const getColor = (status: string) => {
    switch (status) {
      case 'ACTIVE': return new THREE.Color('#00e676') // Green
      case 'UPCOMING': return new THREE.Color('#ffc107') // Yellow
      case 'COMING_SOON': return new THREE.Color('#2196f3') // Blue
      default: return new THREE.Color('#666666')
    }
  }

  useFrame((state) => {
    if (!meshRef.current) return
    const time = state.clock.getElapsedTime()
    
    attractions.forEach((attr: AttractionMarker, i: number) => {
      const pos = getCoords(attr.lat, attr.lng)
      const height = attr.capacityLevel * 0.4
      
      // Pulsing effect for active
      const pulse = attr.status === 'ACTIVE' ? Math.sin(time * 3 + i) * 0.1 + 1 : 1
      const scaleY = height * pulse
      
      dummy.position.set(pos.x, scaleY / 2, pos.z)
      
      // If hovered, make it slightly thicker
      const scaleXZ = hoveredId === attr.id ? 1.5 : 1
      dummy.scale.set(scaleXZ, scaleY, scaleXZ)
      dummy.updateMatrix()
      meshRef.current!.setMatrixAt(i, dummy.matrix)
      
      const c = getColor(attr.status)
      if (hoveredId === attr.id) c.multiplyScalar(2) // Brighten on hover
      meshRef.current!.setColorAt(i, c)
    })
    
    meshRef.current.instanceMatrix.needsUpdate = true
    if (meshRef.current.instanceColor) meshRef.current.instanceColor.needsUpdate = true
  })

  return (
    <>
      <instancedMesh 
        ref={meshRef} 
        args={[geometry, material, attractions.length]}
        onPointerMove={(e) => {
          e.stopPropagation()
          const id = attractions[e.instanceId!].id
          if (hoveredId !== id) setHoveredId(id)
        }}
        onPointerOut={(e) => {
          e.stopPropagation()
          setHoveredId(null)
        }}
        onClick={(e) => {
          e.stopPropagation()
          onMarkerClick(attractions[e.instanceId!])
        }}
      />
      {/* Lights & Tooltips */}
      {attractions.map((attr: AttractionMarker) => {
        const pos = getCoords(attr.lat, attr.lng)
        const isHovered = hoveredId === attr.id
        const isActive = attr.status === 'ACTIVE'
        return (
          <group key={attr.id} position={[pos.x, 0, pos.z]}>
            {isActive && <pointLight position={[0, 1, 0]} intensity={1.5} distance={3} color="#00e676" />}
            <Html position={[0, (attr.capacityLevel * 0.4) + 0.5, 0]} center style={{ pointerEvents: 'none', opacity: isHovered ? 1 : 0, transition: 'opacity 0.2s' }}>
              <div className="bg-zinc-950/90 backdrop-blur border border-white/10 px-3 py-1.5 rounded-lg whitespace-nowrap shadow-xl">
                <div className="text-white font-bold text-xs">{attr.name}</div>
                <div className="text-[var(--color-primary)] font-bold text-[10px]">{attr.status}</div>
              </div>
            </Html>
          </group>
        )
      })}
    </>
  )
}

function CameraController({ targetPosition }: { targetPosition: THREE.Vector3 | null }) {
  const { camera } = useThree()
  
  useFrame((state, delta) => {
    // Subtle mouse parallax if no target
    if (!targetPosition) {
      const mouseX = (state.pointer.x * 2) // -2 to 2
      const mouseY = (state.pointer.y * 2)
      
      // Interpolate camera position slightly based on mouse
      camera.position.set(
        camera.position.x + (mouseX - camera.position.x) * 0.05 * delta * 10,
        camera.position.y,
        camera.position.z + (mouseY + 8 - camera.position.z) * 0.05 * delta * 10
      )
      camera.lookAt(0, 0, 0)
      return
    }

    // Fly to target
    const targetCamPos = new THREE.Vector3(targetPosition.x, 3, targetPosition.z + 4)
    camera.position.lerp(targetCamPos, 0.05)
    
    // Look at target

    // We should ideally track the lookAt point, but for simplicity we'll interpolate the rotation
    // by using a dummy object or just lerping the position and looking at the target
    camera.lookAt(targetPosition)
  })

  return <OrbitControls 
    enablePan={false} 
    enableZoom={true} 
    minDistance={2} 
    maxDistance={15}
    maxPolarAngle={Math.PI / 2.2}
    enableDamping
    dampingFactor={0.05}
  />
}

// ----------------------------------------------------------------------
// MAIN COMPONENT
// ----------------------------------------------------------------------
export default function SpatialHub({ attractions, onAttractionClick }: SpatialHubProps) {
  const [isLowEnd] = useState(() => {
    if (typeof window !== 'undefined') {
      const isMobile = window.innerWidth < 768
      const cores = navigator.hardwareConcurrency || 2
      return isMobile && cores <= 4
    }
    return false
  })
  const [activeAttraction, setActiveAttraction] = useState<AttractionMarker | null>(null)
  const [hoveredId, setHoveredId] = useState<string | null>(null)
  const [cameraTarget, setCameraTarget] = useState<THREE.Vector3 | null>(null)
  const containerRef = useRef<HTMLDivElement>(null)
  const [inView, setInView] = useState(true)
  
  // Hardware capabilities check & Intersection Observer
  useEffect(() => {

    const observer = new IntersectionObserver(
      ([entry]) => {
        setInView(entry.isIntersecting)
      },
      { threshold: 0.1 }
    )
    
    if (containerRef.current) observer.observe(containerRef.current)
    return () => observer.disconnect()
  }, [])

  const handleMarkerClick = (attr: AttractionMarker) => {
    setActiveAttraction(attr)
    setCameraTarget(getCoords(attr.lat, attr.lng))
  }

  const handleClosePanel = () => {
    setActiveAttraction(null)
    setCameraTarget(null) // Resets to default parallax
  }

  const handleActionClick = (slug: string) => {
    if (onAttractionClick) onAttractionClick(slug)
  }

  // Graceful degradation fallback
  if (isLowEnd) {
    return (
      <div className="w-full h-[40vh] md:h-[60vh] bg-zinc-950 border border-white/10 rounded-2xl relative overflow-hidden flex items-center justify-center">
        <div className="absolute inset-0 opacity-20 pointer-events-none" style={{ backgroundImage: 'radial-gradient(circle at center, #333 1px, transparent 1px)', backgroundSize: '20px 20px' }} />
        
        <div className="relative w-full max-w-sm aspect-square border border-white/5 rounded-full flex items-center justify-center">
          <div className="text-center p-6">
            <h3 className="text-white font-bold mb-2">2D Map Mode</h3>
            <p className="text-white/50 text-xs mb-6">Running in low-power mode to save battery.</p>
            
            <div className="flex flex-col gap-2">
              {attractions.map(attr => (
                <button 
                  key={attr.id}
                  onClick={() => handleActionClick(attr.slug)}
                  className="bg-white/5 hover:bg-white/10 border border-white/10 rounded-lg p-3 text-left transition-colors flex justify-between items-center"
                >
                  <div>
                    <div className="text-white font-bold text-sm">{attr.name}</div>
                    <div className="text-[var(--color-primary)] font-bold text-[10px]">{attr.status}</div>
                  </div>
                  <div className={`w-2 h-2 rounded-full ${attr.status === 'ACTIVE' ? 'bg-[var(--color-primary)] animate-pulse' : 'bg-yellow-500'}`} />
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div ref={containerRef} className="relative w-full h-[40vh] md:h-[60vh] bg-[#020202] rounded-2xl overflow-hidden border border-white/10 group cursor-crosshair">
      <Suspense fallback={<div className="absolute inset-0 flex items-center justify-center text-white/50 text-sm font-bold uppercase tracking-widest">Initializing Spatial Engine...</div>}>
        <Canvas camera={{ position: [0, 8, 8], fov: 45 }} dpr={[1, 1.5]} frameloop={inView ? 'always' : 'never'}>
          <color attach="background" args={['#020202']} />
          <ambientLight intensity={0.2} />
          
          <GroundMap />
          <Markers 
            attractions={attractions} 
            onMarkerClick={handleMarkerClick}
            hoveredId={hoveredId}
            setHoveredId={setHoveredId}
          />
          <CameraController targetPosition={cameraTarget} />
          
          {/* Add a subtle fog for depth */}
          <fog attach="fog" args={['#020202', 5, 25]} />
        </Canvas>
      </Suspense>

      {/* Info Panel Overlay */}
      <div 
        className={`absolute top-4 end-4 bottom-4 w-72 bg-zinc-950/80 backdrop-blur-md border border-white/10 rounded-xl p-5 shadow-2xl transition-transform duration-500 ease-[cubic-bezier(0.23,1,0.32,1)] flex flex-col ${activeAttraction ? 'translate-x-0' : 'translate-x-[120%]'}`}
      >
        {activeAttraction && (
          <>
            <button onClick={handleClosePanel} className="absolute top-4 end-4 text-white/50 hover:text-white">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
            </button>
            <div className="inline-flex px-2 py-1 bg-[var(--color-primary)]/10 text-[var(--color-primary)] text-[10px] font-black tracking-widest rounded mb-3 w-fit">
              {activeAttraction.status}
            </div>
            <h3 className="text-xl font-black text-white mb-2">{activeAttraction.name}</h3>
            <p className="text-sm text-white/70 mb-6">{activeAttraction.tagline}</p>
            
            <div className="mt-auto space-y-2">
              <button 
                onClick={() => handleActionClick(activeAttraction.slug)}
                onDoubleClick={() => {
                   window.open(`/b2b/services/${activeAttraction.slug}`, '_blank')
                }}
                className="w-full py-2.5 bg-white text-zinc-950 font-bold text-sm rounded-lg hover:bg-white/90 transition-colors"
              >
                View Attraction (Double-click to open)
              </button>
              <button 
                className="w-full py-2.5 bg-transparent text-white border border-white/20 font-bold text-sm rounded-lg hover:bg-white/10 transition-colors"
              >
                Book Tickets
              </button>
            </div>
          </>
        )}
      </div>

      {/* Control Hint */}
      <div className="absolute bottom-4 start-4 text-[10px] font-bold text-white/30 uppercase tracking-widest pointer-events-none">
        Drag to rotate • Scroll to zoom
      </div>
    </div>
  )
}

"use client"

import { useRef, useMemo, useState, useEffect } from "react"
import { useFrame, useThree } from "@react-three/fiber"
import { OrbitControls, Html, Grid } from "@react-three/drei"
import * as THREE from "three"
import { AttractionData } from "./SpatialFallback"
import "next/link"
import { Info, Ticket } from "lucide-react"
import { Button } from "@/components/ui/Button"

interface SpatialSceneProps {
  attractions: AttractionData[]
  onAttractionClick?: (slug: string) => void
}

// Map 0-100% coordinates to 3D space (-10 to 10)
const mapCoord = (val: number, max: number = 20) => (val / 100) * max - (max / 2)

// A highly simplified shape representing Qatar for extrusion
const QATAR_POINTS = [
  [45, 15], [60, 5], [75, 10], [80, 25], [85, 40], [70, 60], [85, 80], 
  [90, 90], [70, 105], [50, 110], [45, 100], [30, 90], [25, 70], [20, 50], [30, 30]
]

export function SpatialScene({ attractions, onAttractionClick }: SpatialSceneProps) {
  const { camera } = useThree()
  const instancedMeshRef = useRef<THREE.InstancedMesh>(null)
  
  const [hoveredIdx, setHoveredIdx] = useState<number | null>(null)
  const [selectedIdx, setSelectedIdx] = useState<number | null>(null)
  const targetCamPos = useRef(new THREE.Vector3(0, 12, 12))
  const targetLookAt = useRef(new THREE.Vector3(0, 0, 0))

  // Base Map Geometry
  const mapGeometry = useMemo(() => {
    const shape = new THREE.Shape()
    QATAR_POINTS.forEach((pt, i) => {
      const x = mapCoord(pt[0], 12)
      const z = mapCoord(pt[1], 15) // Flip Y to Z
      if (i === 0) shape.moveTo(x, z)
      else shape.lineTo(x, z)
    })
    shape.lineTo(mapCoord(QATAR_POINTS[0][0], 12), mapCoord(QATAR_POINTS[0][1], 15))

    const extrudeSettings = { depth: 0.5, bevelEnabled: true, bevelSegments: 1, steps: 1, bevelSize: 0.1, bevelThickness: 0.1 }
    const geo = new THREE.ExtrudeGeometry(shape, extrudeSettings)
    // Rotate to lie flat on XZ plane
    geo.rotateX(Math.PI / 2)
    geo.translate(0, -0.25, 0)
    return geo
  }, [])

  // Instanced Mesh Setup
  const object = useMemo(() => new THREE.Object3D(), [])
  const color = useMemo(() => new THREE.Color(), [])
  
  useEffect(() => {
    if (!instancedMeshRef.current) return
    
    attractions.forEach((attr, i) => {
      const x = mapCoord(attr.location[0], 12)
      const z = mapCoord(attr.location[1], 15)
      const h = attr.capacity > 5000 ? 2 : 1
      
      object.position.set(x, h/2, z)
      object.scale.set(1, h, 1)
      object.updateMatrix()
      instancedMeshRef.current!.setMatrixAt(i, object.matrix)
      
      let hex = "#ffffff"
      if (attr.status === 'active') hex = "#10b981"
      else if (attr.status === 'upcoming') hex = "#f59e0b"
      else if (attr.status === 'coming_soon') hex = "#3b82f6"
      
      instancedMeshRef.current!.setColorAt(i, color.set(hex))
    })
    
    instancedMeshRef.current.instanceMatrix.needsUpdate = true
    if (instancedMeshRef.current.instanceColor) instancedMeshRef.current.instanceColor.needsUpdate = true
  }, [attractions, object, color])

  // Animation Loop
  useFrame((state) => {
    // Pulse animation for active markers
    if (instancedMeshRef.current) {
      const time = state.clock.getElapsedTime()
      attractions.forEach((attr, i) => {
        if (attr.status === 'active') {
          instancedMeshRef.current!.getMatrixAt(i, object.matrix)
          object.matrix.decompose(object.position, object.quaternion, object.scale)
          
          const scaleY = (attr.capacity > 5000 ? 2 : 1) * (1 + Math.sin(time * 3 + i) * 0.1)
          object.scale.set(1, scaleY, 1)
          
          object.updateMatrix()
          instancedMeshRef.current!.setMatrixAt(i, object.matrix)
        }
      })
      instancedMeshRef.current.instanceMatrix.needsUpdate = true
    }

    // Camera Fly-to
    camera.position.lerp(targetCamPos.current, 0.05)
    
    // Parallax on mouse move (if not selected)
    if (selectedIdx === null) {
      targetLookAt.current.x = THREE.MathUtils.lerp(targetLookAt.current.x, (state.pointer.x * 2), 0.05)
      targetLookAt.current.z = THREE.MathUtils.lerp(targetLookAt.current.z, (-state.pointer.y * 2), 0.05)
    }

    camera.lookAt(targetLookAt.current)
  })

  // Handlers
  const handleClick = (e: any) => {
    e.stopPropagation()
    if (e.instanceId === undefined) return
    
    setSelectedIdx(e.instanceId)
    const attr = attractions[e.instanceId]
    const x = mapCoord(attr.location[0], 12)
    const z = mapCoord(attr.location[1], 15)
    
    // Fly camera near the marker
    targetCamPos.current.set(x, 4, z + 6)
    targetLookAt.current.set(x, 0, z)
  }

  const handlePointerMissed = () => {
    setSelectedIdx(null)
    targetCamPos.current.set(0, 12, 12)
    targetLookAt.current.set(0, 0, 0)
  }

  return (
    <>
      <ambientLight intensity={0.5} />
      <directionalLight position={[10, 10, 5]} intensity={1} />
      
      {/* Grid Floor */}
      <Grid infiniteGrid fadeDistance={40} sectionColor="#333" cellColor="#222" position={[0, -0.26, 0]} />

      {/* Qatar Base Model */}
      <mesh geometry={mapGeometry} onPointerMissed={handlePointerMissed}>
        <meshStandardMaterial color="#0a0a0a" roughness={0.8} metalness={0.2} />
      </mesh>

      {/* Markers */}
      <instancedMesh 
        ref={instancedMeshRef} 
        args={[undefined, undefined, attractions.length]} 
        onPointerOver={(e) => { e.stopPropagation(); setHoveredIdx(e.instanceId ?? null); document.body.style.cursor = 'pointer' }}
        onPointerOut={() => { setHoveredIdx(null); document.body.style.cursor = 'auto' }}
        onClick={handleClick}
        onDoubleClick={(e) => { if (e.instanceId !== undefined) onAttractionClick?.(attractions[e.instanceId].slug) }}
      >
        <cylinderGeometry args={[0.2, 0.2, 1, 8]} />
        <meshStandardMaterial emissiveIntensity={2} toneMapped={false} />
      </instancedMesh>

      {/* Tooltips / Info Panels */}
      {attractions.map((attr, i) => {
        const x = mapCoord(attr.location[0], 12)
        const z = mapCoord(attr.location[1], 15)
        
        return (
          <group key={attr.id} position={[x, 1, z]}>
            {/* Hover Tooltip */}
            {hoveredIdx === i && selectedIdx !== i && (
              <Html center position={[0, 1.5, 0]} className="pointer-events-none">
                <div className="bg-zinc-950/80 backdrop-blur border border-white/20 text-white px-3 py-1.5 rounded-sg text-sm font-bold whitespace-nowrap">
                  {attr.name}
                </div>
              </Html>
            )}

            {/* Clicked Info Panel */}
            {selectedIdx === i && (
              <Html position={[1, 0, 0]} className="pointer-events-auto">
                <div className="bg-zinc-950/90 backdrop-blur-md border border-[var(--color-primary)]/50 p-5 rounded-2xl w-64 shadow-2xl animate-in slide-in-from-start-4 fade-in">
