      <OrbitControls 
        enablePan={false}
        enableZoom={selectedIdx === null}
        maxPolarAngle={Math.PI / 2.2}
        minDistance={5}
        maxDistance={25}
      />
    </>
  )
}

"use client"

import React, { useEffect } from 'react'
import { useEditor, EditorContent } from "@tiptap/react"
import StarterKit from "@tiptap/starter-kit"
import { 
  Bold, 
  Italic, 
  List, 
