"use client";

/*
  Storybook Usage:
  <Accordion type="single" collapsible>
    <AccordionItem value="item-1">
      <AccordionTrigger>Is it accessible?</AccordionTrigger>
      <AccordionContent>Yes. It adheres to the WAI-ARIA design pattern.</AccordionContent>
    </AccordionItem>
  </Accordion>
*/

import * as React from "react";
import { motion, AnimatePresence } from "framer-motion";
import { ChevronDown } from "lucide-react";
import { cn } from "@/lib/utils";

type AccordionContextValue = {
  value: string[];
  onItemChange: (itemValue: string) => void;
};

const AccordionContext = React.createContext<AccordionContextValue | null>(null);

export interface AccordionProps {
  type?: "single" | "multiple";
  collapsible?: boolean;
  value?: string | string[];
  defaultValue?: string | string[];
  onValueChange?: (value: any) => void;
  className?: string;
  children: React.ReactNode;
}

export const Accordion = React.forwardRef<HTMLDivElement, AccordionProps>(
  (
    {
      type = "single",
      collapsible = false,
      value,
      defaultValue,
      onValueChange,
      className,
      children,
      ...props
    },
    ref
  ) => {
    const [internalValue, setInternalValue] = React.useState<string[]>(() => {
      if (value !== undefined) return Array.isArray(value) ? value : [value];
      if (defaultValue !== undefined) return Array.isArray(defaultValue) ? defaultValue : [defaultValue];
      return [];
    });

    const activeValues = React.useMemo(
      () => (value !== undefined ? (Array.isArray(value) ? value : [value]) : internalValue),
      [value, internalValue]
    );

    const handleItemChange = React.useCallback(
      (itemValue: string) => {
        let newValues = [...activeValues];
        
        if (type === "single") {
          if (activeValues.includes(itemValue)) {
            newValues = collapsible ? [] : activeValues;
          } else {
            newValues = [itemValue];
          }
        } else {
          if (activeValues.includes(itemValue)) {
            newValues = activeValues.filter((v) => v !== itemValue);
          } else {
            newValues = [...activeValues, itemValue];
          }
        }

        if (value === undefined) {
          setInternalValue(newValues);
        }
        
        if (onValueChange) {
          onValueChange(type === "single" ? newValues[0] || "" : newValues);
        }
      },
      [activeValues, collapsible, type, value, onValueChange]
    );

    return (
      <AccordionContext.Provider value={{ value: activeValues, onItemChange: handleItemChange }}>
        <div ref={ref} className={cn("flex flex-col w-full", className)} {...props}>
          {children}
        </div>
      </AccordionContext.Provider>
    );
  }
);
Accordion.displayName = "Accordion";

type AccordionItemContextValue = {
  value: string;
  isOpen: boolean;
  triggerId: string;
  contentId: string;
};

const AccordionItemContext = React.createContext<AccordionItemContextValue | null>(null);

export interface AccordionItemProps extends React.HTMLAttributes<HTMLDivElement> {
  value: string;
  disabled?: boolean;
}

export const AccordionItem = React.forwardRef<HTMLDivElement, AccordionItemProps>(
  ({ className, value, disabled, children, ...props }, ref) => {
    const context = React.useContext(AccordionContext);
    if (!context) throw new Error("AccordionItem must be used within Accordion");

    const isOpen = context.value.includes(value);
    const triggerId = React.useId();
    const contentId = React.useId();

    return (
      <AccordionItemContext.Provider value={{ value, isOpen, triggerId, contentId }}>
        <div
          ref={ref}
          className={cn(
            "border-b border-[var(--border-level-2)] overflow-hidden",
            disabled && "opacity-50 pointer-events-none",
            className
          )}
          {...props}
        >
          {children}
        </div>
      </AccordionItemContext.Provider>
    );
  }
);
AccordionItem.displayName = "AccordionItem";

export const AccordionTrigger = React.forwardRef<
  HTMLButtonElement,
  React.ButtonHTMLAttributes<HTMLButtonElement>
>(({ className, children, ...props }, ref) => {
  const rootContext = React.useContext(AccordionContext);
  const itemContext = React.useContext(AccordionItemContext);

  if (!rootContext || !itemContext) {
    throw new Error("AccordionTrigger must be used within AccordionItem");
  }

  return (
    <button
      ref={ref}
      id={itemContext.triggerId}
      aria-expanded={itemContext.isOpen}
      aria-controls={itemContext.contentId}
      onClick={() => rootContext.onItemChange(itemContext.value)}
      className={cn(
        "flex flex-1 w-full items-center justify-between py-4 font-medium transition-all text-[var(--text-primary)] hover:text-[var(--color-primary)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-primary)] rounded-md",
        className
      )}
      {...props}
    >
      {children}
      <motion.div
        animate={{ rotate: itemContext.isOpen ? 180 : 0 }}
        transition={{ duration: 0.2 }}
        className="shrink-0 ms-2 text-[var(--text-tertiary)]"
      >
        <ChevronDown size={18} />
      </motion.div>
    </button>
  );
});
AccordionTrigger.displayName = "AccordionTrigger";

export const AccordionContent = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className, children, ...props }, ref) => {
  const itemContext = React.useContext(AccordionItemContext);
  
  if (!itemContext) {
    throw new Error("AccordionContent must be used within AccordionItem");
  }

  return (
    <AnimatePresence initial={false}>
      {itemContext.isOpen && (
        <motion.div
          id={itemContext.contentId}
          role="region"
          aria-labelledby={itemContext.triggerId}
          initial={{ height: 0, opacity: 0 }}
          animate={{ height: "auto", opacity: 1 }}
          exit={{ height: 0, opacity: 0 }}
          transition={{ duration: 0.3, ease: "easeInOut" }}
          className="overflow-hidden"
        >
          <div ref={ref} className={cn("pb-4 pt-0 text-[var(--text-secondary)]", className)} {...props}>
            {children}
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
});
AccordionContent.displayName = "AccordionContent";

'use client';

import React, { useRef } from 'react';
import { motion, useInView } from 'framer-motion';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

interface AnimatedTextProps {
  text: string;
  className?: string;
  once?: boolean;
  delay?: number;
  as?: React.ElementType;
}

export function AnimatedText({ text, className, once = true, delay = 0, as = 'div' }: AnimatedTextProps) {
  const Component = as as any;
  const ref = useRef<HTMLElement>(null);
  const isInView = useInView(ref, { once, margin: '-10% 0px' });

  // Split text into words for staggered reveal
  const words = text.split(' ');

  const container = {
    hidden: { opacity: 0 },
    visible: (i = 1) => ({
      opacity: 1,
      transition: { staggerChildren: 0.08, delayChildren: delay * i },
    }),
  };

  const child: any = {
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        type: 'spring',
        damping: 12,
        stiffness: 100,
      },
    },
    hidden: {
      opacity: 0,
      y: 20,
      transition: {
        type: 'spring',
        damping: 12,
        stiffness: 100,
      },
    },
  };

  return (
    <Component
      ref={ref}
      className={cn('flex flex-wrap m-0', className)}
    >
      <motion.div
        variants={container}
        initial="hidden"
        animate={isInView ? 'visible' : 'hidden'}
        className="flex flex-wrap"
      >
        {words.map((word, index) => (
          <motion.span
            variants={child}
            style={{ marginRight: '0.25em', display: 'inline-block' }}
            key={index}
          >
            {word}
          </motion.span>
        ))}
      </motion.div>
    </Component>
  );
}

"use client";

import React, { createContext, useContext, useState } from 'react';
import { motion, AnimatePresence } from "framer-motion";
import { cn } from "@/lib/utils";
import { MapPin, Clock, Ticket, Users, AlertCircle, HelpCircle, ArrowRight } from "lucide-react";
import Link from "next/link";

// ==========================================
// 1. Theme Provider & Context
// ==========================================

type Theme = "light" | "dark";

interface B2CThemeContextType {
  theme: Theme;
  setTheme: (theme: Theme) => void;
  toggleTheme: () => void;
  locale: string;
  isAr: boolean;
}

const B2CThemeContext = createContext<B2CThemeContextType | undefined>(undefined);

export function B2CThemeProvider({
  children,
  locale = "en",
}: {
  children: React.ReactNode;
  locale?: string;
}) {
  const theme = React.useSyncExternalStore(
    (callback) => {
      const root = window.document.documentElement;
      const observer = new MutationObserver((mutations) => {
        for (const m of mutations) {
          if (m.attributeName === "data-theme") callback();
        }
      });
      observer.observe(root, { attributes: true, attributeFilter: ["data-theme"] });
      return () => observer.disconnect();
    },
    () => {
      if (typeof window === "undefined") return "dark";
      const currentTheme = window.document.documentElement.getAttribute("data-theme");
      return (currentTheme === "light" || currentTheme === "dark") ? currentTheme : "dark";
    },
    () => "dark" as Theme
  );
  const isAr = locale === "ar";

  const setTheme = (newTheme: Theme) => {
    const root = window.document.documentElement;
    root.setAttribute("data-theme", newTheme);
    localStorage.setItem("theme", newTheme);
    // removed setThemeState
  };

  const toggleTheme = () => {
    setTheme(theme === "dark" ? "light" : "dark");
  };

  return (
    <B2CThemeContext.Provider value={{ theme, setTheme, toggleTheme, locale, isAr }}>
      <div className={cn("b2c-theme w-full min-h-screen text-[var(--text-primary)] bg-[var(--bg-level-1)] transition-colors duration-300", isAr ? "rtl" : "ltr")} dir={isAr ? "rtl" : "ltr"}>
        {children}
      </div>
    </B2CThemeContext.Provider>
  );
}

export function useB2CTheme() {
  const context = useContext(B2CThemeContext);
  if (!context) {
    throw new Error("useB2CTheme must be used within a B2CThemeProvider");
  }
  return context;
}

// ==========================================
// 2. Reusable Layout Components
// ==========================================

export function B2CPageShell({
  children,
  className,
  showBgOrbs = true,
}: {
  children: React.ReactNode;
  className?: string;
  showBgOrbs?: boolean;
}) {
  const { theme } = useB2CTheme();

  return (
    <div className={cn("relative w-full overflow-hidden", className)}>
      {/* Background Cinematic Orbs (Dark Mode ONLY) */}
      {showBgOrbs && theme === "dark" && (
        <div className="fixed inset-0 overflow-hidden pointer-events-none z-0">
          <motion.div
            animate={{
              scale: [1, 1.15, 1],
              x: [0, 80, 0],
              y: [0, -40, 0],
            }}
            transition={{ duration: 18, repeat: Infinity, ease: "easeInOut" }}
            className="absolute -top-40 -start-40 w-[600px] h-[600px] bg-[var(--e3-purple)] rounded-full mix-blend-screen filter blur-[128px] opacity-[0.15]"
          />
          <motion.div
            animate={{
              scale: [1.1, 0.95, 1.1],
              x: [0, -60, 0],
              y: [0, 50, 0],
            }}
            transition={{ duration: 22, repeat: Infinity, ease: "easeInOut", delay: 2 }}
            className="absolute -bottom-40 -end-40 w-[600px] h-[600px] bg-[var(--e3-royal-blue)] rounded-full mix-blend-screen filter blur-[128px] opacity-[0.15]"
          />
        </div>
      )}

      {/* Background Soft Gradients (Light Mode ONLY) */}
      {showBgOrbs && theme === "light" && (
        <div className="fixed inset-0 overflow-hidden pointer-events-none z-0">
          <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-b from-[#EBF0FF]/40 to-transparent" />
          <div className="absolute top-1/4 right-0 w-[400px] h-[400px] bg-[var(--e3-soft-border)]/20 rounded-full filter blur-[80px]" />
        </div>
      )}

      <div className="relative z-10 w-full">
        {children}
      </div>
    </div>
  );
}

