"use client";

/*
  Storybook Usage:
  <Badge variant="success" size="md" dot>
    Active User
  </Badge>
  <Badge variant="gradient" removable onRemove={() => console.log('removed')}>
    Premium
  </Badge>
*/

import * as React from "react";
import { motion, AnimatePresence } from "framer-motion";
import { X } from "lucide-react";
import { cn } from "@/lib/utils";

export type BadgeVariant = "default" | "success" | "warning" | "error" | "info" | "gradient";
export type BadgeSize = "sm" | "md" | "lg";

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  variant?: BadgeVariant;
  size?: BadgeSize;
  dot?: boolean;
  removable?: boolean;
  onRemove?: () => void;
}

const variantStyles: Record<BadgeVariant, string> = {
  default: "bg-[var(--surface-active)] text-[var(--text-primary)] border-[var(--border-level-2)]",
  success: "bg-[#22C55E15] text-[var(--color-success)] border-[#22C55E30]",
  warning: "bg-[#F59E0B15] text-[var(--color-warning)] border-[#F59E0B30]",
  error: "bg-[#EF444415] text-[var(--color-error)] border-[#EF444430]",
  info: "bg-[#3B82F615] text-[var(--color-info)] border-[#3B82F630]",
  gradient: "bg-gradient-to-r from-[var(--color-primary)] to-[var(--color-accent)] text-white border-transparent",
};

const dotColors: Record<BadgeVariant, string> = {
  default: "bg-[var(--text-tertiary)]",
  success: "bg-[var(--color-success)]",
  warning: "bg-[var(--color-warning)]",
  error: "bg-[var(--color-error)]",
  info: "bg-[var(--color-info)]",
  gradient: "bg-white",
};

const sizeStyles: Record<BadgeSize, string> = {
  sm: "text-xs px-2 py-0.5 gap-1",
  md: "text-sm px-2.5 py-1 gap-1.5",
  lg: "text-base px-3 py-1.5 gap-2",
};

export const Badge = React.forwardRef<HTMLSpanElement, BadgeProps>(
  (
    {
      className,
      variant = "default",
      size = "md",
      dot = false,
      removable = false,
      onRemove,
      children,
      ...props
    },
    ref
  ) => {
    const [isVisible, setIsVisible] = React.useState(true);

    const handleRemove = (e: React.MouseEvent | React.KeyboardEvent) => {
      e.preventDefault();
      e.stopPropagation();
      setIsVisible(false);
      setTimeout(() => {
        onRemove?.();
      }, 200); // Wait for exit animation
    };

    return (
      <AnimatePresence>
        {isVisible && (
          <motion.span
            ref={ref}
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.8 }}
            transition={{ duration: 0.2 }}
            className={cn(
              "inline-flex items-center justify-center rounded-full border font-medium transition-colors",
              variantStyles[variant],
              sizeStyles[size],
              className
            )}
            {...(props as any)}
          >
            {dot && (
              <span
                className={cn(
                  "rounded-full shrink-0",
                  dotColors[variant],
                  size === "sm" ? "w-1.5 h-1.5" : size === "md" ? "w-2 h-2" : "w-2.5 h-2.5"
                )}
                aria-hidden="true"
              />
            )}
            
            <span>{children}</span>
            
            {removable && (
              <button
                type="button"
                onClick={handleRemove}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") handleRemove(e);
                }}
                className={cn(
                  "shrink-0 rounded-full focus:outline-none focus:ring-2 focus:ring-offset-1 hover:brightness-90 transition-all",
                  variant === "gradient" ? "focus:ring-white text-white/80 hover:text-white" : "focus:ring-[var(--color-primary)] opacity-70 hover:opacity-100"
                )}
                aria-label="Remove badge"
              >
                <X size={size === "sm" ? 12 : size === "md" ? 14 : 16} />
              </button>
            )}
          </motion.span>
        )}
      </AnimatePresence>
    );
  }
);
Badge.displayName = "Badge";

"use client";

import * as React from "react";
import { motion, useMotionValue, useSpring, useTransform, HTMLMotionProps } from "framer-motion";
import { cn } from "@/lib/utils";

export type CardVariant = "flat" | "elevated" | "glass" | "bordered" | "gradient-border";

export interface CardProps extends Omit<HTMLMotionProps<"div">, "children"> {
  children: React.ReactNode;
  variant?: CardVariant;
  interactive?: boolean;
  className?: string;
}

const variantStyles: Record<CardVariant, string> = {
  flat: "bg-[var(--surface-default)]",
  elevated: "bg-[var(--surface-default)] shadow-lg shadow-[var(--shadow-1)]",
  glass: "glass",
  bordered: "bg-[var(--surface-default)] border border-[var(--border-level-2)]",
  "gradient-border": "border-gradient p-[1px] bg-[var(--surface-default)]",
};

export const Card = React.forwardRef<HTMLDivElement, CardProps>(
  (
    {
      children,
      variant = "flat",
      interactive = false,
      className,
      onPointerMove,
      onPointerLeave,
      ...props
    },
    ref
  ) => {
    // 3D Tilt Physics state
    const x = useMotionValue(0);
    const y = useMotionValue(0);

    const mouseXSpring = useSpring(x, { stiffness: 300, damping: 30 });
    const mouseYSpring = useSpring(y, { stiffness: 300, damping: 30 });

    const rotateX = useTransform(mouseYSpring, [-0.5, 0.5], ["10deg", "-10deg"]);
    const rotateY = useTransform(mouseXSpring, [-0.5, 0.5], ["-10deg", "10deg"]);

    const [isHovered, setIsHovered] = React.useState(false);

    const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
      if (!interactive) return;
      
      // Disable tilt on touch devices/small viewports where pointerType is touch or pen
      if (e.pointerType !== "mouse") return;

      const rect = e.currentTarget.getBoundingClientRect();
      const width = rect.width;
      const height = rect.height;
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const xPct = mouseX / width - 0.5;
      const yPct = mouseY / height - 0.5;

      x.set(xPct);
      y.set(yPct);

      setIsHovered(true);
      onPointerMove?.(e);
    };

    const handlePointerLeave = (e: React.PointerEvent<HTMLDivElement>) => {
      if (!interactive) return;
      x.set(0);
      y.set(0);
      setIsHovered(false);
      onPointerLeave?.(e);
    };

    return (
      <motion.div
        ref={ref as any}
        onPointerMove={handlePointerMove}
        onPointerLeave={handlePointerLeave}
        style={
          interactive
            ? {
                rotateX,
                rotateY,
                transformPerspective: 1000,
              }
            : undefined
        }
        className={cn(
          "relative rounded-xl overflow-hidden transition-all duration-300",
          variantStyles[variant],
          interactive && "cursor-pointer transform-gpu hover:-translate-y-1 hover:shadow-2xl",
          // Dark Mode specific hover glow using the CSS variable defined in globals.css
          interactive && isHovered && "dark:glow",
          className
        )}
        {...props}
      >
        {children}
      </motion.div>
    );
  }
);

Card.displayName = "Card";

"use client";

import * as React from "react";
import { motion, AnimatePresence } from "framer-motion";
import { X, AlertCircle } from "lucide-react";
import { cn } from "@/lib/utils";

export interface InputProps extends React.InputHTMLAttributes<HTMLInputElement | HTMLTextAreaElement> {
  label?: string;
  helperText?: string;
  error?: string;
  icon?: React.ReactNode;
  clearable?: boolean;
  onClear?: () => void;
  as?: "input" | "textarea";
}

export const Input = React.forwardRef<HTMLInputElement | HTMLTextAreaElement, InputProps>(
  (
    {
      className,
      label,
      helperText,
      error,
      icon,
      clearable,
      onClear,
      as = "input",
      disabled,
      value,
      defaultValue,
      onChange,
      onFocus,
      onBlur,
      type = "text",
      ...props
    },
    ref
  ) => {
    const [isFocused, setIsFocused] = React.useState(false);
    
    // Check if the input is filled to keep the label floating
    const isFilled = React.useMemo(() => {
      if (value !== undefined && value !== null && value !== "") return true;
      if (defaultValue !== undefined && defaultValue !== null && defaultValue !== "") return true;
      return false;
    }, [value, defaultValue]);

    const handleFocus = (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      setIsFocused(true);
      onFocus?.(e);
    };

    const handleBlur = (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      setIsFocused(false);
      onBlur?.(e);
    };

    const showClearButton = clearable && isFilled && !disabled;
    const Component = as as any;
    const isFloating = isFocused || isFilled;

    return (
      <div className={cn("relative flex flex-col w-full", className)}>
        <div className="relative flex items-center w-full">
          {icon && (
            <div className="absolute start-3 rtl:end-3 rtl:start-auto text-[var(--text-tertiary)] z-10 pointer-events-none transition-colors duration-200">
              {icon}
            </div>
          )}
          
          <Component
            ref={ref}
            type={as === "input" ? type : undefined}
            disabled={disabled}
            value={value}
            defaultValue={defaultValue}
            onChange={onChange}
            onFocus={handleFocus}
            onBlur={handleBlur}
            className={cn(
              "w-full bg-[var(--surface-active)] text-[var(--text-primary)] rounded-sg transition-all duration-200 outline-none border border-transparent",
              as === "textarea" ? "py-4 min-h-[120px] resize-y" : "h-14",
              label ? "pt-5 pb-1" : "py-3",
              icon ? "ps-10 rtl:pe-10 rtl:ps-4" : "px-4",
              showClearButton ? "pe-10 rtl:ps-10 rtl:pe-4" : "",
              "focus:bg-[var(--surface-default)] focus:border-[var(--color-primary)] focus:ring-1 focus:ring-[var(--color-primary)]",
              error && "border-[var(--color-error)] focus:border-[var(--color-error)] focus:ring-[var(--color-error)]",
              disabled && "opacity-50 cursor-not-allowed bg-[var(--bg-level-2)]"
            )}
            {...props}
          />

          {label && (
            <motion.label
              initial={false}
              animate={{
                y: isFloating ? (as === "textarea" ? -14 : -10) : 0,
                scale: isFloating ? 0.8 : 1,
                color: error 
                  ? "var(--color-error)" 
                  : isFocused 
                    ? "var(--color-primary)" 
                    : "var(--text-tertiary)",
              }}
              className={cn(
                "absolute pointer-events-none origin-[0_0] transition-colors duration-200",
                icon ? "start-10 rtl:end-10 rtl:start-auto" : "start-4 rtl:end-4 rtl:start-auto",
                as === "textarea" ? "top-4" : "top-[15px]"
              )}
            >
              {label}
            </motion.label>
          )}

          <AnimatePresence>
            {showClearButton && (
              <motion.button
                type="button"
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.8 }}
                onClick={onClear}
                className="absolute end-3 rtl:start-3 rtl:end-auto p-1 rounded-full text-[var(--text-tertiary)] hover:text-[var(--text-primary)] hover:bg-[var(--surface-hover)] transition-colors focus:outline-none focus:ring-2 focus:ring-[var(--color-primary)]"
                aria-label="Clear input"
              >
                <X size={16} />
              </motion.button>
            )}
          </AnimatePresence>

          {error && !showClearButton && (
            <div className="absolute end-3 rtl:start-3 rtl:end-auto text-[var(--color-error)] pointer-events-none">
              <AlertCircle size={18} />
            </div>
          )}
        </div>

        <AnimatePresence>
          {(error || helperText) && (
            <motion.p
              initial={{ opacity: 0, y: -5, x: 0 }}
              animate={
                error 
                  ? { opacity: 1, y: 0, x: [-2, 2, -2, 2, 0] } 
                  : { opacity: 1, y: 0, x: 0 }
              }
              transition={
                error 
                  ? { type: "spring", stiffness: 500, damping: 10, mass: 0.5 } 
                  : { duration: 0.2 }
              }
              exit={{ opacity: 0, y: -5 }}
              className={cn(
                "text-sm mt-1.5 px-1",
                error ? "text-[var(--color-error)]" : "text-[var(--text-secondary)]"
              )}
            >
              {error || helperText}
            </motion.p>
          )}
        </AnimatePresence>
      </div>
    );
  }
);

Input.displayName = "Input";

'use client';

import React, { useRef, useEffect } from 'react';
import gsap from 'gsap';
import { cn } from './AnimatedText';

interface MagneticButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  children: React.ReactNode;
  strength?: number;
  className?: string;
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  href?: string;
}

export function MagneticButton({ 
  children, 
  strength = 30, 
  className,
  variant = 'primary',
  size = 'md',
  href,
  ...props 
}: MagneticButtonProps) {
  const buttonRef = useRef<HTMLButtonElement>(null);
  const textRef = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    const button = buttonRef.current;
    if (!button) return;

    // Use GSAP quickTo for highly performant animations
    const xTo = gsap.quickTo(button, 'x', { duration: 1, ease: 'elastic.out(1, 0.3)' });
    const yTo = gsap.quickTo(button, 'y', { duration: 1, ease: 'elastic.out(1, 0.3)' });
    
    const xTextTo = textRef.current ? gsap.quickTo(textRef.current, 'x', { duration: 1, ease: 'elastic.out(1, 0.3)' }) : null;
    const yTextTo = textRef.current ? gsap.quickTo(textRef.current, 'y', { duration: 1, ease: 'elastic.out(1, 0.3)' }) : null;

    const handleMouseMove = (e: MouseEvent) => {
      const { clientX, clientY } = e;
      const { height, width, left, top } = button.getBoundingClientRect();
      const x = clientX - (left + width / 2);
      const y = clientY - (top + height / 2);
      
      xTo(x * (strength / 100));
      yTo(y * (strength / 100));
      
      if (xTextTo && yTextTo) {
        xTextTo(x * (strength / 200));
        yTextTo(y * (strength / 200));
      }
    };

    const handleMouseLeave = () => {
      xTo(0);
      yTo(0);
      if (xTextTo && yTextTo) {
        xTextTo(0);
        yTextTo(0);
      }
    };

    button.addEventListener('mousemove', handleMouseMove);
    button.addEventListener('mouseleave', handleMouseLeave);

    return () => {
      button.removeEventListener('mousemove', handleMouseMove);
      button.removeEventListener('mouseleave', handleMouseLeave);
    };
  }, [strength]);

  const variantStyles = {
    primary: 'bg-[var(--accent-primary)] text-white hover:bg-[var(--accent-secondary)] shadow-lg shadow-[var(--accent-primary)]/20',
    secondary: 'bg-[var(--surface-secondary)] text-[var(--text-primary)] hover:bg-[var(--border-primary)]',
    outline: 'border border-[var(--border-primary)] text-[var(--text-primary)] hover:bg-[var(--surface-secondary)]',
    ghost: 'text-[var(--text-primary)] hover:bg-[var(--surface-secondary)]'
  };

  const sizeStyles = {
    sm: 'px-4 py-2 text-sm',
    md: 'px-6 py-3 text-base',
    lg: 'px-8 py-4 text-lg font-medium'
  };

  const Component: any = href ? 'a' : 'button';

  return (
    <Component
      ref={buttonRef}
      href={href}
      className={cn(
        'relative overflow-hidden rounded-full font-sans transition-colors duration-300',
        variantStyles[variant],
        sizeStyles[size],
        className
      )}
      {...props}
    >
      <span ref={textRef} className="relative z-10 inline-block pointer-events-none">
        {children}
      </span>
    </Component>
  );
}

import React from "react"
import Image from "next/image"

interface MediaRendererProps {
  url: string | null | undefined
  type: string | null | undefined
  alt: string
  className?: string
  fill?: boolean
}

export function MediaRenderer({ url, type, alt, className, fill }: MediaRendererProps) {
  if (!url) {
    if (fill) {
      return <Image src="/placeholder.jpg" alt={alt} fill className={className} />
    }
    return <img src="/placeholder.jpg" alt={alt} className={className} />
  }

  if (type === "VIDEO") {
    return (
      <video
        src={url}
        autoPlay
        muted
        loop
        playsInline
        className={className}
        style={fill ? { width: "100%", height: "100%", objectFit: "cover", position: "absolute", inset: 0 } : undefined}
      />
    )
  }

  if (type === "IFRAME") {
    return (
      <iframe
        src={url}
        title={alt}
        allow="autoplay; fullscreen"
        className={className}
        style={fill ? { width: "100%", height: "100%", border: "none", position: "absolute", inset: 0 } : { border: "none" }}
      />
    )
  }

  // Default to IMAGE
  if (fill) {
    return <Image src={url} alt={alt} fill className={className} />
  }
  
  return <img src={url} alt={alt} className={className} />
}

"use client"

import { useState, useRef } from "react"
import { Upload, Loader2, Link as LinkIcon } from "lucide-react"
import { cn } from "@/lib/utils"

import { uploadFile } from "@/lib/upload"

interface MediaUploaderProps {
  value: string
  onChange: (url: string) => void
  placeholder?: string
  className?: string
  accept?: string
  context?: string
}

export function MediaUploader({ value, onChange, placeholder = "https://...", className, accept = "image/*,video/*,audio/*", context }: MediaUploaderProps) {
  const [isUploading, setIsUploading] = useState(false)
  const [_progress, setProgress] = useState(0)
  const [, setError] = useState<string | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    setError(null)
    setIsUploading(true)
    setProgress(0)

    try {
      const progressInterval = setInterval(() => {
        setProgress(p => Math.min(p + 10, 90))
      }, 100)

      const result = await uploadFile(file, context)

      clearInterval(progressInterval)
      setProgress(100)

      onChange(result.url)
    } catch (err: any) {
      setError(err.message || "Something went wrong")
    } finally {
      setIsUploading(false)
      setTimeout(() => setProgress(0), 1000)
      if (fileInputRef.current) {
        fileInputRef.current.value = ""
      }
    }
  }

  return (
    <div className={cn("flex w-full items-center gap-2", className)}>
      <div className="relative flex-1">
        <LinkIcon className="absolute start-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[var(--text-tertiary)]" />
        <input 
          type="text" 
          value={value} 
          onChange={e => onChange(e.target.value)} 
          placeholder={placeholder}
          className="w-full bg-[var(--surface-default)] border border-[var(--border-default)] rounded-lg ps-9 pe-3 py-2 text-sm focus:border-[var(--color-primary)] focus:outline-none transition-colors text-[var(--text-primary)]"
        />
      </div>
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleUpload} 
        className="hidden" 
        accept={accept}
      />
      <button 
        type="button"
        onClick={() => fileInputRef.current?.click()}
        disabled={isUploading}
        className="flex shrink-0 items-center justify-center gap-2 bg-[var(--surface-hover)] border border-[var(--border-default)] hover:border-[var(--color-primary)]/50 rounded-lg px-3 py-2 text-sm font-medium transition-colors disabled:opacity-50 text-[var(--text-secondary)] hover:text-[var(--text-primary)] min-w-[100px]"
      >
        {isUploading ? (
          <>
            <Loader2 className="w-4 h-4 animate-spin" />
            <span className="hidden sm:inline">Uploading</span>
          </>
        ) : (
          <>
            <Upload className="w-4 h-4" />
            <span className="hidden sm:inline">Upload</span>
          </>
        )}
      </button>
    </div>
  )
}

"use client";

import * as React from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Check, ChevronDown, Search, X } from "lucide-react";
import { cn } from "@/lib/utils";

export type Option = {
  label: string;
  value: string;
};

export interface SelectProps {
  options: Option[];
  value?: string | string[];
  onChange?: (value: any) => void;
  multiple?: boolean;
  placeholder?: string;
  searchable?: boolean;
  disabled?: boolean;
  className?: string;
  label?: string;
  error?: string;
  name?: string;
}

export const Select = React.forwardRef<HTMLDivElement, SelectProps>(
  (
    {
      options,
      value,
      onChange,
      multiple = false,
      placeholder = "Select an option",
      searchable = false,
      disabled = false,
      className,
      label,
      error,
      name,
    },
    ref
  ) => {
    const [isOpen, setIsOpen] = React.useState(false);
    const [search, setSearch] = React.useState("");
    const [focusedIndex, setFocusedIndex] = React.useState(-1);
    const containerRef = React.useRef<HTMLDivElement>(null);
    const inputRef = React.useRef<HTMLInputElement>(null);
    const listboxRef = React.useRef<HTMLUListElement>(null);

    const filteredOptions = React.useMemo(() => {
      if (!search) return options;
      return options.filter((opt) =>
        opt.label.toLowerCase().includes(search.toLowerCase())
      );
    }, [options, search]);

    const handleSelect = (optionValue: string) => {
      if (multiple) {
        const current = Array.isArray(value) ? value : [];
        const newValue = current.includes(optionValue)
          ? current.filter((v) => v !== optionValue)
          : [...current, optionValue];
        onChange?.(newValue);
      } else {
        onChange?.(optionValue);
        setIsOpen(false);
      }
      setSearch("");
    };

    const removeOption = (e: React.MouseEvent, optionValue: string) => {
      e.stopPropagation();
      if (multiple && Array.isArray(value)) {
        onChange?.(value.filter((v) => v !== optionValue));
      }
    };

    // Click outside to close
    React.useEffect(() => {
      const handleOutsideClick = (e: MouseEvent) => {
        if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
          setIsOpen(false);
        }
      };
      document.addEventListener("mousedown", handleOutsideClick);
      return () => document.removeEventListener("mousedown", handleOutsideClick);
    }, []);

    // Keyboard navigation
    const handleKeyDown = (e: React.KeyboardEvent) => {
      if (disabled) return;

      switch (e.key) {
        case "Enter":
        case " ":
          if (!isOpen) {
            setIsOpen(true);
            e.preventDefault();
          } else if (focusedIndex >= 0 && focusedIndex < filteredOptions.length) {
            handleSelect(filteredOptions[focusedIndex].value);
            e.preventDefault();
          }
          break;
        case "Escape":
          setIsOpen(false);
          break;
        case "ArrowDown":
          e.preventDefault();
          if (!isOpen) setIsOpen(true);
          else setFocusedIndex((prev) => (prev + 1) % filteredOptions.length);
          break;
        case "ArrowUp":
          e.preventDefault();
          if (!isOpen) setIsOpen(true);
          else setFocusedIndex((prev) => (prev - 1 + filteredOptions.length) % filteredOptions.length);
          break;
      }
    };

    // Scroll to focused item
    React.useEffect(() => {
      if (isOpen && focusedIndex >= 0 && listboxRef.current) {
        const item = listboxRef.current.children[focusedIndex] as HTMLElement;
        if (item) {
          item.scrollIntoView({ block: "nearest" });
        }
      }
    }, [focusedIndex, isOpen]);

    const isSelected = (val: string) => {
      if (multiple && Array.isArray(value)) return value.includes(val);
      return value === val;
    };

    const getDisplayValue = () => {
      if (multiple && Array.isArray(value)) {
        if (value.length === 0) return <span className="text-[var(--text-tertiary)]">{placeholder}</span>;
        return (
          <div className="flex flex-wrap gap-1">
            {value.map((v) => {
              const opt = options.find((o) => o.value === v);
              return (
                <span
                  key={v}
                  className="flex items-center gap-1 bg-[var(--surface-active)] text-[var(--text-primary)] text-sm px-2 py-0.5 rounded-md"
                >
                  {opt?.label || v}
                  <button
                    onClick={(e) => removeOption(e, v)}
                    className="hover:text-[var(--color-error)] focus:outline-none"
                    aria-label={`Remove ${opt?.label}`}
                  >
                    <X size={14} />
                  </button>
                </span>
              );
            })}
          </div>
        );
      }
      
      const opt = options.find((o) => o.value === value);
      return opt ? (
        <span className="text-[var(--text-primary)] truncate block">{opt.label}</span>
      ) : (
        <span className="text-[var(--text-tertiary)]">{placeholder}</span>
      );
    };

    return (
      <div className={cn("relative w-full flex flex-col", className)} ref={containerRef}>
        {label && (
          <label className="text-sm font-medium mb-1.5 text-[var(--text-secondary)]">
            {label}
          </label>
        )}
        
        <div
          ref={ref}
          role="combobox"
          aria-expanded={isOpen}
          aria-haspopup="listbox"
          aria-controls="select-listbox"
          tabIndex={disabled ? -1 : 0}
          onKeyDown={handleKeyDown}
          onClick={() => !disabled && setIsOpen(!isOpen)}
          className={cn(
            "relative flex items-center justify-between w-full min-h-[56px] px-4 py-3 bg-[var(--surface-active)] rounded-sg border transition-all duration-200 cursor-pointer outline-none",
            isOpen ? "border-[var(--color-primary)] ring-1 ring-[var(--color-primary)] bg-[var(--surface-default)]" : "border-transparent",
            error && "border-[var(--color-error)]",
            disabled && "opacity-50 cursor-not-allowed bg-[var(--bg-level-2)]"
          )}
        >
          <div className="flex-1 overflow-hidden pe-4 rtl:pe-0 rtl:ps-4">
            {getDisplayValue()}
          </div>
          
          <div className="text-[var(--text-tertiary)] shrink-0">
            <motion.div animate={{ rotate: isOpen ? 180 : 0 }} transition={{ duration: 0.2 }}>
              <ChevronDown size={20} />
            </motion.div>
          </div>
        </div>

        <AnimatePresence>
          {isOpen && (
            <motion.div
              initial={{ opacity: 0, y: -8, scale: 0.95 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: -8, scale: 0.95 }}
              transition={{ duration: 0.2, ease: "easeOut" }}
              className="absolute top-[calc(100%+8px)] start-0 w-full z-50 bg-[var(--surface-default)] border border-[var(--border-level-2)] rounded-sg shadow-lg overflow-hidden flex flex-col"
            >
              {searchable && (
                <div className="p-2 border-b border-[var(--border-level-1)] relative">
                  <Search className="absolute start-4 top-1/2 -translate-y-1/2 text-[var(--text-tertiary)]" size={16} />
                  <input
                    ref={inputRef}
                    type="text"
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    onClick={(e) => e.stopPropagation()}
                    onKeyDown={(e) => {
                      if (e.key === "ArrowDown" || e.key === "ArrowUp" || e.key === "Enter" || e.key === "Escape") {
                        handleKeyDown(e);
                      }
                    }}
                    placeholder="Search..."
                    className="w-full bg-[var(--surface-active)] rounded-md ps-9 rtl:pe-9 rtl:ps-3 pe-3 py-2 text-sm outline-none focus:ring-1 focus:ring-[var(--color-primary)] text-[var(--text-primary)]"
                    autoFocus
                  />
                </div>
              )}
              
              <ul
                ref={listboxRef}
                role="listbox"
                id="select-listbox"
                aria-multiselectable={multiple}
                className="max-h-60 overflow-y-auto p-1"
              >
                {filteredOptions.length === 0 ? (
                  <li className="px-4 py-3 text-sm text-[var(--text-tertiary)] text-center">
                    No options found
                  </li>
                ) : (
                  filteredOptions.map((option, index) => {
                    const selected = isSelected(option.value);
                    const focused = index === focusedIndex;
                    
                    return (
                      <li
                        key={option.value}
                        role="option"
                        aria-selected={selected}
                        onClick={(e) => {
                          e.stopPropagation();
                          handleSelect(option.value);
                        }}
                        onMouseEnter={() => setFocusedIndex(index)}
                        className={cn(
                          "flex items-center justify-between px-3 py-2.5 rounded-md text-sm cursor-pointer transition-colors",
                          selected ? "text-[var(--color-primary)] font-medium bg-[var(--surface-selected)]" : "text-[var(--text-primary)]",
                          focused && !selected && "bg-[var(--surface-hover)]",
                          focused && selected && "bg-[var(--surface-selected)] brightness-95"
                        )}
                      >
                        <span className="truncate">{option.label}</span>
                        {selected && <Check size={16} className="text-[var(--color-primary)] shrink-0" />}
                      </li>
                    );
                  })
                )}
              </ul>
            </motion.div>
          )}
        </AnimatePresence>

        {error && (
          <motion.p
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="text-sm mt-1.5 px-1 text-[var(--color-error)]"
          >
            {error}
          </motion.p>
        )}
        {name && (
          <input 
            type="hidden" 
            name={name} 
            value={Array.isArray(value) ? value.join(',') : (value || '')} 
          />
        )}
      </div>
    );
  }
);

Select.displayName = "Select";

"use client";

/*
  Storybook Usage:
  <Tabs defaultValue="tab1">
    <TabsList>
      <TabsTrigger value="tab1">Account</TabsTrigger>
      <TabsTrigger value="tab2">Password</TabsTrigger>
    </TabsList>
    <TabsContent value="tab1">Account settings here.</TabsContent>
    <TabsContent value="tab2">Password settings here.</TabsContent>
  </Tabs>
*/

import * as React from "react";
import { motion, AnimatePresence } from "framer-motion";
import { cn } from "@/lib/utils";

type TabsContextValue = {
  activeTab: string;
  setActiveTab: (val: string) => void;
  orientation: "horizontal" | "vertical";
  id: string;
};

const TabsContext = React.createContext<TabsContextValue | null>(null);

export interface TabsProps {
  defaultValue: string;
  value?: string;
  onValueChange?: (val: string) => void;
  orientation?: "horizontal" | "vertical";
  className?: string;
  children: React.ReactNode;
}

export const Tabs = ({
  defaultValue,
  value,
  onValueChange,
  orientation = "horizontal",
  className,
  children,
}: TabsProps) => {
  const [internalValue, setInternalValue] = React.useState(defaultValue);
  const activeTab = value !== undefined ? value : internalValue;
  const id = React.useId();

  const setActiveTab = React.useCallback(
    (val: string) => {
      if (value === undefined) setInternalValue(val);
      onValueChange?.(val);
    },
    [value, onValueChange]
  );

  return (
    <TabsContext.Provider value={{ activeTab, setActiveTab, orientation, id }}>
      <div
        className={cn(
          "flex w-full",
          orientation === "horizontal" ? "flex-col" : "flex-row gap-4",
          className
        )}
      >
        {children}
      </div>
    </TabsContext.Provider>
  );
};

export const TabsList = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, children, ...props }, ref) => {
    const context = React.useContext(TabsContext);
    if (!context) throw new Error("TabsList must be used within a Tabs component");

    return (
      <div
        ref={ref}
        role="tablist"
        aria-orientation={context.orientation}
        className={cn(
          "flex items-center p-1 bg-[var(--surface-active)] rounded-sg",
          context.orientation === "horizontal"
            ? "flex-row overflow-x-auto overflow-y-hidden snap-x snap-mandatory hide-scrollbar"
            : "flex-col w-48 shrink-0",
          className
        )}
        {...props}
      >
        {children}
      </div>
    );
  }
);
TabsList.displayName = "TabsList";

export const TabsTrigger = React.forwardRef<
  HTMLButtonElement,
  React.ButtonHTMLAttributes<HTMLButtonElement> & { value: string }
>(({ className, value, children, disabled, ...props }, ref) => {
  const context = React.useContext(TabsContext);
  if (!context) throw new Error("TabsTrigger must be used within a Tabs component");

  const isActive = context.activeTab === value;

  return (
    <button
      ref={ref}
      role="tab"
      aria-selected={isActive}
      aria-controls={`${context.id}-panel-${value}`}
      id={`${context.id}-tab-${value}`}
      disabled={disabled}
      onClick={() => context.setActiveTab(value)}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          context.setActiveTab(value);
        }
      }}
      className={cn(
        "relative flex items-center justify-center px-4 py-2 text-sm font-medium transition-colors rounded-md focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-primary)] whitespace-nowrap snap-center z-10",
        context.orientation === "horizontal" ? "flex-1" : "w-full justify-start",
        isActive ? "text-[var(--text-primary)]" : "text-[var(--text-secondary)] hover:text-[var(--text-primary)]",
        disabled && "opacity-50 cursor-not-allowed",
        className
      )}
      {...props}
    >
      {isActive && (
        <motion.div
          layoutId={`${context.id}-active-tab`}
          className="absolute inset-0 bg-[var(--surface-default)] rounded-md shadow-sm border border-[var(--border-level-2)] -z-10"
          initial={false}
          transition={{ type: "spring", stiffness: 400, damping: 30 }}
        />
      )}
      {children}
    </button>
  );
});
TabsTrigger.displayName = "TabsTrigger";

export const TabsContent = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> & { value: string }
>(({ className, value, children, ...props }, ref) => {
  const context = React.useContext(TabsContext);
  if (!context) throw new Error("TabsContent must be used within a Tabs component");

  const isActive = context.activeTab === value;

  return (
    <AnimatePresence mode="wait">
      {isActive && (
        <motion.div
          ref={ref}
          role="tabpanel"
          id={`${context.id}-panel-${value}`}
          aria-labelledby={`${context.id}-tab-${value}`}
          tabIndex={0}
          initial={{ opacity: 0, y: 5 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -5 }}
          transition={{ duration: 0.2 }}
          className={cn(
            "flex-1 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-primary)] rounded-sg",
            context.orientation === "horizontal" ? "mt-4" : "",
            className
          )}
          {...(props as any)}
        >
          {children}
        </motion.div>
      )}
    </AnimatePresence>
  );
});
TabsContent.displayName = "TabsContent";

"use client";

import { useSession } from "next-auth/react";
import { hasPermission, Role } from "@/lib/permissions";

export function useAuth() {
  const { data: session, status } = useSession();

  const user = session?.user;
  const role = (user as any)?.role as Role | undefined;

  return {
    user,
    role,
    status,
    isLoading: status === "loading",
    isAuthenticated: status === "authenticated",
  };
}

export function useIsAuthenticated() {
  const { status } = useSession();
  return status === "authenticated";
}

export function useHasPermission(resource: string, action: string) {
  const { role } = useAuth();
  return hasPermission(role, resource, action);
}

"use client"

import { useEffect, useState } from 'react'
import { io, Socket } from 'socket.io-client'
import type { 
  OccupancyEvent, 
  StatusEvent, 
  DashboardStatsEvent, 
  NewLeadEvent, 
  TicketSoldEvent, 
  NewFeedbackEvent, 
  BroadcastEvent 
} from '@/lib/socket'

// Base hook for connecting to a namespace
export function useSocket(namespace: string) {
  const [socket, setSocket] = useState<Socket | null>(null)

  useEffect(() => {
    // Socket.io automatically handles exponential backoff and reconnection
    const socketInstance = io(namespace, {
      path: '/api/socket.io',
      transports: ['websocket', 'polling'],
      withCredentials: true, // Important for sending NextAuth cookies during handshake
      reconnectionAttempts: Infinity,
      reconnectionDelay: 1000,
      reconnectionDelayMax: 5000,
      timeout: 20000,
    })

    // eslint-disable-next-line react-hooks/set-state-in-effect -- Expected pattern for connection initialization
    setSocket(socketInstance)

    return () => {
      socketInstance.disconnect()
    }
  }, [namespace])

  return socket
}

// ---------------------------------------------------------
// DOMAIN HOOKS
// ---------------------------------------------------------

export function useAttractionOccupancy(attractionId: string) {
  const socket = useSocket('/public')
  const [occupancy, setOccupancy] = useState<OccupancyEvent | null>(null)
  const [isOpen, setIsOpen] = useState(true)
  const [isConnected, setIsConnected] = useState(false)

  useEffect(() => {
    if (!socket) return

    const handleConnect = () => {
      setIsConnected(true)
      socket.emit('join:attraction', attractionId)
    }

    const handleDisconnect = () => setIsConnected(false)

    const handleOccupancy = (data: OccupancyEvent) => {
      if (data.attractionId === attractionId) {
        setOccupancy(data)
      }
    }

    const handleStatus = (data: StatusEvent) => {
      if (data.attractionId === attractionId) {
        setIsOpen(data.isOpen)
      }
    }

    socket.on('connect', handleConnect)
    socket.on('disconnect', handleDisconnect)
    socket.on('attraction:occupancy', handleOccupancy)
    socket.on('attraction:status', handleStatus)

    if (socket.connected) {
      handleConnect()
    }

    return () => {
      socket.off('connect', handleConnect)
      socket.off('disconnect', handleDisconnect)
      socket.off('attraction:occupancy', handleOccupancy)
      socket.off('attraction:status', handleStatus)
      if (socket.connected) socket.emit('leave:attraction', attractionId)
    }
  }, [socket, attractionId])

  return {
    ...occupancy,
    percentage: occupancy ? (occupancy.current / occupancy.max) * 100 : 0,
    isOpen,
    isConnected,
  }
}

// Feed item type
export type FeedItem = {
  id: string
  type: 'lead' | 'ticket' | 'feedback' | 'broadcast'
  timestamp: Date
  data: any
}

export function useDashboardFeed(initialItems: FeedItem[] = []) {
  const socket = useSocket('/dashboard')
  const [feed, setFeed] = useState<FeedItem[]>(initialItems)
  const [isConnected, setIsConnected] = useState(false)

  useEffect(() => {
    if (!socket) return

    const handleConnect = () => setIsConnected(true)
    const handleDisconnect = () => setIsConnected(false)

    const addFeedItem = (type: FeedItem['type'], data: any) => {
      setFeed(prev => {
        const newItem: FeedItem = { id: crypto.randomUUID(), type, timestamp: new Date(), data }
        const next = [newItem, ...prev]
        return next.slice(0, 50) // Max 50 items
      })
    }

    const handleLead = (data: NewLeadEvent) => addFeedItem('lead', data)
    const handleTicket = (data: TicketSoldEvent) => addFeedItem('ticket', data)
    const handleFeedback = (data: NewFeedbackEvent) => addFeedItem('feedback', data)
    const handleBroadcast = (data: BroadcastEvent) => addFeedItem('broadcast', data)

    socket.on('connect', handleConnect)
    socket.on('disconnect', handleDisconnect)
    socket.on('lead:new', handleLead)
    socket.on('ticket:sold', handleTicket)
    socket.on('feedback:new', handleFeedback)
    socket.on('broadcast:active', handleBroadcast)

    if (socket.connected) handleConnect()

    return () => {
      socket.off('connect', handleConnect)
      socket.off('disconnect', handleDisconnect)
      socket.off('lead:new', handleLead)
      socket.off('ticket:sold', handleTicket)
      socket.off('feedback:new', handleFeedback)
      socket.off('broadcast:active', handleBroadcast)
    }
  }, [socket])

  return { feed, isConnected }
}

export function useLiveStats() {
  const socket = useSocket('/dashboard')
  const [stats, setStats] = useState<DashboardStatsEvent | null>(null)

  useEffect(() => {
    if (!socket) return

    const handleStats = (data: DashboardStatsEvent) => {
      setStats(data)
    }

    socket.on('dashboard:stats', handleStats)

    return () => {
      socket.off('dashboard:stats', handleStats)
    }
  }, [socket])

  return stats
}

import type { NextAuthConfig } from "next-auth"

export const authConfig = {
  trustHost: true,
  providers: [], // Providers (like Credentials which uses Node APIs) are injected in auth.ts
  session: {
    strategy: "jwt",
    maxAge: 24 * 60 * 60, // 24 hours
  },
  callbacks: {
    async jwt({ token, user }) {
      if (user) {
        token.id = user.id
        token.role = (user as any).role
      }
      return token
    },
    async session({ session, token }) {
      if (token && session.user) {
        session.user.id = token.id as string
        ;(session.user as any).role = token.role as string
      }
      return session
    }
  },
  pages: {
    signIn: "/auth/login",
  },
} satisfies NextAuthConfig

import NextAuth from "next-auth"
import CredentialsProvider from "next-auth/providers/credentials"
import db from "@/lib/db"
import bcrypt from "bcryptjs"
import { authConfig } from "./auth.config"

export const { handlers, auth, signIn, signOut } = NextAuth({
  ...authConfig,
  trustHost: true,
  session: { strategy: "jwt", maxAge: 86400 },
  providers: [
    CredentialsProvider({
      name: "Credentials",
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" }
      },
      async authorize(credentials) {
        if (!credentials?.email || !credentials?.password) {
          return null
        }

        const user = await db.user.findUnique({
          where: { email: credentials.email as string }
        })

        if (!user) {
          throw new Error("Invalid credentials")
        }

        if (!user.isActive) {
          throw new Error("Account is inactive")
        }

        if (!user.emailVerified) {
          throw new Error("Email not verified")
        }

        if (!user.password) {
          throw new Error("Invalid credentials")
        }

        const isPasswordValid = await bcrypt.compare(
          credentials.password as string,
          user.password
        )

        if (!isPasswordValid) {
          throw new Error("Invalid credentials")
        }

        return {
          id: user.id,
          email: user.email,
          role: user.role,
        }
      }
    })
  ],
  callbacks: {
    async jwt({ token, user }) {
      if (user) {
        token.id = user.id
        token.role = (user as any).role
      }
      return token
    },
    async session({ session, token }) {
      if (session.user) {
        (session.user as any).id = token.id as string;
        (session.user as any).role = token.role as string;
      }
      return session
    }
  }
})

import { PrismaClient } from '@prisma/client'

const prismaClientSingleton = () => {
  return new PrismaClient({
    log: [
      { emit: 'event', level: 'query' },
      { emit: 'stdout', level: 'error' },
      { emit: 'stdout', level: 'info' },
      { emit: 'stdout', level: 'warn' },
    ],
  }).$extends({
    query: {
      $allModels: {
        async $allOperations({ operation, model, args, query }: any) {
          const start = performance.now()
          const TIMEOUT_MS = 5000 // 5 seconds max per query
          
          const timeoutPromise = new Promise((_, reject) => {
            setTimeout(() => reject(new Error(`[DB TIMEOUT] ${model}.${operation} exceeded ${TIMEOUT_MS}ms`)), TIMEOUT_MS)
          })

          try {
            const result = await Promise.race([query(args), timeoutPromise])
            const end = performance.now()
            const duration = end - start

            // Log warning if query exceeds 100ms budget
            if (duration > 100) {
              console.warn(`[PRISMA PERFORMANCE BREACH] ${model}.${operation} took ${Math.round(duration)}ms`)
            }

            return result
          } catch (error) {
            console.error(`[DB ERROR] ${model}.${operation} failed:`, error)
            throw error
          }
        }
      }
    }
  })
}

